public struct JobItem: Identifiable {
    public var id: String { jobId }
    public let jobId: String
    public let applicationId: String
    public let companyName: String
    public let title: String
    public let canonicalUrl: String
    public let description: String
    public let postedAt: String
    public let postedLabel: String
    public let workplaceMode: String
    public let locationLabel: String
    public let salaryMaxUsd: Int
    public let eligible: Bool
    public let eligibilityStatus: String // "eligible" | "not_eligible"
    public let exclusionReason: String?
    public let filterSummary: String
    public let dedupeStatus: String
    public var state: String
    public var pipelineStage: String // "not_applied" | "applying" | "submitted" | "failed"
    public var previousPipelineStage: String
    public let failureReason: String
    public let failureKind: String
    public let trackerSyncState: String
    public let remoteReceiptId: String?
    public let uncertainEffect: Bool
    public let screeningAnswers: [String: String]
    public let timeline: [String]
    public let matchScorePct: Int
    public let matchTier: String
    public let roleFitPct: Int
    public let skillsFitPct: Int
    public let experienceFitPct: Int
    public let logisticsFitPct: Int
    public let matchedSkills: [String]
    public let missingGaps: [String]
    public let matchSummary: String
    public let matchJevVerified: Bool
    public let matchModel: String

    public var matchScoreColor: Color {
        if matchScorePct >= 80 { return .green }
        if matchScorePct >= 65 { return .accentColor }
        if matchScorePct >= 50 { return .orange }
        return .secondary
    }

    public var pipelineStageLabel: String {
        switch pipelineStage {
        case "submitted": return "Submitted"
        case "applying": return "Applying"
        case "failed": return "Failed"
        default: return "Not Applied"
        }
    }

    public var previousPipelineStageLabel: String {
        switch previousPipelineStage {
        case "submitted": return "Submitted"
        case "applying": return "Applying"
        case "failed": return "Failed"
        case "not_applied": return "Not Applied"
        default: return pipelineStage == "submitted" ? "Applying" : "Not Applied"
        }
    }

    public var effectivePreviousPipelineStage: String {
        if ["not_applied", "applying", "submitted", "failed"].contains(previousPipelineStage) && previousPipelineStage != pipelineStage {
            return previousPipelineStage
        }
        return pipelineStage == "submitted" ? "applying" : "not_applied"
    }

    public var pipelineStageIcon: String {
        switch pipelineStage {
        case "submitted": return "checkmark.seal.fill"
        case "applying": return "sparkles.rectangle.stack.fill"
        case "failed": return "exclamationmark.triangle.fill"
        default: return "tray.and.arrow.down.fill"
        }
    }

    public var pipelineStageColor: Color {
        switch pipelineStage {
        case "submitted": return .green
        case "applying": return .blue
        case "failed": return .orange
        default: return .secondary
        }
    }
}

