// MARK: - High-Performance Off-Main-Thread Thumbnail Cache & Precompiled Message Parser

public final class FastThumbnailCache: @unchecked Sendable {
    public static let shared = FastThumbnailCache()

    private let memoryCache: NSCache<NSString, NSImage> = {
        let c = NSCache<NSString, NSImage>()
        c.countLimit = 1200
        c.totalCostLimit = 36 * 1024 * 1024
        return c
    }()

    private let lock = NSLock()
    private var inFlightCallbacks: [String: [(NSImage?) -> Void]] = [:]
    private var failedRemoteUrls: [String: TimeInterval] = [:]

    private let diskDecodeQueue: OperationQueue = {
        let q = OperationQueue()
        q.name = "com.autoapply.thumbnail.decode"
        q.qualityOfService = .userInitiated
        q.maxConcurrentOperationCount = 6
        return q
    }()

    private let remoteFetchQueue: OperationQueue = {
        let q = OperationQueue()
        q.name = "com.autoapply.thumbnail.network"
        q.qualityOfService = .utility
        q.maxConcurrentOperationCount = 4
        return q
    }()

    private lazy var avatarsRootDir: URL? = {
        guard let appSup = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first else {
            return nil
        }
        let dir = appSup.appendingPathComponent("AutoApply/avatars", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir.appendingPathComponent("originals", isDirectory: true), withIntermediateDirectories: true)
        try? FileManager.default.createDirectory(at: dir.appendingPathComponent("thumbs_96", isDirectory: true), withIntermediateDirectories: true)
        return dir
    }()

    private lazy var supportsWebPEncode: Bool = {
        guard let types = CGImageDestinationCopyTypeIdentifiers() as? [String] else { return false }
        return types.contains("org.webmproject.webp")
    }()

    private init() {}

    /// Prefer sibling compressed 96x96 WebP icon when given a full-res profile_avatar.* or legacy flat avatar path.
    public func resolvePreferredThumbnailPath(_ rawPath: String) -> String {
        let trimmed = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }
        if trimmed.hasSuffix(".webp") && FileManager.default.fileExists(atPath: trimmed) {
            return trimmed
        }
        let url = URL(fileURLWithPath: trimmed)
        let dir = url.deletingLastPathComponent()
        let stem = url.deletingPathExtension().lastPathComponent
        if stem.hasPrefix("profile_avatar") {
            let webpSibling = dir.appendingPathComponent("profile_avatar_icon_96.webp").path
            if FileManager.default.fileExists(atPath: webpSibling) {
                return webpSibling
            }
        }
        let subThumb = dir.appendingPathComponent("thumbs_96/\(stem).webp").path
        if FileManager.default.fileExists(atPath: subThumb) {
            return subThumb
        }
        return trimmed
    }

    public func cacheKey(localPath: String, remoteUrl: String, pixelBucket: Int) -> String {
        let resolvedLocal = resolvePreferredThumbnailPath(localPath)
        let sourceId = !resolvedLocal.isEmpty ? "file:\(resolvedLocal)" : "url:\(remoteUrl.trimmingCharacters(in: .whitespacesAndNewlines))"
        return "\(sourceId)#\(pixelBucket)"
    }

    public static func pixelBucket(forPointSize size: CGFloat) -> Int {
        let rawPx = Int(ceil(size * 2.0))
        if rawPx <= 64 { return 64 }
        if rawPx <= 96 { return 96 }
        return min(160, rawPx)
    }

    public func cachedImage(forKey key: String) -> NSImage? {
        guard !key.hasPrefix("url:#") else { return nil }
        return memoryCache.object(forKey: key as NSString)
    }

    public func invalidate(path: String) {
        let resolved = resolvePreferredThumbnailPath(path)
        for bucket in [64, 96, 128, 160] {
            memoryCache.removeObject(forKey: "file:\(path)#\(bucket)" as NSString)
            memoryCache.removeObject(forKey: "file:\(resolved)#\(bucket)" as NSString)
        }
    }

    /// Hardware-accelerated ImageIO thumbnail downsampling & immediate background bitmap decompression (zero main-thread image decode).
    public static func decodeDownsampledImage(from source: CGImageSource, maxPixelSize: Int) -> (NSImage, CGImage)? {
        let opts: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: max(32, maxPixelSize),
        ]
        guard let cgImg = CGImageSourceCreateThumbnailAtIndex(source, 0, opts as CFDictionary) else {
            return nil
        }
        let nsImg = NSImage(cgImage: cgImg, size: NSSize(width: cgImg.width, height: cgImg.height))
        return (nsImg, cgImg)
    }

    public func loadThumbnail(
        localPath: String,
        remoteUrl: String = "",
        cacheSlugHint: String = "",
        pointSize: CGFloat,
        completion: @escaping @Sendable (NSImage?) -> Void
    ) {
        let bucket = Self.pixelBucket(forPointSize: pointSize)
        let resolvedLocal = resolvePreferredThumbnailPath(localPath)
        let trimmedRemote = remoteUrl.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !resolvedLocal.isEmpty || !trimmedRemote.isEmpty else {
            completion(nil)
            return
        }

        let key = cacheKey(localPath: resolvedLocal, remoteUrl: trimmedRemote, pixelBucket: bucket)
        if let hit = memoryCache.object(forKey: key as NSString) {
            completion(hit)
            return
        }

        lock.lock()
        if !resolvedLocal.isEmpty == false && !trimmedRemote.isEmpty {
            if let failedAt = failedRemoteUrls[trimmedRemote], Date().timeIntervalSince1970 - failedAt < 300 {
                lock.unlock()
                completion(nil)
                return
            }
        }
        if var existing = inFlightCallbacks[key] {
            existing.append(completion)
            inFlightCallbacks[key] = existing
            lock.unlock()
            return
        }
        inFlightCallbacks[key] = [completion]
        lock.unlock()

        let finish: @Sendable (NSImage?) -> Void = { [weak self] img in
            guard let self = self else { return }
            if let img = img {
                let approxBytes = bucket * bucket * 4
                self.memoryCache.setObject(img, forKey: key as NSString, cost: approxBytes)
            }
            self.lock.lock()
            let callbacks = self.inFlightCallbacks.removeValue(forKey: key) ?? []
            self.lock.unlock()
            DispatchQueue.main.async {
                for cb in callbacks {
                    cb(img)
                }
            }
        }

        if !resolvedLocal.isEmpty && FileManager.default.fileExists(atPath: resolvedLocal) {
            diskDecodeQueue.addOperation {
                let fileUrl = URL(fileURLWithPath: resolvedLocal)
                let srcOpts: [CFString: Any] = [kCGImageSourceShouldCache: false]
                if let src = CGImageSourceCreateWithURL(fileUrl as CFURL, srcOpts as CFDictionary),
                   let (nsImg, _) = Self.decodeDownsampledImage(from: src, maxPixelSize: bucket)
                {
                    finish(nsImg)
                    return
                }
                finish(nil)
            }
            return
        }

        guard !trimmedRemote.isEmpty, let url = URL(string: trimmedRemote) else {
            finish(nil)
            return
        }

        remoteFetchQueue.addOperation { [weak self] in
            var req = URLRequest(url: url, cachePolicy: .returnCacheDataElseLoad, timeoutInterval: 5.0)
            req.setValue("Mozilla/5.0", forHTTPHeaderField: "User-Agent")
            let task = URLSession.shared.dataTask(with: req) { data, resp, _ in
                guard let self = self else { return }
                guard let data = data, data.count > 120,
                      let http = resp as? HTTPURLResponse, http.statusCode == 200
                else {
                    self.lock.lock()
                    self.failedRemoteUrls[trimmedRemote] = Date().timeIntervalSince1970
                    self.lock.unlock()
                    finish(nil)
                    return
                }
                let srcOpts: [CFString: Any] = [kCGImageSourceShouldCache: false]
                guard let src = CGImageSourceCreateWithData(data as CFData, srcOpts as CFDictionary),
                      let (nsImg, cgThumb) = Self.decodeDownsampledImage(from: src, maxPixelSize: max(96, bucket))
                else {
                    self.lock.lock()
                    self.failedRemoteUrls[trimmedRemote] = Date().timeIntervalSince1970
                    self.lock.unlock()
                    finish(nil)
                    return
                }
                // Persist full higher-res original in avatars/originals/ AND compressed low-res icon in avatars/thumbs_96/
                self.persistFetchedAvatarDualTier(rawData: data, cgThumb: cgThumb, slugHint: cacheSlugHint, remoteUrl: trimmedRemote)
                finish(nsImg)
            }
            task.resume()
        }
    }

    private func persistFetchedAvatarDualTier(rawData: Data, cgThumb: CGImage, slugHint: String, remoteUrl: String) {
        guard let root = avatarsRootDir else { return }
        let rawSlug = slugHint.isEmpty ? String(abs(remoteUrl.hashValue)) : slugHint
        let cleanSlug = rawSlug
            .lowercased()
            .replacingOccurrences(of: "[^a-z0-9_]+", with: "_", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "_"))
        guard !cleanSlug.isEmpty else { return }
        let stem = String(cleanSlug.prefix(76))

        let isPng = rawData.starts(with: [0x89, 0x50, 0x4E, 0x47])
        let isWebP = rawData.count > 12 && String(data: rawData.subdata(in: 8..<12), encoding: .ascii) == "WEBP"
        let origExt = isPng ? "png" : (isWebP ? "webp" : "jpg")
        let origUrl = root.appendingPathComponent("originals/\(stem).\(origExt)")
        if !FileManager.default.fileExists(atPath: origUrl.path) {
            try? rawData.write(to: origUrl, options: .atomic)
        }

        let thumbExt = supportsWebPEncode ? "webp" : "jpg"
        let thumbType: CFString = (supportsWebPEncode ? "org.webmproject.webp" : "public.jpeg") as CFString
        let thumbUrl = root.appendingPathComponent("thumbs_96/\(stem).\(thumbExt)")
        if !FileManager.default.fileExists(atPath: thumbUrl.path),
           let dest = CGImageDestinationCreateWithURL(thumbUrl as CFURL, thumbType, 1, nil)
        {
            let props: [CFString: Any] = [kCGImageDestinationLossyCompressionQuality: 0.80]
            CGImageDestinationAddImage(dest, cgThumb, props as CFDictionary)
            CGImageDestinationFinalize(dest)
        }
    }
}

public enum MessageTextProcessor {
    private static let mailtoRegex = try? NSRegularExpression(pattern: #"<mailto:[^>]+>"#, options: [.caseInsensitive])
    private static let inlineImageTagRegex = try? NSRegularExpression(pattern: #"\[image:[^\]]*\]"#, options: [.caseInsensitive])
    private static let bracketedBareUrlRegex = try? NSRegularExpression(pattern: #"\[(https?://[^\]]+)\](?!\()"#)
    private static let gmailAboutRegex = try? NSRegularExpression(pattern: #"<https://www\.google\.com/gmail/about/[^>]+>"#)
    private static let angleUrlRegex = try? NSRegularExpression(pattern: #"<(https?://[^>]+)>"#)
    private static let bareKnownFormDomainRegex = try? NSRegularExpression(
        pattern: #"(?<![/:a-zA-Z0-9])((?:coda\.io/form|app\.willotalent\.com|app\.rembrandtadvantage\.com|app\.fluencyfox\.ai|candidateassessments\.ajaia\.ai|calendly\.com)/[^\s)>\]]+)"#
    )
    private static let replyAboveLine1Regex = try? NSRegularExpression(
        pattern: #"^[\s\-—_=*]*please reply above this line[\s\-—_=*]*\n*"#,
        options: [.caseInsensitive, .anchorsMatchLines]
    )
    private static let replyAboveLine2Regex = try? NSRegularExpression(
        pattern: #"^[\s\-—_=*]*reply above this line\.?[\s\-—_=*]*\n*"#,
        options: [.caseInsensitive, .anchorsMatchLines]
    )
    private static let quoteCutRegexes: [NSRegularExpression] = [
        #"^[>\s]*On\s+(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun|Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|\d{1,2}\s+[A-Za-z]{3,9}|[A-Za-z]{3,9}\s+\d{1,2})\b[^\n]*(?:\n[^\n]{0,140})?\bwrote:\s*$"#,
        #"^[>\s]*-{3,}\s*Original Message\s*-{3,}.*$"#,
        #"^[>\s]*_{8,}\s*\n+\s*(?:From|От|Sent|Date)\s*:.*$"#,
        #"^[>\s]*(?:From|От)\s*:\s*[^\n]*\n+\s*(?:Sent|Date|To|Subject|Отправлено|Дата|Кому|Тема)\s*:.*$"#,
        #"^[>\s]*(?:From|От)\s*:\s*[^\n]*(?:@|<mailto:)[^\n]*$"#,
        #"^[>\s]*[^\n]*(?:wrote|написав|написала|написал|пишет|schrieb|a écrit)\s*:\s*$"#,
    ].compactMap { try? NSRegularExpression(pattern: $0, options: [.caseInsensitive, .anchorsMatchLines]) }

    private static let trailingRuleRegex = try? NSRegularExpression(pattern: #"(?:\n\s*[_\-—=]{6,}\s*)+\z"#)
    private static let multiNewlineRegex = try? NSRegularExpression(pattern: #"\n{3,}"#)
    private static let markdownLinkStripRegex = try? NSRegularExpression(pattern: #"\[([^\]]+)\]\(https?://[^)]+\)"#)
    private static let multiSpaceRegex = try? NSRegularExpression(pattern: #"\s{2,}"#)
    private static let bareUrlWrapRegex = try? NSRegularExpression(pattern: #"(?<!\]\()(?<!\[)(https?://[^\s)>\]]+)"#)
    private static let mdLinkExtractRegex = try? NSRegularExpression(pattern: #"\[([^\]]+)\]\((https?://[^)\s]+)\)"#)
    private static let bareUrlExtractRegex = try? NSRegularExpression(pattern: #"https?://[^\s)>\]]+"#)

    private static let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

    private final class AttributedBox: NSObject {
        let value: AttributedString
        init(_ value: AttributedString) { self.value = value }
    }

    private final class LinksBox: NSObject {
        let value: [(label: String, url: String)]
        init(_ value: [(label: String, url: String)]) { self.value = value }
    }

    nonisolated(unsafe) private static let attributedCache: NSCache<NSString, AttributedBox> = {
        let c = NSCache<NSString, AttributedBox>()
        c.countLimit = 800
        return c
    }()

    nonisolated(unsafe) private static let linksCache: NSCache<NSString, LinksBox> = {
        let c = NSCache<NSString, LinksBox>()
        c.countLimit = 800
        return c
    }()

    private static func replace(_ regex: NSRegularExpression?, in text: String, with template: String) -> String {
        guard let regex = regex, !text.isEmpty else { return text }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        return regex.stringByReplacingMatches(in: text, options: [], range: range, withTemplate: template)
    }

    public static func stripQuotedEmailReply(_ rawBody: String) -> String {
        var txt = rawBody
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !txt.isEmpty else { return "" }

        if txt.contains("<") || txt.contains("[") {
            txt = replace(mailtoRegex, in: txt, with: "")
            txt = replace(inlineImageTagRegex, in: txt, with: "")
            txt = replace(bracketedBareUrlRegex, in: txt, with: "$1")
            txt = replace(gmailAboutRegex, in: txt, with: "")
            txt = replace(angleUrlRegex, in: txt, with: "$1")
        }
        txt = replace(bareKnownFormDomainRegex, in: txt, with: "https://$1")
        if txt.localizedCaseInsensitiveContains("reply above this line") {
            txt = replace(replyAboveLine1Regex, in: txt, with: "")
            txt = replace(replyAboveLine2Regex, in: txt, with: "")
        }

        let nsRange = NSRange(txt.startIndex..<txt.endIndex, in: txt)
        var earliestCutLocation: Int? = nil
        for regex in quoteCutRegexes {
            if let match = regex.firstMatch(in: txt, options: [], range: nsRange), match.range.location > 0 {
                if earliestCutLocation == nil || match.range.location < earliestCutLocation! {
                    earliestCutLocation = match.range.location
                }
            }
        }
        if let cutLoc = earliestCutLocation,
           let cutRange = Range(NSRange(location: 0, length: cutLoc), in: txt)
        {
            let prefix = String(txt[cutRange]).trimmingCharacters(in: .whitespacesAndNewlines)
            if !prefix.isEmpty && !prefix.localizedCaseInsensitiveContains("forwarded message") {
                txt = prefix
            }
        }

        if txt.contains(">") {
            let nonQuotedLines = txt.split(separator: "\n", omittingEmptySubsequences: false).filter { line in
                let trimmedLine = line.drop(while: { $0 == " " || $0 == "\t" })
                return !trimmedLine.hasPrefix(">")
            }
            let candidate = nonQuotedLines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
            if !candidate.isEmpty {
                txt = candidate
            }
        }

        txt = replace(trailingRuleRegex, in: txt, with: "")
        txt = replace(multiNewlineRegex, in: txt, with: "\n\n")
        return txt.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    public static func makeSingleLinePreviewSnippet(_ cleanedOrRaw: String, senderRole: String, maxChars: Int = 180) -> String {
        let prefixCrop = cleanedOrRaw.count > 600 ? String(cleanedOrRaw.prefix(600)) : cleanedOrRaw
        var s = replace(markdownLinkStripRegex, in: prefixCrop, with: "$1")
            .replacingOccurrences(of: "\r\n", with: " ")
            .replacingOccurrences(of: "\r", with: " ")
            .replacingOccurrences(of: "\n", with: " ")
        s = replace(multiSpaceRegex, in: s, with: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !s.isEmpty else { return "No message preview" }
        let prefix = (senderRole == "them") ? "" : "You: "
        let combined = prefix + s
        if combined.count <= maxChars {
            return combined
        }
        return String(combined.prefix(maxChars)) + "…"
    }

    public static func formatCompactTimestamp(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 10 else { return trimmed }
        let datePart = String(trimmed.prefix(10))
        let parts = datePart.split(separator: "-")
        guard parts.count == 3, let monthInt = Int(parts[1]), let dayInt = Int(parts[2]),
              monthInt >= 1 && monthInt <= 12
        else {
            return datePart
        }
        return "\(months[monthInt - 1]) \(dayInt)"
    }

    public static func formatReadableTimestamp(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 10 else { return trimmed }
        let shortDate = formatCompactTimestamp(trimmed)
        if trimmed.count >= 16 {
            let timePart = String(trimmed.dropFirst(11).prefix(5))
            return "\(shortDate), \(timePart)"
        }
        return shortDate
    }

    public static func formatCompactHandle(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.hasPrefix("https://www.linkedin.com/") {
            return trimmed.replacingOccurrences(of: "https://www.", with: "")
        }
        if trimmed.hasPrefix("https://") {
            return String(trimmed.dropFirst(8)).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        }
        if trimmed.hasPrefix("http://") {
            return String(trimmed.dropFirst(7)).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        }
        return trimmed
    }

    public static func richMessageAttributedString(_ rawBody: String, cacheId: String = "") -> AttributedString {
        guard !rawBody.isEmpty else { return AttributedString("") }
        let key = (cacheId.isEmpty ? "\(rawBody.hashValue)#\(rawBody.count)" : "\(cacheId)#\(rawBody.hashValue)") as NSString
        if let hit = attributedCache.object(forKey: key) {
            return hit.value
        }
        let markdownReady: String
        if rawBody.contains("http://") || rawBody.contains("https://") {
            markdownReady = replace(bareUrlWrapRegex, in: rawBody, with: "[$1]($1)")
        } else if !rawBody.contains("[") && !rawBody.contains("*") && !rawBody.contains("_") && !rawBody.contains("`") {
            let plain = AttributedString(rawBody)
            attributedCache.setObject(AttributedBox(plain), forKey: key)
            return plain
        } else {
            markdownReady = rawBody
        }
        let options = AttributedString.MarkdownParsingOptions(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        if var attr = try? AttributedString(markdown: markdownReady, options: options) {
            for run in attr.runs where run.link != nil {
                attr[run.range].foregroundColor = .accentColor
                attr[run.range].underlineStyle = .single
            }
            attributedCache.setObject(AttributedBox(attr), forKey: key)
            return attr
        }
        let fallback = AttributedString(rawBody)
        attributedCache.setObject(AttributedBox(fallback), forKey: key)
        return fallback
    }

    public static func extractActionableMessageLinks(_ rawBody: String, cacheId: String = "") -> [(label: String, url: String)] {
        guard !rawBody.isEmpty, (rawBody.contains("http://") || rawBody.contains("https://")) else { return [] }
        let key = (cacheId.isEmpty ? "links#\(rawBody.hashValue)#\(rawBody.count)" : "links#\(cacheId)#\(rawBody.hashValue)") as NSString
        if let hit = linksCache.object(forKey: key) {
            return hit.value
        }

        let ignoredSubstrings = [
            "facebook.com", "instagram.com", "twitter.com", "x.com/", "youtube.com",
            "dribbble.com", "unsubscribe", "orizon.co/refer", "zandahealth.com/reviews",
            "tanishasystems.com", "infuse.com/about", "artsclub", "musqueam", "squamish", "twnation",
            "whatsapp.com/channel"
        ]
        var results: [(label: String, url: String)] = []
        var seenUrls = Set<String>()

        func cleanUrl(_ u: String) -> String {
            var trimmed = u.trimmingCharacters(in: .whitespacesAndNewlines)
            while let last = trimmed.last, ".,;)>]*".contains(last) {
                trimmed.removeLast()
            }
            return trimmed
        }

        func friendlyLabel(explicitLabel: String?, url: String) -> String {
            let lowU = url.lowercased()
            if let exp = explicitLabel?.trimmingCharacters(in: .whitespacesAndNewlines),
               !exp.isEmpty,
               !exp.lowercased().hasPrefix("http")
            {
                if exp.lowercased() == "click here" {
                    if lowU.contains("comeet.co/pub/questionnaires") {
                        return "Complete Application Questionnaire"
                    }
                    return "Open Application Link"
                }
                return exp
            }
            if lowU.contains("rembrandtadvantage.com") { return "Rembrandt Portrait Assessment" }
            if lowU.contains("willotalent.com") { return "Start One-Way Video Interview (Willo)" }
            if lowU.contains("candidateassessments.ajaia.ai") { return "Open Product Manager Assessment" }
            if lowU.contains("fluencyfox.ai") { return "Start Assessment (FluencyFox)" }
            if lowU.contains("loom.com/share") { return "Watch Assessment Walkthrough (Loom)" }
            if lowU.contains("coda.io/form") { return "Complete Application Form (Coda)" }
            if lowU.contains("comeet.co/pub/questionnaires") { return "Complete Application Questionnaire" }
            if lowU.contains("greenhouse.io/application_form") { return "Confirm Test Receipt (Greenhouse)" }
            if lowU.contains("hrpartner.io/jobs") { return "Apply via Zanda Careers Portal" }
            if lowU.contains("jobs.micro1.ai") { return "View Micro1 Role" }
            if lowU.contains("calendly.com") { return "Schedule Call (Calendly)" }
            if let host = URL(string: url)?.host?.replacingOccurrences(of: "www.", with: "") {
                return "Open \(host)"
            }
            return "Open Link"
        }

        let nsRange = NSRange(rawBody.startIndex..<rawBody.endIndex, in: rawBody)
        if let mdRegex = mdLinkExtractRegex {
            for match in mdRegex.matches(in: rawBody, range: nsRange) {
                guard let lblRange = Range(match.range(at: 1), in: rawBody),
                      let urlRange = Range(match.range(at: 2), in: rawBody) else { continue }
                let u = cleanUrl(String(rawBody[urlRange]))
                let lowU = u.lowercased()
                if u.isEmpty || seenUrls.contains(lowU) || ignoredSubstrings.contains(where: { lowU.contains($0) }) {
                    continue
                }
                if lowU == "https://infuse.com/" || lowU == "https://zandahealth.com/" || lowU.contains("linkedin.com/company/") {
                    continue
                }
                seenUrls.insert(lowU)
                results.append((label: friendlyLabel(explicitLabel: String(rawBody[lblRange]), url: u), url: u))
            }
        }
        if let bareRegex = bareUrlExtractRegex {
            for match in bareRegex.matches(in: rawBody, range: nsRange) {
                guard let urlRange = Range(match.range(at: 0), in: rawBody) else { continue }
                let u = cleanUrl(String(rawBody[urlRange]))
                let lowU = u.lowercased()
                if u.isEmpty || seenUrls.contains(lowU) || ignoredSubstrings.contains(where: { lowU.contains($0) }) {
                    continue
                }
                if lowU == "https://infuse.com/" || lowU == "https://zandahealth.com/" || lowU.contains("linkedin.com/company/") {
                    continue
                }
                seenUrls.insert(lowU)
                results.append((label: friendlyLabel(explicitLabel: nil, url: u), url: u))
            }
        }

        linksCache.setObject(LinksBox(results), forKey: key)
        return results
    }

    public static func isFormSubmissionUrl(_ url: String, jevClassification: String) -> Bool {
        let low = url.lowercased()
        let nonFormPatterns = [
            "linkedin.com/in/", "linkedin.com/company/", "turboapply.agency",
            "calendly.com", "cal.com", "loom.com/share", "zoom.us",
            "meet.google.com", "teams.microsoft.com", "dribbble.com",
            "twitter.com", "x.com/", "instagram.com", "youtube.com",
            "communication_preferences", "zendesk.com/hc",
        ]
        if nonFormPatterns.contains(where: { low.contains($0) }) {
            return false
        }
        let explicitFormPatterns = [
            "coda.io/form", "docs.superhuman.com/form", "comeet.co/pub/questionnaires",
            "comeet.com/pub/questionnaires", "greenhouse.io/application_form",
            "boards.greenhouse.io", "job-boards.greenhouse.io", "jobs.ashbyhq.com",
            "jobs.lever.co", "hrpartner.io/jobs", "forms.gle", "docs.google.com/forms",
            "typeform.com", "tally.so", "airtable.com/shr", "airtable.com/app",
            "jotform.com", "workable.com", "myworkdayjobs.com", "bamboohr.com",
            "smartrecruiters.com", "breezy.hr", "recruitee.com", "pinpointhq.com",
            "teamtailor.com", "dover.com", "rippling.com", "jobs.micro1.ai",
            "/form/", "/forms/", "/questionnaire", "/application_form", "/apply",
        ]
        if explicitFormPatterns.contains(where: { low.contains($0) }) {
            return true
        }
        return jevClassification.contains("details_requested")
    }
}

private struct UncheckedImageBox: @unchecked Sendable {
    let image: NSImage?
}

@MainActor
public final class ThumbnailViewLoader: ObservableObject {
    @Published public var image: NSImage? = nil
    private var activeKey: String = ""

    public init() {}

    public func loadIfNeeded(
        lookupKey: String,
        localPath: String,
        remoteUrl: String,
        slugHint: String,
        pointSize: CGFloat
    ) {
        if let hit = FastThumbnailCache.shared.cachedImage(forKey: lookupKey) {
            activeKey = lookupKey
            if image !== hit {
                image = hit
            }
            return
        }
        guard activeKey != lookupKey else { return }
        activeKey = lookupKey
        if image != nil {
            image = nil
        }
        FastThumbnailCache.shared.loadThumbnail(
            localPath: localPath,
            remoteUrl: remoteUrl,
            cacheSlugHint: slugHint,
            pointSize: pointSize
        ) { [weak self] decoded in
            let box = UncheckedImageBox(image: decoded)
            Task { @MainActor [weak self] in
                guard let self = self, self.activeKey == lookupKey else { return }
                if let img = box.image {
                    self.image = img
                }
            }
        }
    }
}

public struct CachedAvatarImageView: View, Equatable {
    public let localPath: String
    public let remoteUrl: String
    public let slugHint: String
    public let size: CGFloat
    public let isCompanyLogo: Bool
    public let fallbackInitials: String
    public let accentFallback: Bool
    public let accentBorder: Bool

    @StateObject private var loader = ThumbnailViewLoader()

    nonisolated public static func == (lhs: CachedAvatarImageView, rhs: CachedAvatarImageView) -> Bool {
        lhs.localPath == rhs.localPath
            && lhs.remoteUrl == rhs.remoteUrl
            && lhs.size == rhs.size
            && lhs.isCompanyLogo == rhs.isCompanyLogo
            && lhs.fallbackInitials == rhs.fallbackInitials
            && lhs.accentFallback == rhs.accentFallback
            && lhs.accentBorder == rhs.accentBorder
    }

    private var lookupKey: String {
        let bucket = FastThumbnailCache.pixelBucket(forPointSize: size)
        return FastThumbnailCache.shared.cacheKey(localPath: localPath, remoteUrl: remoteUrl, pixelBucket: bucket)
    }

    public init(
        localPath: String,
        remoteUrl: String = "",
        slugHint: String = "",
        size: CGFloat,
        isCompanyLogo: Bool = false,
        fallbackInitials: String = "",
        accentFallback: Bool = false,
        accentBorder: Bool = false
    ) {
        self.localPath = localPath
        self.remoteUrl = remoteUrl
        self.slugHint = slugHint
        self.size = size
        self.isCompanyLogo = isCompanyLogo
        self.fallbackInitials = fallbackInitials
        self.accentFallback = accentFallback
        self.accentBorder = accentBorder
    }

    public var body: some View {
        let key = lookupKey
        let activeImage = loader.image ?? FastThumbnailCache.shared.cachedImage(forKey: key)

        Group {
            if let nsImg = activeImage {
                if isCompanyLogo {
                    ZStack {
                        RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                            .fill(Color.white.opacity(0.92))
                            .frame(width: size, height: size)
                        Image(nsImage: nsImg)
                            .resizable()
                            .interpolation(.high)
                            .scaledToFit()
                            .frame(width: size * 0.76, height: size * 0.76)
                            .clipShape(RoundedRectangle(cornerRadius: size * 0.18, style: .continuous))
                    }
                    .overlay(
                        RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                            .stroke(Color.secondary.opacity(0.22), lineWidth: 1)
                    )
                } else {
                    Image(nsImage: nsImg)
                        .resizable()
                        .interpolation(.high)
                        .scaledToFill()
                        .frame(width: size, height: size)
                        .clipShape(Circle())
                        .overlay(
                            Circle()
                                .stroke(accentBorder ? Color.accentColor : Color.secondary.opacity(0.22), lineWidth: accentBorder ? 2 : 1)
                        )
                }
            } else if isCompanyLogo {
                ZStack {
                    RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                        .fill(Color.accentColor.opacity(0.12))
                        .frame(width: size, height: size)
                    Text(fallbackInitials)
                        .font(.system(size: size * 0.36, weight: .bold))
                        .foregroundColor(.accentColor)
                }
                .overlay(
                    RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                        .stroke(Color.accentColor.opacity(0.22), lineWidth: 1)
                )
            } else if fallbackInitials.isEmpty {
                ZStack {
                    Circle()
                        .fill(
                            LinearGradient(
                                colors: [Color.accentColor, Color.teal],
                                startPoint: .topLeading,
                                endPoint: .bottomTrailing
                            )
                        )
                        .frame(width: size, height: size)
                    Image(systemName: "person.crop.circle.fill")
                        .font(.system(size: size * 0.56))
                        .foregroundColor(.white)
                }
            } else {
                ZStack {
                    Circle()
                        .fill(accentFallback ? Color.accentColor.opacity(0.16) : Color.secondary.opacity(0.15))
                        .frame(width: size, height: size)
                    Text(fallbackInitials)
                        .font(.system(size: size * (accentFallback ? 0.40 : 0.38), weight: .semibold))
                        .foregroundColor(accentFallback ? .accentColor : .primary.opacity(0.85))
                }
                .overlay(
                    Circle().stroke(Color.secondary.opacity(accentFallback ? 0.0 : 0.18), lineWidth: 1)
                )
            }
        }
        .frame(width: size, height: size)
        .onAppear {
            loader.loadIfNeeded(
                lookupKey: key,
                localPath: localPath,
                remoteUrl: remoteUrl,
                slugHint: slugHint,
                pointSize: size
            )
        }
        .onChange(of: key) { newKey in
            loader.loadIfNeeded(
                lookupKey: newKey,
                localPath: localPath,
                remoteUrl: remoteUrl,
                slugHint: slugHint,
                pointSize: size
            )
        }
    }
}

public struct OutreachChatMessageItem: Identifiable, Equatable {
    public let id: String
    public let senderRole: String // "me" | "them"
    public let senderName: String
    public let senderHandle: String
    public let subject: String
    public let body: String
    public let timestamp: String
    public let deliveryStatus: String
    public let scheduledFor: String
    public let queueEstimate: String
    public let attachments: [String]

    // Precomputed display fields (zero regex / string formatting during 60fps SwiftUI view rendering)
    public let isQueued: Bool
    public let isPending: Bool
    public let displayBody: String
    public let readableTimestamp: String
    public let compactSenderHandle: String

    public init(
        id: String,
        senderRole: String,
        senderName: String,
        senderHandle: String,
        subject: String,
        body: String,
        timestamp: String,
        deliveryStatus: String,
        scheduledFor: String = "",
        queueEstimate: String = "",
        attachments: [String] = []
    ) {
        self.id = id
        self.senderRole = senderRole
        self.senderName = senderName
        self.senderHandle = senderHandle
        self.subject = subject
        self.body = body
        self.timestamp = timestamp
        self.deliveryStatus = deliveryStatus
        self.scheduledFor = scheduledFor
        self.queueEstimate = queueEstimate
        self.attachments = attachments

        let lowStatus = deliveryStatus.lowercased()
        let queuedFlag = lowStatus.contains("queued")
        self.isQueued = queuedFlag
        self.isPending = !queuedFlag && ((lowStatus.contains("pending") && !lowStatus.contains("invite")) || lowStatus.contains("retry"))

        let stripped = MessageTextProcessor.stripQuotedEmailReply(body)
        self.displayBody = stripped.isEmpty ? body.trimmingCharacters(in: .whitespacesAndNewlines) : stripped
        self.readableTimestamp = MessageTextProcessor.formatReadableTimestamp(timestamp)
        self.compactSenderHandle = MessageTextProcessor.formatCompactHandle(senderHandle)
    }

    public static func == (lhs: OutreachChatMessageItem, rhs: OutreachChatMessageItem) -> Bool {
        lhs.id == rhs.id
            && lhs.deliveryStatus == rhs.deliveryStatus
            && lhs.body == rhs.body
            && lhs.subject == rhs.subject
            && lhs.queueEstimate == rhs.queueEstimate
            && lhs.timestamp == rhs.timestamp
    }
}

public struct OutreachThreadItem: Identifiable, Equatable {
    public let id: String
    public let company: String
    public let role: String
    public let contactName: String
    public let contactHandle: String
    public let channel: String // "email" | "linkedin" | "hh" | "imessage"
    public let channelLabel: String
    public let subject: String
    public let threadUrl: String
    public let profileUrl: String
    public let actionRequired: Bool
    public let unreadInbound: Bool
    public let jevClassification: String
    public let jevLabel: String
    public let jevSummary: String
    public let jevModel: String
    public let deliveryState: String // "action_required" | "replied" | "queued" | "sent" | "invite_pending" | "followup_due"
    public let statusBadge: String
    public let lastActivityAt: String
    public let draftText: String
    public let draftSubject: String
    public let isCompanyContact: Bool
    public let avatarUrl: String
    public let avatarPath: String
    public let avatarOriginalPath: String
    public let messages: [OutreachChatMessageItem]

    // Precomputed O(1) display & search fields
    public var isFollowUp: Bool
    public let actionRequiredDisplayLabel: String
    public let isMarkedReplied: Bool
    public let isResolvedMonitoring: Bool
    public let hasInboundReply: Bool
    public let isRepliedBadgeVisible: Bool
    public let isQueuedThread: Bool
    public let isPendingThread: Bool
    public let isSubmittedConfirmation: Bool
    public let isRejectedThread: Bool
    public let primaryRowTitle: String
    public let roleSubtitle: String
    public let previewSnippet: String
    public let compactLastActivity: String
    public let compactHandle: String
    public let showCompactHandle: Bool
    public let avatarInitials: String
    public let avatarSlugHint: String
    public let detectedFormLabel: String
    public let detectedFormUrl: String
    public let searchableTextLower: String

    public init(
        id: String,
        company: String,
        role: String,
        contactName: String,
        contactHandle: String,
        channel: String,
        channelLabel: String,
        subject: String,
        threadUrl: String,
        profileUrl: String,
        actionRequired: Bool,
        unreadInbound: Bool,
        jevClassification: String,
        jevLabel: String,
        jevSummary: String,
        jevModel: String,
        deliveryState: String,
        statusBadge: String,
        lastActivityAt: String,
        draftText: String,
        draftSubject: String,
        isCompanyContact: Bool,
        avatarUrl: String,
        avatarPath: String,
        avatarOriginalPath: String = "",
        messages: [OutreachChatMessageItem]
    ) {
        self.id = id
        self.company = company
        self.role = role
        self.contactName = contactName
        self.contactHandle = contactHandle
        self.channel = channel
        self.channelLabel = channelLabel
        self.subject = subject
        self.threadUrl = threadUrl
        self.profileUrl = profileUrl
        self.actionRequired = actionRequired
        self.unreadInbound = unreadInbound
        self.jevClassification = jevClassification
        self.jevLabel = jevLabel
        self.jevSummary = jevSummary
        self.jevModel = jevModel
        self.deliveryState = deliveryState
        self.statusBadge = statusBadge
        self.lastActivityAt = lastActivityAt
        self.draftText = draftText
        self.draftSubject = draftSubject
        self.isCompanyContact = isCompanyContact
        self.avatarUrl = avatarUrl
        self.avatarPath = avatarPath
        self.avatarOriginalPath = avatarOriginalPath
        self.messages = messages

        self.isFollowUp = !actionRequired && jevClassification.hasPrefix("followup_")

        let arLabel: String = {
            switch jevClassification {
            case "action_required_online_assessment":
                return "Online Assessment"
            case "action_required_real_interview", "action_required_interview":
                return "Real Interview"
            case "action_required_details_requested", "action_required_document", "action_required_screening":
                return "Details Requested"
            default:
                let lbl = jevLabel.trimmingCharacters(in: .whitespacesAndNewlines)
                if lbl == "Online Assessment" || lbl == "Real Interview" || lbl == "Details Requested" {
                    return lbl
                }
                return "Action Required"
            }
        }()
        self.actionRequiredDisplayLabel = arLabel

        var inbound = false
        var msgQueued = false
        var msgPending = false
        for m in messages {
            if m.senderRole == "them" { inbound = true }
            if m.isQueued { msgQueued = true }
            if m.isPending { msgPending = true }
        }
        let markedReplied = (jevClassification == "replied_waiting" || deliveryState == "replied")
        let resolvedMon = (jevClassification == "resolved_monitoring")
        self.isMarkedReplied = markedReplied
        self.isResolvedMonitoring = resolvedMon
        self.hasInboundReply = inbound || markedReplied
        let qFlag = (deliveryState == "queued") || msgQueued
        self.isQueuedThread = qFlag
        self.isPendingThread = !qFlag && ((deliveryState == "pending") || msgPending)
        self.isSubmittedConfirmation = (jevClassification == "submitted_confirmation")
        self.isRejectedThread = (jevClassification == "rejected" || jevClassification == "closed_declined")
        self.isRepliedBadgeVisible = !actionRequired
            && !self.isFollowUp
            && !self.isSubmittedConfirmation
            && !self.isRejectedThread
            && !self.isQueuedThread
            && !self.isPendingThread
            && !resolvedMon
            && self.hasInboundReply

        let cleanComp = company.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanContact = contactName.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanRole = role.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleanComp.isEmpty || cleanContact.localizedCaseInsensitiveContains(cleanComp) {
            self.primaryRowTitle = cleanContact
        } else {
            self.primaryRowTitle = "\(cleanComp) — \(cleanContact)"
        }
        self.roleSubtitle = cleanRole.isEmpty ? cleanComp : "\(cleanComp) · \(cleanRole)"

        let lastMsg = messages.last
        let previewSource = lastMsg?.displayBody ?? MessageTextProcessor.stripQuotedEmailReply(subject)
        self.previewSnippet = MessageTextProcessor.makeSingleLinePreviewSnippet(
            previewSource,
            senderRole: lastMsg?.senderRole ?? "them",
            maxChars: 180
        )
        self.compactLastActivity = MessageTextProcessor.formatCompactTimestamp(lastActivityAt)

        let cHandle = MessageTextProcessor.formatCompactHandle(contactHandle)
        self.compactHandle = cHandle
        self.showCompactHandle = !cHandle.isEmpty
            && cHandle.caseInsensitiveCompare(contactName) != .orderedSame
            && cHandle.caseInsensitiveCompare(company) != .orderedSame

        let initialsSrc = isCompanyContact ? (cleanComp.isEmpty ? cleanContact : cleanComp) : cleanContact
        let initParts = initialsSrc.split(separator: " ")
        if initParts.count >= 2 {
            self.avatarInitials = "\(initParts[0].prefix(1))\(initParts[1].prefix(1))".uppercased()
        } else {
            self.avatarInitials = String(initialsSrc.prefix(2)).uppercased()
        }
        self.avatarSlugHint = isCompanyContact ? "company_\(cleanComp)" : "person_\(cleanContact)_\(cleanComp)"

        var foundFormLabel = ""
        var foundFormUrl = ""
        if actionRequired || jevClassification.contains("details_requested") || jevSummary.contains("http") {
            outerLoop: for m in messages.reversed() where m.senderRole.lowercased() != "you" && m.senderRole.lowercased() != "me" {
                for link in MessageTextProcessor.extractActionableMessageLinks(m.displayBody, cacheId: m.id) {
                    if MessageTextProcessor.isFormSubmissionUrl(link.url, jevClassification: jevClassification) {
                        foundFormLabel = link.label
                        foundFormUrl = link.url
                        break outerLoop
                    }
                }
            }
            if foundFormUrl.isEmpty && !jevSummary.isEmpty {
                for link in MessageTextProcessor.extractActionableMessageLinks(jevSummary) {
                    if MessageTextProcessor.isFormSubmissionUrl(link.url, jevClassification: jevClassification) {
                        foundFormLabel = link.label
                        foundFormUrl = link.url
                        break
                    }
                }
            }
        } else {
            // Quick check only if any inbound message contains a form/http link
            outerFast: for m in messages.reversed() where m.senderRole == "them" && (m.displayBody.contains("http://") || m.displayBody.contains("https://")) {
                for link in MessageTextProcessor.extractActionableMessageLinks(m.displayBody, cacheId: m.id) {
                    if MessageTextProcessor.isFormSubmissionUrl(link.url, jevClassification: jevClassification) {
                        foundFormLabel = link.label
                        foundFormUrl = link.url
                        break outerFast
                    }
                }
            }
        }
        self.detectedFormLabel = foundFormLabel
        self.detectedFormUrl = foundFormUrl

        let msgSearchSample = messages.suffix(4).map { "\($0.senderName) \($0.displayBody.prefix(400))" }.joined(separator: " ")
        self.searchableTextLower = "\(company) \(contactName) \(role) \(contactHandle) \(subject) \(jevLabel) \(msgSearchSample)".lowercased()
    }

    public var detectedFormLink: (label: String, url: String)? {
        guard !detectedFormUrl.isEmpty else { return nil }
        return (label: detectedFormLabel, url: detectedFormUrl)
    }

    public var actionRequiredIconName: String {
        switch actionRequiredDisplayLabel {
        case "Online Assessment":
            return "checklist"
        case "Real Interview":
            return "video.fill"
        case "Details Requested":
            return "doc.text.fill"
        default:
            return "exclamationmark.circle.fill"
        }
    }

    public func withManualStatus(_ status: String) -> OutreachThreadItem {
        let norm = status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let nextActionReq: Bool
        let nextUnreadInbound: Bool
        let nextJevCls: String
        let nextJevLbl: String
        let nextJevSummary: String
        let nextDeliveryState: String
        let nextStatusBadge: String

        let preserveQueueDelivery: (String) -> String = { desired in
            if self.isQueuedThread { return "queued" }
            if self.isPendingThread { return "pending" }
            return desired
        }

        switch norm {
        case "online_assessment", "action_required_online_assessment", "assessment":
            nextActionReq = true
            nextUnreadInbound = messages.last?.senderRole == "them"
            nextJevCls = "action_required_online_assessment"
            nextJevLbl = "Online Assessment"
            nextJevSummary = "\(contactName) (\(company)) classified as Online Assessment."
            nextDeliveryState = preserveQueueDelivery("action_required")
            nextStatusBadge = "Online Assessment"
        case "real_interview", "action_required_real_interview", "interview":
            nextActionReq = true
            nextUnreadInbound = messages.last?.senderRole == "them"
            nextJevCls = "action_required_real_interview"
            nextJevLbl = "Real Interview"
            nextJevSummary = "\(contactName) (\(company)) classified as Real Interview."
            nextDeliveryState = preserveQueueDelivery("action_required")
            nextStatusBadge = "Real Interview"
        case "details_requested", "action_required_details_requested", "details":
            nextActionReq = true
            nextUnreadInbound = messages.last?.senderRole == "them"
            nextJevCls = "action_required_details_requested"
            nextJevLbl = "Details Requested"
            nextJevSummary = "\(contactName) (\(company)) classified as Details Requested."
            nextDeliveryState = preserveQueueDelivery("action_required")
            nextStatusBadge = "Details Requested"
        case "submitted", "submitted_confirmation":
            nextActionReq = false
            nextUnreadInbound = false
            nextJevCls = "submitted_confirmation"
            nextJevLbl = "Submitted"
            nextJevSummary = "Application submitted confirmation from \(company)."
            nextDeliveryState = preserveQueueDelivery("sent")
            nextStatusBadge = "Submitted"
        case "rejected", "closed_declined":
            nextActionReq = false
            nextUnreadInbound = false
            nextJevCls = "rejected"
            nextJevLbl = "Rejected"
            nextJevSummary = "Rejected by \(company)."
            nextDeliveryState = preserveQueueDelivery("sent")
            nextStatusBadge = "Rejected"
        case "replied":
            nextActionReq = false
            nextUnreadInbound = false
            nextJevCls = "replied_waiting"
            nextJevLbl = "Replied"
            nextJevSummary = "You provided details / replied to \(contactName) (\(company)) and are waiting for them to get back to you."
            nextDeliveryState = preserveQueueDelivery("replied")
            nextStatusBadge = "Replied"
        case "followup", "follow_up", "follow-up":
            nextActionReq = false
            nextUnreadInbound = false
            nextJevCls = "followup_manual"
            nextJevLbl = "Follow-Up"
            nextJevSummary = "Waiting on \(contactName) (\(company)) to get back to you — flagged for follow-up."
            nextDeliveryState = preserveQueueDelivery("followup_due")
            nextStatusBadge = "Follow-Up"
        case "action_required":
            nextActionReq = true
            nextUnreadInbound = messages.last?.senderRole == "them"
            nextJevCls = "action_required"
            nextJevLbl = "Action Required"
            nextJevSummary = "Inbound message from \(contactName) (\(company)) awaiting your action or reply."
            nextDeliveryState = preserveQueueDelivery("action_required")
            nextStatusBadge = "Action Required"
        default: // "resolved"
            nextActionReq = false
            nextUnreadInbound = false
            nextJevCls = "resolved_monitoring"
            nextJevLbl = "Resolved"
            nextJevSummary = "Marked resolved for \(contactName) (\(company))."
            nextDeliveryState = preserveQueueDelivery("sent")
            nextStatusBadge = "Resolved"
        }

        return OutreachThreadItem(
            id: id,
            company: company,
            role: role,
            contactName: contactName,
            contactHandle: contactHandle,
            channel: channel,
            channelLabel: channelLabel,
            subject: subject,
            threadUrl: threadUrl,
            profileUrl: profileUrl,
            actionRequired: nextActionReq,
            unreadInbound: nextUnreadInbound,
            jevClassification: nextJevCls,
            jevLabel: nextJevLbl,
            jevSummary: nextJevSummary,
            jevModel: jevModel,
            deliveryState: nextDeliveryState,
            statusBadge: nextStatusBadge,
            lastActivityAt: lastActivityAt,
            draftText: draftText,
            draftSubject: draftSubject,
            isCompanyContact: isCompanyContact,
            avatarUrl: avatarUrl,
            avatarPath: avatarPath,
            avatarOriginalPath: avatarOriginalPath,
            messages: messages
        )
    }

    public static func == (lhs: OutreachThreadItem, rhs: OutreachThreadItem) -> Bool {
        lhs.id == rhs.id
            && lhs.actionRequired == rhs.actionRequired
            && lhs.jevClassification == rhs.jevClassification
            && lhs.deliveryState == rhs.deliveryState
            && lhs.lastActivityAt == rhs.lastActivityAt
            && lhs.avatarPath == rhs.avatarPath
            && lhs.draftText == rhs.draftText
            && lhs.messages == rhs.messages
    }
}

