    public static func normalizeLogicModelId(_ modelId: String) -> String {
        let trimmed = modelId.trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = trimmed.lowercased()
        if lower == "openai/codex-commercial-session" || lower == "codex" || lower == "chatgpt" || lower == "openai-codex" {
            return "openai-codex/gpt-6.1-sol"
        }
        if let codexMatch = codexCatalog.first(where: {
            $0.id.lowercased() == lower || $0.id.components(separatedBy: "/").last?.lowercased() == lower
        }) {
            return codexMatch.id
        }
        return trimmed
    }

    public static func shortLogicTitle(for modelId: String) -> String {
        let normalized = normalizeLogicModelId(modelId)
        if let match = logicCatalog.first(where: { $0.id == normalized }) {
            return match.shortLabel
        }
        if let match = writerCatalog.first(where: { $0.id == normalized }) {
            return match.shortLabel
        }
        if normalized.lowercased().hasPrefix("openai-codex/") {
            let slug = normalized.components(separatedBy: "/").last ?? normalized
            return "\(slug.uppercased().replacingOccurrences(of: "GPT-", with: "GPT-")) · OpenAI Codex"
        }
        let cleaned = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.isEmpty { return "DeepSeek Flash Latest" }
        return cleaned.components(separatedBy: "/").last ?? cleaned
    }

    public static func shortWriterTitle(for modelId: String) -> String {
        if let match = writerCatalog.first(where: { $0.id == modelId }) {
            return match.shortLabel
        }
        if let match = logicCatalog.first(where: { $0.id == modelId }) {
            return match.shortLabel
        }
        let cleaned = modelId.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.isEmpty { return "Claude Sonnet Latest" }
        return cleaned.components(separatedBy: "/").last ?? cleaned
    }
}

// MARK: - Live Microphone & Natural Neural Voice Interview Controller

@MainActor
public final class VoiceRecorderController: NSObject, ObservableObject {
    @Published public var isRecording: Bool = false
    @Published public var isChatRecording: Bool = false
    @Published public var isSpeakingQuestion: Bool = false
    @Published public var isTranscribing: Bool = false
    @Published public var isLiveChunkTranscribing: Bool = false
    @Published public var backgroundProcessingCount: Int = 0
    @Published public var statusText: String = "Ready — click 'Start Conversation' to hear the question aloud and speak your answer."
    @Published public var audioLevel: Double = 0.0
    @Published public var recordingSeconds: Int = 0
    @Published public var waveformBars: [Double] = Array(repeating: 0.14, count: 24)
    @Published public var isConversationSessionActive: Bool = false
    @Published public var userExplicitlyStoppedSession: Bool = false
    public var appSupportDirForAudioCache: URL? = nil
    public var lastAudioFilePath: String = ""
    public var preRecordingDraftText: String = ""
    public var lastLiveTranscriptText: String = ""
    public var lastAppliedCombinedDraftText: String = ""

    public var isConversationActive: Bool {
        isSpeakingQuestion || isRecording
    }

    private var audioRecorder: AVAudioRecorder?
    private var audioPlayer: AVAudioPlayer?
    private var levelTimer: Timer?
    private var speechPollTimer: Timer?
    private var onSpeechFinishedCallback: (() -> Void)?
    private let speechSynthesizer = AVSpeechSynthesizer()
    private var tickCount: Int = 0
    private var isChunkRequestInFlight: Bool = false
    private var hasDetectedSpeechSinceLastChunk: Bool = false
    private var everDetectedSpeechInSession: Bool = false

    public func syncPreTypedDraft(_ text: String) {
        preRecordingDraftText = text
        lastAppliedCombinedDraftText = text
        lastLiveTranscriptText = ""
    }

    public func pauseMicrophoneForAssistantSpeech() {
        levelTimer?.invalidate()
        levelTimer = nil
        if let rec = audioRecorder, rec.isRecording {
            rec.stop()
        }
        audioRecorder = nil
        isRecording = false
        isLiveChunkTranscribing = false
        isChunkRequestInFlight = false
        audioLevel = 0.0
        waveformBars = Array(repeating: 0.14, count: 24)
    }

    public func speakAssistantCue(audioId: String, fallbackText: String, repoRootDir: URL?, onFinished: (() -> Void)? = nil) {
        pauseMicrophoneForAssistantSpeech()
        startNaturalQuestionPlayback(questionId: audioId, prompt: fallbackText, repoRootDir: repoRootDir) {
            onFinished?()
        }
    }

    public func speakAssistantCueAfterCurrentFinishes(audioId: String, fallbackText: String, repoRootDir: URL?, onFinished: (() -> Void)? = nil) {
        let isCurrentlySpeaking = (audioPlayer?.isPlaying == true) || speechSynthesizer.isSpeaking
        if isSpeakingQuestion && isCurrentlySpeaking {
            onSpeechFinishedCallback = { [weak self] in
                guard let self = self else { return }
                self.startNaturalQuestionPlayback(questionId: audioId, prompt: fallbackText, repoRootDir: repoRootDir) {
                    onFinished?()
                }
            }
        } else {
            speakAssistantCue(audioId: audioId, fallbackText: fallbackText, repoRootDir: repoRootDir, onFinished: onFinished)
        }
    }

    private func resolveNaturalQuestionAudioURL(questionId: String, repoRootDir: URL?) -> URL? {
        guard !questionId.isEmpty else { return nil }
        var candidates: [URL] = []
        if let res = Bundle.main.resourceURL {
            candidates.append(res.appendingPathComponent("packaging/interview_audio/\(questionId).mp3"))
            candidates.append(res.appendingPathComponent("interview_audio/\(questionId).mp3"))
        }
        if let root = repoRootDir {
            candidates.append(root.appendingPathComponent("packaging/interview_audio/\(questionId).mp3"))
            candidates.append(root.appendingPathComponent("interview_audio/\(questionId).mp3"))
        }
        if let appSup = appSupportDirForAudioCache {
            candidates.append(appSup.appendingPathComponent("interview_audio/\(questionId).mp3"))
        }
        let defaultAppSup = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/AutoApply/interview_audio/\(questionId).mp3")
        candidates.append(defaultAppSup)
        let cwd = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        candidates.append(cwd.appendingPathComponent("packaging/interview_audio/\(questionId).mp3"))

        for url in candidates {
            if FileManager.default.fileExists(atPath: url.path) {
                return url
            }
        }
        return nil
    }

    private func bestEnglishVoice() -> AVSpeechSynthesisVoice? {
        let voices = AVSpeechSynthesisVoice.speechVoices().filter { $0.language.hasPrefix("en") }
        let preferredFemaleNames = ["ava", "samantha", "allison", "zoe", "susan", "karen", "moira", "tessa", "victoria", "sandy", "shelley", "flo"]
        let femaleVoices = voices.filter { v in
            if #available(macOS 10.15, *) {
                if v.gender == .female {
                    return true
                }
                if v.gender == .male {
                    return false
                }
            }
            let lowerName = v.name.lowercased()
            return preferredFemaleNames.contains(where: { lowerName.contains($0) })
        }
        if let avaVoice = femaleVoices.first(where: { $0.name.lowercased().contains("ava") }) {
            return avaVoice
        }
        if let bestFemaleUS = femaleVoices.filter({ $0.language == "en-US" }).max(by: { $0.quality.rawValue < $1.quality.rawValue }) {
            return bestFemaleUS
        }
        if let bestFemaleAny = femaleVoices.max(by: { $0.quality.rawValue < $1.quality.rawValue }) {
            return bestFemaleAny
        }
        if let samantha = AVSpeechSynthesisVoice(identifier: "com.apple.voice.compact.en-US.Samantha") {
            return samantha
        }
        return AVSpeechSynthesisVoice(language: "en-US")
    }

    private func beginSpeechPollTimer() {
        speechPollTimer?.invalidate()
        speechPollTimer = Timer.scheduledTimer(withTimeInterval: 0.10, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                let stillPlaying = (self.audioPlayer?.isPlaying == true) || self.speechSynthesizer.isSpeaking
                if stillPlaying {
                    self.tickCount += 1
                    var meterBoost: Double = 0.65
                    if let player = self.audioPlayer, player.isPlaying {
                        player.updateMeters()
                        let power = player.averagePower(forChannel: 0)
                        meterBoost = max(0.25, min(1.0, Double((power + 48.0) / 44.0)))
                    }
                    self.waveformBars = (0..<24).map { idx in
                        let wave = abs(sin(Double(self.tickCount) * 0.38 + Double(idx) * 0.45))
                        return max(0.16, min(0.92, 0.18 + wave * meterBoost * 0.72))
                    }
                } else {
                    self.speechPollTimer?.invalidate()
                    self.speechPollTimer = nil
                    self.audioPlayer = nil
                    self.isSpeakingQuestion = false
                    self.waveformBars = Array(repeating: 0.14, count: 24)
                    let cb = self.onSpeechFinishedCallback
                    self.onSpeechFinishedCallback = nil
                    cb?()
                }
            }
        }
    }

    private func speakWithFemaleSynthesizerFallback(_ prompt: String) {
        let utterance = AVSpeechUtterance(string: prompt)
        utterance.voice = bestEnglishVoice()
        utterance.rate = 0.50
        utterance.pitchMultiplier = 1.02
        speechSynthesizer.speak(utterance)
        beginSpeechPollTimer()
    }

    private func startNaturalQuestionPlayback(questionId: String, prompt: String, repoRootDir: URL?, onFinished: @escaping () -> Void) {
        stopSpeaking()
        isSpeakingQuestion = true
        onSpeechFinishedCallback = onFinished

        if let audioURL = resolveNaturalQuestionAudioURL(questionId: questionId, repoRootDir: repoRootDir),
           let player = try? AVAudioPlayer(contentsOf: audioURL) {
            player.isMeteringEnabled = true
            player.prepareToPlay()
            player.play()
            self.audioPlayer = player
            beginSpeechPollTimer()
            return
        }

        let trimmedPrompt = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedPrompt.isEmpty, let companionURL = URL(string: "http://127.0.0.1:19299") else {
            speakWithFemaleSynthesizerFallback(prompt)
            return
        }

        var req = URLRequest(url: companionURL)
        req.httpMethod = "POST"
        req.timeoutInterval = 10.0
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let bodyObj: [String: Any] = [
            "action": "synthesize_interview_tts",
            "payload": [
                "question_id": questionId.isEmpty ? "dyn_cue" : questionId,
                "text": trimmedPrompt,
            ],
        ]
        req.httpBody = try? JSONSerialization.data(withJSONObject: bodyObj, options: [])
        URLSession.shared.dataTask(with: req) { [weak self] data, _, error in
            var synthesizedPath: String? = nil
            if error == nil,
               let data = data,
               let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
               let path = json["audio_path"] as? String,
               !path.isEmpty {
                synthesizedPath = path
            }
            Task { @MainActor in
                guard let self = self, self.isSpeakingQuestion else { return }
                if let validPath = synthesizedPath,
                   FileManager.default.fileExists(atPath: validPath),
                   let player = try? AVAudioPlayer(contentsOf: URL(fileURLWithPath: validPath)) {
                    player.isMeteringEnabled = true
                    player.prepareToPlay()
                    player.play()
                    self.audioPlayer = player
                    self.beginSpeechPollTimer()
                } else {
                    self.synthesizeNaturalQuestionFallback(questionId: questionId, prompt: trimmedPrompt, repoRootDir: repoRootDir)
                }
            }
        }.resume()
    }

    private func synthesizeNaturalQuestionFallback(questionId: String, prompt: String, repoRootDir: URL?) {
        let rootDir = repoRootDir ?? URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        let appSupDir = appSupportDirForAudioCache
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support/AutoApply")
        let payloadDict: [String: String] = [
            "question_id": questionId.isEmpty ? "dyn_cue" : questionId,
            "text": prompt,
        ]
        let payloadData = (try? JSONSerialization.data(withJSONObject: payloadDict, options: [])) ?? Data("{}".utf8)
        let payloadStr = String(data: payloadData, encoding: .utf8) ?? "{}"

        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let proc = Process()
            let bundledPython = rootDir.appendingPathComponent("python-env/bin/python3").path
            if FileManager.default.isExecutableFile(atPath: bundledPython) {
                proc.executableURL = URL(fileURLWithPath: bundledPython)
                proc.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", appSupDir.path, "--action", "synthesize_interview_tts", "--payload", payloadStr]
            } else {
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/env")
                proc.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", appSupDir.path, "--action", "synthesize_interview_tts", "--payload", payloadStr]
            }
            proc.currentDirectoryURL = rootDir
            var env = ProcessInfo.processInfo.environment
            let runtimeParent = rootDir.appendingPathComponent("runtime").path
            let existingPythonPath = env["PYTHONPATH"] ?? ""
            env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
            proc.environment = env
            let outPipe = Pipe()
            proc.standardOutput = outPipe
            proc.standardError = FileHandle.nullDevice
            var validAudioPath: String? = nil
            if (try? proc.run()) != nil {
                let data = outPipe.fileHandleForReading.readDataToEndOfFile()
                proc.waitUntilExit()
                if let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
                   let p = json["audio_path"] as? String, !p.isEmpty {
                    validAudioPath = p
                }
            }
            Task { @MainActor in
                guard let self = self, self.isSpeakingQuestion else { return }
                if let path = validAudioPath,
                   FileManager.default.fileExists(atPath: path),
                   let player = try? AVAudioPlayer(contentsOf: URL(fileURLWithPath: path)) {
                    player.isMeteringEnabled = true
                    player.prepareToPlay()
                    player.play()
                    self.audioPlayer = player
                    self.beginSpeechPollTimer()
                } else if let cachedURL = self.resolveNaturalQuestionAudioURL(questionId: questionId, repoRootDir: rootDir),
                          let player = try? AVAudioPlayer(contentsOf: cachedURL) {
                    player.isMeteringEnabled = true
                    player.prepareToPlay()
                    player.play()
                    self.audioPlayer = player
                    self.beginSpeechPollTimer()
                } else {
                    self.speakWithFemaleSynthesizerFallback(prompt)
                }
            }
        }
    }

    public func stopSpeaking() {
        speechPollTimer?.invalidate()
        speechPollTimer = nil
        onSpeechFinishedCallback = nil
        if let player = audioPlayer, player.isPlaying {
            player.stop()
        }
        audioPlayer = nil
        if speechSynthesizer.isSpeaking {
            speechSynthesizer.stopSpeaking(at: .immediate)
        }
        isSpeakingQuestion = false
    }

    private func proceedWithInterviewTurn(questionId: String, questionPrompt: String, speakFirst: Bool, repoRootDir: URL?, store: WorkspaceStore?) {
        if speakFirst && !questionPrompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            statusText = "Reading question aloud… (Listening starts automatically right after)"
            startNaturalQuestionPlayback(questionId: questionId, prompt: questionPrompt, repoRootDir: repoRootDir) { [weak self, weak store] in
                guard let self = self else { return }
                guard self.isConversationSessionActive && !self.userExplicitlyStoppedSession else { return }
                self.beginMicrophoneCapture(store: store)
            }
        } else {
            beginMicrophoneCapture(store: store)
        }
    }

    public func startInterviewTurn(questionId: String = "", questionPrompt: String, speakFirst: Bool = true, repoRootDir: URL? = nil, store: WorkspaceStore? = nil) {
        if isRecording {
            return
        }
        appSupportDirForAudioCache = store?.appSupportDir ?? appSupportDirForAudioCache
        userExplicitlyStoppedSession = false
        isConversationSessionActive = true
        stopSpeaking()
        let authStatus = AVCaptureDevice.authorizationStatus(for: .audio)
        switch authStatus {
        case .authorized:
            proceedWithInterviewTurn(questionId: questionId, questionPrompt: questionPrompt, speakFirst: speakFirst, repoRootDir: repoRootDir, store: store)
        case .notDetermined:
            statusText = "Please click 'Allow' on the Microphone permission prompt to start…"
            AVCaptureDevice.requestAccess(for: .audio) { [weak self, weak store] granted in
                Task { @MainActor in
                    guard let self = self else { return }
                    if granted {
                        self.proceedWithInterviewTurn(questionId: questionId, questionPrompt: questionPrompt, speakFirst: speakFirst, repoRootDir: repoRootDir, store: store)
                    } else {
                        self.statusText = "Microphone permission needed in System Settings — or type your answer below."
                    }
                }
            }
        case .denied, .restricted:
            statusText = "Microphone permission is turned off in System Settings → Privacy & Security → Microphone."
        @unknown default:
            proceedWithInterviewTurn(questionId: questionId, questionPrompt: questionPrompt, speakFirst: speakFirst, repoRootDir: repoRootDir, store: store)
        }
    }

    public func skipSpeechAndRecordNow(store: WorkspaceStore? = nil) {
        stopSpeaking()
        beginMicrophoneCapture(store: store)
    }

    public func toggleChatMicrophoneRecording(store: WorkspaceStore) {
        if isRecording {
            let finalPath = lastAudioFilePath
            stopRecording()
            isChatRecording = false
            if !finalPath.isEmpty && FileManager.default.fileExists(atPath: finalPath) {
                isTranscribing = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) { [weak self, weak store] in
                    guard let self = self, let store = store else { return }
                    self.transcribeFinalChatAudio(audioPath: finalPath, store: store)
                }
            }
            return
        }
        stopSpeaking()
        let authStatus = AVCaptureDevice.authorizationStatus(for: .audio)
        switch authStatus {
        case .authorized:
            beginMicrophoneCapture(store: store, forChatComposer: true)
        case .notDetermined:
            AVCaptureDevice.requestAccess(for: .audio) { [weak self, weak store] granted in
                Task { @MainActor in
                    guard let self = self, let store = store, granted else { return }
                    self.beginMicrophoneCapture(store: store, forChatComposer: true)
                }
            }
        default:
            store.statusBannerMessage = "Microphone permission is required in System Settings → Privacy & Security → Microphone."
        }
    }

    private func transcribeFinalChatAudio(audioPath: String, store: WorkspaceStore) {
        guard let url = URL(string: "http://127.0.0.1:19299") else {
            transcribeFinalChatAudioFallback(audioPath: audioPath, store: store)
            return
        }
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.timeoutInterval = 12.0
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let bodyObj: [String: Any] = [
            "action": "transcribe_voice_live",
            "payload": ["audio_path": audioPath],
        ]
        req.httpBody = try? JSONSerialization.data(withJSONObject: bodyObj, options: [])
        URLSession.shared.dataTask(with: req) { [weak self, weak store] data, _, error in
            var trimmed = ""
            if error == nil,
               let data = data,
               let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
               let text = json["transcript"] as? String {
                trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            }
            if !trimmed.isEmpty {
                Task { @MainActor in
                    guard let self = self, let store = store else { return }
                    self.isTranscribing = false
                    let prefix = self.preRecordingDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
                    store.hermesPromptInput = prefix.isEmpty ? trimmed : (prefix + " " + trimmed)
                }
            } else {
                Task { @MainActor in
                    guard let self = self, let store = store else { return }
                    self.transcribeFinalChatAudioFallback(audioPath: audioPath, store: store)
                }
            }
        }.resume()
    }

    private func transcribeFinalChatAudioFallback(audioPath: String, store: WorkspaceStore) {
        let repoRoot = store.repoRootDir
        let appSupport = store.appSupportDir
        DispatchQueue.global(qos: .userInitiated).async { [weak self, weak store] in
            let proc = Process()
            let bundledPython = repoRoot.appendingPathComponent("python-env/bin/python3").path
            let payloadStr = "{\"audio_path\":\"\(audioPath)\"}"
            if FileManager.default.isExecutableFile(atPath: bundledPython) {
                proc.executableURL = URL(fileURLWithPath: bundledPython)
                proc.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", "transcribe_voice_live", "--payload", payloadStr]
            } else {
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/env")
                proc.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", "transcribe_voice_live", "--payload", payloadStr]
            }
            proc.currentDirectoryURL = repoRoot
            var env = ProcessInfo.processInfo.environment
            let runtimeParent = repoRoot.appendingPathComponent("runtime").path
            let existingPythonPath = env["PYTHONPATH"] ?? ""
            env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
            proc.environment = env
            let outPipe = Pipe()
            proc.standardOutput = outPipe
            proc.standardError = FileHandle.nullDevice
            var transcript = ""
            if (try? proc.run()) != nil {
                let data = outPipe.fileHandleForReading.readDataToEndOfFile()
                proc.waitUntilExit()
                if let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
                   let text = json["transcript"] as? String {
                    transcript = text.trimmingCharacters(in: .whitespacesAndNewlines)
                }
            }
            Task { @MainActor in
                guard let self = self, let store = store else { return }
                self.isTranscribing = false
                if !transcript.isEmpty {
                    let prefix = self.preRecordingDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
                    store.hermesPromptInput = prefix.isEmpty ? transcript : (prefix + " " + transcript)
                }
            }
        }
    }

    public func beginMicrophoneCapture(store: WorkspaceStore? = nil, forChatComposer: Bool = false, preserveDuration: Bool = false) {
        stopSpeaking()
        self.isChatRecording = forChatComposer
        if !forChatComposer {
            self.userExplicitlyStoppedSession = false
            self.isConversationSessionActive = true
        }
        preRecordingDraftText = forChatComposer ? (store?.hermesPromptInput ?? "") : (store?.interviewDraftText ?? "")
        lastAppliedCombinedDraftText = preRecordingDraftText
        lastLiveTranscriptText = ""
        hasDetectedSpeechSinceLastChunk = false
        everDetectedSpeechInSession = false
        let tempDir = FileManager.default.temporaryDirectory
        let fileURL = tempDir.appendingPathComponent("autoapply_voice_\(UUID().uuidString.prefix(8)).wav")
        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatLinearPCM),
            AVSampleRateKey: 16000.0,
            AVNumberOfChannelsKey: 1,
            AVLinearPCMBitDepthKey: 16,
            AVLinearPCMIsFloatKey: false,
            AVLinearPCMIsBigEndianKey: false,
        ]

        do {
            let recorder = try AVAudioRecorder(url: fileURL, settings: settings)
            recorder.isMeteringEnabled = true
            if recorder.record() {
                self.audioRecorder = recorder
                self.lastAudioFilePath = fileURL.path
                self.isRecording = true
                if !preserveDuration {
                    self.recordingSeconds = 0
                }
                self.tickCount = 0
                self.isChunkRequestInFlight = false
                self.statusText = "Listening & transcribing live… Speak naturally."
                self.levelTimer = Timer.scheduledTimer(withTimeInterval: 0.10, repeats: true) { [weak self, weak store] _ in
                    Task { @MainActor in
                        guard let self = self, let rec = self.audioRecorder, rec.isRecording else { return }
                        rec.updateMeters()
                        self.tickCount += 1
                        if self.tickCount % 10 == 0 {
                            self.recordingSeconds += 1
                        }
                        let power = rec.averagePower(forChannel: 0)
                        let peak = rec.peakPower(forChannel: 0)
                        if power > -50.0 || peak > -36.0 {
                            self.hasDetectedSpeechSinceLastChunk = true
                            self.everDetectedSpeechInSession = true
                        }
                        let normalized = max(0.10, min(1.0, Double((power + 58.0) / 38.0)))
                        self.audioLevel = normalized
                        self.waveformBars = (0..<24).map { idx in
                            let phase = abs(sin(Double(self.tickCount) * 0.42 + Double(idx) * 0.55))
                            return max(0.12, min(1.0, normalized * (0.38 + phase * 0.62)))
                        }
                        let softSpeechPeriodicProbe = (self.tickCount >= 15 && self.tickCount % 15 == 0 && (power > -55.0 || peak > -42.0))
                        let activeSpeechChunkDue = (self.tickCount >= 6 && self.tickCount % 6 == 0 && self.hasDetectedSpeechSinceLastChunk)
                        if !self.isChunkRequestInFlight && (activeSpeechChunkDue || softSpeechPeriodicProbe) {
                            if let store = store {
                                if softSpeechPeriodicProbe {
                                    self.everDetectedSpeechInSession = true
                                }
                                self.hasDetectedSpeechSinceLastChunk = false
                                self.transcribeLiveChunk(audioPath: fileURL.path, store: store)
                            }
                        }
                    }
                }
            } else {
                self.isChatRecording = false
                self.statusText = "Microphone unavailable — type your answer directly below."
            }
        } catch {
            self.isChatRecording = false
            self.statusText = "Microphone permission needed in System Settings — or type your answer below."
        }
    }

    private func applyLiveTranscript(_ liveTranscript: String, to store: WorkspaceStore) {
        let trimmed = liveTranscript.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        if !isChatRecording {
            if !lastAppliedCombinedDraftText.isEmpty && store.interviewDraftText != lastAppliedCombinedDraftText {
                // User edited or typed while microphone was active: preserve their edits in preRecordingDraftText.
                if !lastLiveTranscriptText.isEmpty,
                   let range = store.interviewDraftText.range(of: lastLiveTranscriptText, options: .backwards) {
                    preRecordingDraftText = String(store.interviewDraftText[..<range.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
                } else {
                    preRecordingDraftText = store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
                }
            }
        }
        let prefix = preRecordingDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
        if isChatRecording {
            if prefix.isEmpty {
                store.hermesPromptInput = trimmed
            } else {
                store.hermesPromptInput = prefix + " " + trimmed
            }
        } else {
            lastLiveTranscriptText = trimmed
            let separator = preRecordingDraftText.hasSuffix("\n\n") ? "\n\n" : "\n"
            let combined = prefix.isEmpty ? trimmed : (prefix + separator + trimmed)
            lastAppliedCombinedDraftText = combined
            store.interviewDraftText = combined
        }
    }

    private func transcribeLiveChunk(audioPath: String, store: WorkspaceStore) {
        guard isRecording, !isChunkRequestInFlight, FileManager.default.fileExists(atPath: audioPath) else { return }
        isChunkRequestInFlight = true
        isLiveChunkTranscribing = true

        guard let url = URL(string: "http://127.0.0.1:19299") else {
            isChunkRequestInFlight = false
            isLiveChunkTranscribing = false
            return
        }
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.timeoutInterval = 8.0
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let bodyObj: [String: Any] = [
            "action": "transcribe_voice_live",
            "payload": ["audio_path": audioPath],
        ]
        req.httpBody = try? JSONSerialization.data(withJSONObject: bodyObj, options: [])

        URLSession.shared.dataTask(with: req) { [weak self, weak store] data, response, error in
            var liveTranscript: String? = nil
            if error == nil,
               let data = data,
               let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
               let text = json["transcript"] as? String {
                liveTranscript = text.trimmingCharacters(in: .whitespacesAndNewlines)
            }
            Task { @MainActor in
                guard let self = self else { return }
                if let store = store, let validText = liveTranscript {
                    self.isChunkRequestInFlight = false
                    self.isLiveChunkTranscribing = false
                    if self.isRecording && !validText.isEmpty {
                        self.applyLiveTranscript(validText, to: store)
                    }
                } else if let store = store, self.isRecording {
                    self.transcribeLiveChunkFallback(audioPath: audioPath, store: store)
                } else {
                    self.isChunkRequestInFlight = false
                    self.isLiveChunkTranscribing = false
                }
            }
        }.resume()
    }

    private func transcribeLiveChunkFallback(audioPath: String, store: WorkspaceStore) {
        let repoRoot = store.repoRootDir
        let appSupport = store.appSupportDir
        DispatchQueue.global(qos: .userInitiated).async { [weak self, weak store] in
            let proc = Process()
            let bundledPython = repoRoot.appendingPathComponent("python-env/bin/python3").path
            let payloadStr = "{\"audio_path\":\"\(audioPath)\"}"
            if FileManager.default.isExecutableFile(atPath: bundledPython) {
                proc.executableURL = URL(fileURLWithPath: bundledPython)
                proc.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", "transcribe_voice_live", "--payload", payloadStr]
            } else {
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/env")
                proc.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", "transcribe_voice_live", "--payload", payloadStr]
            }
            proc.currentDirectoryURL = repoRoot
            var env = ProcessInfo.processInfo.environment
            let runtimeParent = repoRoot.appendingPathComponent("runtime").path
            let existingPythonPath = env["PYTHONPATH"] ?? ""
            env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
            proc.environment = env
            let outPipe = Pipe()
            proc.standardOutput = outPipe
            proc.standardError = FileHandle.nullDevice
            var transcript = ""
            if (try? proc.run()) != nil {
                let data = outPipe.fileHandleForReading.readDataToEndOfFile()
                proc.waitUntilExit()
                if let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
                   let text = json["transcript"] as? String {
                    transcript = text.trimmingCharacters(in: .whitespacesAndNewlines)
                }
            }
            Task { @MainActor in
                guard let self = self else { return }
                self.isChunkRequestInFlight = false
                self.isLiveChunkTranscribing = false
                if self.isRecording, let store = store, !transcript.isEmpty {
                    self.applyLiveTranscript(transcript, to: store)
                }
            }
        }
    }

    public func stopRecordingAndTranscribe(store: WorkspaceStore, onComplete: (@MainActor @Sendable () -> Void)? = nil) {
        userExplicitlyStoppedSession = true
        isConversationSessionActive = false
        stopSpeaking()
        levelTimer?.invalidate()
        levelTimer = nil
        audioRecorder?.stop()
        audioRecorder = nil
        isRecording = false
        isLiveChunkTranscribing = false
        audioLevel = 0.0
        waveformBars = Array(repeating: 0.14, count: 24)

        let audioPath = lastAudioFilePath
        let fallbackDraft = store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
        let preTyped = preRecordingDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard (!audioPath.isEmpty && FileManager.default.fileExists(atPath: audioPath)) || !fallbackDraft.isEmpty else {
            statusText = "No speech captured yet — click 'Start Conversation' or type below."
            onComplete?()
            return
        }

        if !everDetectedSpeechInSession && lastLiveTranscriptText.isEmpty && !preTyped.isEmpty {
            store.interviewDraftText = preTyped
            syncPreTypedDraft(preTyped)
            statusText = "Ready — review or edit your answer below, then click 'Save & Next'."
            onComplete?()
            return
        }

        isTranscribing = true
        statusText = "Summarizing your answer…"
        let qid = store.selectedInterviewQuestionId
        store.sendActionInBackground("transcribe_voice_audio", payload: [
            "audio_path": audioPath,
            "draft_text": fallbackDraft,
            "pre_typed_text": preTyped,
            "question_id": qid,
        ], silent: true) { [weak self, weak store] in
            guard let self = self, let store = store else { return }
            self.isTranscribing = false
            self.syncPreTypedDraft(store.interviewDraftText)
            if !store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                self.statusText = "Here's your summary. Edit it if needed, then click 'Save & Next'."
            } else {
                self.statusText = "No speech detected — try speaking closer to the microphone or type below."
            }
            onComplete?()
        }
    }

    public func captureAndStopForImmediateNext() -> String {
        stopSpeaking()
        levelTimer?.invalidate()
        levelTimer = nil
        audioRecorder?.stop()
        audioRecorder = nil
        isRecording = false
        isLiveChunkTranscribing = false
        audioLevel = 0.0
        recordingSeconds = 0
        waveformBars = Array(repeating: 0.14, count: 24)
        let captured = lastAudioFilePath
        lastAudioFilePath = ""
        return captured
    }

    public func cancelRecordingOrReset(store: WorkspaceStore, currentQuestion: InterviewQuestionItem?) {
        userExplicitlyStoppedSession = true
        stopSpeaking()
        levelTimer?.invalidate()
        levelTimer = nil
        if let rec = audioRecorder, rec.isRecording {
            rec.stop()
        }
        audioRecorder = nil
        isRecording = false
        isConversationSessionActive = false
        isTranscribing = false
        isLiveChunkTranscribing = false
        isChunkRequestInFlight = false
        audioLevel = 0.0
        recordingSeconds = 0
        waveformBars = Array(repeating: 0.14, count: 24)
        if !lastAudioFilePath.isEmpty {
            try? FileManager.default.removeItem(atPath: lastAudioFilePath)
            lastAudioFilePath = ""
        }
        let saved = currentQuestion?.savedTranscript ?? ""
        store.interviewDraftText = saved
        syncPreTypedDraft(saved)
        statusText = "Ready — click 'Start Conversation' to hear the question aloud and speak your answer."
    }

    public func stopRecording() {
        userExplicitlyStoppedSession = true
        stopSpeaking()
        levelTimer?.invalidate()
        levelTimer = nil
        audioRecorder?.stop()
        audioRecorder = nil
        isRecording = false
        isConversationSessionActive = false
        isLiveChunkTranscribing = false
        audioLevel = 0.0
        waveformBars = Array(repeating: 0.14, count: 24)
    }

    public var formattedDuration: String {
        let mins = recordingSeconds / 60
        let secs = recordingSeconds % 60
        return String(format: "%02d:%02d", mins, secs)
    }
}

