    public var statusBannerIcon: String {
        let lower = statusBannerMessage.lowercased()
        if lower.contains("no active subscription") || lower.contains("checking") {
            return "info.circle.fill"
        }
        if lower.contains("expired") || lower.contains("deactivated") || lower.contains("paused") || lower.contains("cancelled") {
            return "exclamationmark.circle.fill"
        }
        return "checkmark.circle.fill"
    }

    public var statusBannerColor: Color {
        let lower = statusBannerMessage.lowercased()
        if lower.contains("no active subscription") || lower.contains("checking") {
            return .accentColor
        }
        if lower.contains("expired") || lower.contains("deactivated") || lower.contains("paused") || lower.contains("cancelled") {
            return .orange
        }
        return .green
    }

    public func openBuyLicenseWebsite(plan: String? = nil) {
        if let plan = plan, !plan.isEmpty {
            selectedSubscriptionPlanId = plan
        }
        let chosenPlan = selectedSubscriptionPlanId.isEmpty ? "monthly" : selectedSubscriptionPlanId
        var components = URLComponents(string: subscriptionCheckoutUrl.isEmpty ? "https://turboapply.agency/job-searcher/license/" : subscriptionCheckoutUrl)
        var existingItems = components?.queryItems ?? []
        func upsertQueryItem(name: String, value: String) {
            guard !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
            if let idx = existingItems.firstIndex(where: { $0.name == name }) {
                existingItems[idx] = URLQueryItem(name: name, value: value)
            } else {
                existingItems.append(URLQueryItem(name: name, value: value))
            }
        }
        existingItems.removeAll(where: { $0.name == "support_code" })
        upsertQueryItem(name: "device_id", value: "mac_local_device")
        upsertQueryItem(name: "plan", value: chosenPlan)
        upsertQueryItem(name: "email", value: profileEmail.isEmpty ? gmailEmailInput : profileEmail)
        components?.queryItems = existingItems
        if let url = components?.url ?? URL(string: "https://turboapply.agency/job-searcher/license/") {
            NSWorkspace.shared.open(url)
        }
        sendActionInBackground("prepare_subscription_checkout", payload: ["plan": chosenPlan], silent: true, preserveLocalEdits: true)
        startSubscriptionCheckoutPolling()
    }

    public func openUpgradeLicenseWebsite(targetPlan: String? = nil) {
        let currentPlan = activeSubscriptionPlanId.isEmpty ? "monthly" : activeSubscriptionPlanId
        let defaultUpgrade: String = {
            if !recommendedUpgradePlanId.isEmpty { return recommendedUpgradePlanId }
            switch currentPlan {
            case "weekly": return "monthly"
            case "monthly": return "annual"
            case "annual": return "lifetime"
            default: return "lifetime"
            }
        }()
        let chosenUpgrade = (targetPlan?.isEmpty == false) ? targetPlan! : defaultUpgrade
        selectedSubscriptionPlanId = chosenUpgrade
        var components = URLComponents(string: "https://turboapply.agency/job-searcher/license/")
        var queryItems: [URLQueryItem] = [
            URLQueryItem(name: "mode", value: "upgrade"),
            URLQueryItem(name: "current_plan", value: currentPlan),
            URLQueryItem(name: "plan", value: chosenUpgrade),
            URLQueryItem(name: "device_id", value: "mac_local_device")
        ]
        let emailVal = (profileEmail.isEmpty ? gmailEmailInput : profileEmail).trimmingCharacters(in: .whitespacesAndNewlines)
        if !emailVal.isEmpty {
            queryItems.append(URLQueryItem(name: "email", value: emailVal))
        }
        if !activeLicenseKeyMasked.isEmpty {
            queryItems.append(URLQueryItem(name: "key", value: activeLicenseKeyMasked))
        }
        components?.queryItems = queryItems
        if let url = components?.url ?? URL(string: upgradeSubscriptionUrl) {
            NSWorkspace.shared.open(url)
        }
        sendActionInBackground("prepare_subscription_checkout", payload: ["plan": chosenUpgrade], silent: true, preserveLocalEdits: true)
    }

    public func openPauseSubscriptionWebsite() {
        let currentPlan = activeSubscriptionPlanId.isEmpty ? "monthly" : activeSubscriptionPlanId
        var components = URLComponents(string: "https://turboapply.agency/job-searcher/license/cancel/")
        var queryItems: [URLQueryItem] = [
            URLQueryItem(name: "action", value: "pause"),
            URLQueryItem(name: "plan", value: currentPlan),
            URLQueryItem(name: "device_id", value: "mac_local_device")
        ]
        if !activeLicenseKeyMasked.isEmpty {
            queryItems.append(URLQueryItem(name: "key", value: activeLicenseKeyMasked))
        }
        let emailVal = (profileEmail.isEmpty ? gmailEmailInput : profileEmail).trimmingCharacters(in: .whitespacesAndNewlines)
        if !emailVal.isEmpty {
            queryItems.append(URLQueryItem(name: "email", value: emailVal))
        }
        if !subscriptionId.isEmpty {
            queryItems.append(URLQueryItem(name: "sub_id", value: subscriptionId))
        }
        components?.queryItems = queryItems
        if let url = components?.url ?? URL(string: pauseSubscriptionUrl) {
            NSWorkspace.shared.open(url)
        }
    }

    public func startSubscriptionCheckoutPolling() {
        stopSubscriptionCheckoutPolling()
        guard !isLicenseActivated else { return }
        subscriptionPollCount = 0
        subscriptionPollTimer = Timer.scheduledTimer(withTimeInterval: 5.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                if self.isLicenseActivated || self.subscriptionPollCount >= 60 {
                    self.stopSubscriptionCheckoutPolling()
                    return
                }
                self.subscriptionPollCount += 1
                self.sendActionInBackground(
                    "check_subscription_status",
                    payload: ["silent": true],
                    silent: true,
                    preserveLocalEdits: true
                ) { [weak self] in
                    guard let self = self else { return }
                    if self.isLicenseActivated {
                        self.stopSubscriptionCheckoutPolling()
                        self.showLicenseExpiredModal = false
                    }
                }
            }
        }
    }

    public func stopSubscriptionCheckoutPolling() {
        subscriptionPollTimer?.invalidate()
        subscriptionPollTimer = nil
        subscriptionPollCount = 0
    }

    public func checkSubscriptionStatusNow(silent: Bool = false) {
        isCheckingSubscriptionStatus = true
        sendActionInBackground(
            "check_subscription_status",
            payload: ["silent": silent],
            silent: silent,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            self.isCheckingSubscriptionStatus = false
            if self.isLicenseActivated {
                self.stopSubscriptionCheckoutPolling()
                self.showLicenseExpiredModal = false
            }
        }
    }

