    private var errorDismissGeneration: Int = 0
    private var statusDismissGeneration: Int = 0
    @Published public var errorMessage: String = "" {
        didSet {
            errorDismissGeneration &+= 1
            let gen = errorDismissGeneration
            let trimmed = errorMessage.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 5.0) { [weak self] in
                guard let self = self, self.errorDismissGeneration == gen else { return }
                withAnimation(.easeInOut(duration: 0.2)) {
                    self.errorMessage = ""
                }
            }
        }
    }
    @Published public var statusBannerMessage: String = "" {
        didSet {
            statusDismissGeneration &+= 1
            let gen = statusDismissGeneration
            let trimmed = statusBannerMessage.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 5.0) { [weak self] in
                guard let self = self, self.statusDismissGeneration == gen else { return }
                withAnimation(.easeInOut(duration: 0.2)) {
                    self.statusBannerMessage = ""
                }
            }
        }
    }

