    public let appSupportDir: URL
    public let repoRootDir: URL

    public init() {
        if let overrideDir = ProcessInfo.processInfo.environment["AUTOAPPLY_APP_SUPPORT_DIR"], !overrideDir.isEmpty {
            self.appSupportDir = URL(fileURLWithPath: overrideDir)
        } else {
            let home = FileManager.default.homeDirectoryForCurrentUser
            self.appSupportDir = home.appendingPathComponent("Library/Application Support/AutoApply")
        }

        if let bundleResources = Bundle.main.resourceURL,
           FileManager.default.fileExists(atPath: bundleResources.appendingPathComponent("runtime/autoapply/app_bridge.py").path) {
            self.repoRootDir = bundleResources
        } else {
            self.repoRootDir = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        }
        self.voiceRecorder.appSupportDirForAudioCache = self.appSupportDir

        refreshState()
        if completedOnboarding {
            selectedSection = .jobs
        }
        if isMessageAnalysisStale(maxAgeSeconds: 3600) {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { [weak self] in
                self?.syncAndAnalyzeMessagesIfNeeded(force: false, maxAgeSeconds: 3600, silent: true)
            }
        }
        if !neverShowPrivacyModalAgain {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
                guard let self = self else { return }
                if !self.neverShowPrivacyModalAgain {
                    self.showPrivacyModal = true
                }
            }
        }
    }

    public func dismissPrivacyModal() {
        UserDefaults.standard.set(neverShowPrivacyModalAgain, forKey: "autoapply.hide_privacy_pledge_modal")
        showPrivacyModal = false
        privacyModalStep = 1
    }

    public func refreshState() {
        sendAction("get_state", payload: [:])
    }

    public func sendActionInBackground(
        _ action: String,
        payload: [String: Any],
        silent: Bool = false,
        preserveInterviewSelection: Bool = false,
        preserveLocalEdits: Bool = false,
        completion: (@MainActor @Sendable () -> Void)? = nil
    ) {
        if self.isForceUpdateLocked && !Self.forceUpdateAllowedActions.contains(action) {
            if !silent {
                self.errorMessage = "Required Update (v\(self.latestAppVersion)): AutoApply is in view-only mode until updated. Only Settings and view-only access are enabled."
                self.showUpdateModal = true
            }
            completion?()
            return
        }
        self.lastOwnBridgeWriteAt = Date()
        let payloadData = (try? JSONSerialization.data(withJSONObject: payload, options: [])) ?? Data("{}".utf8)
        let payloadString = String(data: payloadData, encoding: .utf8) ?? "{}"
        let repoRoot = self.repoRootDir
        let appSupport = self.appSupportDir

        if action == "launch_browser_session" {
            self.statusBannerMessage = "Opening AutoApply Browser…"
            for app in NSWorkspace.shared.runningApplications {
                let name = (app.localizedName ?? "").lowercased()
                let execPath = (app.executableURL?.path ?? "").lowercased()
                let bundlePath = (app.bundleURL?.path ?? "").lowercased()
                if name.contains("autoapply browser") || bundlePath.contains("autoapply browser.app") || execPath.contains("autoapply browser.app") {
                    app.unhide()
                    app.activate(options: [.activateAllWindows])
                }
            }
        }

        let targetQueue: DispatchQueue = (action == "launch_browser_session")
            ? DispatchQueue.global(qos: .userInteractive)
            : Self.backgroundBridgeQueue

        targetQueue.async { [weak self] in
            let process = Process()
            let bundledPython = repoRoot.appendingPathComponent("python-env/bin/python3").path
            if FileManager.default.isExecutableFile(atPath: bundledPython) {
                process.executableURL = URL(fileURLWithPath: bundledPython)
                process.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", action, "--payload", payloadString]
            } else {
                process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
                process.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", appSupport.path, "--action", action, "--payload", payloadString]
            }
            process.currentDirectoryURL = repoRoot

            var env = ProcessInfo.processInfo.environment
            let runtimeParent = repoRoot.appendingPathComponent("runtime").path
            let existingPythonPath = env["PYTHONPATH"] ?? ""
            env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
            env["AUTOAPPLY_RESOURCES_DIR"] = repoRoot.path
            env["PYTHONDONTWRITEBYTECODE"] = "1"
            env["PYTHONNOUSERSITE"] = "1"
            let bundledBin = repoRoot.appendingPathComponent("bin").path
            let existingPath = env["PATH"] ?? "/usr/bin:/bin:/usr/sbin:/sbin"
            env["PATH"] = "\(bundledBin):/opt/homebrew/bin:/usr/local/bin:\(existingPath)"
            process.environment = env

            let outPipe = Pipe()
            let errPipe = Pipe()
            process.standardOutput = outPipe
            process.standardError = errPipe

            var outData = Data()
            var errData = Data()
            var termStatus: Int32 = -1
            if (try? process.run()) != nil {
                let pipeGroup = DispatchGroup()
                pipeGroup.enter()
                DispatchQueue.global(qos: .userInitiated).async {
                    outData = outPipe.fileHandleForReading.readDataToEndOfFile()
                    pipeGroup.leave()
                }
                pipeGroup.enter()
                DispatchQueue.global(qos: .userInitiated).async {
                    errData = errPipe.fileHandleForReading.readDataToEndOfFile()
                    pipeGroup.leave()
                }
                pipeGroup.wait()
                process.waitUntilExit()
                termStatus = process.terminationStatus
            }

            Task { @MainActor in
                guard let self = self else { return }
                self.lastOwnBridgeWriteAt = Date()
                if termStatus == 0,
                   let json = try? JSONSerialization.jsonObject(with: outData, options: []) as? [String: Any] {
                    if !silent {
                        self.errorMessage = ""
                    }
                    self.applyWorkspaceState(
                        json,
                        silent: silent,
                        preserveInterviewSelection: preserveInterviewSelection,
                        preserveLocalEdits: preserveLocalEdits || action == "launch_browser_session",
                        allowVoiceDraftUpdate: (action == "transcribe_voice_audio" || action == "generate_recommended_interview_answer")
                    )
                } else if !silent {
                    if let json = try? JSONSerialization.jsonObject(with: outData, options: []) as? [String: Any],
                       let msg = json["message"] as? String {
                        if !msg.hasPrefix("Extra data:") {
                            self.errorMessage = msg
                        }
                    } else {
                        let errStr = String(data: errData, encoding: .utf8) ?? "Operation failed"
                        let trimmed = errStr.trimmingCharacters(in: .whitespacesAndNewlines)
                        if !trimmed.isEmpty && !trimmed.hasPrefix("Extra data:") {
                            self.errorMessage = trimmed
                        }
                    }
                }
                completion?()
            }
        }
    }

    public func sendAction(_ action: String, payload: [String: Any], silent: Bool = false) {
        if self.isForceUpdateLocked && !Self.forceUpdateAllowedActions.contains(action) {
            if !silent {
                self.errorMessage = "Required Update (v\(self.latestAppVersion)): AutoApply is in view-only mode until updated. Only Settings and view-only access are enabled."
                self.showUpdateModal = true
            }
            return
        }
        self.lastOwnBridgeWriteAt = Date()
        errorMessage = ""
        let payloadData = (try? JSONSerialization.data(withJSONObject: payload, options: [])) ?? Data("{}".utf8)
        let payloadString = String(data: payloadData, encoding: .utf8) ?? "{}"

        let process = Process()
        let bundledPython = repoRootDir.appendingPathComponent("python-env/bin/python3").path
        if FileManager.default.isExecutableFile(atPath: bundledPython) {
            process.executableURL = URL(fileURLWithPath: bundledPython)
            process.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", appSupportDir.path, "--action", action, "--payload", payloadString]
        } else {
            process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
            process.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", appSupportDir.path, "--action", action, "--payload", payloadString]
        }
        process.currentDirectoryURL = repoRootDir

        var env = ProcessInfo.processInfo.environment
        let runtimeParent = repoRootDir.appendingPathComponent("runtime").path
        let existingPythonPath = env["PYTHONPATH"] ?? ""
        env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
        env["AUTOAPPLY_RESOURCES_DIR"] = repoRootDir.path
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        env["PYTHONNOUSERSITE"] = "1"
        let bundledBin = repoRootDir.appendingPathComponent("bin").path
        let existingPath = env["PATH"] ?? "/usr/bin:/bin:/usr/sbin:/sbin"
        env["PATH"] = "\(bundledBin):/opt/homebrew/bin:/usr/local/bin:\(existingPath)"
        process.environment = env

        let outPipe = Pipe()
        let errPipe = Pipe()
        process.standardOutput = outPipe
        process.standardError = errPipe

        do {
            try process.run()
            var outData = Data()
            var errData = Data()
            let pipeGroup = DispatchGroup()
            pipeGroup.enter()
            DispatchQueue.global(qos: .userInitiated).async {
                outData = outPipe.fileHandleForReading.readDataToEndOfFile()
                pipeGroup.leave()
            }
            pipeGroup.enter()
            DispatchQueue.global(qos: .userInitiated).async {
                errData = errPipe.fileHandleForReading.readDataToEndOfFile()
                pipeGroup.leave()
            }
            pipeGroup.wait()
            process.waitUntilExit()
            self.lastOwnBridgeWriteAt = Date()

            if process.terminationStatus != 0 {
                if let json = try? JSONSerialization.jsonObject(with: outData, options: []) as? [String: Any],
                   let msg = json["message"] as? String {
                    if !msg.hasPrefix("Extra data:") {
                        self.errorMessage = msg
                    }
                } else {
                    let errStr = String(data: errData, encoding: .utf8) ?? "Operation failed"
                    let trimmed = errStr.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !trimmed.hasPrefix("Extra data:") {
                        self.errorMessage = trimmed
                    }
                }
                if action == "generate_tailored_document" && !self.customTailorManualMode {
                    self.customTailorUrlError = self.errorMessage.isEmpty ? "Could not parse job details from URL. Please specify them manually below." : self.errorMessage
                    self.customTailorManualMode = true
                } else if action == "add_job_posting" && !self.addJobManualMode {
                    self.addJobUrlError = self.errorMessage.isEmpty ? "Could not parse job details from URL. Please specify them manually below." : self.errorMessage
                    self.addJobManualMode = true
                }
                return
            }

            if action == "generate_tailored_document" {
                self.customTailorUrlError = ""
            } else if action == "add_job_posting" {
                self.addJobUrlError = ""
            }

            guard let json = try JSONSerialization.jsonObject(with: outData, options: []) as? [String: Any] else {
                return
            }
            let allowVoiceDraft = (action == "transcribe_voice_audio" || action == "generate_recommended_interview_answer" || (!self.hasLoadedInitialWorkspaceState && self.interviewDraftText.isEmpty))
            applyWorkspaceState(json, silent: silent, allowVoiceDraftUpdate: allowVoiceDraft)
            if action == "generate_tailored_document" {
                self.resumesSubtab = "generated"
                if let newest = self.documents.first {
                    self.selectDocument(newest.id)
                }
            }
        } catch {
            self.errorMessage = "Bridge execution error: \(error.localizedDescription)"
        }
    }

    private func applyWorkspaceState(
        _ json: [String: Any],
        silent: Bool = false,
        preserveInterviewSelection: Bool = false,
        preserveLocalEdits: Bool = false,
        allowVoiceDraftUpdate: Bool = false
    ) {
        if let exportPath = json["last_export_path"] as? String, !exportPath.isEmpty {
            self.lastExportPath = exportPath
        }
        if let importPath = json["last_import_path"] as? String, !importPath.isEmpty {
            self.lastImportPath = importPath
        }
        if !silent,
           let notice = json["action_notice"] as? String,
           !notice.isEmpty,
           !notice.localizedCaseInsensitiveContains("CapSolver pinned"),
           !notice.localizedCaseInsensitiveContains(" in Browser") {
            self.statusBannerMessage = notice
        }
        if allowVoiceDraftUpdate,
           !preserveInterviewSelection,
           !self.voiceRecorder.isRecording,
           let vTranscript = json["last_voice_transcript"] as? String,
           !vTranscript.isEmpty {
            let targetQid = (json["last_voice_question_id"] as? String) ?? self.selectedInterviewQuestionId
            if targetQid.isEmpty || targetQid == self.selectedInterviewQuestionId {
                self.interviewDraftText = vTranscript
            }
        }
        if let launch = json["last_browser_launch"] as? [String: String],
           let url = launch["url"] {
            self.lastBrowserLaunchSummary = "Opened \(url) in Browser"
        }

        if let onb = json["onboarding"] as? [String: Any] {
            self.completedOnboarding = onb["completed_onboarding"] as? Bool ?? false
            if self.completedOnboarding && !self.isSetupWizardReopened && self.selectedSection == .setup {
                self.selectedSection = .jobs
            }
            self.trialState = onb["trial_state"] as? String ?? "unselected"
            self.trialExpiresAt = onb["trial_expires_at"] as? String ?? ""
            if let sc = onb["support_code"] as? String, !sc.isEmpty {
                self.supportCode = sc
            }

            if let cb = onb["cloakbrowser_config"] as? [String: Any] {
                self.browserLicenseTier = cb["tier"] as? String ?? "free"
                self.browserLicenseKeyConfigured = cb["license_key_configured"] as? Bool ?? false
                self.browserLicenseKeyMasked = cb["license_key_masked"] as? String ?? "Included"
            }

            if let comps = onb["components"] as? [[String: Any]] {
                self.components = comps.map { c in
                    ComponentItem(
                        id: c["id"] as? String ?? UUID().uuidString,
                        name: c["name"] as? String ?? "",
                        source: c["source"] as? String ?? "",
                        version: c["version"] as? String ?? "",
                        size: c["size"] as? String ?? "",
                        status: c["status"] as? String ?? "ready"
                    )
                }
            }

            if let ai = onb["ai_config"] as? [String: Any] {
                self.openrouterKeyMasked = ai["openrouter_key_masked"] as? String ?? "Not Connected"
                self.capsolverKeyMasked = ai["capsolver_key_masked"] as? String ?? "Optional (Recommended)"
                self.capsolverConfigured = ai["capsolver_key_configured"] as? Bool ?? false
                self.dailyBudgetUsd = ai["daily_budget_usd"] as? Double ?? 15.0
                self.perRunBudgetUsd = ai["per_run_budget_usd"] as? Double ?? 2.5
                self.currentDailySpendUsd = ai["current_daily_spend_usd"] as? Double ?? 0.0
                if !preserveLocalEdits {
                    if let lm = ai["logic_model"] as? String, !lm.isEmpty {
                        self.hermesLogicModel = AIModelChoiceItem.normalizeLogicModelId(lm)
                    }
                    if let wm = ai["writer_model"] as? String, !wm.isEmpty {
                        self.hermesWriterModel = (wm == "anthropic/claude-sonnet-5.5") ? "~anthropic/claude-sonnet-latest" : wm
                    }
                    if let lre = ai["logic_reasoning_effort"] as? String, !lre.isEmpty {
                        self.hermesLogicReasoningEffort = lre.lowercased()
                    }
                    if let wre = ai["writer_reasoning_effort"] as? String, !wre.isEmpty {
                        self.hermesWriterReasoningEffort = wre.lowercased()
                    }
                }
            }

            if let cg = onb["chatgpt_config"] as? [String: Any] {
                self.chatgptConnected = cg["connected"] as? Bool ?? false
                self.chatgptAccountEmail = cg["account_email"] as? String ?? ""
                self.chatgptStatusLabel = cg["status_label"] as? String ?? "Optional — Uses OpenRouter if not connected"
                self.chatgptLogicProvider = cg["logic_provider"] as? String ?? "openrouter_default"
            }

            if let gm = onb["gmail_config"] as? [String: Any] {
                self.gmailConnected = gm["connected"] as? Bool ?? false
                let acct = gm["account_email"] as? String ?? ""
                if !acct.isEmpty { self.gmailEmailInput = acct }
            }
            if let tl = onb["teal_config"] as? [String: Any] {
                self.tealConnected = tl["session_connected"] as? Bool ?? false
                self.tealStatusLabel = tl["status_label"] as? String ?? (self.tealConnected ? "✓ Validated — Syncs Applied Jobs to Teal (app.tealhq.com)" : "Optional — Syncs applied jobs to your Teal tracker if connected")
            }
            if let li = onb["linkedin_config"] as? [String: Any] {
                self.linkedinConnected = li["session_connected"] as? Bool ?? false
            }
            if let upd = onb["update_config"] as? [String: Any] {
                let wasForceLocked = self.isForceUpdateLocked
                self.currentAppVersion = upd["current_version"] as? String ?? "0.1.0"
                self.latestAppVersion = upd["latest_version"] as? String ?? "0.1.0"
                self.minimumRequiredAppVersion = upd["minimum_required_version"] as? String ?? "0.1.0"
                self.updateAvailable = upd["update_available"] as? Bool ?? false
                self.updateRequired = (upd["update_required"] as? Bool ?? false) || (upd["force_update_required"] as? Bool ?? false)
                self.shouldPromptDailyUpdate = upd["should_prompt_daily"] as? Bool ?? false
                self.lastDailyUpdatePromptDate = upd["last_daily_prompt_date"] as? String ?? ""
                self.updateDownloadUrl = upd["download_url"] as? String ?? "https://turboapply.agency/job-searcher/download/AutoApply-latest.dmg"
                self.updateChannel = upd["channel"] as? String ?? "stable"
                self.updateFeedUrl = upd["feed_url"] as? String ?? "https://turboapply.ru/api/autoapply-updates/appcast.json"
                self.autoCheckForUpdates = upd["auto_check_enabled"] as? Bool ?? true
                self.lastUpdateCheckAt = upd["last_checked_at"] as? String ?? ""
                self.updateStatusMessage = upd["status_message"] as? String ?? "AutoApply v0.1.0 is up to date."
                if let notes = upd["release_notes"] as? String, !notes.isEmpty {
                    self.updateReleaseNotes = notes
                }
                let isAutomatedHeadless = CommandLine.arguments.contains("--snapshot-screens")
                    || CommandLine.arguments.contains("--self-test")
                    || CommandLine.arguments.contains("--bundle-self-test")
                if !isAutomatedHeadless {
                    if self.isForceUpdateLocked && (!wasForceLocked || (json["blocked_by_force_update"] as? Bool == true)) {
                        self.showUpdateModal = true
                    } else if self.updateAvailable && !self.updateRequired && self.shouldPromptDailyUpdate {
                        self.shouldPromptDailyUpdate = false
                        self.showUpdateModal = true
                        self.sendActionInBackground("dismiss_daily_update_prompt", payload: [:], silent: true, preserveLocalEdits: true)
                    }
                }
            }

            if let prefs = onb["preferences"] as? [String: Any], (!preserveLocalEdits || !self.hasLoadedInitialWorkspaceState || self.residenceCountry.isEmpty) {
                func normalizeChoice(_ rawVal: String?) -> String {
                    let v = (rawVal ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                    if v.isEmpty || v == "-" || v == "[PLEASE SPECIFY HERE]" || v.lowercased() == "please specify" {
                        return ""
                    }
                    if v == "Citizen / PR" {
                        return "Citizen"
                    }
                    return v
                }
                self.residenceCountry = normalizeChoice(prefs["residence_country"] as? String)
                self.minimumSalaryUsd = prefs["minimum_salary_usd"] as? Int ?? 150000
                self.targetSalaryUsd = prefs["target_salary_usd"] as? Int ?? 200000
                self.useHighestListedRange = prefs["use_highest_listed_range"] as? Bool ?? true
                self.salaryCurrency = prefs["salary_currency"] as? String ?? "USD"
                self.noticePeriod = prefs["notice_period"] as? String ?? "2 Weeks"
                self.relocationPreference = prefs["relocation_preference"] as? String ?? "Remote or Hybrid"
                self.globalB2BContractor = prefs["global_b2b_contractor"] as? Bool ?? true

                if let titles = prefs["desired_titles"] as? [String] {
                    self.desiredTitlesInput = titles.joined(separator: ", ")
                }
                if let sen = prefs["seniority_levels"] as? [String] {
                    self.seniorityLevels = sen
                }
                if let emp = prefs["employment_types"] as? [String] {
                    self.employmentTypes = emp
                }
                if let modes = prefs["accepted_workplace_modes"] as? [String] {
                    self.workplaceModes = modes
                }
                if let mh = prefs["must_have_keywords"] as? [String] {
                    self.mustHaveKeywordsInput = mh.joined(separator: ", ")
                }
                if let exk = prefs["excluded_keywords"] as? [String] {
                    self.excludedKeywordsInput = exk.joined(separator: ", ")
                }
                if let exc = prefs["excluded_employers"] as? [String] {
                    self.excludedEmployersInput = exc.joined(separator: ", ")
                }
                if let wa = prefs["work_auth_by_region"] as? [String: String] {
                    self.workAuthUS = normalizeChoice(wa["US"])
                    self.workAuthEU = normalizeChoice(wa["EU"])
                    self.workAuthUK = normalizeChoice(wa["UK"])
                    self.workAuthCA = normalizeChoice(wa["CA"])
                    self.workAuthAU = normalizeChoice(wa["AU"])
                }
                if let eeo = prefs["eeo_disclosures"] as? [String: String] {
                    self.eeoGender = normalizeChoice(eeo["gender"])
                    self.eeoHispanicLatino = normalizeChoice(eeo["hispanic_latino"])
                    self.eeoRaceEthnicity = normalizeChoice(eeo["race_ethnicity"])
                    self.eeoVeteranStatus = normalizeChoice(eeo["veteran_status"])
                    self.eeoDisabilityStatus = normalizeChoice(eeo["disability_status"])
                    self.eeoLgbtq = normalizeChoice(eeo["lgbtq"])
                }
            }

            if let pol = onb["operating_policy"] as? [String: Any] {
                if !preserveLocalEdits {
                    self.documentMode = pol["document_mode"] as? String ?? "tailored_approved"
                    self.visibilityMode = pol["visibility_mode"] as? String ?? "foreground"
                    self.autonomyMode = pol["autonomy_mode"] as? String ?? "review_each_application"
                }
                self.emergencyStopActive = pol["emergency_stop_active"] as? Bool ?? false
                self.statusCopy = pol["status_copy"] as? String ?? "Ready"
            }

            let savedAnswers = onb["interview_answers"] as? [String: [String: Any]] ?? [:]
            if let qList = json["interview_questions"] as? [[String: Any]] {
                let prevSelected = self.selectedInterviewQuestionId
                let prevIndex = self.interviewQuestions.firstIndex(where: { $0.id == prevSelected }) ?? 0
                let allQuestions = qList.map { q in
                    let qid = q["id"] as? String ?? ""
                    let ans = savedAnswers[qid]
                    return InterviewQuestionItem(
                        id: qid,
                        title: q["title"] as? String ?? "",
                        icon: q["icon"] as? String ?? "mic.fill",
                        prompt: q["prompt"] as? String ?? "",
                        whyItMatters: q["why_it_matters"] as? String ?? "",
                        factKey: q["fact_key"] as? String ?? qid,
                        kbSectionId: q["kb_section_id"] as? String ?? "about",
                        savedTranscript: ans?["transcript"] as? String ?? "",
                        isSaved: (ans?["status"] as? String) == "saved",
                        isLlmGenerated: q["is_llm_generated"] as? Bool ?? qid.hasPrefix("ai_")
                    )
                }
                self.interviewQuestions = allQuestions.filter { !$0.isSaved }
                if !self.interviewQuestions.contains(where: { $0.id == prevSelected }) {
                    if !self.interviewQuestions.isEmpty {
                        let nextIdx = min(prevIndex, self.interviewQuestions.count - 1)
                        self.selectedInterviewQuestionId = self.interviewQuestions[nextIdx].id
                    } else {
                        self.selectedInterviewQuestionId = ""
                    }
                    if !self.voiceRecorder.isRecording {
                        if allowVoiceDraftUpdate, let vTranscript = json["last_voice_transcript"] as? String, !vTranscript.isEmpty {
                            self.interviewDraftText = vTranscript
                        } else if !preserveInterviewSelection {
                            let selId = self.selectedInterviewQuestionId
                            self.interviewDraftText = self.interviewQuestions.first(where: { $0.id == selId })?.savedTranscript ?? ""
                        }
                    }
                } else if allowVoiceDraftUpdate,
                          !preserveInterviewSelection,
                          !self.voiceRecorder.isRecording,
                          let vTranscript = json["last_voice_transcript"] as? String,
                          !vTranscript.isEmpty {
                    let targetQid = (json["last_voice_question_id"] as? String) ?? self.selectedInterviewQuestionId
                    if targetQid.isEmpty || targetQid == self.selectedInterviewQuestionId {
                        self.interviewDraftText = vTranscript
                    }
                }
            }
        }

        if let kb = json["knowledge_base"] as? [String: Any] {
            if let hdr = kb["profile_header"] as? [String: Any] {
                let forceLoad = !preserveLocalEdits || !self.hasLoadedInitialWorkspaceState
                if forceLoad || self.profileFullName.isEmpty {
                    self.profileFullName = hdr["full_name"] as? String ?? ""
                }
                if forceLoad || self.profilePronouns.isEmpty {
                    self.profilePronouns = hdr["pronouns"] as? String ?? ""
                }
                if forceLoad || self.profileHeadline.isEmpty {
                    self.profileHeadline = hdr["headline"] as? String ?? ""
                }
                if forceLoad || self.profileEmail.isEmpty {
                    self.profileEmail = hdr["email"] as? String ?? ""
                }
                if forceLoad || self.profilePhone.isEmpty {
                    self.profilePhone = hdr["phone"] as? String ?? ""
                }
                if forceLoad || self.profileLocation.isEmpty {
                    self.profileLocation = hdr["location"] as? String ?? ""
                }
                if forceLoad || self.profileLinkedinUrl.isEmpty {
                    self.profileLinkedinUrl = hdr["linkedin_url"] as? String ?? ""
                }
                if forceLoad || self.profileGithubUrl.isEmpty {
                    self.profileGithubUrl = hdr["github_url"] as? String ?? ""
                }
                let incomingPhoto = hdr["photo_path"] as? String ?? self.profilePhotoPath
                let incomingThumb = hdr["photo_thumb_path"] as? String ?? ""
                if incomingPhoto != self.profilePhotoPath {
                    FastThumbnailCache.shared.invalidate(path: self.profilePhotoPath)
                    FastThumbnailCache.shared.invalidate(path: incomingPhoto)
                }
                if incomingThumb != self.profilePhotoThumbPath {
                    FastThumbnailCache.shared.invalidate(path: self.profilePhotoThumbPath)
                    FastThumbnailCache.shared.invalidate(path: incomingThumb)
                }
                self.profilePhotoPath = incomingPhoto
                self.profilePhotoThumbPath = incomingThumb
                if forceLoad {
                    self.includePhotoOnResume = hdr["include_photo_on_resume"] as? Bool ?? false
                }
            }
            if let secs = kb["sections"] as? [[String: Any]] {
                let oldSelected = self.selectedKBSectionId
                self.kbSections = secs.map { s in
                    KBSectionItem(
                        id: s["id"] as? String ?? "about",
                        title: s["title"] as? String ?? "Section",
                        icon: s["icon"] as? String ?? "doc.text.fill",
                        subtitle: s["subtitle"] as? String ?? "",
                        markdown: s["markdown"] as? String ?? "",
                        isCustom: s["is_custom"] as? Bool ?? false,
                        updatedAt: s["updated_at"] as? String ?? ""
                    )
                }
                if let activeSec = self.kbSections.first(where: { $0.id == oldSelected }) ?? self.kbSections.first {
                    self.selectedKBSectionId = activeSec.id
                    if !preserveLocalEdits || (!self.kbShowEditor && self.kbEditorText.isEmpty) {
                        self.kbEditorText = activeSec.markdown
                    }
                }
            }
        }

        if let rm = json["readiness_matrix"] as? [String: Any] {
            self.isolRuntimeReady = rm["isolated_runtime_ready"] as? Bool ?? false
            self.aiReady = rm["authorized_orchestration_and_writer_ready"] as? Bool ?? false
            self.factsConfirmedReady = rm["candidate_facts_confirmed"] as? Bool ?? false
            self.submissionFixtureReady = rm["supported_submission_fixture_ready"] as? Bool ?? false
            self.gmailReady = rm["gmail_ready"] as? Bool ?? false
            self.tealReady = rm["teal_ready"] as? Bool ?? false
            self.canActivateTrialOrRun = rm["can_activate_trial_or_run"] as? Bool ?? false
            if self.aiReady {
                if self.expandedAIItemId == "openrouter" {
                    self.expandedAIItemId = ""
                }
            } else if self.expandedAIItemId.isEmpty {
                self.expandedAIItemId = "openrouter"
            }
        }

        if let ent = json["entitlement"] as? [String: Any] {
            self.entitlementStatus = ent["status"] as? String ?? "blocked"
            if let sc = ent["support_code"] as? String, !sc.isEmpty {
                self.supportCode = sc
            }
            if let co = ent["checkout_url"] as? String, !co.isEmpty {
                self.subscriptionCheckoutUrl = co
            }
            if let ap = ent["active_plan"] as? String, !ap.isEmpty {
                self.activeSubscriptionPlanId = ap
            }
            if let apName = ent["active_plan_name"] as? String, !apName.isEmpty {
                self.activeSubscriptionPlanName = apName
            }
            if let apLabel = ent["active_plan_label"] as? String, !apLabel.isEmpty {
                self.activeSubscriptionPlanLabel = apLabel
            }
            if let canUp = ent["can_upgrade_plan"] as? Bool {
                self.canUpgradeSubscription = canUp
            }
            if let recUp = ent["recommended_upgrade_plan"] as? String {
                self.recommendedUpgradePlanId = recUp
            }
            if let pUrl = ent["pause_subscription_url"] as? String, !pUrl.isEmpty {
                self.pauseSubscriptionUrl = pUrl
            }
            if let uUrl = ent["upgrade_subscription_url"] as? String, !uUrl.isEmpty {
                self.upgradeSubscriptionUrl = uUrl
            }
            if let subId = ent["subscription_id"] as? String {
                self.subscriptionId = subId
            }
            if let pauseUntil = ent["subscription_pause_until"] as? String {
                self.subscriptionPauseUntil = pauseUntil
            }
            if let cancelledAt = ent["subscription_cancelled_at"] as? String {
                self.subscriptionCancelledAt = cancelledAt
            }
            if let masked = ent["active_license_key_masked"] as? String {
                self.activeLicenseKeyMasked = masked
            }
            if let prov = ent["subscription_provider"] as? String, !prov.isEmpty {
                self.subscriptionProvider = prov
            }
            if self.isLicenseActivated {
                self.stopSubscriptionCheckoutPolling()
                self.showLicenseExpiredModal = false
            }
            let entCanRun = ent["can_run_automation"] as? Bool ?? false
            if self.isForceUpdateLocked {
                self.canRunAutomation = false
                self.emergencyStopActive = true
                self.statusCopy = "Update Required (v\(self.latestAppVersion)) — View-Only Mode"
            } else if self.isLicenseExpired {
                self.canRunAutomation = false
                self.emergencyStopActive = true
                self.statusCopy = "Paused"
            } else {
                self.canRunAutomation = entCanRun || (self.completedOnboarding && self.canActivateTrialOrRun)
            }
        } else if self.isForceUpdateLocked {
            self.canRunAutomation = false
            self.emergencyStopActive = true
            self.statusCopy = "Update Required (v\(self.latestAppVersion)) — View-Only Mode"
        } else if self.isLicenseExpired {
            self.canRunAutomation = false
            self.emergencyStopActive = true
            self.statusCopy = "Paused"
        } else if self.completedOnboarding && self.canActivateTrialOrRun {
            self.canRunAutomation = true
        }

        self.activeConfirmedCount = json["active_confirmed_count"] as? Int ?? 0
        self.unconfirmedCount = json["unconfirmed_count"] as? Int ?? 0

        if let rawFacts = json["candidate_facts"] as? [[String: Any]] {
            self.facts = rawFacts.compactMap { f in
                let key = f["key"] as? String ?? ""
                if key.hasPrefix("kb_") { return nil }
                let fid = f["id"] as? String ?? UUID().uuidString
                let valStr: String
                if let s = f["value"] as? String {
                    valStr = s
                } else if let n = f["value"] as? NSNumber {
                    valStr = n.stringValue
                } else {
                    valStr = String(describing: f["value"] ?? "")
                }
                let conf = f["confirmed"] as? Bool ?? false
                if !conf && self.questionableFactEdits[fid] == nil {
                    self.questionableFactEdits[fid] = valStr
                }
                return CandidateFactItem(
                    id: fid,
                    key: key,
                    category: f["category"] as? String ?? "",
                    value: valStr,
                    sourceType: f["source_type"] as? String ?? "",
                    sourceRef: f["source_ref"] as? String ?? "",
                    confidence: f["confidence"] as? Double ?? 1.0,
                    confirmed: conf,
                    scopeCountry: f["scope_country"] as? String ?? "GLOBAL",
                    version: f["version"] as? Int ?? 1,
                    supersedesId: f["supersedes_id"] as? String,
                    supersededById: f["superseded_by_id"] as? String
                )
            }
            let unconf = self.facts.filter { !$0.confirmed && $0.supersededById == nil }
            if self.expandedQuestionFactId.isEmpty || !unconf.contains(where: { $0.id == self.expandedQuestionFactId }) {
                self.expandedQuestionFactId = unconf.first?.id ?? ""
            }
        }

        if let rawResumes = json["resumes"] as? [[String: Any]] {
            self.resumes = rawResumes.map { r in
                let sp = r["style_profile"] as? [String: Any] ?? [:]
                return ResumeItem(
                    referenceId: r["reference_id"] as? String ?? UUID().uuidString,
                    filename: r["filename"] as? String ?? "Resume.pdf",
                    sha256: r["original_sha256"] as? String ?? "",
                    storedPath: r["stored_path"] as? String ?? "",
                    isPrimary: r["is_primary_reference"] as? Bool ?? false,
                    uploadedAt: r["uploaded_at"] as? String ?? "Just now",
                    extractedText: r["extracted_text"] as? String ?? "",
                    fontFamily: sp["font_family"] as? String ?? "Georgia + Arial (Reference Style)",
                    pageCount: sp["target_page_count"] as? Int ?? 2
                )
            }
            if let primary = self.resumes.first(where: { $0.isPrimary }) ?? self.resumes.first {
                self.resumeFontChoice = primary.fontFamily
                self.resumePageTarget = primary.pageCount
            }
        }

        if let rawDocs = json["documents"] as? [[String: Any]] {
            self.documents = rawDocs.map { d in
                let claims = d["claims"] as? [[String: Any]] ?? []
                return DocumentArtifactItem(
                    artifactId: d["artifact_id"] as? String ?? UUID().uuidString,
                    jobId: d["job_id"] as? String ?? "",
                    jobLabel: d["job_Label"] as? String ?? "Tailored Resume",
                    companyName: d["company_name"] as? String ?? "Company",
                    roleTitle: d["role_title"] as? String ?? "Role",
                    createdAt: d["created_at"] as? String ?? "Today",
                    fontFamily: d["font_family"] as? String ?? "Arial",
                    includePhoto: d["include_photo"] as? Bool ?? false,
                    writerModel: d["writer_model"] as? String ?? "claude-sonnet-4.6",
                    pdfPath: d["pdf_path"] as? String ?? "",
                    docxPath: d["docx_path"] as? String ?? "",
                    coverLetterPdfPath: d["cover_letter_pdf_path"] as? String ?? "",
                    coverLetterDocxPath: d["cover_letter_docx_path"] as? String ?? "",
                    pdfSha256: d["pdf_sha256"] as? String ?? "",
                    docxSha256: d["docx_sha256"] as? String ?? "",
                    qaPassed: d["qa_passed"] as? Bool ?? true,
                    estimatedPages: d["estimated_pages"] as? Int ?? 2,
                    approvedByUser: d["approved_by_user"] as? Bool ?? true,
                    resumeMarkdown: d["resume_markdown"] as? String ?? "",
                    coverLetterMarkdown: d["cover_letter_markdown"] as? String ?? "",
                    kbSectionsUsed: d["kb_sections_used"] as? [String] ?? [],
                    claimStatement: claims.first?["statement"] as? String ?? "",
                    isSubmitted: d["is_submitted"] as? Bool ?? false
                )
            }
            if !self.selectedDocumentId.isEmpty,
               let activeDoc = self.documents.first(where: { $0.id == self.selectedDocumentId }) {
                if !preserveLocalEdits || (!self.resumeShowEditor && self.resumeEditorText.isEmpty) {
                    self.resumeEditorText = activeDoc.resumeMarkdown
                    self.coverLetterEditorText = activeDoc.coverLetterMarkdown
                }
            } else {
                self.selectedDocumentId = ""
                self.resumeEditorText = ""
                self.coverLetterEditorText = ""
            }
        }

        if let rawJobs = json["jobs"] as? [[String: Any]] {
            self.jobs = rawJobs.map { j in
                let elig = j["eligible"] as? Bool ?? true
                let stateStr = j["state"] as? String ?? "ready_to_submit"
                let explicitStage = j["pipeline_stage"] as? String ?? ""
                let issueObj = j["application_issue"] as? [String: Any]
                let failReason = (j["failure_reason"] as? String) ?? (issueObj?["reason"] as? String) ?? ""
                let failKind = (j["failure_kind"] as? String) ?? (issueObj?["kind"] as? String) ?? ""
                let computedStage: String
                if !explicitStage.isEmpty {
                    computedStage = explicitStage
                } else if stateStr == "submitted_verified" || stateStr == "submitted" || (j["remote_receipt_id"] as? String != nil) {
                    computedStage = "submitted"
                } else if stateStr == "failed" || !failReason.isEmpty {
                    computedStage = "failed"
                } else if stateStr == "applying" || stateStr == "uncertain" {
                    computedStage = "applying"
                } else {
                    computedStage = "not_applied"
                }
                let postedAtStr = (j["posted_at"] as? String) ?? ""
                let postedLabelStr: String = {
                    if let lbl = j["posted_label"] as? String, !lbl.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                        return lbl
                    }
                    if !postedAtStr.isEmpty {
                        return "Posted \(postedAtStr)"
                    }
                    return "Posted recently"
                }()
                let matchPct = j["match_score_pct"] as? Int ?? 0
                let bdObj = j["match_breakdown"] as? [String: Any]
                let defaultTier: String = {
                    if matchPct >= 80 { return "Strong Match" }
                    if matchPct >= 65 { return "Good Match" }
                    if matchPct >= 50 { return "Partial Match" }
                    return "Low Match"
                }()
                return JobItem(
                    jobId: j["job_id"] as? String ?? UUID().uuidString,
                    applicationId: j["application_id"] as? String ?? "",
                    companyName: j["company_name"] as? String ?? "Target Employer",
                    title: j["title"] as? String ?? "Product Manager",
                    canonicalUrl: j["canonical_url"] as? String ?? "",
                    description: j["description"] as? String ?? "",
                    postedAt: postedAtStr,
                    postedLabel: postedLabelStr,
                    workplaceMode: j["workplace_mode"] as? String ?? "remote",
                    locationLabel: j["location_label"] as? String ?? "",
                    salaryMaxUsd: j["salary_max_usd"] as? Int ?? 0,
                    eligible: elig,
                    eligibilityStatus: (j["eligibility_status"] as? String) ?? (elig ? "eligible" : "not_eligible"),
                    exclusionReason: j["exclusion_reason"] as? String,
                    filterSummary: j["filter_summary"] as? String ?? "Matches Criteria",
                    dedupeStatus: j["dedupe_status"] as? String ?? "",
                    state: stateStr,
                    pipelineStage: computedStage,
                    previousPipelineStage: (j["previous_pipeline_stage"] as? String) ?? "",
                    failureReason: failReason,
                    failureKind: failKind,
                    trackerSyncState: j["tracker_sync_state"] as? String ?? "pending",
                    remoteReceiptId: j["remote_receipt_id"] as? String,
                    uncertainEffect: j["uncertain_effect"] as? Bool ?? false,
                    screeningAnswers: j["screening_answers"] as? [String: String] ?? [:],
                    timeline: j["timeline"] as? [String] ?? [],
                    matchScorePct: matchPct,
                    matchTier: (j["match_tier"] as? String) ?? defaultTier,
                    roleFitPct: (bdObj?["role_fit_pct"] as? Int) ?? matchPct,
                    skillsFitPct: (bdObj?["skills_fit_pct"] as? Int) ?? matchPct,
                    experienceFitPct: (bdObj?["experience_fit_pct"] as? Int) ?? matchPct,
                    logisticsFitPct: (bdObj?["logistics_fit_pct"] as? Int) ?? matchPct,
                    matchedSkills: j["matched_skills"] as? [String] ?? [],
                    missingGaps: j["missing_gaps"] as? [String] ?? [],
                    matchSummary: j["match_summary"] as? String ?? "",
                    matchJevVerified: j["match_jev_verified"] as? Bool ?? false,
                    matchModel: j["match_model"] as? String ?? "JEV Multi-Factor Rubric"
                )
            }
            if self.selectedJobId.isEmpty || !self.jobs.contains(where: { $0.jobId == self.selectedJobId }) {
                self.selectedJobId = ""
            }
            if let activeDoc = self.selectedDocument, self.isDocumentSubmitted(activeDoc) {
                self.resumeShowEditor = false
                self.resumeShowPreview = true
            }
        }

        if let rawBoards = json["job_boards"] as? [[String: Any]], !rawBoards.isEmpty {
            self.jobBoards = rawBoards.map { b in
                JobBoardChannelItem(
                    id: b["id"] as? String ?? UUID().uuidString,
                    name: b["name"] as? String ?? "Job Board",
                    slug: b["slug"] as? String ?? "globe",
                    domain: b["domain"] as? String ?? "",
                    url: b["url"] as? String ?? "",
                    authUrl: b["auth_url"] as? String ?? (b["url"] as? String ?? ""),
                    isPrimary: b["is_primary"] as? Bool ?? false,
                    requiresAuth: b["requires_auth"] as? Bool ?? false,
                    operational: b["operational"] as? Bool ?? false,
                    excluded: b["excluded"] as? Bool ?? false,
                    operationalNote: b["operational_note"] as? String ?? "Operational",
                    attentionReason: b["attention_reason"] as? String ?? "Requires setup"
                )
            }
        }

        if let ot = json["outreach_tracker"] as? [String: Any] {
            if let sum = ot["summary"] as? [String: Any] {
                self.outreachSummary = OutreachSummaryItem(
                    totalEvents: sum["total_events"] as? Int ?? 0,
                    verifiedSentCount: sum["verified_sent_count"] as? Int ?? 0,
                    emailSentCount: sum["email_sent_count"] as? Int ?? 0,
                    linkedinDmSentCount: sum["linkedin_dm_sent_count"] as? Int ?? 0,
                    linkedinPendingInvitesCount: sum["linkedin_pending_invites_count"] as? Int ?? 0,
                    linkedinAcceptedHoldCount: sum["linkedin_accepted_hold_count"] as? Int ?? 0,
                    followupDueCount: sum["followup_due_count"] as? Int ?? 0,
                    suppressedBouncesCount: sum["suppressed_bounces_count"] as? Int ?? 0,
                    lastLinkedinScanAt: sum["last_linkedin_scan_at"] as? String ?? "Every 12h Active",
                    threadsCount: sum["threads_count"] as? Int ?? 0,
                    actionRequiredCount: sum["action_required_count"] as? Int ?? 0,
                    queuedMessagesCount: sum["queued_messages_count"] as? Int ?? 0
                )
                if let sumTs = sum["last_message_analysis_at"] as? String, !sumTs.isEmpty {
                    self.lastMessageAnalysisAt = sumTs
                    if let parsed = Self.parseAnalysisTimestamp(sumTs) {
                        self.lastMessageAnalysisDate = parsed
                    }
                }
            }
            if let topTs = ot["last_message_analysis_at"] as? String, !topTs.isEmpty {
                self.lastMessageAnalysisAt = topTs
                if let parsed = Self.parseAnalysisTimestamp(topTs) {
                    self.lastMessageAnalysisDate = parsed
                }
            }
            if let rawThreads = ot["threads"] as? [[String: Any]] {
                let prevSelectedId = self.selectedOutreachThreadId
                self.outreachThreads = rawThreads.map { t in
                    let rawMsgs = t["messages"] as? [[String: Any]] ?? []
                    let msgs: [OutreachChatMessageItem] = rawMsgs.map { m in
                        OutreachChatMessageItem(
                            id: m["id"] as? String ?? UUID().uuidString,
                            senderRole: m["sender_role"] as? String ?? "me",
                            senderName: m["sender_name"] as? String ?? "Alex Mercer",
                            senderHandle: m["sender_handle"] as? String ?? "",
                            subject: m["subject"] as? String ?? "",
                            body: m["body"] as? String ?? "",
                            timestamp: m["timestamp"] as? String ?? "Recent",
                            deliveryStatus: m["delivery_status"] as? String ?? "Verified Sent",
                            scheduledFor: m["scheduled_for"] as? String ?? "",
                            queueEstimate: m["queue_estimate"] as? String ?? "",
                            attachments: m["attachments"] as? [String] ?? []
                        )
                    }
                    let tid = t["id"] as? String ?? UUID().uuidString
                    var mergedMsgs = msgs
                    if var localQueued = self.locallyQueuedMessagesByThreadId[tid], !localQueued.isEmpty {
                        localQueued.removeAll { lq in
                            mergedMsgs.contains(where: { $0.id == lq.id && !$0.isQueued && !$0.isPending })
                        }
                        for lq in localQueued {
                            if !mergedMsgs.contains(where: { $0.id == lq.id }) {
                                mergedMsgs.append(lq)
                            }
                        }
                        if localQueued.isEmpty {
                            self.locallyQueuedMessagesByThreadId.removeValue(forKey: tid)
                        } else {
                            self.locallyQueuedMessagesByThreadId[tid] = localQueued
                        }
                    }
                    let rawDeliveryState = t["delivery_state"] as? String ?? "sent"
                    let effectiveDeliveryState: String = {
                        if mergedMsgs.contains(where: { $0.isQueued }) { return "queued" }
                        if mergedMsgs.contains(where: { $0.isPending }) { return "pending" }
                        return rawDeliveryState
                    }()
                    let avPath = t["avatar_path"] as? String ?? ""
                    let avOrigPath = t["avatar_original_path"] as? String ?? ""
                    let incomingDraft = t["draft_text"] as? String ?? ""
                    let incomingAiDrafted = (t["ai_drafted"] as? Bool ?? false) || !incomingDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    if incomingAiDrafted && (self.localThreadDraftTextById[tid]?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty != true) {
                        self.aiGeneratedDraftThreadIds.insert(tid)
                    }
                    return OutreachThreadItem(
                        id: tid,
                        company: t["company"] as? String ?? "Target Employer",
                        role: t["role"] as? String ?? "Product Manager",
                        contactName: t["contact_name"] as? String ?? "Hiring Contact",
                        contactHandle: t["contact_handle"] as? String ?? "",
                        channel: t["channel"] as? String ?? "email",
                        channelLabel: t["channel_label"] as? String ?? "Email",
                        subject: t["subject"] as? String ?? "",
                        threadUrl: t["thread_url"] as? String ?? "",
                        profileUrl: t["profile_url"] as? String ?? "",
                        actionRequired: t["action_required"] as? Bool ?? false,
                        unreadInbound: t["unread_inbound"] as? Bool ?? false,
                        jevClassification: t["jev_classification"] as? String ?? "awaiting_recipient",
                        jevLabel: t["jev_label"] as? String ?? "Verified Sent",
                        jevSummary: t["jev_summary"] as? String ?? "",
                        jevModel: t["jev_model"] as? String ?? "~typesafe/jev-latest",
                        deliveryState: effectiveDeliveryState,
                        statusBadge: t["status_badge"] as? String ?? "Verified Sent",
                        lastActivityAt: t["last_activity_at"] as? String ?? "Recent",
                        draftText: t["draft_text"] as? String ?? "",
                        draftSubject: t["draft_subject"] as? String ?? "",
                        isCompanyContact: t["is_company_contact"] as? Bool ?? false,
                        avatarUrl: t["avatar_url"] as? String ?? "",
                        avatarPath: avPath,
                        avatarOriginalPath: avOrigPath,
                        messages: mergedMsgs
                    )
                }
                if self.selectedOutreachThreadId.isEmpty || self.outreachThreadsById[self.selectedOutreachThreadId] == nil {
                    self.selectedOutreachThreadId = ""
                } else if let activeThread = self.outreachThreadsById[prevSelectedId] {
                    // Never overwrite threadComposerText while the user is viewing/editing the same thread
                    if self.threadComposerSubject.isEmpty && self.localThreadDraftSubjectById[activeThread.id] == nil {
                        self.threadComposerSubject = activeThread.draftSubject.isEmpty
                            ? (activeThread.subject.lowercased().hasPrefix("re:") ? activeThread.subject : "Re: \(activeThread.subject)")
                            : activeThread.draftSubject
                    }
                }
            }
            if let rawEvents = ot["events"] as? [[String: Any]] {
                self.outreachEvents = rawEvents.map { e in
                    OutreachEventItem(
                        id: e["id"] as? String ?? UUID().uuidString,
                        company: e["company"] as? String ?? "Target Employer",
                        role: e["role"] as? String ?? "Product Manager",
                        contactName: e["contact_name"] as? String ?? "Hiring Contact",
                        channel: e["channel"] as? String ?? "linkedin_dm",
                        channelLabel: e["channel_label"] as? String ?? "LinkedIn DM",
                        contactValue: e["contact_value"] as? String ?? "",
                        contactUrl: e["contact_url"] as? String ?? "",
                        threadUrl: e["thread_url"] as? String ?? "",
                        subject: e["subject"] as? String ?? "",
                        messageText: e["message_text"] as? String ?? "",
                        status: e["status"] as? String ?? "",
                        statusCategory: e["status_category"] as? String ?? "verified_sent",
                        statusBadge: e["status_badge"] as? String ?? "Verified Sent",
                        sentAt: e["sent_at"] as? String ?? "Recent"
                    )
                }
                if self.selectedOutreachEventId.isEmpty || !self.outreachEvents.contains(where: { $0.id == self.selectedOutreachEventId }) {
                    self.selectedOutreachEventId = self.outreachEvents.first?.id ?? ""
                }
            }
            if let rawLi = ot["linkedin_connections"] as? [[String: Any]] {
                self.linkedinConnections = rawLi.map { c in
                    LinkedInConnectionItem(
                        id: c["id"] as? String ?? UUID().uuidString,
                        contactName: c["contact_name"] as? String ?? "LinkedIn Contact",
                        company: c["company"] as? String ?? "Target Employer",
                        role: c["role"] as? String ?? "Product Manager",
                        profileUrl: c["profile_url"] as? String ?? "",
                        threadUrl: c["thread_url"] as? String ?? "",
                        stage: c["stage"] as? String ?? "invite_pending",
                        statusLabel: c["status_label"] as? String ?? "Invitation Pending",
                        body: c["body"] as? String ?? "",
                        sentAt: c["sent_at"] as? String ?? "",
                        lastCheckedAt: c["last_checked_at"] as? String ?? ""
                    )
                }
                if self.selectedLinkedinConnectionId.isEmpty || !self.linkedinConnections.contains(where: { $0.id == self.selectedLinkedinConnectionId }) {
                    self.selectedLinkedinConnectionId = self.linkedinConnections.first(where: { $0.stage == "dm_sent" })?.id ?? self.linkedinConnections.first?.id ?? ""
                }
            }
            if let rawFq = ot["followup_queue"] as? [[String: Any]] {
                self.followUpQueueItems = rawFq.map { f in
                    FollowUpQueueItem(
                        id: f["id"] as? String ?? UUID().uuidString,
                        company: f["company"] as? String ?? "Employer",
                        role: f["role"] as? String ?? "Product Manager",
                        sourceUrl: f["source_url"] as? String ?? "",
                        stage: f["stage"] as? String ?? "applied",
                        stageLabel: f["stage_label"] as? String ?? "Follow-Up Review",
                        appliedAt: f["applied_at"] as? String ?? "",
                        ageDays: f["age_days"] as? Int ?? 0,
                        decision: f["decision"] as? String ?? "Pending review",
                        priority: f["priority"] as? Int ?? 1
                    )
                }
            }
            if let rawSupp = ot["suppressed_emails"] as? [[String: Any]] {
                self.suppressedEmails = rawSupp.map { s in
                    SuppressedEmailItem(
                        id: s["id"] as? String ?? UUID().uuidString,
                        email: s["email"] as? String ?? "",
                        company: s["company"] as? String ?? "",
                        reason: s["reason"] as? String ?? "",
                        statusCode: s["status_code"] as? String ?? "5.1.1",
                        diagnostic: s["diagnostic"] as? String ?? ""
                    )
                }
            }
        }

        if let hc = json["hermes_chat"] as? [String: Any] {
            self.hermesGatewayOnline = hc["gateway_online"] as? Bool ?? true
            self.hermesSandboxPath = hc["sandbox_path"] as? String ?? ""
            if !preserveLocalEdits {
                self.hermesProviderLabel = hc["provider_label"] as? String ?? "Logic: \(self.hermesLogicModel) • Copywriting: \(self.hermesWriterModel)"
                self.hermesModelName = hc["model_name"] as? String ?? "Claude Sonnet Latest (~anthropic/claude-sonnet-latest)"
                if let lm = hc["logic_model"] as? String, !lm.isEmpty {
                    self.hermesLogicModel = AIModelChoiceItem.normalizeLogicModelId(lm)
                }
                if let wm = hc["writer_model"] as? String, !wm.isEmpty {
                    self.hermesWriterModel = (wm == "anthropic/claude-sonnet-5.5") ? "~anthropic/claude-sonnet-latest" : wm
                }
                if let lre = hc["logic_reasoning_effort"] as? String, !lre.isEmpty {
                    self.hermesLogicReasoningEffort = lre.lowercased()
                }
                if let wre = hc["writer_reasoning_effort"] as? String, !wre.isEmpty {
                    self.hermesWriterReasoningEffort = wre.lowercased()
                }
            }

            if let rawSkills = hc["skills"] as? [[String: Any]] {
                self.hermesSkills = rawSkills.map { sk in
                    HermesSkillItem(
                        id: sk["id"] as? String ?? UUID().uuidString,
                        name: sk["name"] as? String ?? "",
                        description: sk["description"] as? String ?? ""
                    )
                }
            }

            if let rawSessions = hc["sessions"] as? [[String: Any]] {
                let parsedSessions: [HermesChatSessionItem] = rawSessions.map { s in
                    let rawMsgs = s["messages"] as? [[String: Any]] ?? []
                    let msgs: [HermesChatMessageItem] = rawMsgs.map { m in
                        let rawAtts = m["attachments"] as? [[String: Any]] ?? []
                        let atts: [HermesAttachmentItem] = rawAtts.map { a in
                            HermesAttachmentItem(
                                id: a["id"] as? String ?? UUID().uuidString,
                                name: a["name"] as? String ?? "File",
                                path: a["path"] as? String ?? "",
                                kind: a["kind"] as? String ?? "file",
                                extensionName: a["extension"] as? String ?? "file",
                                sizeLabel: a["size_label"] as? String ?? ""
                            )
                        }
                        let rawTools = m["tool_calls"] as? [[String: Any]] ?? []
                        let tools: [HermesToolCallItem] = rawTools.map { t in
                            HermesToolCallItem(
                                name: t["name"] as? String ?? "hermes_tool",
                                status: t["status"] as? String ?? "completed",
                                summary: t["summary"] as? String ?? ""
                            )
                        }
                        return HermesChatMessageItem(
                            id: m["id"] as? String ?? UUID().uuidString,
                            role: m["role"] as? String ?? "assistant",
                            content: m["content"] as? String ?? "",
                            timestamp: m["timestamp"] as? String ?? "",
                            attachments: atts,
                            toolCalls: tools
                        )
                    }
                    return HermesChatSessionItem(
                        id: s["id"] as? String ?? UUID().uuidString,
                        title: s["title"] as? String ?? "Agent Session",
                        createdAt: s["created_at"] as? String ?? "",
                        updatedAt: s["updated_at"] as? String ?? "",
                        model: s["model"] as? String ?? "anthropic/claude-sonnet-4.5",
                        messages: msgs
                    )
                }
                self.hermesSessions = parsedSessions

                let serverUnread = hc["unread_count"] as? Int ?? 0
                let allAssistantMsgs: [HermesChatMessageItem] = parsedSessions.flatMap { sess in
                    sess.messages.filter { $0.role == "assistant" }
                }
                if !self.hasInitializedAssistantMessages {
                    self.hasInitializedAssistantMessages = true
                    for m in allAssistantMsgs {
                        self.knownAssistantMessageIds.insert(m.id)
                    }
                    if self.selectedSection != .agentChat && serverUnread > 0 {
                        self.unreadAgentMessagesCount = serverUnread
                        NSApplication.shared.dockTile.badgeLabel = "\(serverUnread)"
                    }
                } else {
                    var newlyArrived: [HermesChatMessageItem] = []
                    for m in allAssistantMsgs {
                        if !self.knownAssistantMessageIds.contains(m.id) {
                            self.knownAssistantMessageIds.insert(m.id)
                            newlyArrived.append(m)
                        }
                    }
                    let isChatInFocus = (self.selectedSection == .agentChat) && NSApplication.shared.isActive
                    if !newlyArrived.isEmpty && !isChatInFocus {
                        self.unreadAgentMessagesCount = max(self.unreadAgentMessagesCount + newlyArrived.count, serverUnread)
                        NSApplication.shared.dockTile.badgeLabel = "\(self.unreadAgentMessagesCount)"
                        if let latest = newlyArrived.last {
                            self.deliverAgentChatNotification(message: latest.content)
                        }
                    } else if serverUnread > self.unreadAgentMessagesCount && !isChatInFocus {
                        self.unreadAgentMessagesCount = serverUnread
                        NSApplication.shared.dockTile.badgeLabel = "\(self.unreadAgentMessagesCount)"
                        if let latest = allAssistantMsgs.last {
                            self.deliverAgentChatNotification(message: latest.content)
                        }
                    } else if isChatInFocus && (self.unreadAgentMessagesCount > 0 || serverUnread > 0) {
                        self.markAgentChatRead()
                    }
                }
            }

            let serverActiveId = hc["active_session_id"] as? String ?? ""
            if !serverActiveId.isEmpty {
                self.activeHermesSessionId = serverActiveId
            } else if self.activeHermesSessionId.isEmpty, let firstSess = self.hermesSessions.first {
                self.activeHermesSessionId = firstSess.id
            }
        }

        if let ac = json["activity_center"] as? [String: Any] {
            let eng = ac["engine_status"] as? [String: Any] ?? [:]
            let sum = ac["summary"] as? [String: Any] ?? [:]
            let isRun = (eng["is_running"] as? Bool) ?? !self.emergencyStopActive
            self.activitySummary = ActivityCenterSummaryItem(
                isRunning: isRun,
                statusLabel: eng["status_label"] as? String ?? (isRun ? "Running" : "Paused"),
                statusHeadline: eng["status_headline"] as? String ?? (isRun ? "Autonomous Agents Running" : "Autonomous Agents Paused"),
                statusSubtitle: eng["status_subtitle"] as? String ?? "",
                totalActivitiesCount: sum["total_activities_count"] as? Int ?? 0,
                appliedCount: sum["applied_count"] as? Int ?? 0,
                filledNotSubmittedCount: sum["filled_not_submitted_count"] as? Int ?? 0,
                messagedCount: sum["messaged_count"] as? Int ?? 0,
                resumesTailoredCount: sum["resumes_tailored_count"] as? Int ?? 0,
                periodicRunsCount: sum["periodic_runs_count"] as? Int ?? 0,
                activeLanesCount: sum["active_lanes_count"] as? Int ?? (eng["active_lanes_count"] as? Int ?? 0),
                enabledLanesCount: sum["enabled_lanes_count"] as? Int ?? (eng["enabled_lanes_count"] as? Int ?? 0),
                pausedLanesCount: sum["paused_lanes_count"] as? Int ?? (eng["paused_lanes_count"] as? Int ?? 0),
                totalLanesCount: sum["total_lanes_count"] as? Int ?? (eng["total_lanes_count"] as? Int ?? 0),
                totalRunsCompleted: sum["total_runs_completed"] as? Int ?? (eng["total_runs_completed"] as? Int ?? 0)
            )
            if let rawLanes = ac["worker_lanes"] as? [[String: Any]] {
                self.workerLanes = rawLanes.map { w in
                    WorkerLaneTaskItem(
                        id: w["id"] as? String ?? UUID().uuidString,
                        title: w["title"] as? String ?? "Worker Lane",
                        category: w["category"] as? String ?? "Application Worker",
                        icon: w["icon"] as? String ?? "paperplane.circle.fill",
                        platforms: w["platforms"] as? String ?? "",
                        description: w["description"] as? String ?? "",
                        frequencyLabel: w["frequency_label"] as? String ?? "Periodic Schedule",
                        enabled: w["enabled"] as? Bool ?? false,
                        isActivelyRunning: w["is_actively_running"] as? Bool ?? false,
                        statusState: w["status_state"] as? String ?? "paused",
                        statusLabel: w["status_label"] as? String ?? "Standby • Paused",
                        completedRuns: w["completed_runs"] as? Int ?? 0,
                        lastRunAt: w["last_run_at"] as? String ?? "",
                        lastRunLabel: w["last_run_label"] as? String ?? "Not run yet",
                        nextRunAt: w["next_run_at"] as? String ?? "",
                        nextRunLabel: w["next_run_label"] as? String ?? "Paused",
                        lastStatus: w["last_status"] as? String ?? "ok"
                    )
                }
            }
            if let rawActs = ac["activities"] as? [[String: Any]] {
                self.unifiedActivities = rawActs.map { a in
                    UnifiedActivityEventItem(
                        id: a["id"] as? String ?? UUID().uuidString,
                        category: a["category"] as? String ?? "applied",
                        categoryLabel: a["category_label"] as? String ?? "Applied",
                        statusBadge: a["status_badge"] as? String ?? "Submitted",
                        badgeColor: a["badge_color"] as? String ?? "green",
                        icon: a["icon"] as? String ?? "checkmark.seal.fill",
                        title: a["title"] as? String ?? "Activity",
                        subtitle: a["subtitle"] as? String ?? "",
                        platform: a["platform"] as? String ?? "",
                        detail: a["detail"] as? String ?? "",
                        timestamp: a["timestamp"] as? String ?? "Recent",
                        url: a["url"] as? String ?? "",
                        jobId: a["job_id"] as? String ?? "",
                        threadId: a["thread_id"] as? String ?? "",
                        documentId: a["document_id"] as? String ?? ""
                    )
                }
            }
        }

        if let rawVault = json["password_vault"] as? [[String: Any]] {
            self.passwordVaultEntries = rawVault.map { e in
                let pwd = e["password"] as? String ?? ""
                return PasswordVaultEntryItem(
                    id: e["id"] as? String ?? UUID().uuidString,
                    websiteName: e["website_name"] as? String ?? "Career Portal",
                    websiteUrl: e["website_url"] as? String ?? "",
                    username: e["username"] as? String ?? "",
                    password: pwd,
                    passwordLength: e["password_length"] as? Int ?? pwd.count,
                    totpToken: e["totp_token"] as? String ?? "",
                    totpCurrentCode: e["totp_current_code"] as? String ?? "",
                    description: e["description"] as? String ?? "",
                    autoRegistered: e["auto_registered"] as? Bool ?? false,
                    createdAt: e["created_at"] as? String ?? "",
                    updatedAt: e["updated_at"] as? String ?? ""
                )
            }
        }

        if let fs = json["feedback_staging"] as? [String: Any] {
            if let dp = fs["desktop_screenshot_path"] as? String, !dp.isEmpty {
                self.feedbackDesktopScreenshotPath = dp
            }
            if let ds = fs["desktop_screenshot_size"] as? String, !ds.isEmpty {
                self.feedbackDesktopScreenshotSize = ds
            }
            let bp = fs["browser_screenshot_path"] as? String ?? ""
            let bs = fs["browser_screenshot_size"] as? String ?? ""
            let bu = fs["browser_url"] as? String ?? ""
            let bt = fs["browser_title"] as? String ?? ""
            if bp.isEmpty || !FileManager.default.fileExists(atPath: bp) {
                self.feedbackBrowserScreenshotPath = ""
                self.feedbackBrowserScreenshotSize = ""
                self.feedbackBrowserUrl = ""
                self.feedbackBrowserTitle = ""
                self.feedbackIncludeBrowserScreenshot = false
            } else {
                self.feedbackBrowserScreenshotPath = bp
                self.feedbackBrowserScreenshotSize = bs
                self.feedbackBrowserUrl = bu
                self.feedbackBrowserTitle = bt
                self.feedbackIncludeBrowserScreenshot = true
            }
        }

        if let rawFeedback = json["feedback_submissions"] as? [[String: Any]] {
            self.feedbackSubmissions = rawFeedback.map { f in
                let rawAtts = f["attachments"] as? [[String: Any]] ?? []
                return FeedbackSubmissionRecordItem(
                    id: f["id"] as? String ?? UUID().uuidString,
                    classification: f["classification"] as? String ?? "bug",
                    classificationLabel: f["classification_label"] as? String ?? "Bug Report",
                    comment: f["comment"] as? String ?? "",
                    appSection: f["app_section"] as? String ?? "",
                    browserUrl: f["browser_url"] as? String ?? "",
                    createdAt: f["created_at"] as? String ?? "",
                    deliveryStatus: f["delivery_status"] as? String ?? "staged_locally",
                    attachmentsCount: rawAtts.count,
                    bundlePath: f["bundle_path"] as? String ?? ""
                )
            }
        }
        self.hasLoadedInitialWorkspaceState = true
    }

    @MainActor
    public static func generateStrongRandomPassword(length: Int = 20) -> String {
        let targetLen = (length <= 12) ? 12 : length
        let upper = Array("ABCDEFGHJKLMNPQRSTUVWXYZ")
        let lower = Array("abcdefghijkmnopqrstuvwxyz")
        let digits = Array("0123456789")
        let specials = Array("!@#$%^&*()-_=+")
        let allChars = upper + lower + digits + specials

        let minPerClass = targetLen <= 12 ? 2 : 3
        var chars: [Character] = []
        for pool in [upper, lower, digits, specials] {
            for _ in 0..<minPerClass {
                if let ch = pool.randomElement() {
                    chars.append(ch)
                }
            }
        }
        while chars.count < targetLen {
            if let ch = allChars.randomElement() {
                chars.append(ch)
            }
        }
        chars.shuffle()
        if let first = chars.first, !first.isLetter {
            if let letterIdx = chars.firstIndex(where: { $0.isLetter }) {
                chars.swapAt(0, letterIdx)
            }
        }
        return String(chars.prefix(targetLen))
    }

