    @MainActor
    public func addHermesAttachmentPath(_ path: String, customLabel: String = "") {
        let trimmed = path.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, FileManager.default.fileExists(atPath: trimmed) else { return }
        if hermesPendingAttachments.contains(where: { $0.path == trimmed }) { return }
        let url = URL(fileURLWithPath: trimmed)
        let ext = url.pathExtension.lowercased()
        let kind: String
        if ["png", "jpg", "jpeg", "webp", "gif", "heic"].contains(ext) {
            kind = "image"
        } else if ["pdf", "docx", "doc", "rtf"].contains(ext) {
            kind = "document"
        } else if ["md", "txt", "json", "csv", "yaml", "yml", "py", "js", "ts", "swift", "html"].contains(ext) {
            kind = "text"
        } else if ["wav", "mp3", "m4a"].contains(ext) {
            kind = "audio"
        } else {
            kind = "file"
        }
        let attrs = try? FileManager.default.attributesOfItem(atPath: trimmed)
        let bytes = (attrs?[.size] as? NSNumber)?.intValue ?? 0
        let sizeLabel: String
        if bytes < 1024 {
            sizeLabel = "\(bytes) B"
        } else if bytes < 1024 * 1024 {
            sizeLabel = String(format: "%.1f KB", Double(bytes) / 1024.0)
        } else {
            sizeLabel = String(format: "%.1f MB", Double(bytes) / (1024.0 * 1024.0))
        }
        hermesPendingAttachments.append(
            HermesAttachmentItem(
                id: UUID().uuidString,
                name: customLabel.isEmpty ? url.lastPathComponent : customLabel,
                path: trimmed,
                kind: kind,
                extensionName: ext.isEmpty ? "file" : ext,
                sizeLabel: sizeLabel
            )
        )
    }

