    @MainActor
    public func sendHermesChatMessage(quickPrompt: String? = nil) {
        let text = (quickPrompt ?? hermesPromptInput).trimmingCharacters(in: .whitespacesAndNewlines)
        let pendingAtts = hermesPendingAttachments
        guard !text.isEmpty || !pendingAtts.isEmpty else { return }

        let displayMsg = text.isEmpty ? "Please analyze the attached file(s): \(pendingAtts.map(\.name).joined(separator: ", "))" : text
        let sessId = activeHermesSession?.id ?? activeHermesSessionId
        if quickPrompt == nil {
            hermesPromptInput = ""
        }
        hermesPendingAttachments = []
        isHermesSending = true

        // Optimistically append user message to active session so UI feels instantaneous
        if let idx = hermesSessions.firstIndex(where: { $0.id == sessId }) {
            let optimisticUserMsg = HermesChatMessageItem(
                id: "optimistic_\(UUID().uuidString.prefix(8))",
                role: "user",
                content: displayMsg,
                timestamp: "Just now",
                attachments: pendingAtts,
                toolCalls: []
            )
            hermesSessions[idx].messages.append(optimisticUserMsg)
        }

        let attPayload: [[String: String]] = pendingAtts.map { a in
            ["path": a.path, "name": a.name]
        }
        sendActionInBackground(
            "send_hermes_chat_message",
            payload: [
                "session_id": sessId,
                "message": displayMsg,
                "prompt": displayMsg,
                "attachments": attPayload,
                "attachment_paths": pendingAtts.map(\.path),
                "selected_job_id": hermesSelectedJobId,
                "selected_kb_section_id": hermesSelectedKbSectionId,
                "chat_not_in_focus": (selectedSection != .agentChat) || !NSApplication.shared.isActive,
            ],
            silent: true,
            preserveLocalEdits: true
        ) { [weak self] in
            self?.isHermesSending = false
        }
    }

