    @MainActor
    public func updateAIModels(
        logicModel: String? = nil,
        writerModel: String? = nil,
        logicReasoningEffort: String? = nil,
        writerReasoningEffort: String? = nil
    ) {
        if let lm = logicModel?.trimmingCharacters(in: .whitespacesAndNewlines), !lm.isEmpty {
            hermesLogicModel = AIModelChoiceItem.normalizeLogicModelId(lm)
        }
        if let wm = writerModel?.trimmingCharacters(in: .whitespacesAndNewlines), !wm.isEmpty {
            hermesWriterModel = wm
        }
        if let lre = logicReasoningEffort?.lowercased(), ["low", "medium", "high"].contains(lre) {
            hermesLogicReasoningEffort = lre
        }
        if let wre = writerReasoningEffort?.lowercased(), ["low", "medium", "high"].contains(wre) {
            hermesWriterReasoningEffort = wre
        }
        hermesProviderLabel = "Chat: \(AIModelChoiceItem.shortLogicTitle(for: hermesLogicModel)) • Writing: \(AIModelChoiceItem.shortWriterTitle(for: hermesWriterModel))"
        hermesModelName = AIModelChoiceItem.shortLogicTitle(for: hermesLogicModel)
        statusBannerMessage = "Models updated: \(AIModelChoiceItem.shortLogicTitle(for: hermesLogicModel)) for chat, \(AIModelChoiceItem.shortWriterTitle(for: hermesWriterModel)) for writing."
        sendActionInBackground(
            "save_model_selection",
            payload: [
                "logic_model": hermesLogicModel,
                "writer_model": hermesWriterModel,
                "logic_reasoning_effort": hermesLogicReasoningEffort,
                "writer_reasoning_effort": hermesWriterReasoningEffort,
            ],
            silent: true,
            preserveLocalEdits: true
        )
    }

