    @MainActor
    public func deliverAgentChatNotification(message: String) {
        let cleaned = message
            .replacingOccurrences(of: "#", with: "")
            .replacingOccurrences(of: "*", with: "")
            .replacingOccurrences(of: "`", with: "")
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        let preview = cleaned.count > 120 ? String(cleaned.prefix(120)) + "…" : cleaned
        self.latestUnreadAgentNotificationPreview = preview.isEmpty ? "AutoApply AI Agent sent a new message." : preview

        NSSound(named: "Glass")?.play()

        if Bundle.main.bundleIdentifier != nil {
            let center = UNUserNotificationCenter.current()
            center.requestAuthorization(options: [.alert, .sound, .badge]) { granted, _ in
                guard granted else { return }
                let content = UNMutableNotificationContent()
                content.title = "AutoApply AI Agent"
                content.body = preview.isEmpty ? "New message in AI Agent chat." : preview
                content.sound = .default
                let req = UNNotificationRequest(
                    identifier: "autoapply.agent.msg.\(UUID().uuidString.prefix(8))",
                    content: content,
                    trigger: nil
                )
                center.add(req, withCompletionHandler: nil)
            }
        }
    }

