    public var filteredJobs: [JobItem] {
        let baseFiltered = jobs.enumerated().filter { _, job in
            let matchesPipeline: Bool
            switch jobPipelineFilter {
            case "not_applied": matchesPipeline = job.pipelineStage == "not_applied"
            case "applying": matchesPipeline = job.pipelineStage == "applying"
            case "submitted": matchesPipeline = job.pipelineStage == "submitted"
            case "failed": matchesPipeline = job.pipelineStage == "failed"
            default: matchesPipeline = true
            }
            guard matchesPipeline else { return false }

            let matchesEligibility: Bool
            switch jobEligibilityFilter {
            case "eligible": matchesEligibility = job.eligible
            case "not_eligible": matchesEligibility = !job.eligible
            default: matchesEligibility = true
            }
            guard matchesEligibility else { return false }

            let q = jobSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            guard !q.isEmpty else { return true }
            return job.title.lowercased().contains(q)
                || job.companyName.lowercased().contains(q)
                || job.locationLabel.lowercased().contains(q)
                || job.failureReason.lowercased().contains(q)
                || job.filterSummary.lowercased().contains(q)
                || job.matchTier.lowercased().contains(q)
                || job.matchedSkills.contains(where: { $0.lowercased().contains(q) })
        }
        if jobSortOrder == "best_match" {
            return baseFiltered.sorted { lhs, rhs in
                if lhs.element.matchScorePct != rhs.element.matchScorePct {
                    return lhs.element.matchScorePct > rhs.element.matchScorePct
                }
                let lDate = lhs.element.postedAt.trimmingCharacters(in: .whitespacesAndNewlines)
                let rDate = rhs.element.postedAt.trimmingCharacters(in: .whitespacesAndNewlines)
                if lDate != rDate {
                    return lDate > rDate
                }
                if lhs.element.eligible != rhs.element.eligible {
                    return lhs.element.eligible && !rhs.element.eligible
                }
                return lhs.offset < rhs.offset
            }.map(\.element)
        }
        return baseFiltered.sorted { lhs, rhs in
            let lDate = lhs.element.postedAt.trimmingCharacters(in: .whitespacesAndNewlines)
            let rDate = rhs.element.postedAt.trimmingCharacters(in: .whitespacesAndNewlines)
            if lDate != rDate {
                return lDate > rDate
            }
            if lhs.element.matchScorePct != rhs.element.matchScorePct {
                return lhs.element.matchScorePct > rhs.element.matchScorePct
            }
            return lhs.offset < rhs.offset
        }.map(\.element)
    }

    @MainActor
    public func moveJobToStage(_ jobId: String, targetStage: String) {
        let trimmedId = jobId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedId.isEmpty else { return }
        guard let idx = jobs.firstIndex(where: { $0.jobId == trimmedId }) else { return }
        let oldStage = jobs[idx].pipelineStage
        if oldStage == targetStage {
            draggingJobId = ""
            dropTargetColumnKey = ""
            return
        }
        withAnimation(.easeInOut(duration: 0.16)) {
            jobs[idx].previousPipelineStage = oldStage
            jobs[idx].pipelineStage = targetStage
            jobs[idx].state = (targetStage == "submitted") ? "submitted_verified" : (targetStage == "applying" ? "applying" : (targetStage == "failed" ? "failed" : "ready_to_submit"))
            if jobPipelineFilter != "all" && jobPipelineFilter != targetStage {
                jobPipelineFilter = "all"
            }
            draggingJobId = ""
            dropTargetColumnKey = ""
        }
        sendActionInBackground(
            "set_job_pipeline_stage",
            payload: [
                "job_id": trimmedId,
                "pipeline_stage": targetStage
            ],
            silent: true
        )
    }

