    private static func threadSortTimestampKey(_ rawTs: String) -> String {
        let s = rawTs.trimmingCharacters(in: .whitespacesAndNewlines)
        if s.count >= 16 {
            let prefix10 = String(s.prefix(10))
            let chars = Array(prefix10)
            if chars.count == 10 && chars[4] == "-" && chars[7] == "-" {
                return String(s.prefix(16)).replacingOccurrences(of: "T", with: " ")
            }
        } else if s.count == 10 {
            let chars = Array(s)
            if chars.count == 10 && chars[4] == "-" && chars[7] == "-" {
                return "\(s) 00:00"
            }
        }
        return "0000-00-00 00:00"
    }

    public static func parseAnalysisTimestamp(_ rawTs: String) -> Date? {
        let trimmed = rawTs.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        let isoFrac = ISO8601DateFormatter()
        isoFrac.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        if let d = isoFrac.date(from: trimmed) {
            return d
        }
        let isoStd = ISO8601DateFormatter()
        isoStd.formatOptions = [.withInternetDateTime]
        if let d = isoStd.date(from: trimmed) {
            return d
        }
        let df = DateFormatter()
        df.locale = Locale(identifier: "en_US_POSIX")
        df.timeZone = TimeZone.current
        df.dateFormat = "yyyy-MM-dd HH:mm"
        if let d = df.date(from: String(trimmed.prefix(16)).replacingOccurrences(of: "T", with: " ")) {
            return d
        }
        return nil
    }

    public func isMessageAnalysisStale(maxAgeSeconds: TimeInterval = 3600) -> Bool {
        if lastMessageAnalysisDate == nil && !lastMessageAnalysisAt.isEmpty {
            lastMessageAnalysisDate = Self.parseAnalysisTimestamp(lastMessageAnalysisAt)
        }
        guard let lastDate = lastMessageAnalysisDate else {
            return true
        }
        return Date().timeIntervalSince(lastDate) >= maxAgeSeconds
    }

    public func syncAndAnalyzeMessagesIfNeeded(force: Bool = false, maxAgeSeconds: TimeInterval = 3600, silent: Bool = true) {
        guard !isSyncingMessages && !emergencyStopActive && !isForceUpdateLocked else { return }
        guard force || isMessageAnalysisStale(maxAgeSeconds: maxAgeSeconds) else { return }
        isSyncingMessages = true
        sendActionInBackground(
            "sync_and_analyze_messages",
            payload: [
                "force": force,
                "if_stale_only": !force,
                "max_age_seconds": Int(maxAgeSeconds),
            ],
            silent: silent,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            self.isSyncingMessages = false
            self.lastMessageAnalysisDate = Date()
        }
    }

    private func rebuildOutreachCaches(resetPagination: Bool) {
        var counts = OutreachCountsSnapshot()
        counts.allCount = outreachThreads.count

        var byId: [String: OutreachThreadItem] = Dictionary(minimumCapacity: outreachThreads.count)
        var filtered: [OutreachThreadItem] = []
        filtered.reserveCapacity(outreachThreads.count)
        var filteredIds = Set<String>(minimumCapacity: outreachThreads.count)

        let subView = outreachSubView
        let actionFilter = outreachActionFilter
        let q = outreachSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        var totalActionReqAllChannels = 0

        let sortedThreads = outreachThreads.enumerated().sorted { lhs, rhs in
            let lKey = Self.threadSortTimestampKey(lhs.element.lastActivityAt)
            let rKey = Self.threadSortTimestampKey(rhs.element.lastActivityAt)
            if lKey != rKey {
                return lKey > rKey
            }
            return lhs.offset < rhs.offset
        }.map(\.element)

        for th in sortedThreads {
            byId[th.id] = th
            if th.actionRequired {
                totalActionReqAllChannels += 1
            }

            switch th.channel {
            case "email": counts.emailCount += 1
            case "linkedin": counts.linkedinCount += 1
            case "hh": counts.hhCount += 1
            case "imessage": counts.imessageCount += 1
            default: break
            }

            let matchesChannel: Bool
            switch subView {
            case "email": matchesChannel = th.channel == "email"
            case "linkedin": matchesChannel = th.channel == "linkedin"
            case "hh": matchesChannel = th.channel == "hh"
            case "imessage": matchesChannel = th.channel == "imessage"
            default: matchesChannel = true
            }
            guard matchesChannel else { continue }

            counts.channelScopedCount += 1
            if th.actionRequired {
                counts.actionRequiredCount += 1
                switch th.actionRequiredDisplayLabel {
                case "Online Assessment": counts.onlineAssessmentCount += 1
                case "Real Interview": counts.realInterviewCount += 1
                case "Details Requested": counts.detailsRequestedCount += 1
                default: break
                }
            }
            if th.isFollowUp { counts.followUpCount += 1 }
            if th.isSubmittedConfirmation { counts.submittedConfirmationCount += 1 }
            if th.isRejectedThread { counts.rejectedCount += 1 }
            if th.hasInboundReply { counts.repliedCount += 1 }
            if th.isQueuedThread { counts.queuedCount += 1 }
            if th.deliveryState == "invite_pending" { counts.invitePendingCount += 1 }

            var matchesAction: Bool
            switch actionFilter {
            case "action_required": matchesAction = th.actionRequired
            case "online_assessment": matchesAction = th.actionRequired && th.actionRequiredDisplayLabel == "Online Assessment"
            case "real_interview": matchesAction = th.actionRequired && th.actionRequiredDisplayLabel == "Real Interview"
            case "details_requested": matchesAction = th.actionRequired && th.actionRequiredDisplayLabel == "Details Requested"
            case "followup": matchesAction = th.isFollowUp
            case "submitted_confirmation": matchesAction = th.isSubmittedConfirmation
            case "rejected": matchesAction = th.isRejectedThread
            case "replied": matchesAction = th.hasInboundReply
            case "queued": matchesAction = th.isQueuedThread
            case "invite_pending": matchesAction = (th.deliveryState == "invite_pending")
            default: matchesAction = true
            }
            if !matchesAction && th.id == selectedOutreachThreadId && (th.isQueuedThread || th.isPendingThread) {
                matchesAction = true
            }
            guard matchesAction else { continue }

            if !q.isEmpty && !th.searchableTextLower.contains(q) {
                continue
            }
            filtered.append(th)
            filteredIds.insert(th.id)
        }

        outreachThreadsById = byId
        cachedFilteredOutreachThreads = filtered
        cachedFilteredOutreachThreadIds = filteredIds
        if outreachCounts != counts {
            outreachCounts = counts
        }
        if !outreachThreads.isEmpty && outreachSummary.actionRequiredCount != totalActionReqAllChannels {
            outreachSummary.actionRequiredCount = totalActionReqAllChannels
        }
        if resetPagination {
            if outreachVisiblePageLimit != Self.outreachPageSize {
                outreachVisiblePageLimit = Self.outreachPageSize
            }
        }
    }

    public var filteredOutreachThreads: [OutreachThreadItem] {
        cachedFilteredOutreachThreads
    }

    public var selectedOutreachThread: OutreachThreadItem? {
        guard !selectedOutreachThreadId.isEmpty,
              cachedFilteredOutreachThreadIds.contains(selectedOutreachThreadId) else {
            return nil
        }
        return outreachThreadsById[selectedOutreachThreadId]
    }

    @MainActor
    public func loadMoreOutreachThreadsIfNeeded(currentIndex: Int) {
        let total = cachedFilteredOutreachThreads.count
        guard outreachVisiblePageLimit < total else { return }
        if currentIndex >= max(0, outreachVisiblePageLimit - 8) {
            outreachVisiblePageLimit = min(total, outreachVisiblePageLimit + Self.outreachPageSize)
        }
    }

    @MainActor
    public func loadNextOutreachThreadsPage() {
        let total = cachedFilteredOutreachThreads.count
        guard outreachVisiblePageLimit < total else { return }
        outreachVisiblePageLimit = min(total, outreachVisiblePageLimit + Self.outreachPageSize)
    }

    @MainActor
    public func loadEarlierTranscriptMessages(totalCount: Int) {
        guard transcriptVisibleMessageLimit < totalCount else { return }
        transcriptVisibleMessageLimit = min(totalCount, transcriptVisibleMessageLimit + Self.transcriptPageSize)
    }

    @MainActor
    public func selectOutreachThread(_ thread: OutreachThreadItem) {
        if !selectedOutreachThreadId.isEmpty,
           let prevThread = outreachThreadsById[selectedOutreachThreadId] {
            let prevDefaultSubj = prevThread.draftSubject.isEmpty
                ? (prevThread.subject.lowercased().hasPrefix("re:") ? prevThread.subject : "Re: \(prevThread.subject)")
                : prevThread.draftSubject
            localThreadDraftTextById[selectedOutreachThreadId] = threadComposerText
            if threadComposerSubject != prevDefaultSubj {
                localThreadDraftSubjectById[selectedOutreachThreadId] = threadComposerSubject
            }
        }
        isClearingComposerProgrammatically = true
        let defaultSubj = thread.draftSubject.isEmpty
            ? (thread.subject.lowercased().hasPrefix("re:") ? thread.subject : "Re: \(thread.subject)")
            : thread.draftSubject
        threadComposerSubject = localThreadDraftSubjectById[thread.id] ?? defaultSubj
        threadComposerText = localThreadDraftTextById[thread.id] ?? thread.draftText
        selectedOutreachThreadId = thread.id
        DispatchQueue.main.async { [weak self] in
            self?.isClearingComposerProgrammatically = false
        }
        if transcriptVisibleMessageLimit != Self.transcriptPageSize {
            transcriptVisibleMessageLimit = Self.transcriptPageSize
        }
        if let idx = cachedFilteredOutreachThreads.firstIndex(where: { $0.id == thread.id }),
           idx >= outreachVisiblePageLimit {
            outreachVisiblePageLimit = min(
                cachedFilteredOutreachThreads.count,
                ((idx / Self.outreachPageSize) + 1) * Self.outreachPageSize
            )
        }
        requestThreadAvatarIfNeeded(thread)
    }

    @MainActor
    public func clearSelectedThreadDraft() {
        threadComposerText = ""
        if let th = selectedOutreachThread {
            localThreadDraftTextById[th.id] = ""
            aiGeneratedDraftThreadIds.remove(th.id)
            sendActionInBackground(
                "clear_thread_draft",
                payload: [
                    "thread_id": th.id,
                    "company": th.company,
                    "contact_name": th.contactName,
                    "channel": th.channel,
                ],
                silent: true,
                preserveLocalEdits: true
            )
        }
    }

    @MainActor
    public func deleteOutreachThread(_ thread: OutreachThreadItem) {
        let removedId = thread.id
        let visibleList = filteredOutreachThreads
        var nextSelected: OutreachThreadItem? = nil
        if selectedOutreachThreadId == removedId {
            if let idx = visibleList.firstIndex(where: { $0.id == removedId }) {
                if idx + 1 < visibleList.count {
                    nextSelected = visibleList[idx + 1]
                } else if idx > 0 {
                    nextSelected = visibleList[idx - 1]
                }
            }
        }
        outreachThreads.removeAll { $0.id == removedId }
        localThreadDraftTextById.removeValue(forKey: removedId)
        localThreadDraftSubjectById.removeValue(forKey: removedId)
        aiGeneratedDraftThreadIds.remove(removedId)
        if selectedOutreachThreadId == removedId {
            if let next = nextSelected ?? filteredOutreachThreads.first ?? outreachThreads.first {
                selectOutreachThread(next)
            } else {
                selectedOutreachThreadId = ""
                threadComposerText = ""
                threadComposerSubject = ""
            }
        }
        sendAction("delete_outreach_thread", payload: ["thread_id": removedId])
    }

    @MainActor
    public func setOutreachThreadStatus(_ thread: OutreachThreadItem, status: String) {
        let tid = thread.id
        let norm = status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let prevVisibleList = filteredOutreachThreads
        let wasSelected = (selectedOutreachThreadId == tid)
        var nextCandidate: OutreachThreadItem? = nil
        if wasSelected, let vIdx = prevVisibleList.firstIndex(where: { $0.id == tid }) {
            if vIdx + 1 < prevVisibleList.count {
                nextCandidate = prevVisibleList[vIdx + 1]
            } else if vIdx > 0 {
                nextCandidate = prevVisibleList[vIdx - 1]
            }
        }

        if norm != "auto" {
            if let idx = outreachThreads.firstIndex(where: { $0.id == tid }) {
                outreachThreads[idx] = outreachThreads[idx].withManualStatus(norm)
            }
        }

        if wasSelected {
            if cachedFilteredOutreachThreadIds.contains(tid) {
                selectedOutreachThreadId = tid
            } else if let candidate = nextCandidate, cachedFilteredOutreachThreadIds.contains(candidate.id) {
                selectOutreachThread(candidate)
            } else if let firstMatch = filteredOutreachThreads.first {
                selectOutreachThread(firstMatch)
            } else {
                selectedOutreachThreadId = ""
                threadComposerText = ""
                threadComposerSubject = ""
            }
        }

        let cleanComp = thread.company.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanContact = thread.contactName.trimmingCharacters(in: .whitespacesAndNewlines)
        let whoLabel: String = {
            if !cleanContact.isEmpty && !cleanComp.isEmpty && !cleanContact.localizedCaseInsensitiveContains(cleanComp) {
                return "\(cleanContact) (\(cleanComp))"
            }
            return cleanContact.isEmpty ? (cleanComp.isEmpty ? tid : cleanComp) : cleanContact
        }()

        switch norm {
        case "online_assessment", "action_required_online_assessment", "assessment":
            statusBannerMessage = "Reclassified as Online Assessment\nMoved \(whoLabel) to Online Assessment."
        case "real_interview", "action_required_real_interview", "interview":
            statusBannerMessage = "Reclassified as Real Interview\nMoved \(whoLabel) to Real Interview."
        case "details_requested", "action_required_details_requested", "details":
            statusBannerMessage = "Reclassified as Details Requested\nMoved \(whoLabel) to Details Requested."
        case "submitted", "submitted_confirmation":
            statusBannerMessage = "Reclassified as Submitted\nMoved \(whoLabel) to Submitted confirmations."
        case "rejected", "closed_declined":
            statusBannerMessage = "Reclassified as Rejected\nMoved \(whoLabel) to Rejected."
        case "replied":
            statusBannerMessage = "Marked as Replied\nWaiting for \(whoLabel) to get back to you."
        case "followup", "follow_up", "follow-up":
            statusBannerMessage = "Marked as Follow-Up\nMoved \(whoLabel) to Follow-Up while waiting for their response."
        case "action_required":
            statusBannerMessage = "Marked as Action Required\nMoved \(whoLabel) back to Action Required."
        case "auto":
            statusBannerMessage = "Reset Classification\nRestored automatic classification for \(whoLabel)."
        default:
            statusBannerMessage = "Marked Resolved\n\(whoLabel) no longer requires action or follow-up."
        }

        sendActionInBackground(
            "set_outreach_thread_status",
            payload: [
                "thread_id": tid,
                "status": norm,
                "company": thread.company,
                "contact_name": thread.contactName,
                "channel": thread.channel,
            ],
            silent: false,
            preserveLocalEdits: true
        )
    }

    @MainActor
    public func autofillAndSubmitThreadForm(_ thread: OutreachThreadItem, formUrl: String = "") {
        let tid = thread.id
        autofillingThreadId = tid
        let compLabel = thread.company.isEmpty ? thread.contactName : thread.company
        statusBannerMessage = "Autofilling & submitting form for \(compLabel)\nOpening form in AutoApply Browser, filling KB details & attaching Resume PDF..."
        sendActionInBackground(
            "autofill_and_submit_thread_form",
            payload: [
                "thread_id": tid,
                "form_url": formUrl,
                "company_name": thread.company,
                "title": thread.role,
                "submit": true,
            ],
            silent: false,
