        ) { [weak self] in
            if self?.autofillingThreadId == tid {
                self?.autofillingThreadId = ""
            }
        }
    }

    @MainActor
    public func requestThreadAvatarIfNeeded(_ thread: OutreachThreadItem) {
        guard !thread.avatarPath.isEmpty || !thread.avatarUrl.isEmpty else { return }
        FastThumbnailCache.shared.loadThumbnail(
            localPath: thread.avatarPath,
            remoteUrl: thread.avatarUrl,
            cacheSlugHint: thread.avatarSlugHint,
            pointSize: 38
        ) { _ in }
    }

    @MainActor
    public func draftFollowUpForSelectedThread() {
        guard let th = selectedOutreachThread else { return }
        guard draftingFollowUpThreadId.isEmpty else { return }
        selectedOutreachThreadId = th.id
        errorMessage = ""
        let previousDraft = threadComposerText
        let trimmedPrev = previousDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        let isRegenerating = !trimmedPrev.isEmpty && (
            aiGeneratedDraftThreadIds.contains(th.id)
                || !th.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        )
        draftingFollowUpThreadId = th.id

        sendActionInBackground(
            "draft_thread_followup",
            payload: [
                "thread_id": th.id,
                "company": th.company,
                "role": th.role,
                "contact_name": th.contactName,
                "channel": th.channel,
                "subject": th.subject,
                "current_draft": previousDraft,
                "regenerate": isRegenerating,
            ],
            silent: false,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            defer {
                self.draftingFollowUpThreadId = ""
            }
            let matched = self.outreachThreads.first(where: { $0.id == th.id })
                ?? self.outreachThreads.first(where: {
                    $0.company.lowercased() == th.company.lowercased()
                        && $0.contactName.lowercased() == th.contactName.lowercased()
                        && $0.channel.lowercased() == th.channel.lowercased()
                })
            var resolvedDraft = ""
            var resolvedSubj = ""
            var targetId = th.id
            if let updated = matched, !updated.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                targetId = updated.id
                resolvedDraft = updated.draftText
                resolvedSubj = updated.draftSubject
            }
            if resolvedDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                let firstName = th.contactName.split(separator: " ").first.map(String.init) ?? "there"
                let greeting = ["hiring", "talent", "recruiting", "team", "careers", "hr"].contains(firstName.lowercased())
                    ? "Hi \(th.company) team,"
                    : "Hi \(firstName),"
                let hasInbound = th.messages.contains(where: { $0.senderRole == "them" })
                if hasInbound {
                    if th.channel.lowercased().contains("linkedin") {
                        resolvedDraft = "\(greeting) Thank you again for the update regarding the \(th.role) role at \(th.company). I wanted to follow up briefly to see if there are any news on the review or if you need any additional information from my end.\n\nBest,\nAlex"
                    } else {
                        resolvedDraft = "\(greeting)\n\nThank you again for the update regarding my application for the \(th.role) role at \(th.company).\n\nI wanted to follow up briefly to see if there are any updates on the review process, or if there is any additional information or context I can provide from my end to help with your evaluation.\n\nBest,\nAlex Mercer\n+1 555 234 5678\nhttps://www.linkedin.com/in/alexander-mercer/\nhttps://turboapply.agency/"
                    }
                } else if th.channel.lowercased().contains("linkedin") {
                    resolvedDraft = "\(greeting) I recently applied for the \(th.role) role at \(th.company) and wanted to follow up briefly to see if there are any updates or if you need anything additional from my end.\n\nBest,\nAlex"
                } else {
                    resolvedDraft = "\(greeting)\n\nI wanted to follow up briefly on my application for the \(th.role) role at \(th.company) to see if there are any updates on the review or if you need any additional information from my end.\n\nAt Apex Industrial, I led a 14-person multidisciplinary team across software, hardware, firmware, and UI/UX from requirements through release, running up to 10 concurrent projects and aligning rollout across 12 departments. At TurboApply Agency, I run end-to-end client delivery for production AI agents and CRM integrations.\n\nPlease let me know if there is anything else I can share to support your review.\n\nBest,\nAlex Mercer\n+1 555 234 5678\nhttps://www.linkedin.com/in/alexander-mercer/\nhttps://turboapply.agency/"
                }
                resolvedSubj = th.subject.lowercased().hasPrefix("re:") ? th.subject : "Re: \(th.subject)"
                self.statusBannerMessage = "Follow-up draft ready\nPrepared a follow-up for \(th.contactName) (\(th.company))."
            }

            self.localThreadDraftTextById[targetId] = resolvedDraft
            self.localThreadDraftTextById[th.id] = resolvedDraft
            if !resolvedSubj.isEmpty {
                self.localThreadDraftSubjectById[targetId] = resolvedSubj
                self.localThreadDraftSubjectById[th.id] = resolvedSubj
            }
            self.aiGeneratedDraftThreadIds.insert(targetId)
            self.aiGeneratedDraftThreadIds.insert(th.id)

            if self.selectedOutreachThreadId == th.id || self.selectedOutreachThreadId == targetId {
                self.selectedOutreachThreadId = targetId
                self.threadComposerText = resolvedDraft
                if !resolvedSubj.isEmpty {
                    self.threadComposerSubject = resolvedSubj
                }
            }
        }
    }

    @MainActor
    public func generateTailoredDocument(payload: [String: Any], clearInputsOnSuccess: Bool = false) {
        guard !isGeneratingTailoredDocument else { return }
        isGeneratingTailoredDocument = true
        errorMessage = ""
        let wasManualMode = customTailorManualMode
        let prevDocIds = Set(documents.map(\.id))
        sendActionInBackground(
            "generate_tailored_document",
            payload: payload,
            silent: false,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            self.isGeneratingTailoredDocument = false
            if !self.errorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                if !wasManualMode && (payload["job_url"] as? String)?.isEmpty == false {
                    self.customTailorUrlError = self.errorMessage
                    self.customTailorManualMode = true
                }
                return
            }
            self.customTailorUrlError = ""
            if clearInputsOnSuccess {
                self.customTailorJobUrl = ""
                self.customTailorCompany = ""
                self.customTailorRole = ""
                self.customTailorDescription = ""
            }
            self.selectedSection = .resumes
            self.resumesSubtab = "generated"
            if let newlyCreated = self.documents.first(where: { !prevDocIds.contains($0.id) }) ?? self.documents.first {
                self.selectDocument(newlyCreated.id)
            }
        }
    }

    @MainActor
    public func scoreJobsWithJev(jobId: String = "batch", limit: Int = 12) {
        guard scoringJevJobId.isEmpty else { return }
        let targetKey = jobId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "batch" : jobId
        scoringJevJobId = targetKey
        errorMessage = ""
