        }
    }

    @MainActor
    public func sendOrQueueSelectedThreadMessage(mode: String) {
        guard let th = selectedOutreachThread else { return }
        let msg = threadComposerText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !msg.isEmpty else { return }
        let subj = threadComposerSubject.trimmingCharacters(in: .whitespacesAndNewlines)
        let effectiveSubj = subj.isEmpty ? th.subject : subj
        let msgId = "msg_\(UUID().uuidString.replacingOccurrences(of: "-", with: "").lowercased().prefix(8))"

        let nowFmt = DateFormatter()
        nowFmt.timeZone = TimeZone(abbreviation: "UTC")
        nowFmt.dateFormat = "yyyy-MM-dd HH:mm"
        let tsStr = nowFmt.string(from: Date())

        let localFmt = DateFormatter()
        localFmt.dateFormat = "HH:mm"
        let estDate = Date().addingTimeInterval(15 * 60)
        let estStr = mode == "queue" ? "Est. \(localFmt.string(from: estDate)) (in ~15m)" : ""

        let optimisticMsg = OutreachChatMessageItem(
            id: msgId,
            senderRole: "me",
            senderName: "Alex Mercer",
            senderHandle: th.channel == "email" ? "alex.mercer@example.com" : "linkedin.com/in/alex-mercer",
            subject: effectiveSubj,
            body: msg,
            timestamp: tsStr,
            deliveryStatus: mode == "queue" ? "Queued" : "Pending",
            scheduledFor: "",
            queueEstimate: estStr,
            attachments: []
        )

        var localQueueList = locallyQueuedMessagesByThreadId[th.id] ?? []
        localQueueList.removeAll(where: { $0.id == optimisticMsg.id })
        localQueueList.append(optimisticMsg)
        locallyQueuedMessagesByThreadId[th.id] = localQueueList

        if let idx = outreachThreads.firstIndex(where: { $0.id == th.id }) {
            let cur = outreachThreads[idx]
            var updatedMsgs = cur.messages
            updatedMsgs.append(optimisticMsg)
            outreachThreads[idx] = OutreachThreadItem(
                id: cur.id,
                company: cur.company,
                role: cur.role,
                contactName: cur.contactName,
                contactHandle: cur.contactHandle,
                channel: cur.channel,
                channelLabel: cur.channelLabel,
                subject: cur.subject,
                threadUrl: cur.threadUrl,
                profileUrl: cur.profileUrl,
                actionRequired: false,
                unreadInbound: cur.unreadInbound,
                jevClassification: cur.jevClassification,
                jevLabel: cur.jevLabel,
                jevSummary: cur.jevSummary,
                jevModel: cur.jevModel,
                deliveryState: mode == "queue" ? "queued" : "pending",
                statusBadge: cur.statusBadge,
                lastActivityAt: tsStr,
                draftText: "",
                draftSubject: effectiveSubj,
                isCompanyContact: cur.isCompanyContact,
                avatarUrl: cur.avatarUrl,
                avatarPath: cur.avatarPath,
                avatarOriginalPath: cur.avatarOriginalPath,
                messages: updatedMsgs
            )
        }

        isClearingComposerProgrammatically = true
        threadComposerText = ""
        localThreadDraftTextById[th.id] = ""
        aiGeneratedDraftThreadIds.remove(th.id)
        DispatchQueue.main.async { [weak self] in
            self?.isClearingComposerProgrammatically = false
        }
        if mode == "queue" {
            statusBannerMessage = "Queued message to \(th.contactName) (\(th.company)) • \(estStr)."
        } else {
            statusBannerMessage = "Sending follow-up to \(th.contactName) (\(th.company))…"
        }

        sendActionInBackground(
            "send_or_queue_thread_message",
            payload: [
                "thread_id": th.id,
                "message_id": msgId,
                "company": th.company,
                "role": th.role,
                "contact_name": th.contactName,
                "contact_handle": th.contactHandle,
                "channel": th.channel,
                "subject": effectiveSubj,
                "message_text": msg,
                "mode": mode,
            ]
        )
    }

