    @MainActor
    public func cancelEditingQueuedMessage() {
        editingQueuedMessageId = ""
        editingQueuedMessageThreadId = ""
        editingQueuedMessageSubject = ""
        editingQueuedMessageBody = ""
    }

    @MainActor
    public func saveEditedQueuedMessage(_ msg: OutreachChatMessageItem, thread: OutreachThreadItem) {
        let updatedBody = editingQueuedMessageBody.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !updatedBody.isEmpty else { return }
        let updatedSubj = editingQueuedMessageSubject.trimmingCharacters(in: .whitespacesAndNewlines)
        let effectiveSubj = updatedSubj.isEmpty ? msg.subject : updatedSubj

        if let tIdx = outreachThreads.firstIndex(where: { $0.id == thread.id }) {
            let cur = outreachThreads[tIdx]
            let updatedMsgs = cur.messages.map { m -> OutreachChatMessageItem in
                guard m.id == msg.id else { return m }
                return OutreachChatMessageItem(
                    id: m.id,
                    senderRole: m.senderRole,
                    senderName: m.senderName,
                    senderHandle: m.senderHandle,
                    subject: effectiveSubj,
                    body: updatedBody,
                    timestamp: m.timestamp,
                    deliveryStatus: m.deliveryStatus,
                    scheduledFor: m.scheduledFor,
                    queueEstimate: m.queueEstimate,
                    attachments: m.attachments
                )
            }
            outreachThreads[tIdx] = OutreachThreadItem(
                id: cur.id,
                company: cur.company,
                role: cur.role,
                contactName: cur.contactName,
                contactHandle: cur.contactHandle,
                channel: cur.channel,
                channelLabel: cur.channelLabel,
                subject: cur.subject,
                threadUrl: cur.threadUrl,
                profileUrl: cur.profileUrl,
                actionRequired: cur.actionRequired,
                unreadInbound: cur.unreadInbound,
                jevClassification: cur.jevClassification,
                jevLabel: cur.jevLabel,
                jevSummary: cur.jevSummary,
                jevModel: cur.jevModel,
                deliveryState: cur.deliveryState,
                statusBadge: cur.statusBadge,
                lastActivityAt: cur.lastActivityAt,
                draftText: cur.draftText,
                draftSubject: cur.draftSubject,
                isCompanyContact: cur.isCompanyContact,
                avatarUrl: cur.avatarUrl,
                avatarPath: cur.avatarPath,
                avatarOriginalPath: cur.avatarOriginalPath,
                messages: updatedMsgs
            )
        }
        if var localList = locallyQueuedMessagesByThreadId[thread.id] {
            localList = localList.map { m in
                guard m.id == msg.id else { return m }
                return OutreachChatMessageItem(
                    id: m.id,
                    senderRole: m.senderRole,
                    senderName: m.senderName,
                    senderHandle: m.senderHandle,
                    subject: effectiveSubj,
                    body: updatedBody,
                    timestamp: m.timestamp,
                    deliveryStatus: m.deliveryStatus,
                    scheduledFor: m.scheduledFor,
                    queueEstimate: m.queueEstimate,
                    attachments: m.attachments
                )
            }
            locallyQueuedMessagesByThreadId[thread.id] = localList
        }

        cancelEditingQueuedMessage()
        statusBannerMessage = "Updated queued message to \(thread.contactName) (\(thread.company))."
        sendActionInBackground(
            "update_queued_thread_message",
            payload: [
                "thread_id": thread.id,
                "message_id": msg.id,
                "company": thread.company,
                "contact_name": thread.contactName,
                "subject": effectiveSubj,
                "message_text": updatedBody,
            ]
        )
    }

    @MainActor
    public func cancelQueuedOrPendingMessage(_ msg: OutreachChatMessageItem, thread: OutreachThreadItem) {
        if editingQueuedMessageId == msg.id {
            cancelEditingQueuedMessage()
        }
        threadComposerText = msg.body
        localThreadDraftTextById[thread.id] = msg.body
        if !msg.subject.isEmpty {
            threadComposerSubject = msg.subject
            localThreadDraftSubjectById[thread.id] = msg.subject
        }

        if let tIdx = outreachThreads.firstIndex(where: { $0.id == thread.id }) {
            let cur = outreachThreads[tIdx]
            let remainingMsgs = cur.messages.filter { $0.id != msg.id }
            let nextDeliveryState: String = {
                if remainingMsgs.contains(where: { $0.isQueued }) { return "queued" }
                if remainingMsgs.contains(where: { $0.isPending }) { return "pending" }
                return "sent"
            }()
            outreachThreads[tIdx] = OutreachThreadItem(
                id: cur.id,
                company: cur.company,
                role: cur.role,
                contactName: cur.contactName,
                contactHandle: cur.contactHandle,
                channel: cur.channel,
                channelLabel: cur.channelLabel,
                subject: cur.subject,
                threadUrl: cur.threadUrl,
                profileUrl: cur.profileUrl,
                actionRequired: cur.actionRequired,
                unreadInbound: cur.unreadInbound,
                jevClassification: cur.jevClassification,
                jevLabel: cur.jevLabel,
                jevSummary: cur.jevSummary,
                jevModel: cur.jevModel,
                deliveryState: nextDeliveryState,
                statusBadge: cur.statusBadge,
                lastActivityAt: cur.lastActivityAt,
                draftText: msg.body,
                draftSubject: msg.subject.isEmpty ? cur.draftSubject : msg.subject,
                isCompanyContact: cur.isCompanyContact,
                avatarUrl: cur.avatarUrl,
                avatarPath: cur.avatarPath,
                avatarOriginalPath: cur.avatarOriginalPath,
                messages: remainingMsgs
            )
        }
        if var localList = locallyQueuedMessagesByThreadId[thread.id] {
            localList.removeAll(where: { $0.id == msg.id })
            if localList.isEmpty {
                locallyQueuedMessagesByThreadId.removeValue(forKey: thread.id)
            } else {
                locallyQueuedMessagesByThreadId[thread.id] = localList
            }
        }

        statusBannerMessage = "Cancelled queued message to \(thread.contactName) (\(thread.company)) and restored to draft."
        sendActionInBackground(
            "cancel_queued_thread_message",
            payload: [
                "thread_id": thread.id,
                "message_id": msg.id,
                "company": thread.company,
                "contact_name": thread.contactName,
                "restore_to_draft": true,
            ]
        )
    }

