    @MainActor
    public func submitNewOutreachLog(mode: String = "send_now") {
        let comp = newOutreachCompany.trimmingCharacters(in: .whitespacesAndNewlines)
        let role = newOutreachRole.trimmingCharacters(in: .whitespacesAndNewlines)
        let contact = newOutreachContactName.trimmingCharacters(in: .whitespacesAndNewlines)
        let msg = newOutreachMessageText.trimmingCharacters(in: .whitespacesAndNewlines)
        let handle = newOutreachContactValue.trimmingCharacters(in: .whitespacesAndNewlines)
        let subj = newOutreachSubject.trimmingCharacters(in: .whitespacesAndNewlines)
        let useComp = comp.isEmpty ? (selectedJob?.companyName ?? "Target Employer") : comp
        let useRole = role.isEmpty ? (selectedJob?.title ?? "Product Manager") : role
        let useContact = contact.isEmpty ? "\(useComp) Hiring Team" : contact

        let normalizedChannel: String = {
            let chLow = newOutreachChannel.lowercased()
            if chLow.contains("linkedin") { return "linkedin" }
            if chLow.contains("hh") { return "hh" }
            if chLow.contains("imessage") || chLow.contains("sms") { return "imessage" }
            return "email"
        }()

        sendAction("send_or_queue_thread_message", payload: [
            "company": useComp,
            "role": useRole,
            "contact_name": useContact,
            "contact_handle": handle,
            "channel": normalizedChannel,
            "subject": subj.isEmpty ? "\(useRole) — \(useComp)" : subj,
            "message_text": msg.isEmpty ? "Direct reachout to \(useContact) regarding \(useRole) at \(useComp)." : msg,
            "mode": mode,
        ])
        newOutreachContactName = ""
        newOutreachContactValue = ""
        newOutreachSubject = ""
        newOutreachMessageText = ""
        showLogOutreachForm = false
    }

    public func selectKBSection(_ id: String) {
        if id != selectedKBSectionId {
            autoSaveCurrentKBSection()
        }
        selectedKBSectionId = id
        if let sec = kbSections.first(where: { $0.id == id }) {
            kbEditorText = sec.markdown
        }
        // Always default to View mode whenever switching a Knowledge Base section tab
        kbShowEditor = false
        kbShowPreview = true
    }

    public func cycleKBViewEditMode() {
        // Click 1: changes from view (editor=false, preview=true) to edit (editor=true, preview=false)
        // Click 2: changes from edit (editor=true, preview=false) to view+edit (editor=true, preview=true)
        // Click 3: changes from view+edit (editor=true, preview=true) to view (editor=false, preview=true)
        if !kbShowEditor && kbShowPreview {
            kbShowEditor = true
            kbShowPreview = false
        } else if kbShowEditor && !kbShowPreview {
            kbShowEditor = true
            kbShowPreview = true
        } else {
            kbShowEditor = false
            kbShowPreview = true
        }
    }

    public func isDocumentSubmitted(_ doc: DocumentArtifactItem) -> Bool {
        if let latest = documents.first(where: { $0.id == doc.id }) {
            if latest.isSubmitted { return true }
        } else if doc.isSubmitted {
            return true
        }
        if !doc.jobId.isEmpty, let job = jobs.first(where: { $0.jobId == doc.jobId }) {
            return job.state == "submitted_verified" || job.pipelineStage == "submitted"
        }
        return false
    }

    @MainActor
    public func setDocumentSubmittedStatus(_ doc: DocumentArtifactItem, isSubmitted: Bool) {
        if isSubmitted {
            autoSaveCurrentEditedDocument(silent: true)
            if selectedDocumentId == doc.id {
                resumeShowEditor = false
                resumeShowPreview = true
            }
        }
        for idx in documents.indices {
            if documents[idx].id == doc.id || (!doc.jobId.isEmpty && documents[idx].jobId == doc.jobId) {
                documents[idx].isSubmitted = isSubmitted
            }
        }
        if !doc.jobId.isEmpty {
            for jIdx in jobs.indices where jobs[jIdx].jobId == doc.jobId {
                if isSubmitted {
                    if jobs[jIdx].pipelineStage != "submitted" {
                        jobs[jIdx].previousPipelineStage = jobs[jIdx].pipelineStage
                    }
                    jobs[jIdx].pipelineStage = "submitted"
                    jobs[jIdx].state = "submitted_verified"
                } else {
                    let prev = jobs[jIdx].previousPipelineStage
                    let revertStage = (!prev.isEmpty && prev != "submitted") ? prev : "not_applied"
                    jobs[jIdx].pipelineStage = revertStage
                    jobs[jIdx].state = (revertStage == "applying") ? "applying" : "discovered"
                }
            }
        }
        sendAction(
            "set_document_submitted_status",
            payload: [
                "document_id": doc.id,
                "job_id": doc.jobId,
                "is_submitted": isSubmitted
            ]
        )
    }

    @MainActor
    public func submitResumePackage(_ doc: DocumentArtifactItem) {
        guard submittingDocumentId.isEmpty else { return }
        submittingDocumentId = doc.id
        errorMessage = ""

        var payload: [String: Any] = [
            "document_id": doc.id,
            "job_id": doc.jobId,
            "company_name": doc.companyName,
            "role_title": doc.roleTitle,
        ]
        if selectedDocumentId == doc.id {
            let curResume = resumeEditorText.isEmpty ? doc.resumeMarkdown : resumeEditorText
            let curCover = coverLetterEditorText.isEmpty ? doc.coverLetterMarkdown : coverLetterEditorText
            payload["resume_markdown"] = curResume
            payload["cover_letter_markdown"] = curCover
        } else {
            payload["resume_markdown"] = doc.resumeMarkdown
            payload["cover_letter_markdown"] = doc.coverLetterMarkdown
        }

        sendActionInBackground(
            "submit_resume_package",
            payload: payload,
            silent: false,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            self.submittingDocumentId = ""
            if let refreshed = self.documents.first(where: { $0.id == doc.id }), self.isDocumentSubmitted(refreshed) {
                if self.selectedDocumentId == doc.id {
                    self.resumeShowEditor = false
                    self.resumeShowPreview = true
                }
            }
        }
    }

    public func selectDocument(_ id: String) {
        if id != selectedDocumentId {
            autoSaveCurrentEditedDocument(silent: true)
        }
        selectedDocumentId = id
        if let doc = documents.first(where: { $0.id == id }) {
            resumeEditorText = doc.resumeMarkdown
            coverLetterEditorText = doc.coverLetterMarkdown
        }
        resumeShowEditor = false
        resumeShowPreview = true
    }

    @MainActor
    public func deleteGeneratedDocument(_ doc: DocumentArtifactItem) {
        let removedId = doc.id
        var nextSelected: DocumentArtifactItem? = nil
        if selectedDocumentId == removedId {
            if let idx = documents.firstIndex(where: { $0.id == removedId }) {
                if idx + 1 < documents.count {
                    nextSelected = documents[idx + 1]
                } else if idx > 0 {
                    nextSelected = documents[idx - 1]
                }
            }
        }
        documents.removeAll { $0.id == removedId }
        if selectedDocumentId == removedId {
            if let next = nextSelected ?? documents.first {
                selectedDocumentId = next.id
                resumeEditorText = next.resumeMarkdown
                coverLetterEditorText = next.coverLetterMarkdown
            } else {
                selectedDocumentId = ""
                resumeEditorText = ""
                coverLetterEditorText = ""
            }
        }
        sendAction("delete_generated_document", payload: ["document_id": removedId])
    }

    public func cycleResumeViewEditMode() {
        guard let doc = selectedDocument, !isDocumentSubmitted(doc) else {
            resumeShowEditor = false
            resumeShowPreview = true
            return
        }
        if !resumeShowEditor && resumeShowPreview {
            resumeShowEditor = true
            resumeShowPreview = false
        } else if resumeShowEditor && !resumeShowPreview {
            resumeShowEditor = true
            resumeShowPreview = true
        } else {
            autoSaveCurrentEditedDocument(silent: true)
            resumeShowEditor = false
            resumeShowPreview = true
        }
    }

    public func autoSaveCurrentEditedDocument(silent: Bool = true) {
        guard let doc = selectedDocument, !isDocumentSubmitted(doc) else { return }
        let curResume = resumeEditorText.isEmpty ? doc.resumeMarkdown : resumeEditorText
        let curCover = coverLetterEditorText.isEmpty ? doc.coverLetterMarkdown : coverLetterEditorText
        if !silent || curResume != doc.resumeMarkdown || curCover != doc.coverLetterMarkdown {
            sendActionInBackground(
                "save_edited_document_package",
                payload: [
                    "document_id": doc.id,
                    "job_id": doc.jobId,
                    "resume_markdown": curResume,
                    "cover_letter_markdown": curCover,
                ],
                silent: silent,
                preserveLocalEdits: true
            )
        }
    }

    @MainActor
    public func selectInterviewQuestion(_ id: String) {
        let wasInConversation = (voiceRecorder.isConversationActive || voiceRecorder.isConversationSessionActive) && !voiceRecorder.userExplicitlyStoppedSession
        if wasInConversation {
            _ = voiceRecorder.captureAndStopForImmediateNext()
        } else {
            voiceRecorder.stopRecording()
        }
        selectedInterviewQuestionId = id
        if let q = interviewQuestions.first(where: { $0.id == id }) {
            interviewDraftText = q.savedTranscript
            voiceRecorder.syncPreTypedDraft(interviewDraftText)
            if wasInConversation {
                voiceRecorder.startInterviewTurn(
                    questionId: q.id,
                    questionPrompt: q.prompt,
                    speakFirst: true,
                    repoRootDir: repoRootDir,
                    store: self
                )
            }
        }
    }

    @MainActor
    public func skipCurrentInterviewQuestion(_ q: InterviewQuestionItem) {
        let wasInConversation = (voiceRecorder.isConversationActive || voiceRecorder.isConversationSessionActive) && !voiceRecorder.userExplicitlyStoppedSession
        if wasInConversation {
            _ = voiceRecorder.captureAndStopForImmediateNext()
        }
        let curIdx = interviewQuestions.firstIndex(where: { $0.id == q.id }) ?? 0
        var updated = interviewQuestions
        var nextSelectedQuestion: InterviewQuestionItem? = nil
        if curIdx < updated.count {
            let removed = updated.remove(at: curIdx)
            let targetIdx = max(updated.count, curIdx + 5)
            if targetIdx >= updated.count {
                updated.append(removed)
            } else {
                updated.insert(removed, at: targetIdx)
            }
            interviewQuestions = updated
            if !interviewQuestions.isEmpty {
                let nextIdx = min(curIdx, interviewQuestions.count - 1)
                let nextQ = interviewQuestions[nextIdx]
                selectedInterviewQuestionId = nextQ.id
                interviewDraftText = nextQ.savedTranscript
                voiceRecorder.syncPreTypedDraft(interviewDraftText)
                nextSelectedQuestion = nextQ
            }
        }
        if wasInConversation, let nextQ = nextSelectedQuestion {
            voiceRecorder.startInterviewTurn(
                questionId: nextQ.id,
                questionPrompt: nextQ.prompt,
                speakFirst: true,
                repoRootDir: repoRootDir,
                store: self
            )
        }
        sendActionInBackground("skip_voice_interview_question", payload: ["question_id": q.id], silent: true, preserveInterviewSelection: true)
    }

    public func advanceToNextInterviewQuestion() {
        if interviewQuestions.isEmpty {
            sendActionInBackground("generate_more_interview_questions", payload: ["count": 3], silent: true) { [weak self] in
                guard let self = self, let firstNew = self.interviewQuestions.first else { return }
                self.selectInterviewQuestion(firstNew.id)
            }
        }
    }

