        ("ai_recommend_done_5", "Okay, that's in place. Go ahead and keep talking if you want to add more."),
    ]

    private var recommendCueDeck: [Int] = []
    private var lastRecommendCueIndex: Int = -1
    private var recommendDoneCueDeck: [Int] = []
    private var lastRecommendDoneCueIndex: Int = -1
    private var recommendTurnGenerationId: Int = 0

    private func nextRecommendStartCue() -> (id: String, text: String) {
        let total = Self.recommendStartCues.count
        if recommendCueDeck.isEmpty {
            var indices = Array(0..<total).shuffled()
            if indices.first == lastRecommendCueIndex && indices.count > 1 {
                indices.swapAt(0, indices.count - 1)
            }
            recommendCueDeck = indices
        }
        let chosen = recommendCueDeck.removeFirst()
        lastRecommendCueIndex = chosen
        return Self.recommendStartCues[chosen]
    }

    private func nextRecommendDoneCue() -> (id: String, text: String) {
        let total = Self.recommendDoneCues.count
        if recommendDoneCueDeck.isEmpty {
            var indices = Array(0..<total).shuffled()
            if indices.first == lastRecommendDoneCueIndex && indices.count > 1 {
                indices.swapAt(0, indices.count - 1)
            }
            recommendDoneCueDeck = indices
        }
        let chosen = recommendDoneCueDeck.removeFirst()
        lastRecommendDoneCueIndex = chosen
        return Self.recommendDoneCues[chosen]
    }

    @MainActor
    public func generateRecommendedInterviewAnswer(for q: InterviewQuestionItem) {
        guard !isGeneratingInterviewAnswer else { return }
        let shouldSpeak = (voiceRecorder.isConversationActive || voiceRecorder.isConversationSessionActive) && !voiceRecorder.userExplicitlyStoppedSession
        selectedInterviewQuestionId = q.id
        isGeneratingInterviewAnswer = true
        recommendTurnGenerationId += 1
        let turnGen = recommendTurnGenerationId
        let previousDraft = interviewDraftText

        var initialCueFinished = false
        var answerGenerationFinished = false

        let resumeListeningIfReady: () -> Void = { [weak self] in
            guard let self = self, turnGen == self.recommendTurnGenerationId else { return }
            guard initialCueFinished && answerGenerationFinished else { return }
            guard shouldSpeak,
                  self.voiceRecorder.isConversationSessionActive,
                  !self.voiceRecorder.userExplicitlyStoppedSession,
                  !self.isGeneratingInterviewAnswer else { return }
            self.voiceRecorder.beginMicrophoneCapture(store: self, preserveDuration: true)
        }

        if shouldSpeak {
            voiceRecorder.isConversationSessionActive = true
            voiceRecorder.userExplicitlyStoppedSession = false
            let startCue = nextRecommendStartCue()
            voiceRecorder.statusText = startCue.text
            voiceRecorder.speakAssistantCue(
                audioId: startCue.id,
                fallbackText: startCue.text,
                repoRootDir: repoRootDir
            ) { [weak self] in
                guard let self = self, turnGen == self.recommendTurnGenerationId else { return }
                initialCueFinished = true
                if answerGenerationFinished {
                    resumeListeningIfReady()
                } else {
                    self.voiceRecorder.statusText = "Finishing recommended answer…"
                }
            }
        } else {
            voiceRecorder.pauseMicrophoneForAssistantSpeech()
            voiceRecorder.statusText = "AI is generating a recommended answer from your profile…"
        }

        sendActionInBackground(
            "generate_recommended_interview_answer",
            payload: [
                "question_id": q.id,
                "question_title": q.title,
                "question_prompt": q.prompt,
                "kb_section_id": q.kbSectionId,
                "current_draft": previousDraft,
            ],
            silent: false,
            preserveInterviewSelection: false
        ) { [weak self] in
            guard let self = self, turnGen == self.recommendTurnGenerationId else { return }
            self.isGeneratingInterviewAnswer = false
            let cleaned = self.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !cleaned.isEmpty {
                let formattedWithNewline = cleaned + "\n"
                self.voiceRecorder.syncPreTypedDraft(formattedWithNewline)
                self.interviewDraftText = formattedWithNewline
            } else {
                self.voiceRecorder.syncPreTypedDraft("")
            }
            self.voiceRecorder.lastAudioFilePath = ""
            answerGenerationFinished = true

            if !cleaned.isEmpty {
                if shouldSpeak && self.voiceRecorder.isConversationSessionActive && !self.voiceRecorder.userExplicitlyStoppedSession {
                    if !initialCueFinished {
                        // The female intro cue is still playing; as soon as it finishes, resumeListeningIfReady() auto-starts the recorder.
                    } else {
                        let doneCue = self.nextRecommendDoneCue()
                        self.voiceRecorder.statusText = doneCue.text
                        self.voiceRecorder.speakAssistantCue(
                            audioId: doneCue.id,
                            fallbackText: doneCue.text,
                            repoRootDir: self.repoRootDir
                        ) {
                            resumeListeningIfReady()
                        }
                    }
                } else {
                    self.voiceRecorder.statusText = "AI recommended answer ready. Review or edit below, then click 'Save & Next'."
                }
            } else {
                if shouldSpeak && self.voiceRecorder.isConversationSessionActive && !self.voiceRecorder.userExplicitlyStoppedSession {
                    if initialCueFinished {
                        resumeListeningIfReady()
                    }
                } else {
                    self.voiceRecorder.statusText = "Ready — click 'Start Conversation' or 'AI Recommended Answer'"
                }
            }
        }
    }

    public var trialDaysRemainingNumber: Int {
        if trialState == "expired" || entitlementStatus == "expired" {
            return 0
        }
        guard !trialExpiresAt.isEmpty else { return 2 }
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let parsed = formatter.date(from: trialExpiresAt) ?? ISO8601DateFormatter().date(from: trialExpiresAt)
        guard let expiry = parsed else { return 2 }
        let diff = expiry.timeIntervalSinceNow
        if diff <= 0 {
            return 0
        }
        let days = Int(ceil(diff / 86400.0))
        return max(0, min(2, days))
    }

    public var trialDaysRemainingLabel: String {
        let d = trialDaysRemainingNumber
        if d <= 0 {
            return "Expired"
        }
        return d == 1 ? "1 Day Left" : "\(d) Days Left"
    }

    public var trialSidebarShortLabel: String {
        let d = trialDaysRemainingNumber
        if d <= 0 {
            return "Expired"
        }
        return "\(d)d left"
    }

    public var isLicenseExpired: Bool {
        !isLicenseActivated && (trialState == "expired" || entitlementStatus == "expired" || trialDaysRemainingNumber <= 0)
    }

