    public func submitKnowledgeIngestion() {
        let rawText = newFactValue.trimmingCharacters(in: .whitespacesAndNewlines)
        let files = kbIngestFilePaths
        guard !rawText.isEmpty || !files.isEmpty else { return }
        isIngestingKnowledge = true
        kbIngestProgressFraction = 0.10
        if let firstFile = files.first {
            let fileName = URL(fileURLWithPath: firstFile).lastPathComponent
            kbIngestProgressMessage = "Processing \(fileName)…"
        } else {
            kbIngestProgressMessage = "Analyzing your notes and extracting key career details…"
        }

        var steps: [String] = []
        for fPath in files {
            let fName = URL(fileURLWithPath: fPath).lastPathComponent
            steps.append("Processing \(fName)…")
        }
        steps.append(contentsOf: [
            "Extracting achievements, metrics, and career facts…",
            "Integrating details about your Work Experience…",
            "Integrating details about your Education & Skills…",
            "Integrating details into your Standard Q&A Bank…",
            "Polishing formatting and running quality check…",
        ])
        let immutableSteps = steps
        kbIngestProgressTimer?.invalidate()
        kbIngestProgressTimer = Timer.scheduledTimer(withTimeInterval: 0.35, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self, self.isIngestingKnowledge else { return }
                let progURL = self.appSupportDir.appendingPathComponent("kb_ingest_progress.json")
                var updatedFromBridge = false
                if let data = try? Data(contentsOf: progURL),
                   let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                   let active = obj["active"] as? Bool, active {
                    if let frac = obj["fraction"] as? Double, frac > self.kbIngestProgressFraction {
                        self.kbIngestProgressFraction = min(0.95, frac)
                    }
                    if let msg = obj["message"] as? String, !msg.isEmpty {
                        self.kbIngestProgressMessage = msg
                        updatedFromBridge = true
                    }
                }
                if !updatedFromBridge {
                    if self.kbIngestProgressFraction < 0.88 {
                        self.kbIngestProgressFraction = min(0.88, self.kbIngestProgressFraction + 0.04)
                    }
                    let idx = min(immutableSteps.count - 1, max(0, Int((self.kbIngestProgressFraction - 0.10) / 0.15)))
                    if idx >= 0 && idx < immutableSteps.count {
                        self.kbIngestProgressMessage = immutableSteps[idx]
                    }
                }
            }
        }

        sendActionInBackground(
            "ingest_knowledge_into_kb",
            payload: [
                "raw_text": rawText,
                "file_paths": files,
                "auto_route": true,
            ],
            silent: false,
            preserveInterviewSelection: false,
            preserveLocalEdits: false
        ) { [weak self] in
            guard let self = self else { return }
            self.kbIngestProgressTimer?.invalidate()
            self.kbIngestProgressTimer = nil
            self.kbIngestProgressFraction = 1.0
            self.kbIngestProgressMessage = "Completed Knowledge Base integration!"
            self.isIngestingKnowledge = false
            if self.errorMessage.isEmpty {
                self.newFactKey = ""
                self.newFactValue = ""
                self.kbIngestFilePaths = []
                self.showAddFactModal = false
            }
        }
    }

