    public func confirmAndRunCleanUninstall() {
        let alert = NSAlert()
        alert.messageText = "Uninstall AutoApply?"
        alert.informativeText = "This will completely remove AutoApply and its saved data from your Mac. Other apps on your Mac remain untouched."
        alert.alertStyle = .critical
        alert.addButton(withTitle: "Uninstall AutoApply")
        alert.addButton(withTitle: "Cancel")
        if alert.runModal() == .alertFirstButtonReturn {
            let bundledScript = Bundle.main.resourceURL?.appendingPathComponent("packaging/uninstall_autoapply.sh").path ?? ""
            let repoScript = repoRootDir.appendingPathComponent("packaging/uninstall_autoapply.sh").path
            let scriptPath = FileManager.default.isExecutableFile(atPath: bundledScript) ? bundledScript : repoScript
            let proc = Process()
            proc.executableURL = URL(fileURLWithPath: "/bin/bash")
            proc.arguments = [scriptPath, "--yes"]
            try? proc.run()
            NSApplication.shared.terminate(nil)
        }
    }

