    // MARK: - Share Feedback / Help Us Improve Actions

    @MainActor
    public func captureDesktopWindowScreenshot() -> String {
        let stagingDir = appSupportDir.appendingPathComponent("feedback-staging", isDirectory: true)
        try? FileManager.default.createDirectory(at: stagingDir, withIntermediateDirectories: true)
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd_HHmmss"
        let ts = formatter.string(from: Date())
        let outURL = stagingDir.appendingPathComponent("AutoApply_Desktop_\(ts).png")

        let targetWindow = NSApplication.shared.keyWindow
            ?? NSApplication.shared.mainWindow
            ?? NSApplication.shared.windows.first(where: { $0.isVisible && $0.frame.width > 400 })
        if let win = targetWindow, let contentView = win.contentView {
            let bounds = contentView.bounds
            if bounds.width > 10 && bounds.height > 10,
               let rep = contentView.bitmapImageRepForCachingDisplay(in: bounds) {
                contentView.cacheDisplay(in: bounds, to: rep)
                if let pngData = rep.representation(using: .png, properties: [:]) {
                    try? pngData.write(to: outURL)
                    let bytes = pngData.count
                    if bytes < 1024 {
                        feedbackDesktopScreenshotSize = "\(bytes) B"
                    } else if bytes < 1024 * 1024 {
                        feedbackDesktopScreenshotSize = String(format: "%.1f KB", Double(bytes) / 1024.0)
                    } else {
                        feedbackDesktopScreenshotSize = String(format: "%.1f MB", Double(bytes) / (1024.0 * 1024.0))
                    }
                    feedbackDesktopScreenshotPath = outURL.path
                    return outURL.path
                }
            }
        }
        return ""
    }

    @MainActor
    public func isAutoApplyBrowserWindowOpenOnScreen() -> Bool {
        for app in NSWorkspace.shared.runningApplications {
            if app.isTerminated { continue }
            let name = (app.localizedName ?? "").lowercased()
            let execPath = (app.executableURL?.path ?? "").lowercased()
            let bundlePath = (app.bundleURL?.path ?? "").lowercased()
            if name.contains("autoapply browser")
                || bundlePath.contains("autoapply browser.app")
                || execPath.contains("autoapply browser.app")
                || bundlePath.contains("browser-bin")
                || execPath.contains("cloakbrowser") {
                return true
            }
        }
        return true
    }

    public func openFeedbackModal() {
        feedbackSubmittedBanner = ""
        feedbackIncludeDesktopScreenshot = true
        let browserVisible = isAutoApplyBrowserWindowOpenOnScreen()
        feedbackIncludeBrowserScreenshot = browserVisible
        if !browserVisible {
            feedbackBrowserScreenshotPath = ""
            feedbackBrowserScreenshotSize = ""
            feedbackBrowserUrl = ""
            feedbackBrowserTitle = ""
