    @MainActor
    public func addFeedbackAttachmentPath(_ path: String, customName: String = "") {
        let trimmed = path.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, FileManager.default.fileExists(atPath: trimmed) else { return }
        if feedbackUserAttachments.contains(where: { $0.path == trimmed }) { return }
        let url = URL(fileURLWithPath: trimmed)
        let ext = url.pathExtension.lowercased()
        let kind: String
        if ["png", "jpg", "jpeg", "webp", "gif", "heic", "bmp", "tiff"].contains(ext) {
            kind = "image"
        } else if ["mp4", "mov", "m4v", "webm", "avi", "mkv"].contains(ext) {
            kind = "video"
        } else {
            kind = "file"
        }
        let attrs = try? FileManager.default.attributesOfItem(atPath: trimmed)
        let bytes = (attrs?[.size] as? NSNumber)?.intValue ?? 0
        let sizeLabel: String
        if bytes < 1024 {
            sizeLabel = "\(bytes) B"
        } else if bytes < 1024 * 1024 {
            sizeLabel = String(format: "%.1f KB", Double(bytes) / 1024.0)
        } else {
            sizeLabel = String(format: "%.1f MB", Double(bytes) / (1024.0 * 1024.0))
        }
        feedbackUserAttachments.append(
            FeedbackAttachmentItem(
                id: UUID().uuidString,
                name: customName.isEmpty ? url.lastPathComponent : customName,
                path: trimmed,
                kind: kind,
                sizeLabel: sizeLabel
            )
        )
    }

    @MainActor
    public func removeFeedbackAttachment(_ id: String) {
        feedbackUserAttachments.removeAll(where: { $0.id == id })
    }

    @MainActor
    public func chooseFeedbackAttachmentsWithOpenPanel() {
        let panel = NSOpenPanel()
        panel.title = "Attach Screenshots, Screen Recordings, or Files"
        panel.message = "Append images (.png, .jpg), video recordings (.mp4, .mov), logs, or any supporting files."
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.allowedContentTypes = [.item, .data, .content, .image, .movie, .video, .mpeg4Movie, .quickTimeMovie, .pdf, .plainText, .zip]
        if panel.runModal() == .OK {
            for url in panel.urls {
                addFeedbackAttachmentPath(url.path)
            }
        }
    }

    @MainActor
    public func submitFeedbackReport() {
        let trimmedComment = feedbackCommentText.trimmingCharacters(in: .whitespacesAndNewlines)
        let hasScreenshots = (feedbackIncludeDesktopScreenshot && !feedbackDesktopScreenshotPath.isEmpty)
            || (feedbackIncludeBrowserScreenshot && !feedbackBrowserScreenshotPath.isEmpty)
        guard !trimmedComment.isEmpty || !feedbackUserAttachments.isEmpty || hasScreenshots else {
            errorMessage = "Please provide a short comment or attach a screenshot/file before submitting."
            return
        }
        feedbackIsSubmitting = true
        let attPayload: [[String: String]] = feedbackUserAttachments.map { item in
            [
                "path": item.path,
                "name": item.name,
                "kind": item.kind,
            ]
        }
        sendActionInBackground(
            "submit_user_feedback",
            payload: [
                "classification": feedbackClassification,
                "comment": trimmedComment,
                "app_section": selectedSection.rawValue,
                "browser_url": feedbackBrowserUrl,
                "browser_title": feedbackBrowserTitle,
                "include_desktop_screenshot": feedbackIncludeDesktopScreenshot,
                "include_browser_screenshot": feedbackIncludeBrowserScreenshot,
                "desktop_screenshot_path": feedbackDesktopScreenshotPath,
                "browser_screenshot_path": feedbackBrowserScreenshotPath,
                "attachments": attPayload,
            ],
            silent: false,
            preserveLocalEdits: true
        ) { [weak self] in
            guard let self = self else { return }
            self.feedbackIsSubmitting = false
            let label = self.feedbackClassification == "improvement" ? "Improvement Suggestion" : "Bug Report"
            self.feedbackSubmittedBanner = "Thank you! Your \(label) and attached context have been packaged and queued for review."
            self.feedbackCommentText = ""
            self.feedbackUserAttachments = []
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) { [weak self] in
                self?.showFeedbackModal = false
            }
        }
    }
}

