public struct AutoApplyRootView: View {
    @ObservedObject var store: WorkspaceStore

    public init(store: WorkspaceStore) {
        self.store = store
    }

    private func activateMainSidebarSection(_ newSection: NavigationSection) {
        if newSection == .jobs {
            store.selectedJobId = ""
        } else if newSection == .followUpTracker {
            store.selectedOutreachThreadId = ""
        } else if newSection == .resumes {
            store.autoSaveCurrentEditedDocument(silent: true)
            store.selectedDocumentId = ""
        }
        store.selectedSection = newSection
    }

    private var sidebarSelectionBinding: Binding<NavigationSection> {
        Binding(
            get: { store.selectedSection },
            set: { newSection in
                guard newSection != store.selectedSection else { return }
                store.requestInterruptableAction {
                    activateMainSidebarSection(newSection)
                }
            }
        )
    }

    public var body: some View {
        HStack(spacing: 0) {
            VStack(alignment: .leading, spacing: 0) {
                // Brand Header with Profile Avatar
                HStack(spacing: 12) {
                    ProfileAvatarThumbnail(
                        photoPath: store.profilePhotoThumbPath.isEmpty ? store.profilePhotoPath : store.profilePhotoThumbPath,
                        size: 40
                    )
                    VStack(alignment: .leading, spacing: 2) {
                        Text(
                            store.profileFullName.isEmpty
                                ? "AutoApply"
                                : store.profileFullName
                                    .replacingOccurrences(of: "Mr. ", with: "")
                                    .replacingOccurrences(of: "Ms. ", with: "")
                                    .replacingOccurrences(of: "Mrs. ", with: "")
                                    .replacingOccurrences(of: "Alexander", with: "Alex")
                        )
                        .font(.system(size: 14, weight: .bold))
                        .lineLimit(1)
                        .minimumScaleFactor(0.82)
                        Text("Job Application Assistant")
                            .font(.caption2)
                            .foregroundColor(.secondary)
                    }
                    Spacer()
                }
                .padding(.horizontal, 16)
                .padding(.top, 18)
                .padding(.bottom, 12)

                ScrollView {
                    VStack(alignment: .leading, spacing: 4) {
                        ForEach(NavigationSection.allCases.filter { section in
                            if section == .activateLicense { return false }
                            if section == .setup && store.isSetupHidden && store.selectedSection != .setup { return false }
                            return true
                        }) { section in
                            let isSelected = (store.selectedSection == section)
                            Button {
                                guard section != store.selectedSection else { return }
                                store.requestInterruptableAction {
                                    activateMainSidebarSection(section)
                                }
                            } label: {
                                HStack(spacing: 10) {
                                    ZStack {
                                        RoundedRectangle(cornerRadius: 7)
                                            .fill(isSelected ? Color.white.opacity(0.22) : Color.secondary.opacity(0.10))
                                            .frame(width: 28, height: 28)
                                        Image(systemName: section.iconName)
                                            .font(.system(size: 13, weight: .semibold))
                                            .foregroundColor(isSelected ? .white : .primary)
                                    }
                                    Text(section.rawValue)
                                        .font(.system(size: 13, weight: .semibold))
                                        .foregroundColor(isSelected ? .white : .primary)
                                    Spacer()
                                    if section == .jobs && !store.jobs.isEmpty {
                                        if isSelected {
                                            Text("\(store.jobs.count)")
                                                .font(.system(size: 11, weight: .bold))
                                                .foregroundColor(.white)
                                                .padding(.horizontal, 7)
                                                .padding(.vertical, 2)
                                                .background(Capsule().fill(Color.white.opacity(0.24)))
                                        } else {
                                            StatusBadge(text: "\(store.jobs.count)", color: .blue)
                                        }
                                    } else if section == .followUpTracker && (!store.outreachThreads.isEmpty || store.outreachSummary.actionRequiredCount > 0) {
                                        let badgeVal = store.outreachSummary.actionRequiredCount > 0
                                            ? "\(store.outreachSummary.actionRequiredCount)"
                                            : "\(store.outreachThreads.count)"
                                        if isSelected {
                                            Text(badgeVal)
                                                .font(.system(size: 11, weight: .bold))
                                                .foregroundColor(.white)
                                                .padding(.horizontal, 7)
                                                .padding(.vertical, 2)
                                                .background(Capsule().fill(Color.white.opacity(0.24)))
                                        } else {
                                            StatusBadge(text: badgeVal, color: .blue)
                                        }
                                    } else if section == .resumes && !store.documents.isEmpty {
                                        if isSelected {
                                            Text("\(store.documents.count)")
                                                .font(.system(size: 11, weight: .bold))
                                                .foregroundColor(.white)
                                                .padding(.horizontal, 7)
                                                .padding(.vertical, 2)
                                                .background(Capsule().fill(Color.white.opacity(0.24)))
                                        } else {
                                            StatusBadge(text: "\(store.documents.count)", color: .blue)
                                        }
                                    } else if section == .agentChat && store.unreadAgentMessagesCount > 0 {
                                        if isSelected {
                                            Text("\(store.unreadAgentMessagesCount)")
                                                .font(.system(size: 11, weight: .bold))
                                                .foregroundColor(.white)
                                                .padding(.horizontal, 7)
                                                .padding(.vertical, 2)
                                                .background(Capsule().fill(Color.white.opacity(0.24)))
                                        } else {
                                            StatusBadge(text: "\(store.unreadAgentMessagesCount)", color: .blue)
                                        }
                                    }
                                }
                                .padding(.horizontal, 10)
                                .padding(.vertical, 6)
                                .background(
                                    RoundedRectangle(cornerRadius: 8)
                                        .fill(isSelected ? Color.accentColor : Color.clear)
                                )
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                        }

                        // Browser Launcher Row (opens in a separate window; never remains in focus)
                        Button {
                            if store.isForceUpdateLocked {
                                store.showUpdateModal = true
                            } else {
                                store.sendActionInBackground("launch_browser_session", payload: ["target": "job_search"])
                            }
                        } label: {
                            HStack(spacing: 10) {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(Color.secondary.opacity(0.10))
                                        .frame(width: 28, height: 28)
                                    Image(systemName: "globe")
                                        .font(.system(size: 13, weight: .semibold))
                                        .foregroundColor(store.isForceUpdateLocked ? .secondary : .primary)
                                }
                                Text("Browser")
                                    .font(.system(size: 13, weight: .semibold))
                                    .foregroundColor(store.isForceUpdateLocked ? .secondary : .primary)
                                Spacer()
                                if store.isForceUpdateLocked {
                                    Text("View-Only")
                                        .font(.system(size: 10, weight: .semibold))
                                        .foregroundColor(.secondary)
                                } else {
                                    Image(systemName: "arrow.up.forward.app")
                                        .font(.system(size: 11, weight: .semibold))
                                        .foregroundColor(.secondary)
                                }
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .help(store.isForceUpdateLocked ? "Required update pending — Browser launch is disabled in view-only mode" : "Open AutoApply Browser in a separate window")

                        // Share Feedback / Help Us Improve Row
                        Button {
                            store.openFeedbackModal()
                        } label: {
                            HStack(spacing: 10) {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(Color.secondary.opacity(0.10))
                                        .frame(width: 28, height: 28)
                                    Image(systemName: "megaphone.fill")
                                        .font(.system(size: 12.5, weight: .semibold))
                                        .foregroundColor(.secondary)
                                }
                                Text("Share Feedback")
                                    .font(.system(size: 13, weight: .semibold))
                                    .foregroundColor(.primary)
                                Spacer()
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .help("Share Feedback or Help Us Improve — automatically captures Desktop & Browser screenshots")
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 6)
                }

                if store.updateAvailable {
                    VStack(spacing: 0) {
                        Button {
                            store.showUpdateModal = true
                        } label: {
                            HStack(spacing: 8) {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(Color.secondary.opacity(0.12))
                                        .frame(width: 26, height: 26)
                                    Image(systemName: store.updateRequired ? "exclamationmark.arrow.triangle.2.circlepath" : "arrow.down.circle.fill")
                                        .font(.system(size: 12, weight: .semibold))
                                        .foregroundColor(store.updateRequired ? .orange : .green)
                                }
                                Text(store.updateRequired ? "Update Required" : "Update Available")
                                    .font(.system(size: 12.5, weight: .semibold))
                                    .foregroundColor(.primary)
                                    .lineLimit(1)
                                Spacer(minLength: 4)
                                Text("v\(store.latestAppVersion)")
                                    .font(.system(size: 10.5, weight: .semibold, design: .rounded))
                                    .foregroundColor(store.updateRequired ? .orange : .secondary)
                                    .padding(.horizontal, 6)
                                    .padding(.vertical, 2)
                                    .background(Capsule().fill(Color.secondary.opacity(0.12)))
                            }
                            .padding(.horizontal, 8)
                            .padding(.vertical, 6)
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 2)
                }

                // Bottom-Pinned "Activate License" Sidebar Button (Clean frameless row, no dot before countdown)
                if !store.isLicenseActivated || store.selectedSection == .activateLicense {
                    let isLicSelected = (store.selectedSection == .activateLicense)
                    let isExpired = store.isLicenseExpired
                    let badgeTint: Color = store.isLicenseActivated ? .green : (isExpired ? .orange : .accentColor)
                    VStack(spacing: 0) {
                        Button {
                            guard store.selectedSection != .activateLicense else { return }
                            store.requestInterruptableAction {
                                store.selectedSection = .activateLicense
                            }
                        } label: {
                            HStack(spacing: 8) {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(isLicSelected ? Color.white.opacity(0.22) : Color.secondary.opacity(0.12))
                                        .frame(width: 26, height: 26)
                                    Image(systemName: isExpired ? "exclamationmark.key.fill" : "key.fill")
                                        .font(.system(size: 12, weight: .semibold))
                                        .foregroundColor(isLicSelected ? .white : badgeTint)
                                }
                                Text("Activate License")
                                    .font(.system(size: 12.5, weight: .semibold))
                                    .foregroundColor(isLicSelected ? .white : .primary)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                                Spacer(minLength: 4)
                                Text(store.isLicenseActivated ? "Pro" : store.trialSidebarShortLabel)
                                    .font(.system(size: 10.5, weight: .semibold, design: .rounded))
                                    .foregroundColor(isLicSelected ? .white : (isExpired ? .orange : .secondary))
                                    .lineLimit(1)
                                    .padding(.horizontal, 6)
                                    .padding(.vertical, 2)
                                    .background(
                                        Capsule()
                                            .fill(isLicSelected ? Color.white.opacity(0.20) : Color.secondary.opacity(0.12))
                                    )
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .padding(.horizontal, 8)
                            .padding(.vertical, 6)
                            .background(
                                RoundedRectangle(cornerRadius: 8)
                                    .fill(isLicSelected ? Color.accentColor : Color.clear)
                            )
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .help("View your Free Trial status, purchase a license key, or activate your Pro license.")
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 4)
                }

                Divider()

                // Simple Status Footer
                HStack(spacing: 8) {
                    Text(store.isForceUpdateLocked ? "View-Only" : (store.emergencyStopActive ? "Paused" : (store.canRunAutomation ? "Ready" : "Setup")))
                        .font(.caption.bold())
                        .foregroundColor(store.isForceUpdateLocked ? Color.orange : (store.emergencyStopActive ? Color.red : (store.canRunAutomation ? Color.green : Color.orange)))
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                    Spacer(minLength: 4)
                    Button {
                        if store.isForceUpdateLocked {
                            store.showUpdateModal = true
                        } else if store.isLicenseExpired {
                            store.emergencyStopActive = true
                            store.statusCopy = "Paused"
                            store.showLicenseExpiredModal = true
                        } else {
                            let nextActive = !store.emergencyStopActive
                            store.emergencyStopActive = nextActive
                            store.statusCopy = nextActive ? "Paused" : "Ready"
                            store.sendActionInBackground("toggle_emergency_stop", payload: ["active": nextActive])
                        }
                    } label: {
                        Label(
                            store.isForceUpdateLocked ? "Update" : (store.emergencyStopActive ? "Start" : "Pause"),
                            systemImage: store.isForceUpdateLocked ? "arrow.down.circle.fill" : (store.emergencyStopActive ? "play.fill" : "pause.fill")
                        )
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .help(
                        store.isForceUpdateLocked
                            ? "Required update pending — update AutoApply to resume execution."
                            : (store.emergencyStopActive
                                ? "Start automated browser autofill and scheduled outreach tasks."
                                : "Pause all automated browser autofill and background outreach tasks immediately.")
                    )
                }
                .padding(14)
                .background(Color(NSColor.controlBackgroundColor))
            }
            .frame(width: 225)
            .frame(maxHeight: .infinity)
            .background(Color(NSColor.controlBackgroundColor))

            Divider()

            VStack(spacing: 0) {
                TopHeaderBar(store: store)
                Divider()
                if store.isForceUpdateLocked {
                    HStack(spacing: 12) {
                        Image(systemName: "exclamationmark.arrow.triangle.2.circlepath")
                            .font(.system(size: 14, weight: .semibold))
                            .foregroundColor(.orange)
                        VStack(alignment: .leading, spacing: 2) {
                            Text("Required Update (v\(store.latestAppVersion)) · View-Only Mode")
                                .font(.system(size: 12.5, weight: .semibold))
                                .foregroundColor(.primary)
                            Text("Automations and execution are disabled until you update. You can view your workspace and access Settings.")
                                .font(.system(size: 11.5))
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }
                        Spacer()
                        if store.selectedSection != .settings {
                            Button {
                                store.selectedSection = .settings
                            } label: {
                                Text("Settings")
                                    .font(.system(size: 12, weight: .medium))
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                        }
                        Button {
                            store.showUpdateModal = true
                        } label: {
                            Label("Update Now", systemImage: "arrow.down.circle.fill")
                                .font(.system(size: 12, weight: .semibold))
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.small)
                    }
                    .padding(.horizontal, 20)
                    .padding(.vertical, 10)
                    .background(Color(NSColor.controlBackgroundColor))
                    Divider()
                }
                Group {
                    if store.selectedSection == .agentChat {
                        VStack(alignment: .leading, spacing: 12) {
                            HermesAgentChatView(store: store)
                                .frame(maxWidth: .infinity, maxHeight: .infinity)
                        }
                        .padding(18)
                        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                        .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .activity {
                        ActivityWorkspaceView(store: store)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .followUpTracker {
                        FollowUpTrackerWorkspaceView(store: store)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .jobs {
                        JobsWorkspaceView(store: store)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .resumes {
                        ResumesStudioView(store: store)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .knowledgeBase {
                        KnowledgeBaseMarkdownView(store: store)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else if store.selectedSection == .voiceInterview {
                        VoiceInterviewSectionView(store: store)
                            .padding(20)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .background(Color(NSColor.windowBackgroundColor))
                    } else {
                        ScrollView {
                            VStack(alignment: .leading, spacing: 20) {
                                if store.unreadAgentMessagesCount > 0 && !store.latestUnreadAgentNotificationPreview.isEmpty {
                                HStack(spacing: 12) {
                                    Image(systemName: "bubble.left.and.exclamationmark.bubble.right.fill")
                                        .font(.system(size: 15, weight: .semibold))
                                        .foregroundColor(.teal)
                                    VStack(alignment: .leading, spacing: 2) {
                                        Text("New AI Agent Reply (\(store.unreadAgentMessagesCount) unread)")
                                            .font(.system(size: 12.5, weight: .bold))
                                            .foregroundColor(.primary)
                                        Text(store.latestUnreadAgentNotificationPreview)
                                            .font(.system(size: 11.5))
                                            .foregroundColor(.secondary)
                                            .lineLimit(1)
                                    }
                                    Spacer()
                                    Button {
                                        store.selectedSection = .agentChat
                                    } label: {
                                        Label("Open Chat", systemImage: "bubble.left.and.bubble.right.fill")
                                            .font(.system(size: 13, weight: .bold))
                                            .padding(.horizontal, 8)
                                            .lineLimit(1)
                                            .fixedSize(horizontal: true, vertical: false)
                                    }
                                    .buttonStyle(.borderedProminent)
                                    .tint(.teal)
                                    .controlSize(.large)
                                    .fixedSize(horizontal: true, vertical: false)

                                    Button {
                                        store.latestUnreadAgentNotificationPreview = ""
                                    } label: {
                                        Image(systemName: "xmark")
                                            .font(.system(size: 11, weight: .semibold))
                                            .foregroundColor(.secondary)
                                    }
                                    .buttonStyle(.plain)
                                }
                                .padding(12)
                                .background(RoundedRectangle(cornerRadius: 10).fill(Color.teal.opacity(0.10)))
                                .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.teal.opacity(0.35), lineWidth: 1))
                            }

                            switch store.selectedSection {
                            case .setup:
                                SetupWizardView(store: store)
                            case .jobs:
                                JobsWorkspaceView(store: store)
                            case .followUpTracker:
                                FollowUpTrackerWorkspaceView(store: store)
                            case .resumes:
                                ResumesStudioView(store: store)
                            case .knowledgeBase:
                                KnowledgeBaseMarkdownView(store: store)
                            case .voiceInterview:
                                VoiceInterviewSectionView(store: store)
                            case .agentChat:
                                HermesAgentChatView(store: store)
                            case .activity:
                                ActivityWorkspaceView(store: store)
                            case .connections:
                                ConnectionsView(store: store)
                            case .passwords:
                                PasswordManagerSectionView(store: store)
                            case .settings:
                                SettingsView(store: store)
                            case .activateLicense:
                                ActivateLicenseSectionView(store: store)
                            }
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(24)
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                        .background(Color(NSColor.windowBackgroundColor))
                    }
                }
                .overlay(alignment: .topTrailing) {
                    ToastNotificationOverlayView(store: store)
                        .padding(.top, 12)
                        .padding(.trailing, 20)
                }
            }
            .frame(minWidth: 680, maxWidth: .infinity, maxHeight: .infinity)
            .background(Color(NSColor.windowBackgroundColor))
        }
        .frame(minWidth: 960, maxWidth: .infinity, minHeight: 680, maxHeight: .infinity)
        .onChange(of: store.selectedSection) { newSection in
            store.statusBannerMessage = ""
            store.errorMessage = ""
            if newSection == .settings {
                store.expandedWorkPrefItemId = store.isLicenseActivated ? "" : "license_section"
            }
        }
        .alert("Stop Recording?", isPresented: $store.showInterruptRecordingAlert) {
            Button("Stop Recording", role: .destructive) {
                store.confirmInterruptRecording()
            }
            Button("Keep Recording", role: .cancel) {
                store.cancelInterruptRecording()
            }
        } message: {
            Text("Are you sure you want to stop the recording? The content will be lost.")
        }
        .alert(
            "Delete Login?",
            isPresented: Binding(
                get: { store.pendingDeletePasswordEntry != nil },
                set: { if !$0 { store.pendingDeletePasswordEntry = nil } }
            ),
            presenting: store.pendingDeletePasswordEntry
        ) { entry in
            Button("Delete", role: .destructive) {
                store.deletePasswordVaultEntry(entry.id)
                store.pendingDeletePasswordEntry = nil
            }
            Button("Cancel", role: .cancel) {
                store.pendingDeletePasswordEntry = nil
            }
        } message: { entry in
            Text("Are you sure you want to delete the saved login for \"\(entry.websiteName.isEmpty ? "this website" : entry.websiteName)\"? This action cannot be undone.")
        }
        .alert(
            "Delete Job?",
            isPresented: Binding(
                get: { store.pendingDeleteJob != nil },
                set: { if !$0 { store.pendingDeleteJob = nil } }
            ),
            presenting: store.pendingDeleteJob
        ) { job in
            Button("Delete", role: .destructive) {
                store.sendAction("delete_job_posting", payload: ["job_id": job.jobId])
                store.pendingDeleteJob = nil
            }
            Button("Cancel", role: .cancel) {
                store.pendingDeleteJob = nil
            }
        } message: { job in
            Text("Are you sure you want to remove \"\(job.title)\" at \(job.companyName) from your job queue?")
        }
        .alert(
            "Delete Resume?",
            isPresented: Binding(
                get: { store.pendingDeleteResume != nil },
                set: { if !$0 { store.pendingDeleteResume = nil } }
            ),
            presenting: store.pendingDeleteResume
        ) { res in
            Button("Delete", role: .destructive) {
                store.sendAction("delete_resume", payload: ["reference_id": res.referenceId])
                store.pendingDeleteResume = nil
            }
            Button("Cancel", role: .cancel) {
                store.pendingDeleteResume = nil
            }
        } message: { res in
            Text("Are you sure you want to delete \"\(res.filename)\"? This action cannot be undone.")
        }
        .alert(
            "Delete Conversation?",
            isPresented: Binding(
                get: { store.pendingDeleteChatSessionId != nil },
                set: { if !$0 { store.pendingDeleteChatSessionId = nil } }
            )
        ) {
            Button("Delete", role: .destructive) {
                if let sid = store.pendingDeleteChatSessionId {
                    store.deleteHermesSession(sid)
                }
                store.pendingDeleteChatSessionId = nil
            }
            Button("Cancel", role: .cancel) {
                store.pendingDeleteChatSessionId = nil
            }
        } message: {
            Text("Are you sure you want to delete this conversation? This action cannot be undone.")
        }
        .sheet(isPresented: $store.showAddEditPasswordCard) {
            PasswordVaultEditorModalView(store: store)
        }
        .sheet(isPresented: $store.showUpdateModal) {
            SoftwareUpdateSheetView(store: store)
        }
        .sheet(isPresented: $store.showPrivacyModal) {
            PrivacyPledgeModalView(store: store)
        }
        .sheet(isPresented: $store.showCustomModelSheet) {
            CustomOpenRouterModelSheetView(store: store)
        }
        .sheet(isPresented: $store.showFeedbackModal) {
            FeedbackSubmissionModalView(store: store)
        }
        .sheet(isPresented: $store.showLicenseExpiredModal) {
            LicenseExpiredPurchaseSheetView(store: store)
        }
    }
}

struct TopHeaderBar: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.accentColor.opacity(0.12))
                    .frame(width: 34, height: 34)
                Image(systemName: store.selectedSection.iconName)
                    .font(.system(size: 15.5, weight: .semibold))
                    .foregroundColor(.accentColor)
                    .frame(width: 18, height: 18)
            }
            VStack(alignment: .leading, spacing: 2) {
                Text(store.selectedSection.rawValue)
                    .font(.system(size: 17.5, weight: .bold))
                Text(headerSubtitle)
                    .font(.caption)
                    .foregroundColor(.secondary)
            }
            Spacer()

            Button {
                store.openFeedbackModal()
            } label: {
                Label("Share Feedback", systemImage: "megaphone.fill")
                    .font(.system(size: 13, weight: .semibold))
                    .padding(.horizontal, 6)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
            }
            .buttonStyle(.bordered)
            .controlSize(.large)
            .fixedSize(horizontal: true, vertical: false)
            .help("Share feedback, report a bug, or suggest an improvement with automatic screenshots.")

            Button {
                store.showPrivacyModal = true
            } label: {
                Label("100% On-Device Privacy", systemImage: "lock.shield.fill")
                    .font(.system(size: 13, weight: .semibold))
                    .padding(.horizontal, 6)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
            }
            .buttonStyle(.bordered)
            .controlSize(.large)
            .fixedSize(horizontal: true, vertical: false)
            .help("View how AutoApply stores all your resumes, credentials, and personal data 100% locally on your Mac.")
        }
        .padding(.horizontal, 24)
        .padding(.vertical, 12)
        .background(Color(NSColor.windowBackgroundColor))
    }

    private var headerSubtitle: String {
        switch store.selectedSection {
        case .setup: return "Complete these quick steps to get started."
        case .jobs: return "Browse jobs, import open tabs, and autofill applications."
        case .followUpTracker: return "Read and respond to Email and LinkedIn conversations, track follow-ups, and draft replies."
        case .resumes: return "Manage your resume and create tailored resumes and cover letters."
        case .knowledgeBase: return "Review your profile details and saved experience."
        case .voiceInterview: return "Listen to each question in a natural voice and speak your answer."
        case .agentChat: return "Ask questions, tailor applications, and update your profile."
        case .activity: return "Automations and activity history."
        case .connections: return "Manage your AI key, accounts, and optional Capcha Solver key."
        case .passwords: return "Saved logins for job boards and application portals."
        case .settings: return "Adjust application preferences, updates, and workspace data."
        case .activateLicense: return "Manage your trial status, subscription plan, and license activation."
        }
    }
}

// MARK: - Board View Drag & Drop Delegate

struct KanbanColumnDropDelegate: DropDelegate {
    let columnKey: String
    let store: WorkspaceStore

    func validateDrop(info: DropInfo) -> Bool {
        return !store.draggingJobId.isEmpty
            || info.hasItemsConforming(to: [UTType.plainText, UTType.text, UTType.utf8PlainText])
    }

    func dropEntered(info: DropInfo) {
        let col = columnKey
        let st = store
        Task { @MainActor in
            st.dropTargetColumnKey = col
        }
    }

    func dropExited(info: DropInfo) {
        let col = columnKey
        let st = store
        Task { @MainActor in
            if st.dropTargetColumnKey == col {
                st.dropTargetColumnKey = ""
            }
        }
    }

    func dropUpdated(info: DropInfo) -> DropProposal? {
        return DropProposal(operation: .move)
    }

    func performDrop(info: DropInfo) -> Bool {
        let col = columnKey
        let st = store
        let activeDragId = store.draggingJobId
        if !activeDragId.isEmpty {
            Task { @MainActor in
                st.moveJobToStage(activeDragId, targetStage: col)
            }
            return true
        }
        let providers = info.itemProviders(for: [UTType.plainText, UTType.text, UTType.utf8PlainText])
        guard let provider = providers.first else {
            Task { @MainActor in
                st.dropTargetColumnKey = ""
                st.draggingJobId = ""
            }
            return false
        }
        provider.loadObject(ofClass: NSString.self) { item, _ in
            if let str = item as? String, !str.isEmpty {
                Task { @MainActor in
                    st.moveJobToStage(str, targetStage: col)
                }
            } else {
                Task { @MainActor in
                    st.dropTargetColumnKey = ""
                    st.draggingJobId = ""
                }
            }
        }
        return true
    }
}

// MARK: - Activity Workspace (Minimal Linear/Raycast-Inspired Automations & Activity History)

struct ActivityWorkspaceView: View {
    @ObservedObject var store: WorkspaceStore

    private var isEngineRunning: Bool {
        !store.emergencyStopActive && store.canRunAutomation
    }

    private var activeRunningLanes: [WorkerLaneTaskItem] {
        store.workerLanes.filter { $0.enabled }
    }

    private var pausedLanes: [WorkerLaneTaskItem] {
        store.workerLanes.filter { !$0.enabled }
    }

    private var filteredWorkerLanes: [WorkerLaneTaskItem] {
        switch store.workerLaneFilterMode {
        case "active":
            return activeRunningLanes.isEmpty ? store.workerLanes : activeRunningLanes
        case "paused":
            return pausedLanes
        default:
            return store.workerLanes
        }
    }

    private var filteredActivities: [UnifiedActivityEventItem] {
        let cat = store.activityCategoryFilter
        let q = store.activitySearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return store.unifiedActivities.filter { item in
            let matchesCat = (cat == "all") || (item.category == cat)
            if !matchesCat { return false }
            if q.isEmpty { return true }
            let hay = "\(item.title) \(item.subtitle) \(item.platform) \(item.detail) \(item.statusBadge) \(item.categoryLabel)".lowercased()
            return hay.contains(q)
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // 1. Consolidated Top Bar: View Switcher (Automations | Activity History) + Compact Status + KPI Strip + Controls
            unifiedTopControlBar

            Divider()

            // 2. Main Tab Content
            ScrollView {
                VStack(alignment: .leading, spacing: 14) {
                    if store.activitySubtab == "history" {
                        activityHistoryTabView
                    } else {
                        automationsTabView
                    }
                }
                .padding(.horizontal, 18)
                .padding(.vertical, 14)
                .frame(maxWidth: .infinity, alignment: .topLeading)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(NSColor.windowBackgroundColor))
    }

    // MARK: - 1. Unified Top Control Bar

    private var unifiedTopControlBar: some View {
        let running = isEngineRunning
        let activeCount = activeRunningLanes.count
        let statusDotColor: Color = running ? .green : .orange
        let statusText = running
            ? "Running · \(activeCount) active \(activeCount == 1 ? "agent" : "agents")"
            : "Paused · \(activeCount) configured"

        return HStack(spacing: 10) {
            // Segmented Tab Switcher: Automations | Activity History
            HStack(spacing: 3) {
                subtabButton(
                    id: "automations",
                    title: "Automations",
                    systemIcon: "bolt.horizontal.fill",
                    badgeCount: activeCount
                )
                subtabButton(
                    id: "history",
                    title: "Activity History",
                    systemIcon: "clock.arrow.circlepath",
                    badgeCount: store.activitySummary.totalActivitiesCount
                )
            }
            .padding(3)
            .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
            .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

            Divider()
                .frame(height: 18)

            // Compact Status Indicator (replaces giant green hero banner)
            HStack(spacing: 6) {
                Text(statusText)
                    .font(.system(size: 12, weight: .semibold))
                    .foregroundColor(statusDotColor)
                    .lineLimit(1)
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 4)

            Divider()
                .frame(height: 18)

            // Compact Inline KPI Indicators (replaces six oversized colorful cards)
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    compactKpiChip(
                        categoryId: "applied",
                        label: "Applied",
                        count: store.activitySummary.appliedCount,
                        attentionDot: nil
                    )
                    compactKpiChip(
                        categoryId: "filled_not_submitted",
                        label: "Needs Review",
                        count: store.activitySummary.filledNotSubmittedCount,
                        attentionDot: store.activitySummary.filledNotSubmittedCount > 0 ? .orange : nil
                    )
                    compactKpiChip(
                        categoryId: "messaged",
                        label: "Messaged",
                        count: store.activitySummary.messagedCount,
                        attentionDot: nil
                    )
                    compactKpiChip(
                        categoryId: "resume_tailored",
                        label: "Resumes",
                        count: store.activitySummary.resumesTailoredCount,
                        attentionDot: nil
                    )
                }
            }

            Spacer(minLength: 8)

            // Standardized Pause / Resume Control
            Button {
                if store.isLicenseExpired {
                    store.emergencyStopActive = true
                    store.statusCopy = "Paused"
                    store.showLicenseExpiredModal = true
                } else {
                    let nextStop = !store.emergencyStopActive
                    store.emergencyStopActive = nextStop
                    store.statusCopy = nextStop ? "Paused" : "Ready"
                    store.sendActionInBackground("toggle_emergency_stop", payload: ["active": nextStop])
                }
            } label: {
                Label(
                    running ? "Pause" : "Resume",
                    systemImage: running ? "pause.fill" : "play.fill"
                )
                .font(.system(size: 12, weight: .semibold))
                .padding(.horizontal, 6)
                .lineLimit(1)
                .fixedSize(horizontal: true, vertical: false)
            }
            .buttonStyle(.bordered)
            .controlSize(.regular)
            .fixedSize(horizontal: true, vertical: false)

            EllipsisActionMenuButton(helpText: "Refresh activity, scan for eligible jobs now, or reset filters.") {
                Button {
                    store.refreshState()
                } label: {
                    Label("Refresh Activity", systemImage: "arrow.clockwise")
                }
                Button {
                    store.sendActionInBackground("discover_and_sync_eligible_jobs", payload: ["run_live_discovery": true])
                } label: {
                    Label("Scan for Eligible Jobs Now", systemImage: "sparkle.magnifyingglass")
                }
                if store.activityCategoryFilter != "all" || !store.activitySearchQuery.isEmpty || store.workerLaneFilterMode != "active" {
                    Divider()
                    Button {
                        store.activityCategoryFilter = "all"
                        store.activitySearchQuery = ""
                        store.workerLaneFilterMode = "active"
                    } label: {
                        Label("Reset Filters", systemImage: "arrow.counterclockwise")
                    }
                }
            }
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 10)
        .background(Color(NSColor.windowBackgroundColor))
    }

