    private func cleanAutomationCategory(_ raw: String) -> String {
        let lower = raw.lowercased()
        if lower.contains("discovery") || lower.contains("scout") { return "Job Discovery" }
        if lower.contains("outreach") || lower.contains("follow") { return "Follow-ups" }
        if lower.contains("quality") || lower.contains("checkpoint") || lower.contains("verif") { return "Verification" }
        if lower.contains("application") || lower.contains("worker") { return "Applications" }
        return raw
    }

    private func cleanAutomationTitle(_ raw: String) -> String {
        var s = raw
        for tok in [" Worker Lane", " Lane", " Scout"] {
            s = s.replacingOccurrences(of: tok, with: "")
        }
        return s.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func automationCompactRow(_ lane: WorkerLaneTaskItem) -> some View {
        let isExpanded = (store.expandedAutomationId == lane.id)
        let isRunningLane = lane.enabled && isEngineRunning
        let statusDotColor: Color = isRunningLane ? .green : (lane.enabled ? .orange : .secondary.opacity(0.45))
        let statusText = isRunningLane ? "Active" : (lane.enabled ? "On Hold" : "Paused")

        return VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 12) {
                // Name + Category (clickable for progressive disclosure)
                Button {
                    withAnimation(.easeInOut(duration: 0.14)) {
                        store.expandedAutomationId = isExpanded ? "" : lane.id
                    }
                } label: {
                    HStack(spacing: 9) {
                        Image(systemName: isExpanded ? "chevron.down" : "chevron.right")
                            .font(.system(size: 10, weight: .semibold))
                            .foregroundColor(.secondary)
                            .frame(width: 12)
                        Image(systemName: lane.icon)
                            .font(.system(size: 12.5, weight: .medium))
                            .foregroundColor(.secondary)
                            .frame(width: 16)
                        Text(cleanAutomationTitle(lane.title))
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.primary)
                            .lineLimit(1)
                        Text("· \(cleanAutomationCategory(lane.category))")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                        Spacer(minLength: 4)
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .frame(maxWidth: .infinity, alignment: .leading)

                // Schedule
                Text(lane.frequencyLabel)
                    .font(.system(size: 12))
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                    .frame(width: 130, alignment: .leading)

                // Last Run
                Text(lane.lastRunLabel)
                    .font(.system(size: 11.5).monospacedDigit())
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                    .frame(width: 135, alignment: .leading)

                // Status
                HStack(spacing: 6) {
                    Text(statusText)
                        .font(.system(size: 12, weight: .medium))
                        .foregroundColor(isRunningLane ? statusDotColor : .secondary)
                        .lineLimit(1)
                }
                .frame(width: 90, alignment: .leading)

                // Standardized Action Control
                HStack(spacing: 6) {
                    Spacer(minLength: 0)
                    Button {
                        store.sendActionInBackground(
                            "toggle_periodic_task",
                            payload: [
                                "task_id": lane.id,
                                "enabled": !lane.enabled,
                            ]
                        )
                    } label: {
                        Text(lane.enabled ? "Pause" : "Enable")
                            .font(.system(size: 11.5, weight: .medium))
                            .frame(minWidth: 52)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.small)
                }
                .frame(width: 96, alignment: .trailing)
            }
            .padding(.horizontal, 14)
            .padding(.vertical, 9)
            .background(isExpanded ? Color.secondary.opacity(0.04) : Color.clear)

            // Progressive Disclosure Drawer (revealed only on demand)
            if isExpanded {
                VStack(alignment: .leading, spacing: 6) {
                    if !lane.description.isEmpty {
                        Text(lane.description)
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    HStack(spacing: 16) {
                        if !lane.platforms.isEmpty {
                            Text("Channels: \(lane.platforms)")
                                .font(.system(size: 11.5))
                                .foregroundColor(.secondary)
                        }
                        Text("Completed: \(lane.completedRuns.formatted()) runs")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                        if !lane.nextRunLabel.isEmpty {
                            Text("Next: \(lane.nextRunLabel)")
                                .font(.system(size: 11.5))
                                .foregroundColor(.secondary)
                        }
                        Spacer()
                    }
                }
                .padding(.leading, 46)
                .padding(.trailing, 14)
                .padding(.bottom, 10)
                .padding(.top, 2)
                .background(Color.secondary.opacity(0.04))
            }
        }
    }

