                    .lineLimit(1)
            }
            .padding(.horizontal, 9)
            .padding(.vertical, 4)
            .background(
                Capsule()
                    .fill(isSelected ? Color.accentColor : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                Capsule()
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.15), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }

    private func conciseEventTypeLabel(_ category: String) -> String {
        switch category {
        case "applied": return "Applied"
        case "filled_not_submitted": return "Needs Review"
        case "messaged": return "Messaged"
        case "resume_tailored": return "Resume"
        case "periodic_run": return "Automation"
        default: return "Activity"
        }
    }

    private func subtleEventDotColor(_ category: String) -> Color {
        switch category {
        case "applied": return .green
        case "filled_not_submitted": return .orange
        default: return .secondary.opacity(0.45)
        }
    }

    private func activityHistoryCompactRow(_ item: UnifiedActivityEventItem) -> some View {
        let isExpanded = (store.expandedActivityEventId == item.id)
        let summaryLabel = !item.platform.isEmpty ? item.platform : item.statusBadge

        return VStack(alignment: .leading, spacing: 0) {
            Button {
                withAnimation(.easeInOut(duration: 0.14)) {
                    store.expandedActivityEventId = isExpanded ? "" : item.id
                }
            } label: {
                HStack(spacing: 12) {
                    // Chevron + Title
                    HStack(spacing: 8) {
                        Image(systemName: isExpanded ? "chevron.down" : "chevron.right")
                            .font(.system(size: 10, weight: .semibold))
                            .foregroundColor(.secondary)
                            .frame(width: 12)
                        Text(item.title)
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.primary)
                            .lineLimit(1)
                        Spacer(minLength: 4)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)

                    // Concise Type
                    Text(conciseEventTypeLabel(item.category))
                        .font(.system(size: 12, weight: item.category == "filled_not_submitted" ? .semibold : .regular))
                        .foregroundColor(item.category == "filled_not_submitted" ? .orange : .secondary)
                        .lineLimit(1)
                        .frame(width: 110, alignment: .leading)

                    // Concise Summary / Platform
                    Text(summaryLabel)
                        .font(.system(size: 12))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                        .frame(width: 220, alignment: .leading)

                    // Timestamp
                    Text(item.timestamp)
                        .font(.system(size: 11.5).monospacedDigit())
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                        .frame(width: 125, alignment: .trailing)
                }
                .padding(.horizontal, 14)
                .padding(.vertical, 9)
                .background(isExpanded ? Color.secondary.opacity(0.04) : Color.clear)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)

            // Progressive Disclosure Detail + Standardized Actions
            if isExpanded {
                VStack(alignment: .leading, spacing: 8) {
                    if !item.detail.isEmpty {
                        Text(item.detail)
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }

                    HStack(spacing: 8) {
                        if !item.statusBadge.isEmpty {
                            Text(item.statusBadge)
                                .font(.system(size: 11.5, weight: .medium))
                                .foregroundColor(.secondary)
                        }

                        Spacer()

                        if !item.url.isEmpty, let targetURL = URL(string: item.url) {
                            Button {
                                NSWorkspace.shared.open(targetURL)
                            } label: {
                                Label("Open Page", systemImage: "arrow.up.right.square")
                                    .font(.system(size: 11.5, weight: .medium))
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                        }

                        if !item.jobId.isEmpty {
                            Button {
                                store.selectedJobId = item.jobId
                                store.selectedSection = .jobs
                            } label: {
                                Label("View in Jobs", systemImage: "briefcase")
                                    .font(.system(size: 11.5, weight: .medium))
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                        }

                        if !item.threadId.isEmpty {
                            Button {
                                store.selectedOutreachThreadId = item.threadId
                                store.selectedSection = .followUpTracker
                            } label: {
                                Label("Open in Messages", systemImage: "bubble.left.and.bubble.right")
                                    .font(.system(size: 11.5, weight: .medium))
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                        }

                        if !item.documentId.isEmpty {
                            Button {
                                store.selectedDocumentId = item.documentId
                                store.selectedSection = .resumes
                            } label: {
                                Label("View Resume", systemImage: "doc.richtext")
                                    .font(.system(size: 11.5, weight: .medium))
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                        }
                    }
                }
                .padding(.leading, 40)
                .padding(.trailing, 14)
                .padding(.bottom, 10)
                .padding(.top, 2)
                .background(Color.secondary.opacity(0.04))
            }
        }
    }
}

// MARK: - Share Feedback / Help Us Improve Modal

struct FeedbackSubmissionModalView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Header
            HStack(spacing: 14) {
                ZStack {
                    RoundedRectangle(cornerRadius: 10)
                        .fill(Color.accentColor.opacity(0.14))
                        .frame(width: 42, height: 42)
                    Image(systemName: "megaphone.fill")
                        .font(.system(size: 19, weight: .semibold))
                        .foregroundColor(.accentColor)
                }
                VStack(alignment: .leading, spacing: 3) {
                    Text("Share Feedback & Help Us Improve")
                        .font(.system(size: 18, weight: .bold))
                    Text("Report a bug or suggest an improvement. Screenshots of the Desktop App and active Browser are captured automatically.")
                        .font(.system(size: 12.5))
                        .foregroundColor(.secondary)
                }
                Spacer()
                Button {
                    store.showFeedbackModal = false
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 20))
                        .foregroundColor(.secondary)
                }
                .buttonStyle(.plain)
            }
            .padding(.horizontal, 24)
            .padding(.vertical, 18)
            .background(Color(NSColor.controlBackgroundColor))

            Divider()

            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    if !store.feedbackSubmittedBanner.isEmpty {
                        HStack(spacing: 10) {
                            Image(systemName: "checkmark.circle.fill")
                                .font(.system(size: 16, weight: .bold))
                                .foregroundColor(.green)
                            Text(store.feedbackSubmittedBanner)
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundColor(.primary)
                            Spacer()
                        }
                        .padding(12)
                        .background(RoundedRectangle(cornerRadius: 10).fill(Color.green.opacity(0.12)))
                        .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.green.opacity(0.35), lineWidth: 1))
                    }

                    // 1. Classification ("Bug" vs "Improvement")
                    VStack(alignment: .leading, spacing: 8) {
                        Text("CLASSIFICATION")
                            .font(.system(size: 11, weight: .bold))
                            .foregroundColor(.secondary)

                        HStack(spacing: 12) {
                            feedbackClassificationCard(
                                id: "bug",
                                title: "Bug",
                                subtitle: "Something isn't working properly or looks broken",
                                icon: "ladybug.fill"
                            )
                            feedbackClassificationCard(
                                id: "improvement",
                                title: "Improvement",
                                subtitle: "Feature request, UX polish, or workflow enhancement",
                                icon: "sparkles"
                            )
                        }
                    }

                    // 2. Auto-Captured Screenshots (Desktop App + Browser as applicable)
                    VStack(alignment: .leading, spacing: 10) {
                        HStack {
                            Text("AUTOMATIC CONTEXT SCREENSHOTS")
                                .font(.system(size: 11, weight: .bold))
                                .foregroundColor(.secondary)
                            Spacer()
                            if store.feedbackIsCapturingScreenshots {
                                HStack(spacing: 6) {
                                    ProgressView()
                                        .controlSize(.small)
                                    Text("Capturing Browser & Desktop...")
                                        .font(.system(size: 11.5, weight: .medium))
                                        .foregroundColor(.secondary)
                                }
                            } else {
                                Button {
                                    store.retakeFeedbackScreenshots()
                                } label: {
                                    Label("Retake Screenshots", systemImage: "camera.rotate")
                                        .font(.system(size: 13, weight: .semibold))
                                        .padding(.horizontal, 6)
                                }
                                .buttonStyle(.bordered)
                                .controlSize(.large)
                            }
                        }

                        let hasActiveBrowserScreenshot = (!store.feedbackBrowserScreenshotPath.isEmpty
                            && FileManager.default.fileExists(atPath: store.feedbackBrowserScreenshotPath))
                            || (store.feedbackIsCapturingScreenshots && store.isAutoApplyBrowserWindowOpenOnScreen())

                        HStack(alignment: .top, spacing: 14) {
                            feedbackScreenshotCard(
                                title: "Desktop App (\(store.selectedSection.rawValue))",
                                subtitle: store.feedbackDesktopScreenshotSize.isEmpty ? "Captured active window" : "PNG • \(store.feedbackDesktopScreenshotSize)",
                                path: store.feedbackDesktopScreenshotPath,
                                isIncluded: store.feedbackIncludeDesktopScreenshot,
                                emptyMessage: "Desktop App window screenshot ready on capture",
                                onToggle: { store.feedbackIncludeDesktopScreenshot.toggle() }
                            )

                            if hasActiveBrowserScreenshot {
                                feedbackScreenshotCard(
                                    title: "AutoApply Browser",
                                    subtitle: !store.feedbackBrowserUrl.isEmpty
                                        ? store.feedbackBrowserUrl
                                        : (store.feedbackBrowserScreenshotSize.isEmpty ? "Capturing active tab…" : "PNG • \(store.feedbackBrowserScreenshotSize)"),
                                    path: store.feedbackBrowserScreenshotPath,
                                    isIncluded: store.feedbackIncludeBrowserScreenshot,
                                    emptyMessage: store.feedbackIsCapturingScreenshots ? "Capturing active AutoApply Browser tab…" : "Browser not currently open (only Desktop screenshot will be sent)",
                                    onToggle: { store.feedbackIncludeBrowserScreenshot.toggle() }
                                )
                            }
                        }
                    }

                    // 3. Comment / Description
                    VStack(alignment: .leading, spacing: 8) {
                        HStack {
                            Text(store.feedbackClassification == "improvement" ? "HOW CAN WE IMPROVE AUTOAPPLY?" : "WHAT HAPPENED OR WENT WRONG?")
                                .font(.system(size: 11, weight: .bold))
                                .foregroundColor(.secondary)
                            Spacer()
                            Text("Section: \(store.selectedSection.rawValue)")
                                .font(.system(size: 11))
                                .foregroundColor(.secondary)
                        }

                        ZStack(alignment: .topLeading) {
                            TextEditor(text: $store.feedbackCommentText)
                                .font(.system(size: 13))
                                .frame(minHeight: 105, maxHeight: 145)
                                .padding(8)
                                .background(RoundedRectangle(cornerRadius: 10).fill(Color(NSColor.textBackgroundColor)))
                                .overlay(
                                    RoundedRectangle(cornerRadius: 10)
                                        .stroke(Color.secondary.opacity(0.25), lineWidth: 1)
                                )
                            if store.feedbackCommentText.isEmpty {
                                Text(
                                    store.feedbackClassification == "improvement"
                                        ? "Describe your idea, workflow improvement, or what would make AutoApply better for you..."
                                        : "Describe what you clicked, what you expected to happen, and what happened instead..."
                                )
                                .font(.system(size: 13))
                                .foregroundColor(.secondary.opacity(0.65))
                                .padding(.horizontal, 13)
                                .padding(.top, 8)
                                .allowsHitTesting(false)
                            }
                        }
                    }

                    // 4. Additional Attachments (Images, Video Files, Logs, Other Files)
                    VStack(alignment: .leading, spacing: 10) {
                        HStack {
                            VStack(alignment: .leading, spacing: 2) {
                                Text("APPEND IMAGES, VIDEO RECORDINGS, OR FILES")
                                    .font(.system(size: 11, weight: .bold))
                                    .foregroundColor(.secondary)
                                Text("Attach screen recordings (.mp4, .mov), extra screenshots (.png, .jpg), PDFs, or logs.")
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            Button {
                                store.chooseFeedbackAttachmentsWithOpenPanel()
                            } label: {
                                Label("Add Images / Videos / Files", systemImage: "plus.circle.fill")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 6)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                        }

                        if store.feedbackUserAttachments.isEmpty {
                            HStack(spacing: 10) {
                                Image(systemName: "photo.on.rectangle.angled")
                                    .font(.system(size: 16))
                                    .foregroundColor(.secondary)
                                Text("Drag & drop images, screen recordings (.mov / .mp4), or files here, or click \"Add Images / Videos / Files\".")
                                    .font(.system(size: 12))
                                    .foregroundColor(.secondary)
                                Spacer()
                            }
                            .padding(14)
                            .background(
                                RoundedRectangle(cornerRadius: 10)
                                    .fill(store.feedbackDropTargeted ? Color.accentColor.opacity(0.10) : Color(NSColor.controlBackgroundColor))
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: 10)
                                    .strokeBorder(
                                        store.feedbackDropTargeted ? Color.accentColor : Color.secondary.opacity(0.25),
                                        style: StrokeStyle(lineWidth: 1, dash: [5, 3])
                                    )
                            )
                            .onDrop(of: [.fileURL], isTargeted: $store.feedbackDropTargeted) { providers in
                                handleDroppedProviders(providers)
                            }
                        } else {
                            VStack(alignment: .leading, spacing: 6) {
                                ForEach(store.feedbackUserAttachments) { item in
                                    HStack(spacing: 10) {
                                        Image(systemName: iconForAttachmentKind(item.kind))
                                            .font(.system(size: 14, weight: .semibold))
                                            .foregroundColor(.accentColor)
                                            .frame(width: 24)
                                        VStack(alignment: .leading, spacing: 1) {
                                            Text(item.name)
                                                .font(.system(size: 12.5, weight: .semibold))
                                                .lineLimit(1)
                                            Text("\(item.kind.capitalized) • \(item.sizeLabel)")
                                                .font(.system(size: 11))
                                                .foregroundColor(.secondary)
                                        }
                                        Spacer()
                                        Button {
                                            store.openFileOnMac(item.path)
                                        } label: {
                                            Text("Preview")
                                                .font(.system(size: 13, weight: .semibold))
                                                .padding(.horizontal, 6)
                                        }
                                        .buttonStyle(.bordered)
                                        .controlSize(.large)

                                        Button {
                                            store.removeFeedbackAttachment(item.id)
                                        } label: {
                                            Image(systemName: "trash")
                                                .font(.system(size: 12))
                                                .foregroundColor(.secondary)
                                        }
                                        .buttonStyle(.plain)
                                    }
                                    .padding(.horizontal, 12)
                                    .padding(.vertical, 8)
                                    .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.controlBackgroundColor)))
                                    .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.18), lineWidth: 1))
                                }
                            }
                            .onDrop(of: [.fileURL], isTargeted: $store.feedbackDropTargeted) { providers in
                                handleDroppedProviders(providers)
                            }
                        }
                    }
                }
                .padding(24)
            }

            Divider()

            // Footer Bar
            HStack(spacing: 12) {
                Image(systemName: "paperplane.circle.fill")
                    .font(.system(size: 15))
                    .foregroundColor(.secondary)
                Text("Feedback package includes your comment, classification, and selected screenshots/media.")
                    .font(.system(size: 11.5))
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                Spacer()
                Button("Cancel") {
                    store.showFeedbackModal = false
                }
                .buttonStyle(.bordered)
                .controlSize(.large)

                Button {
                    store.submitFeedbackReport()
                } label: {
                    HStack(spacing: 6) {
                        if store.feedbackIsSubmitting {
                            ProgressView()
                                .controlSize(.small)
                        } else {
                            Image(systemName: "paperplane.fill")
                        }
                        Text(store.feedbackIsSubmitting ? "Submitting..." : "Submit Feedback")
                            .font(.system(size: 13, weight: .bold))
                    }
                    .padding(.horizontal, 10)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .disabled(store.feedbackIsSubmitting)
            }
            .padding(.horizontal, 24)
            .padding(.vertical, 14)
            .background(Color(NSColor.controlBackgroundColor))
        }
        .frame(width: 720, height: 670)
        .background(Color(NSColor.windowBackgroundColor))
    }

    @ViewBuilder
    private func feedbackClassificationCard(
        id: String,
        title: String,
        subtitle: String,
        icon: String
    ) -> some View {
        let isSelected = (store.feedbackClassification == id)
        Button {
            store.feedbackClassification = id
        } label: {
            HStack(alignment: .center, spacing: 12) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8)
                        .fill(isSelected ? Color.accentColor : Color.secondary.opacity(0.12))
                        .frame(width: 36, height: 36)
                    Image(systemName: icon)
                        .font(.system(size: 15, weight: .semibold))
                        .foregroundColor(isSelected ? .white : .primary)
                }
                VStack(alignment: .leading, spacing: 2) {
                    HStack(spacing: 6) {
                        Text(title)
                            .font(.system(size: 14, weight: .bold))
                            .foregroundColor(.primary)
                        if isSelected {
                            Image(systemName: "checkmark.circle.fill")
                                .font(.system(size: 13, weight: .bold))
                                .foregroundColor(.accentColor)
                        }
                    }
                    Text(subtitle)
                        .font(.system(size: 11.5))
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)
                }
                Spacer(minLength: 0)
            }
            .padding(12)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 10)
                    .fill(isSelected ? Color.accentColor.opacity(0.08) : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 10)
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.22), lineWidth: isSelected ? 1.5 : 1)
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }

    @ViewBuilder
    private func feedbackScreenshotCard(
        title: String,
        subtitle: String,
        path: String,
        isIncluded: Bool,
        emptyMessage: String,
        onToggle: @escaping () -> Void
    ) -> some View {
        let exists = !path.isEmpty && FileManager.default.fileExists(atPath: path)
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                HStack(spacing: 6) {
                    Image(systemName: (isIncluded && exists) ? "checkmark.square.fill" : "square")
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundColor((isIncluded && exists) ? .accentColor : .secondary)
                    Text(title)
                        .font(.system(size: 12.5, weight: .bold))
                        .foregroundColor(.primary)
                        .lineLimit(1)
                }

                Spacer()

                if exists {
                    Button {
                        store.openFileOnMac(path)
                    } label: {
                        Text("Preview")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                }
            }

            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color(NSColor.textBackgroundColor))
                    .frame(height: 118)

                if exists, let nsImg = NSImage(contentsOfFile: path) {
                    Image(nsImage: nsImg)
                        .resizable()
                        .scaledToFit()
                        .frame(maxHeight: 112)
                        .cornerRadius(6)
                        .opacity(isIncluded ? 1.0 : 0.4)
                } else {
                    VStack(spacing: 6) {
                        Image(systemName: "display")
                            .font(.system(size: 20))
                            .foregroundColor(.secondary.opacity(0.6))
                        Text(emptyMessage)
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                            .multilineTextAlignment(.center)
                            .padding(.horizontal, 12)
                    }
                }
            }
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(Color.secondary.opacity(0.18), lineWidth: 1)
            )

            Text(subtitle)
                .font(.system(size: 11))
                .foregroundColor(.secondary)
                .lineLimit(1)
                .truncationMode(.middle)
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 10)
                .fill((isIncluded && exists) ? Color.accentColor.opacity(0.06) : Color(NSColor.controlBackgroundColor))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 10)
                .stroke((isIncluded && exists) ? Color.accentColor.opacity(0.65) : Color.secondary.opacity(0.20), lineWidth: (isIncluded && exists) ? 1.5 : 1)
        )
        .contentShape(Rectangle())
        .onTapGesture {
            if exists {
                onToggle()
            }
        }
        .help("Click anywhere on this card to include or exclude this screenshot.")
    }

    private func iconForAttachmentKind(_ kind: String) -> String {
        switch kind {
        case "image": return "photo.fill"
        case "video": return "video.fill"
        default: return "doc.fill"
        }
    }

    private func handleDroppedProviders(_ providers: [NSItemProvider]) -> Bool {
        var handled = false
        for provider in providers {
            if provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
                handled = true
                provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { item, _ in
                    if let data = item as? Data,
                       let url = URL(dataRepresentation: data, relativeTo: nil) {
                        DispatchQueue.main.async {
                            store.addFeedbackAttachmentPath(url.path)
                        }
                    } else if let url = item as? URL {
                        DispatchQueue.main.async {
                            store.addFeedbackAttachmentPath(url.path)
                        }
                    }
                }
            }
        }
        return handled
    }
}

// MARK: - Privacy Pledge Modal ("We Respect Your Privacy — 100% Local-First Security")

struct PrivacyPledgeModalView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        let step = store.privacyModalStep
        VStack(alignment: .leading, spacing: 20) {
            if step == 1 {
                HStack(spacing: 16) {
                    ZStack {
                        Circle()
                            .fill(
                                LinearGradient(
                                    colors: [Color.teal, Color.accentColor],
                                    startPoint: .topLeading,
                                    endPoint: .bottomTrailing
                                )
                            )
                            .frame(width: 56, height: 56)
                        Image(systemName: "lock.shield.fill")
                            .font(.system(size: 26, weight: .bold))
                            .foregroundColor(.white)
                    }

                    VStack(alignment: .leading, spacing: 4) {
                        HStack(spacing: 8) {
                            Text("We Respect Your Privacy")
                                .font(.system(size: 21, weight: .bold))
                            StatusBadge(text: "100% On-Device", color: .teal)
                        }
                        Text("Your passwords, API keys, and login sessions never leave your Mac.")
                            .font(.subheadline)
                            .foregroundColor(.secondary)
                    }
                    Spacer()
                }

                VStack(alignment: .leading, spacing: 12) {
                    PrivacyPledgeFeatureRow(
                        icon: "key.fill",
                        iconColor: .teal,
                        title: "Passwords & API Keys Stay on Your Device",
                        description: "Encrypted locally on your Mac via macOS Keychain. We have no cloud servers."
                    )

                    PrivacyPledgeFeatureRow(
                        icon: "person.badge.shield.checkmark.fill",
                        iconColor: .blue,
                        title: "Login Sessions Never Leave Your Mac",
                        description: "Your LinkedIn, Teal, Gmail, and ChatGPT logins stay inside local browser profiles on your disk."
                    )

                    PrivacyPledgeFeatureRow(
                        icon: "waveform.and.mic",
                        iconColor: .purple,
                        title: "On-Device Voice & Resume Processing",
                        description: "Your voice recordings and base resume are transcribed and parsed locally on your machine."
                    )
                }
            } else {
                HStack(spacing: 16) {
                    ZStack {
                        Circle()
                            .fill(
                                LinearGradient(
                                    colors: [Color.blue, Color.teal],
                                    startPoint: .topLeading,
                                    endPoint: .bottomTrailing
                                )
                            )
                            .frame(width: 56, height: 56)
                        Image(systemName: "network.badge.shield.half.filled")
                            .font(.system(size: 25, weight: .bold))
                            .foregroundColor(.white)
                    }

                    VStack(alignment: .leading, spacing: 4) {
                        HStack(spacing: 8) {
                            Text("What Leaves Your Device")
                                .font(.system(size: 21, weight: .bold))
                            StatusBadge(text: "We Respect Your Privacy", color: .teal)
                        }
                        Text("Sent directly to OpenRouter or your LLM provider — we never touch your data.")
                            .font(.subheadline)
                            .foregroundColor(.secondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    Spacer()
                }

                VStack(alignment: .leading, spacing: 12) {
                    PrivacyPledgeFeatureRow(
                        icon: "doc.text.magnifyingglass",
                        iconColor: .blue,
                        title: "Resume & Profile via OpenRouter or LLM Provider",
                        description: "Only resume, profile, and job text needed to tailor your applications is sent to OpenRouter or your LLM provider."
                    )

                    PrivacyPledgeFeatureRow(
                        icon: "checkmark.shield.fill",
                        iconColor: .teal,
                        title: "Operated Only by Them — We Don't Touch Your Data",
                        description: "Requests go straight from your Mac to OpenRouter or the LLM provider. We never see, log, or store your data."
                    )

                    PrivacyPledgeFeatureRow(
                        icon: "chevron.left.forwardslash.chevron.right",
                        iconColor: .purple,
                        title: "Open-Source Engine & Best Industry Practices",
                        description: "Built on an open-source engine following industry-best security practices with zero hidden tracking."
                    )
                }
            }

            Divider()

            HStack {
                Toggle("Don't show this again at startup", isOn: $store.neverShowPrivacyModalAgain)
                    .font(.subheadline)
                    .foregroundColor(.secondary)

                Spacer()

                if step == 1 {
                    Button {
                        withAnimation(.easeInOut(duration: 0.18)) {
                            store.privacyModalStep = 2
                        }
                    } label: {
                        Label("Next: What Leaves Your Device", systemImage: "arrow.right.circle.fill")
                            .font(.system(size: 13, weight: .bold))
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.teal)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                } else {
                    Button {
                        withAnimation(.easeInOut(duration: 0.18)) {
                            store.privacyModalStep = 1
                        }
                    } label: {
                        Label("Back", systemImage: "arrow.left")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)

                    Button {
                        store.dismissPrivacyModal()
                    } label: {
                        Label("Got It, Continue", systemImage: "checkmark.shield.fill")
                            .font(.system(size: 13, weight: .bold))
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.teal)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                }
            }
        }
        .padding(28)
        .frame(width: 660)
        .background(Color(NSColor.windowBackgroundColor))
    }
}

