// MARK: - 1. Setup Wizard View (5 Simple Steps)

struct SetupWizardView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            HStack(spacing: 10) {
                ForEach(SetupWizardStep.allCases) { step in
                    let isSelected = store.wizardStep == step
                    let isDone = stepComplete(step)
                    Button {
                        store.wizardStep = step
                    } label: {
                        HStack(spacing: 8) {
                            Image(systemName: isDone ? "checkmark.circle.fill" : step.icon)
                                .font(.system(size: 12, weight: .semibold))
                                .foregroundColor(isDone ? .green : (isSelected ? .accentColor : .secondary))
                            Text(step.title)
                                .font(.system(size: 12, weight: .semibold))
                                .foregroundColor(.primary)
                                .lineLimit(1)
                        }
                        .padding(.horizontal, 14)
                        .padding(.vertical, 9)
                        .fixedSize(horizontal: true, vertical: false)
                        .background(
                            RoundedRectangle(cornerRadius: 9)
                                .fill(isSelected ? Color.accentColor.opacity(0.15) : Color(NSColor.controlBackgroundColor))
                        )
                        .overlay(
                            RoundedRectangle(cornerRadius: 9)
                                .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.18), lineWidth: 1.5)
                        )
                    }
                    .buttonStyle(.plain)
                }
                Spacer()
            }

            switch store.wizardStep {
            case .welcomeAndBrowser:
                SetupStep1BrowserView(store: store)
            case .aiAndChatGPT:
                SetupStep2AIView(store: store)
            case .accountsAndCaptcha:
                SetupStep3AccountsView(store: store)
            case .resumeAndFacts:
                SetupStep4ResumeView(store: store)
            case .workAuthAndFilters:
                SetupStep5PreferencesView(store: store)
            }
        }
    }

    private func stepComplete(_ step: SetupWizardStep) -> Bool {
        switch step {
        case .welcomeAndBrowser: return store.isolRuntimeReady && store.trialState != "unselected"
        case .aiAndChatGPT: return store.aiReady
        case .accountsAndCaptcha: return store.gmailReady || store.tealReady || store.linkedinConnected
        case .resumeAndFacts: return store.submissionFixtureReady
        case .workAuthAndFilters: return store.completedOnboarding
        }
    }
}

struct PricingPlanSelectorStripView: View {
    @ObservedObject var store: WorkspaceStore

    private let plans: [(id: String, name: String, price: String, period: String, badge: String, detail: String, hasSavings: Bool)] = [
        ("weekly", "Weekly", "$10", "/ week", "Flexible", "Billed weekly · Cancel anytime", false),
        ("monthly", "Monthly", "$30", "/ month", "Save 25%", "Save $10/mo vs. weekly", true),
        ("annual", "Yearly", "$200", "/ year", "Save 62%", "Save $320/yr vs. weekly", true),
        ("lifetime", "Lifetime", "$200", "one-time", "LIMITED-TIME SPECIAL", "Pay once, own forever", true)
    ]

    var body: some View {
        HStack(alignment: .top, spacing: 12) {
            ForEach(plans, id: \.id) { p in
                let isSelected = store.selectedSubscriptionPlanId == p.id
                Button {
                    store.selectedSubscriptionPlanId = p.id
                } label: {
                    VStack(alignment: .leading, spacing: 10) {
                        HStack(alignment: .center, spacing: 6) {
                            Text(p.name)
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundColor(.primary)
                                .lineLimit(1)
                            Spacer(minLength: 4)
                            Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                                .font(.system(size: 14, weight: .semibold))
                                .foregroundColor(isSelected ? .accentColor : Color.secondary.opacity(0.4))
                        }

                        HStack(alignment: .firstTextBaseline, spacing: 4) {
                            Text(p.price)
                                .font(.system(size: 24, weight: .bold))
                                .foregroundColor(.primary)
                                .lineLimit(1)
                            Text(p.period)
                                .font(.system(size: 12, weight: .medium))
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }

                        Text(p.badge)
                            .font(.system(size: 10, weight: .semibold))
                            .foregroundColor(p.hasSavings ? .accentColor : .secondary)
                            .lineLimit(1)
                            .minimumScaleFactor(0.85)
                            .padding(.horizontal, 7)
                            .padding(.vertical, 3)
                            .background(
                                Capsule()
                                    .fill(p.hasSavings ? Color.accentColor.opacity(0.14) : Color.secondary.opacity(0.12))
                            )

                        Text(p.detail)
                            .font(.system(size: 11.5, weight: .regular))
                            .foregroundColor(.secondary)
                            .lineLimit(2)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    .padding(14)
                    .frame(maxWidth: .infinity, minHeight: 126, alignment: .topLeading)
                    .background(
                        RoundedRectangle(cornerRadius: 10)
                            .fill(isSelected ? Color.accentColor.opacity(0.09) : Color(NSColor.windowBackgroundColor).opacity(0.45))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 10)
                            .stroke(
                                isSelected ? Color.accentColor : Color.secondary.opacity(0.18),
                                lineWidth: isSelected ? 1.5 : 1
                            )
                    )
                    .contentShape(RoundedRectangle(cornerRadius: 10))
                }
                .buttonStyle(.plain)
            }
        }
    }
}

struct LicenseTrialStatusCardView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        let isExpired = store.isLicenseExpired
        let statusColor: Color = store.isLicenseActivated ? .green : (isExpired ? .orange : .accentColor)
        let statusIcon: String = store.isLicenseActivated
            ? "checkmark.seal.fill"
            : (isExpired ? "exclamationmark.triangle.fill" : "clock.badge.checkmark.fill")
        let planLabel: String = store.activeSubscriptionPlanLabel.isEmpty ? "Monthly Pro ($30/month)" : store.activeSubscriptionPlanLabel
        let statusTitle: String = store.isLicenseActivated
            ? "Pro License Active — \(planLabel)"
            : (isExpired ? "Free Trial Expired" : "2-Day Free Trial")
        let statusSubtitle: String = {
            if store.isLicenseActivated {
                var parts: [String] = ["Subscription: \(planLabel)"]
                if !store.subscriptionPauseUntil.isEmpty {
                    parts.append("Paused")
                }
                parts.append("Unlimited resumes, cover letters & automated applications")
                if !store.activeLicenseKeyMasked.isEmpty {
                    parts.append("Key: \(store.activeLicenseKeyMasked)")
                }
                return parts.joined(separator: " · ")
            }
            if isExpired {
                return "Automated applications are paused. Subscribe to a plan or activate a license key below to continue."
            }
            return "Full access to tailored resumes, cover letters, and browser autofill."
        }()

        HStack(alignment: .center, spacing: 14) {
            ZStack {
                RoundedRectangle(cornerRadius: 10)
                    .fill(statusColor.opacity(0.12))
                    .frame(width: 40, height: 40)
                Image(systemName: statusIcon)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundColor(statusColor)
            }

            VStack(alignment: .leading, spacing: 3) {
                Text(statusTitle)
                    .font(.system(size: 15, weight: .semibold))
                    .foregroundColor(.primary)
                Text(statusSubtitle)
                    .font(.system(size: 12.5))
                    .foregroundColor(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Spacer(minLength: 12)

            HStack(spacing: 10) {
                if store.trialState == "unselected" && !store.isLicenseActivated {
                    Button {
                        store.sendAction("reserve_trial_o02", payload: [:])
                    } label: {
                        Label("Start Free Trial", systemImage: "sparkles")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.accentColor)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                }

                StatusBadge(
                    text: store.isLicenseActivated ? store.activeSubscriptionPlanName : store.trialDaysRemainingLabel,
                    color: statusColor
                )

                if store.isLicenseActivated {
                    if store.canUpgradeSubscription {
                        Button {
                            store.openUpgradeLicenseWebsite()
                        } label: {
                            Label(store.upgradeSubscriptionButtonLabel, systemImage: "arrow.up.forward.circle.fill")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 6)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.borderedProminent)
                        .tint(.accentColor)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                    }

                    Button {
                        store.openPauseSubscriptionWebsite()
                    } label: {
                        Label("Pause Subscription", systemImage: "pause.circle")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)

                    Button {
                        store.sendAction("deactivate_license_key", payload: [:])
                    } label: {
                        Label("Deactivate", systemImage: "xmark.circle")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                }
            }
        }
        .padding(18)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 12)
                .fill(Color(NSColor.controlBackgroundColor).opacity(0.65))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(Color.secondary.opacity(0.16), lineWidth: 1)
        )
    }
}

