struct SetupStep4ResumeView: View {
    @ObservedObject var store: WorkspaceStore

    private var primaryResume: ResumeItem? {
        store.resumes.first(where: \.isPrimary) ?? store.resumes.first
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            // Card 1: Clean, Spacious Base Resume Card
            CardBox(title: "1. Your Base Resume", icon: "doc.richtext.fill") {
                VStack(alignment: .leading, spacing: 14) {
                    HStack(alignment: .center, spacing: 14) {
                        Text("Upload your master resume (PDF, DOCX, or Markdown). AutoApply automatically extracts your experience, education, skills, and profile photo.")
                            .font(.subheadline)
                            .foregroundColor(.secondary)
                        Spacer()
                        Button {
                            store.chooseResumeFileWithOpenPanel()
                        } label: {
                            Label(primaryResume == nil ? "Upload Base Resume…" : "Replace Resume…", systemImage: "arrow.up.doc.fill")
                                .font(.system(size: 13, weight: .bold))
                                .padding(.horizontal, 8)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                    }

                    if let res = primaryResume {
                        HStack(spacing: 14) {
                            ZStack {
                                RoundedRectangle(cornerRadius: 10)
                                    .fill(Color.green.opacity(0.14))
                                    .frame(width: 42, height: 42)
                                Image(systemName: "checkmark.seal.fill")
                                    .font(.system(size: 18, weight: .bold))
                                    .foregroundColor(.green)
                            }
                            VStack(alignment: .leading, spacing: 3) {
                                HStack(spacing: 8) {
                                    Text(res.filename)
                                        .font(.system(size: 14, weight: .bold))
                                        .lineLimit(1)
                                        .truncationMode(.middle)
                                    StatusBadge(text: "Imported & Parsed", color: .green)
                                }
                                Text("Uploaded \(res.uploadedAt) • \(res.fontFamily) • \(res.pageCount) page target")
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            Button {
                                store.openFileOnMac(res.storedPath)
                            } label: {
                                Label("Preview File", systemImage: "eye.fill")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 6)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                        }
                        .padding(14)
                        .background(RoundedRectangle(cornerRadius: 11).fill(Color.secondary.opacity(0.07)))
                        .overlay(RoundedRectangle(cornerRadius: 11).stroke(Color.green.opacity(0.35), lineWidth: 1))
                    }
                }
            }

            // Card 2: Calm, Structured Extracted Profile Overview (Replaces the overwhelming orange wall)
            if primaryResume != nil || !store.profileFullName.isEmpty {
                CardBox(title: "2. Extracted Profile & Knowledge Base", icon: "person.text.rectangle.fill") {
                    VStack(alignment: .leading, spacing: 16) {
                        HStack(alignment: .center, spacing: 18) {
                            ProfileAvatarThumbnail(
                                photoPath: store.profilePhotoThumbPath.isEmpty ? store.profilePhotoPath : store.profilePhotoThumbPath,
                                size: 64
                            )

                            VStack(alignment: .leading, spacing: 4) {
                                Text(store.profileFullName.isEmpty ? "Candidate Profile" : store.profileFullName)
                                    .font(.system(size: 17, weight: .bold))
                                if !store.profileHeadline.isEmpty {
                                    Text(store.profileHeadline)
                                        .font(.system(size: 13, weight: .semibold))
                                        .foregroundColor(.teal)
                                }
                                HStack(spacing: 14) {
                                    if !store.profileEmail.isEmpty {
                                        Label(store.profileEmail, systemImage: "envelope.fill")
                                            .font(.caption)
                                            .foregroundColor(.secondary)
                                    }
                                    if !store.profilePhone.isEmpty {
                                        Label(store.profilePhone, systemImage: "phone.fill")
                                            .font(.caption)
                                            .foregroundColor(.secondary)
                                    }
                                    if !store.profileLocation.isEmpty {
                                        Label(store.profileLocation, systemImage: "mappin.and.ellipse")
                                            .font(.caption)
                                            .foregroundColor(.secondary)
                                    }
                                }
                            }

                            Spacer()

                            VStack(alignment: .trailing, spacing: 8) {
                                Button {
                                    store.selectedSection = .knowledgeBase
                                } label: {
                                    Label("Review Knowledge Base", systemImage: "book.closed.fill")
                                        .font(.system(size: 13, weight: .semibold))
                                        .padding(.horizontal, 6)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)
                                }
                                .buttonStyle(.bordered)
                                .controlSize(.large)
                                .fixedSize(horizontal: true, vertical: false)

                                Button {
                                    store.selectedSection = .voiceInterview
                                } label: {
                                    Label("Voice Interview (Optional)", systemImage: "waveform.and.mic")
                                        .font(.system(size: 13, weight: .semibold))
                                        .padding(.horizontal, 6)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)
                                }
                                .buttonStyle(.bordered)
                                .controlSize(.large)
                                .fixedSize(horizontal: true, vertical: false)
                            }
                        }

                        Divider()

                        HStack(spacing: 10) {
                            ForEach(["about", "experience", "education", "skills", "languages"], id: \.self) { secId in
                                if let sec = store.kbSections.first(where: { $0.id == secId }) {
                                    Button {
                                        store.selectKBSection(sec.id)
                                        store.selectedSection = .knowledgeBase
                                    } label: {
                                        HStack(spacing: 6) {
                                            Image(systemName: "checkmark.circle.fill")
                                                .foregroundColor(.green)
                                                .font(.system(size: 11))
                                            Text(sec.title)
                                                .font(.system(size: 12, weight: .semibold))
                                                .foregroundColor(.primary)
                                        }
                                        .padding(.horizontal, 12)
                                        .padding(.vertical, 7)
                                        .background(RoundedRectangle(cornerRadius: 8).fill(Color.secondary.opacity(0.08)))
                                        .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.18), lineWidth: 1))
                                    }
                                    .buttonStyle(.plain)
                                }
                            }
                            Spacer()
                        }
                    }
                }
            }

            WizardStepFooterBar(
                onBack: {
                    store.wizardStep = .accountsAndCaptcha
                },
                nextTitle: "Next",
                onNext: {
                    if store.unconfirmedCount > 0 {
                        store.sendAction("confirm_all_facts", payload: [:])
                    }
                    store.wizardStep = .workAuthAndFilters
                }
            )
        }
    }
}

