// MARK: - 2. Redesigned Work Authorization, Preferred Compensation Range, Desired Work & Smart Filters (Accordion)

struct WorkAuthAndDesiredWorkEditor: View {
    @ObservedObject var store: WorkspaceStore

    static let priorityEnglishSpeakingCountries: [(code: String, label: String)] = [
        ("US", "United States (US)"),
        ("CA", "Canada (CA)"),
        ("UK", "United Kingdom (UK)"),
        ("AU", "Australia (AU)"),
        ("NZ", "New Zealand (NZ)"),
        ("IE", "Ireland (IE)"),
        ("SG", "Singapore (SG)"),
    ]

    static let otherCountriesAlphabetical: [(code: String, label: String)] = {
        let excludedCodes: Set<String> = [
            "US", "CA", "UK", "GB", "AU", "NZ", "IE", "SG",
            "QO", "EU", "EZ", "UN", "XA", "XB", "ZZ", "CP", "DG", "EA", "IC", "TA", "AC"
        ]
        let enLocale = Locale(identifier: "en_US")
        var items: [(code: String, name: String, label: String)] = []
        for region in Locale.Region.isoRegions {
            let code = region.identifier.uppercased()
            guard code.count == 2,
                  code.allSatisfy({ $0.isASCII && $0.isLetter }),
                  !excludedCodes.contains(code),
                  let name = enLocale.localizedString(forRegionCode: code),
                  !name.isEmpty,
                  name.uppercased() != code
            else { continue }
            items.append((code: code, name: name, label: "\(name) (\(code))"))
        }
        items.append((code: "EU", name: "European Union", label: "European Union (EU)"))
        items.sort { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        return items.map { (code: $0.code, label: $0.label) }
    }()

    private let allSeniorities = ["Co-op", "Entry-Level", "Junior", "Mid-Level", "Senior", "Staff / Principal", "Lead / Manager", "Director / VP"]
    private let allEmploymentTypes = ["Full-Time", "Permanent", "Contract / B2B", "Part-Time", "Advisory / Freelance"]
    private let allWorkplaceModes = [("remote", "Remote", "house.fill"), ("hybrid", "Hybrid", "building.2.fill"), ("onsite", "On-Site", "mappin.and.ellipse")]
    private let usAuthStatuses = ["Citizen", "PR (Green Card)", "Authorized", "Needs Sponsorship", "Remote B2B"]
    private let authStatuses = ["Citizen", "PR", "Authorized", "Needs Sponsorship", "Remote B2B"]

    private let eeoGenderOptions = ["Male", "Female", "Non-Binary", "Decline to Self-Identify"]
    private let eeoHispanicOptions = ["No, not Hispanic or Latino", "Yes, Hispanic or Latino", "Decline to Self-Identify"]
    private let eeoRaceOptions = [
        "White (Not Hispanic or Latino)",
        "Asian (Not Hispanic or Latino)",
        "Black or African American",
        "Hispanic or Latino",
        "American Indian or Alaska Native",
        "Native Hawaiian or Pacific Islander",
        "Two or More Races",
        "Decline to Self-Identify",
    ]
    private let eeoVeteranOptions = [
        "I am not a protected veteran",
        "Protected Veteran",
        "Decline to Self-Identify",
    ]
    private let eeoDisabilityOptions = [
        "No, I do not have a disability",
        "Yes, I have a disability",
        "Decline to Self-Identify",
    ]
    private let eeoLgbtqOptions = [
        "Heterosexual / Straight",
        "LGBTQ+",
        "Decline to Self-Identify",
