    private func residenceLabel(for code: String) -> String {
        let trimmed = code.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed == "-" {
            return "Please specify"
        }
        if let found = Self.priorityEnglishSpeakingCountries.first(where: { $0.code == trimmed }) {
            return found.label
        }
        if let found = Self.otherCountriesAlphabetical.first(where: { $0.code == trimmed }) {
            return found.label
        }
        return trimmed
    }

    private var autoSaveSignature: String {
        [
            store.residenceCountry,
            store.desiredTitlesInput,
            store.seniorityLevels.joined(separator: "|"),
            store.employmentTypes.joined(separator: "|"),
            store.workplaceModes.joined(separator: "|"),
            String(store.minimumSalaryUsd),
            String(store.targetSalaryUsd),
            String(store.useHighestListedRange),
            store.salaryCurrency,
            store.noticePeriod,
            store.relocationPreference,
            String(store.globalB2BContractor),
            store.workAuthUS,
            store.workAuthEU,
            store.workAuthUK,
            store.workAuthCA,
            store.workAuthAU,
            store.eeoGender,
            store.eeoHispanicLatino,
            store.eeoRaceEthnicity,
