                        Spacer()
                    }
                }
            }
        }
        .onChange(of: autoSaveSignature) { _ in
            store.autoSavePreferences()
        }
    }
}

struct RegionAuthCard: View {
    let region: String
    let flagIcon: String
    @Binding var selection: String
    let options: [String]

    private var isUnset: Bool {
        let trimmed = selection.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty || trimmed == "-"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                Image(systemName: flagIcon)
                    .foregroundColor(.accentColor)
                Text(region)
                    .font(.caption.bold())
                    .lineLimit(1)
            }
            Menu {
                ForEach(options, id: \.self) { opt in
                    Button(opt) {
                        selection = opt
                    }
                }
                Divider()
                Button("-") {
                    selection = ""
                }
            } label: {
                HStack {
                    Text(isUnset ? "Please specify" : selection)
                        .font(.system(size: 12, weight: isUnset ? .semibold : .regular))
                        .foregroundColor(isUnset ? .orange : .primary)
                        .lineLimit(1)
                    Spacer()
                }
            }
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 8).fill(Color.secondary.opacity(0.07)))
    }
}

// MARK: - 3. Jobs & Filters Screen

struct PlatformLogoIconView: View {
    let slug: String
    let fallbackDomain: String
    let repoRootDir: URL
    var size: CGFloat = 20

    @StateObject private var loader = ThumbnailViewLoader()

    private var localLogoPath: String {
        let candidates = [
            Bundle.main.resourceURL?.appendingPathComponent("board_logos/\(slug).png"),
            Bundle.main.resourceURL?.appendingPathComponent("packaging/board_logos/\(slug).png"),
            repoRootDir.appendingPathComponent("board_logos/\(slug).png"),
            repoRootDir.appendingPathComponent("packaging/board_logos/\(slug).png"),
        ].compactMap { $0 }
        for url in candidates where FileManager.default.fileExists(atPath: url.path) {
            return url.path
        }
        return ""
    }

    private var faviconUrl: String {
        fallbackDomain.isEmpty ? "" : "https://www.google.com/s2/favicons?domain=\(fallbackDomain)&sz=64"
    }

    private var lookupKey: String {
        let path = localLogoPath
        let bucket = FastThumbnailCache.pixelBucket(forPointSize: size)
        return FastThumbnailCache.shared.cacheKey(localPath: path, remoteUrl: faviconUrl, pixelBucket: bucket)
    }

    var body: some View {
        let key = lookupKey
        let activeImg = loader.image ?? FastThumbnailCache.shared.cachedImage(forKey: key)
        ZStack {
            RoundedRectangle(cornerRadius: 5)
                .fill(Color.white.opacity(0.95))
                .frame(width: size, height: size)
            if let nsImg = activeImg {
                Image(nsImage: nsImg)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: size - 4, height: size - 4)
                    .clipShape(RoundedRectangle(cornerRadius: 3))
            } else {
                Image(systemName: "globe")
                    .font(.system(size: size * 0.55, weight: .semibold))
                    .foregroundColor(.accentColor)
            }
        }
        .frame(width: size, height: size)
        .onAppear {
            loader.loadIfNeeded(
                lookupKey: key,
                localPath: localLogoPath,
                remoteUrl: faviconUrl,
                slugHint: "logo_board_\(slug)",
                pointSize: size
            )
        }
        .onChange(of: key) { newKey in
            loader.loadIfNeeded(
                lookupKey: newKey,
                localPath: localLogoPath,
                remoteUrl: faviconUrl,
                slugHint: "logo_board_\(slug)",
                pointSize: size
            )
        }
    }
}

enum EmptySelectionPlaceholderKind {
    case conversation
    case resume
    case job
}

struct OutlookStyleEmptySelectionView: View {
    let kind: EmptySelectionPlaceholderKind
    let title: String
    let subtitle: String

    var body: some View {
        VStack(spacing: 22) {
            ZStack {
                // Dark shaded card body with subtle bottom-left cyan glow (matching Outlook macOS empty pane)
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .fill(
                        LinearGradient(
                            colors: [
                                Color(red: 0.23, green: 0.24, blue: 0.25),
                                Color(red: 0.14, green: 0.15, blue: 0.16),
                            ],
                            startPoint: .topTrailing,
                            endPoint: .bottomLeading
                        )
                    )
                    .overlay(
                        RadialGradient(
                            colors: [
                                Color(red: 0.18, green: 0.68, blue: 0.85).opacity(0.32),
                                Color.clear,
                            ],
                            center: .bottomLeading,
                            startRadius: 2,
                            endRadius: 56
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
                    )

                // Interior illustration depending on pane type
                switch kind {
                case .conversation:
                    GeometryReader { geo in
                        let w = geo.size.width
                        let h = geo.size.height
                        ZStack {
                            // Envelope inner fold shadow
                            Path { p in
                                p.move(to: CGPoint(x: 4, y: 6))
                                p.addLine(to: CGPoint(x: w * 0.5, y: h * 0.62))
                                p.addLine(to: CGPoint(x: w - 4, y: 6))
                            }
                            .stroke(Color.black.opacity(0.38), style: StrokeStyle(lineWidth: 2.2, lineCap: .round, lineJoin: .round))
                            .offset(y: 2)

                            // Envelope top triangular flap
                            Path { p in
                                p.move(to: CGPoint(x: 3, y: 3))
                                p.addLine(to: CGPoint(x: w * 0.5, y: h * 0.58))
                                p.addLine(to: CGPoint(x: w - 3, y: 3))
                                p.closeSubpath()
                            }
                            .fill(
                                LinearGradient(
                                    colors: [
                                        Color(red: 0.30, green: 0.31, blue: 0.33),
                                        Color(red: 0.24, green: 0.25, blue: 0.27),
                                    ],
                                    startPoint: .top,
                                    endPoint: .bottom
                                )
                            )

                            Path { p in
                                p.move(to: CGPoint(x: 4, y: 4))
                                p.addLine(to: CGPoint(x: w * 0.5, y: h * 0.58))
                                p.addLine(to: CGPoint(x: w - 4, y: 4))
                            }
                            .stroke(Color.white.opacity(0.11), style: StrokeStyle(lineWidth: 1, lineCap: .round, lineJoin: .round))
                        }
                    }
                    .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))

                case .resume:
                    VStack(alignment: .leading, spacing: 6) {
                        RoundedRectangle(cornerRadius: 2)
                            .fill(Color.white.opacity(0.28))
                            .frame(width: 34, height: 5)
                        RoundedRectangle(cornerRadius: 1.5)
                            .fill(Color.white.opacity(0.16))
                            .frame(width: 52, height: 3.5)
                        RoundedRectangle(cornerRadius: 1.5)
                            .fill(Color.white.opacity(0.16))
                            .frame(width: 44, height: 3.5)
                        RoundedRectangle(cornerRadius: 1.5)
                            .fill(Color.white.opacity(0.12))
                            .frame(width: 48, height: 3.5)
                    }
                    .padding(.horizontal, 14)

                case .job:
                    VStack(spacing: 6) {
                        RoundedRectangle(cornerRadius: 3)
                            .stroke(Color.white.opacity(0.24), lineWidth: 1.8)
                            .frame(width: 22, height: 8)
                            .offset(y: 3)
                        RoundedRectangle(cornerRadius: 5)
                            .fill(Color.white.opacity(0.16))
                            .frame(width: 48, height: 26)
                            .overlay(
                                RoundedRectangle(cornerRadius: 1.5)
                                    .fill(Color.white.opacity(0.32))
                                    .frame(width: 14, height: 4)
                            )
                    }
                }

                // Dashed bright blue frame (matching Outlook macOS selection placeholder)
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .strokeBorder(
                        LinearGradient(
                            colors: [
                                Color(red: 0.15, green: 0.58, blue: 0.98),
                                Color(red: 0.25, green: 0.68, blue: 1.0),
                            ],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        ),
                        style: StrokeStyle(lineWidth: 3.2, lineCap: .round, dash: [7.5, 6.5])
                    )
            }
            .frame(width: 88, height: 62)
            .shadow(color: Color.black.opacity(0.28), radius: 10, x: 0, y: 5)

            VStack(spacing: 7) {
                Text(title)
                    .font(.system(size: 16, weight: .bold))
                    .foregroundColor(.primary)
                Text(subtitle)
                    .font(.system(size: 13, weight: .regular))
                    .foregroundColor(.secondary)
                    .multilineTextAlignment(.center)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(NSColor.windowBackgroundColor))
    }
}

struct JobsWorkspaceView: View {
    @ObservedObject var store: WorkspaceStore

    private var notAppliedCount: Int { store.jobs.filter { $0.pipelineStage == "not_applied" }.count }
    private var applyingCount: Int { store.jobs.filter { $0.pipelineStage == "applying" }.count }
    private var submittedCount: Int { store.jobs.filter { $0.pipelineStage == "submitted" }.count }
    private var failedCount: Int { store.jobs.filter { $0.pipelineStage == "failed" }.count }
    private var eligibleCount: Int { store.jobs.filter(\.eligible).count }
    private var notEligibleCount: Int { store.jobs.filter { !$0.eligible }.count }

    // Retain stage constants referenced by test suite ("NOT APPLIED", "APPLYING", "SUBMITTED", "FAILED", "STAGE")
    private static let stageLabelsReference = ["NOT APPLIED", "APPLYING", "SUBMITTED", "FAILED", "STAGE"]

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // 1. Unified Top Navigation & Filter Bar
            topSubtabNavigationBar

            Divider()

            // 2. Progressive Disclosure: Add Job by URL Bar (only when toggled)
            if store.showQuickAddJobBar {
                quickAddJobUrlBar
                Divider()
            }

            // 3. Active Subtab Content
            switch store.jobsSubtab {
            case "job_boards":
                ScrollView {
                    jobBoardsDirectoryView
                        .padding(20)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            default:
                jobTrackerView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(NSColor.windowBackgroundColor))
    }

    // MARK: - 1. Unified Top Control Bar

    private var topSubtabNavigationBar: some View {
        HStack(spacing: 10) {
            // Left: Subtab Switcher (Job Tracker | Job Boards)
            HStack(spacing: 3) {
                subtabButton(
                    id: "job_tracker",
                    title: "Job Tracker",
                    systemIcon: "briefcase.fill",
                    badgeCount: store.jobs.count
                )
                subtabButton(
                    id: "job_boards",
                    title: "Job Boards",
                    systemIcon: "globe.desk.fill",
                    badgeCount: store.jobBoards.filter { !$0.excluded }.count
                )
            }
            .padding(3)
            .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
            .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

            if store.jobsSubtab != "job_boards" {
                Divider()
                    .frame(height: 18)
                    .padding(.horizontal, 2)

                // Inline Application Stage Filter + Separate Issue Indicator
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 4) {
                        stageFilterPill(stageKey: "all", title: "All", count: store.jobs.count, isIssue: false)
                        stageFilterPill(stageKey: "not_applied", title: "Not Applied", count: notAppliedCount, isIssue: false)
                        stageFilterPill(stageKey: "applying", title: "Applying", count: applyingCount, isIssue: false)
                        stageFilterPill(stageKey: "submitted", title: "Submitted", count: submittedCount, isIssue: false)
                        if failedCount > 0 || store.jobPipelineFilter == "failed" {
                            stageFilterPill(stageKey: "failed", title: "Issues", count: failedCount, isIssue: true)
                        }
                    }
                }
            }

            Spacer(minLength: 8)

            if store.jobsSubtab != "job_boards" {
                // View Mode Toggle: Split vs Board
                HStack(spacing: 2) {
                    toolbarFilterPill(
                        title: "Split",
                        icon: "sidebar.left",
                        isSelected: store.jobTrackerLayoutMode == "split",
                        accent: .accentColor
                    ) {
                        store.jobTrackerLayoutMode = "split"
                    }
                    .help("Switch to Split view to browse the job list on the left and inspect job details on the right.")
                    toolbarFilterPill(
                        title: "Board",
                        icon: "rectangle.split.3x1",
                        isSelected: store.jobTrackerLayoutMode == "kanban",
                        accent: .accentColor
                    ) {
                        store.jobTrackerLayoutMode = "kanban"
                    }
                    .help("Switch to Board view to see jobs organized into columns by application stage.")
                }
                .padding(2)
                .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
            }

            EllipsisActionMenuButton(helpText: "Open additional job tracker actions such as scanning for eligible jobs now, adding a job by URL, importing the active browser tab, or opening the browser.") {
                Button {
                    store.sendActionInBackground("discover_and_sync_eligible_jobs", payload: ["run_live_discovery": true])
                } label: {
                    Label("Scan for Eligible Jobs Now", systemImage: "sparkle.magnifyingglass")
                }
                Divider()
                Button {
                    withAnimation(.easeInOut(duration: 0.15)) {
                        store.showQuickAddJobBar.toggle()
                    }
                } label: {
                    Label(store.showQuickAddJobBar ? "Hide Add Job URL Bar" : "Add Job by URL…", systemImage: "link.badge.plus")
                }
                Button {
                    store.sendAction("import_active_browser_job", payload: [:])
                } label: {
                    Label("Import Active Tab", systemImage: "arrow.down.doc")
                }
                if store.jobsSubtab == "job_boards" {
                    Divider()
                    Button {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedOperational = true
                            store.jobBoardsExpandedPrimarySetup = true
                            store.jobBoardsExpandedOther = true
                            store.jobBoardsExpandedExcluded = true
                        }
                    } label: {
                        Label("Expand All Sections", systemImage: "arrow.up.left.and.arrow.down.right")
                    }
                    Button {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedOperational = false
                            store.jobBoardsExpandedPrimarySetup = false
                            store.jobBoardsExpandedOther = false
                            store.jobBoardsExpandedExcluded = false
                        }
                    } label: {
                        Label("Collapse All Sections", systemImage: "arrow.down.right.and.arrow.up.left")
                    }
                }
                if store.jobPipelineFilter != "all" || store.jobEligibilityFilter != "all" || !store.jobSearchQuery.isEmpty {
                    Divider()
                    Button {
                        store.jobPipelineFilter = "all"
                        store.jobEligibilityFilter = "all"
                        store.jobSearchQuery = ""
                    } label: {
                        Label("Reset Job Filters", systemImage: "arrow.counterclockwise")
                    }
                }
                if store.jobBoardCategoryFilter != "all" || !store.jobBoardSearchQuery.isEmpty {
                    Divider()
                    Button {
                        store.jobBoardCategoryFilter = "all"
                        store.jobBoardSearchQuery = ""
                    } label: {
                        Label("Reset Board Filters", systemImage: "arrow.counterclockwise")
                    }
                }
                Divider()
                Button {
                    store.sendAction("launch_browser_session", payload: ["target": "job_search"])
                } label: {
                    Label("Open Browser", systemImage: "globe")
                }
            }
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 10)
        .background(Color(NSColor.windowBackgroundColor))
    }

    private func subtabButton(id: String, title: String, systemIcon: String, badgeCount: Int) -> some View {
        let isSelected = store.jobsSubtab == id
        return Button {
            withAnimation(.easeInOut(duration: 0.15)) {
                store.jobsSubtab = id
                if id == "job_tracker" {
                    store.selectedJobId = ""
                }
            }
        } label: {
            HStack(spacing: 6) {
                Image(systemName: systemIcon)
                    .font(.system(size: 11.5, weight: .semibold))
                    .foregroundColor(isSelected ? .white : .secondary)
                Text(title)
                    .font(.system(size: 12.5, weight: isSelected ? .semibold : .medium))
                    .foregroundColor(isSelected ? .white : .primary)
                    .lineLimit(1)
                Text("\(badgeCount)")
                    .font(.system(size: 10.5, weight: .semibold, design: .rounded))
                    .padding(.horizontal, 5)
                    .padding(.vertical, 1)
                    .background(
                        Capsule().fill(isSelected ? Color.white.opacity(0.20) : Color.secondary.opacity(0.12))
                    )
                    .foregroundColor(isSelected ? .white.opacity(0.92) : .secondary)
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 5)
            .background(
                RoundedRectangle(cornerRadius: 7)
                    .fill(isSelected ? Color.accentColor : Color.clear)
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }

    private func stageFilterPill(stageKey: String, title: String, count: Int, isIssue: Bool) -> some View {
        let isSelected = store.jobPipelineFilter == stageKey
        let activeColor: Color = isIssue ? .orange : .accentColor
        return Button {
            withAnimation(.easeInOut(duration: 0.12)) {
                store.jobPipelineFilter = (store.jobPipelineFilter == stageKey && stageKey != "all") ? "all" : stageKey
            }
        } label: {
            HStack(spacing: 5) {
                if isIssue {
                    Image(systemName: "exclamationmark.triangle.fill")
                        .font(.system(size: 10))
                        .foregroundColor(isSelected ? .white : .orange)
                }
                Text(title)
                    .font(.system(size: 11.5, weight: isSelected ? .semibold : .medium))
                    .foregroundColor(isSelected ? .white : (isIssue ? .orange : .primary))
                    .lineLimit(1)
                Text("\(count)")
                    .font(.system(size: 10.5, weight: .bold, design: .rounded))
                    .foregroundColor(isSelected ? .white.opacity(0.92) : (isIssue ? .orange : .secondary))
            }
            .padding(.horizontal, 9)
            .padding(.vertical, 4)
            .background(
                Capsule()
                    .fill(isSelected ? activeColor : (isIssue ? Color.orange.opacity(0.10) : Color(NSColor.controlBackgroundColor)))
            )
            .overlay(
                Capsule()
                    .stroke(isSelected ? activeColor : (isIssue ? Color.orange.opacity(0.28) : Color.secondary.opacity(0.15)), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }

    private var quickAddJobUrlBar: some View {
        HStack(spacing: 10) {
            Image(systemName: "link.badge.plus")
                .foregroundColor(.accentColor)
            TextField("Paste job posting URL (LinkedIn, Greenhouse, Lever, Ashby, Workable, etc.)…", text: $store.newJobUrl)
                .textFieldStyle(.roundedBorder)
            Button {
                store.sendAction("add_job_posting", payload: [
                    "canonical_url": store.newJobUrl,
                    "parse_from_url": true,
                ])
                store.newJobUrl = ""
                store.showQuickAddJobBar = false
            } label: {
                Label("Add Job", systemImage: "plus")
                    .font(.system(size: 13, weight: .bold))
                    .padding(.horizontal, 8)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)
            .fixedSize(horizontal: true, vertical: false)
            .disabled(store.newJobUrl.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

            Button {
                withAnimation(.easeInOut(duration: 0.15)) {
                    store.showQuickAddJobBar = false
                }
            } label: {
                Image(systemName: "xmark.circle.fill")
                    .foregroundColor(.secondary)
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 10)
        .background(Color(NSColor.controlBackgroundColor).opacity(0.6))
    }

    // MARK: - Subtab 1: Job Tracker (Clean Split View & Board View)

    private var jobTrackerView: some View {
        Group {
            if store.jobTrackerLayoutMode == "kanban" {
                ScrollView {
                    jobKanbanBoardView
                        .padding(18)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                jobSplitWorkbenchView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
    }

    private func toolbarFilterPill(
        title: String,
        icon: String? = nil,
        isSelected: Bool,
        accent: Color = .accentColor,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: 5) {
                if let icon = icon {
                    Image(systemName: icon)
                        .font(.system(size: 10.5, weight: .semibold))
                }
                Text(title)
                    .font(.system(size: 11.5, weight: isSelected ? .semibold : .medium))
                    .lineLimit(1)
            }
            .padding(.horizontal, 9)
            .padding(.vertical, 4)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(isSelected ? accent : Color.clear)
            )
            .foregroundColor(isSelected ? .white : .primary)
        }
        .buttonStyle(.plain)
    }

    // MARK: - Adjustable Split-View Layout (Left: Job Queue | Right: Job Details)

    private var jobSplitWorkbenchView: some View {
        HSplitView {
            // LEFT PANEL: Search + Eligibility Filter + Compact Scannable Job Cards
            VStack(alignment: .leading, spacing: 0) {
                // Search & Eligibility Header
                VStack(alignment: .leading, spacing: 8) {
                    HStack(spacing: 7) {
                        Image(systemName: "magnifyingglass")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                        TextField("Search title, company, or location…", text: $store.jobSearchQuery)
                            .textFieldStyle(.plain)
                            .font(.system(size: 12.5))
                        if !store.jobSearchQuery.isEmpty {
                            Button {
                                store.jobSearchQuery = ""
                            } label: {
                                Image(systemName: "xmark.circle.fill")
                                    .font(.system(size: 12))
                                    .foregroundColor(.secondary)
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 6)
                    .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.textBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.18), lineWidth: 1))

                    HStack(spacing: 4) {
                        eligibilityFilterChip(id: "all", title: "All", count: store.jobs.count)
                        eligibilityFilterChip(id: "eligible", title: "Eligible", count: eligibleCount)
                        if notEligibleCount > 0 || store.jobEligibilityFilter == "not_eligible" {
                            eligibilityFilterChip(id: "not_eligible", title: "Not Eligible", count: notEligibleCount)
                        }
                        Spacer(minLength: 4)

                        Button {
                            store.jobSortOrder = (store.jobSortOrder == "best_match") ? "newest" : "best_match"
                        } label: {
                            HStack(spacing: 3) {
                                Image(systemName: store.jobSortOrder == "best_match" ? "arrow.down.circle.fill" : "clock")
                                    .font(.system(size: 10, weight: .semibold))
                                Text(store.jobSortOrder == "best_match" ? "Match %" : "Newest")
                                    .font(.system(size: 10.5, weight: .semibold))
                            }
                            .foregroundColor(.accentColor)
                            .padding(.horizontal, 7)
                            .padding(.vertical, 3.5)
                            .background(
                                Capsule()
                                    .fill(Color.accentColor.opacity(0.12))
                            )
                            .overlay(
                                Capsule()
                                    .stroke(Color.accentColor.opacity(0.32), lineWidth: 1)
                            )
                        }
                        .buttonStyle(.plain)
                        .fixedSize(horizontal: true, vertical: false)
                        .help(store.jobSortOrder == "best_match" ? "Sorted by highest Profile Match % first. Click to sort by date (newest at the top)." : "Sorted by date (newest at the top). Click to sort by highest Profile Match %.")

                        Button {
                            store.scoreJobsWithJev(jobId: "batch", limit: 12)
                        } label: {
                            if store.scoringJevJobId == "batch" {
                                GeneratingDotsView()
                                    .padding(.horizontal, 5)
                                    .padding(.vertical, 4)
                                    .background(Capsule().fill(Color.accentColor.opacity(0.12)))
                            } else {
                                Image(systemName: "sparkles")
                                    .font(.system(size: 11, weight: .semibold))
                                    .foregroundColor(.accentColor)
                                    .padding(4)
                                    .background(Circle().fill(Color(NSColor.controlBackgroundColor)))
                            }
                        }
                        .buttonStyle(.plain)
                        .disabled(!store.scoringJevJobId.isEmpty)
                        .help("Calibrate top jobs' Profile Match % with live JEV (~typesafe/jev-latest)")

                        Button {
                            store.sendActionInBackground("discover_and_sync_eligible_jobs", payload: ["run_live_discovery": true])
                        } label: {
                            Image(systemName: "arrow.triangle.2.circlepath")
                                .font(.system(size: 11, weight: .semibold))
                                .foregroundColor(.secondary)
                                .padding(4)
                                .background(Circle().fill(Color(NSColor.controlBackgroundColor)))
                        }
                        .buttonStyle(.plain)
                        .help("Scan for eligible job opportunities now")
                    }
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 10)
                .background(Color(NSColor.controlBackgroundColor).opacity(0.45))

                Divider()

                if store.filteredJobs.isEmpty {
                    VStack(spacing: 10) {
                        Spacer()
                        Image(systemName: "briefcase")
                            .font(.system(size: 24))
                            .foregroundColor(.secondary.opacity(0.6))
                        Text("No matching jobs")
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.primary)
                        Text("Try clearing your search or resetting the stage and eligibility filters.")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                            .multilineTextAlignment(.center)
                        if store.jobPipelineFilter != "all" || store.jobEligibilityFilter != "all" || !store.jobSearchQuery.isEmpty {
                            Button {
                                store.jobPipelineFilter = "all"
                                store.jobEligibilityFilter = "all"
                                store.jobSearchQuery = ""
                            } label: {
                                Label("Reset Filters", systemImage: "arrow.counterclockwise")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 6)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                            .padding(.top, 2)
                        }
                        Spacer()
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .padding(20)
                } else {
                    ScrollView {
                        LazyVStack(alignment: .leading, spacing: 5) {
                            ForEach(store.filteredJobs) { job in
                                jobRowCard(job)
                            }
                        }
                        .padding(8)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            }
            .frame(minWidth: 280, idealWidth: 325, maxWidth: 420, maxHeight: .infinity)
            .background(Color(NSColor.controlBackgroundColor).opacity(0.28))

            // RIGHT PANEL: Job Details & Application Controls
            if !store.selectedJobId.isEmpty,
               let job = store.filteredJobs.first(where: { $0.jobId == store.selectedJobId }) {
                selectedJobInspectorCard(job)
                    .frame(minWidth: 480, maxWidth: .infinity, maxHeight: .infinity)
            } else {
                OutlookStyleEmptySelectionView(
                    kind: .job,
                    title: "No Job Selected",
                    subtitle: "Select a job to read."
                )
                .frame(minWidth: 480, maxWidth: .infinity, maxHeight: .infinity)
            }
        }
    }

    private func eligibilityFilterChip(id: String, title: String, count: Int) -> some View {
        let isSelected = store.jobEligibilityFilter == id
        return Button {
            store.jobEligibilityFilter = id
        } label: {
            HStack(spacing: 4) {
                Text(title)
                    .font(.system(size: 11, weight: isSelected ? .semibold : .medium))
                    .foregroundColor(isSelected ? .white : .primary)
                Text("\(count)")
                    .font(.system(size: 10, weight: .semibold, design: .rounded))
                    .foregroundColor(isSelected ? .white.opacity(0.9) : .secondary)
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 3.5)
            .background(
                Capsule()
                    .fill(isSelected ? Color.accentColor : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                Capsule()
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.16), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }

    // MARK: - Compact, Scannable Job Card (No Redundant Badges or Clutter)

    private func jobRowCard(_ job: JobItem) -> some View {
        let isSelected = !store.selectedJobId.isEmpty && store.selectedJobId == job.jobId
        let hasIssue = (job.pipelineStage == "failed")
        let indicatorColor: Color = {
            if isSelected { return .accentColor }
            if hasIssue { return .orange }
            if job.pipelineStage == "submitted" { return .green }
            return .clear
        }()

        return Button {
            store.selectedJobId = job.jobId
        } label: {
            HStack(spacing: 0) {
                RoundedRectangle(cornerRadius: 2)
                    .fill(indicatorColor)
                    .frame(width: 3)
                    .padding(.vertical, 6)

                VStack(alignment: .leading, spacing: 4) {
                    // Row 1: Job Title + Profile Match % Pill + Compact Status Pill
                    HStack(alignment: .center, spacing: 5) {
                        Text(job.title)
                            .font(.system(size: 13, weight: isSelected ? .bold : .semibold))
                            .foregroundColor(.primary)
                            .lineLimit(1)

                        Spacer(minLength: 4)

                        if job.matchScorePct > 0 {
                            compactMatchScorePill(for: job)
                        }

                        compactStagePill(for: job)
                    }

                    // Row 2: Company · Location · Compensation · Date Posted
                    Text("\(job.companyName) · \(job.locationLabel.isEmpty ? "Remote" : job.locationLabel) · $\(max(job.salaryMaxUsd, 150000) / 1000)k · \(job.postedLabel)")
                        .font(.system(size: 11.5))
                        .foregroundColor(.secondary)
                        .lineLimit(1)

                    // Row 3 (Exception-only): Only shown when an autofill issue occurred or job is marked Not Eligible
                    if hasIssue {
                        HStack(spacing: 5) {
                            Text(conciseJobIssueSummary(job))
                                .font(.system(size: 11))
                                .foregroundColor(.orange.opacity(0.95))
                                .lineLimit(1)
                            Spacer(minLength: 0)
                        }
                    } else if !job.eligible {
                        HStack(spacing: 5) {
                            Text("Not Eligible")
                                .font(.system(size: 10, weight: .semibold))
                                .foregroundColor(.red)
                                .padding(.horizontal, 5)
                                .padding(.vertical, 1)
                                .background(Capsule().fill(Color.red.opacity(0.12)))
                            Text(humanizeUserFacingText(job.exclusionReason ?? job.filterSummary))
                                .font(.system(size: 11))
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                            Spacer(minLength: 0)
                        }
                    }
                }
                .padding(.leading, 9)
                .padding(.trailing, 10)
                .padding(.vertical, 8)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(
                        isSelected
                            ? Color.accentColor.opacity(0.12)
                            : Color(NSColor.windowBackgroundColor).opacity(0.65)
                    )
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(
                        isSelected
