    private func matchDimensionBar(title: String, pct: Int) -> some View {
        let clamped = max(0, min(100, pct))
        let barColor: Color = {
            if clamped >= 80 { return .green }
            if clamped >= 65 { return .accentColor }
            if clamped >= 50 { return .orange }
            return .secondary
        }()
        return VStack(alignment: .leading, spacing: 4) {
            HStack {
                Text(title)
                    .font(.system(size: 11, weight: .medium))
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                Spacer(minLength: 4)
                Text("\(clamped)%")
                    .font(.system(size: 11.5, weight: .bold, design: .rounded))
                    .foregroundColor(.primary)
            }
            GeometryReader { geo in
                ZStack(alignment: .leading) {
                    Capsule()
                        .fill(Color.secondary.opacity(0.14))
                    Capsule()
                        .fill(barColor)
                        .frame(width: max(6, geo.size.width * CGFloat(clamped) / 100.0))
                }
            }
            .frame(height: 5)
        }
        .padding(8)
        .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.windowBackgroundColor).opacity(0.6)))
        .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.10), lineWidth: 1))
    }

