    private func humanizeUserFacingText(_ raw: String) -> String {
        var s = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if s.isEmpty { return "" }
        if s.lowercased().hasPrefix("filtered:") {
            s = String(s.dropFirst("filtered:".count)).trimmingCharacters(in: .whitespacesAndNewlines)
        }
        let codeMap: [String: String] = [
            "country_residence_or_location_ineligible": "Location or country of residence is not eligible for this role",
            "role_closed": "Job posting is closed and no longer accepting applications",
            "employer_excluded_by_user": "Company is on your excluded employers list",
            "excluded_employer": "Company is on your excluded employers list",
            "workplace_mode_mismatch": "Workplace mode does not match your remote or hybrid preferences",
            "sponsorship_required_but_not_offered": "Visa sponsorship is required for this location but not offered",
            "work_authorization_missing": "Work authorization is required for this role's location",
            "below_minimum_salary": "Listed compensation is below your minimum salary threshold",
            "excluded_keyword": "Job title or description matches an excluded keyword",
            "excluded_job_board": "Job board is excluded in your preferences",
        ]
        if let mapped = codeMap[s.lowercased()] {
            return mapped
        }
        for (code, text) in codeMap {
            if s.lowercased().contains(code) {
                s = s.replacingOccurrences(of: code, with: text, options: .caseInsensitive)
            }
        }
        s = s.replacingOccurrences(
            of: #"\s*\((?:geo_restricted|no_form_fields|autofill_problem|portal_closed|auth_required)\)"#,
            with: "",
            options: .regularExpression
        )
        s = s.replacingOccurrences(
            of: #"\s*\(job_[a-z0-9_]+\.(?:pdf|docx)\)"#,
            with: "",
            options: .regularExpression
        )
        if s.contains("_") && !s.contains("http://") && !s.contains("https://") {
            s = s.replacingOccurrences(of: "_", with: " ")
        }
        return s
    }

    private func cleanPreparedAnswerValue(key: String, value: String) -> String {
        var v = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if v.contains("(Highest Listed Range)") {
            v = v.replacingOccurrences(of: "(Highest Listed Range)", with: "").trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if key.lowercased().contains("technical degree") && v.hasPrefix("Yes (") {
            return "Yes"
        }
        if key.lowercased().contains("full name") {
            v = v.replacingOccurrences(
                of: #"^(?:Mr\.|Ms\.|Mrs\.|Dr\.|Mx\.)\s*"#,
                with: "",
                options: .regularExpression
            )
            if v.contains("Alexander") {
                v = v.replacingOccurrences(of: "Alexander", with: "Alex")
            }
        }
        return v
    }

    private func conciseJobIssueSummary(_ job: JobItem) -> String {
        let raw = humanizeUserFacingText(job.failureReason.isEmpty ? job.filterSummary : job.failureReason)
        if raw.lowercased().contains("form fields could not be opened") {
            return "External portal or sign-in required before autofill"
        }
        return raw.isEmpty ? "Needs manual review in browser" : raw
    }

