            if store.outreachSubView == "all_outreach" {
                // Channel Segmented Filter
                HStack(spacing: 2) {
                    ForEach([
                        ("all", "All Channels"),
                        ("linkedin_dm", "LinkedIn DM"),
                        ("linkedin_invite", "Invite"),
                        ("email", "Email"),
                        ("whatsapp_sms", "WhatsApp/SMS"),
                    ], id: \.0) { ch in
                        toolbarFilterPill(
                            title: ch.1,
                            isSelected: store.outreachChannelFilter == ch.0,
                            accent: .teal
                        ) {
                            store.outreachChannelFilter = ch.0
                        }
                    }
                }
                .padding(3)
                .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
                .fixedSize(horizontal: true, vertical: true)

                // Status Segmented Filter
                HStack(spacing: 2) {
                    ForEach([
                        ("all", "All Status"),
                        ("verified_sent", "Sent"),
                        ("on_hold", "On Hold"),
                    ], id: \.0) { st in
                        toolbarFilterPill(
                            title: st.1,
                            isSelected: store.outreachStatusFilter == st.0,
                            accent: .blue
                        ) {
                            store.outreachStatusFilter = st.0
                        }
                    }
                }
                .padding(3)
                .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
                .fixedSize(horizontal: true, vertical: true)
            } else if store.outreachSubView == "linkedin_pipeline" {
                let pendingCount = store.linkedinConnections.filter { $0.stage == "invite_pending" }.count
                let holdCount = store.linkedinConnections.filter { $0.stage == "accepted_hold" }.count
                let dmSentCount = store.linkedinConnections.filter { $0.stage == "dm_sent" }.count

                HStack(spacing: 2) {
                    toolbarFilterPill(
                        title: "All (\(store.linkedinConnections.count))",
                        isSelected: store.linkedinStageFilter == "all",
                        accent: .blue
                    ) {
                        store.linkedinStageFilter = "all"
                    }
                    toolbarFilterPill(
                        title: "Invite Pending (\(pendingCount))",
                        isSelected: store.linkedinStageFilter == "invite_pending",
                        accent: .blue
                    ) {
                        store.linkedinStageFilter = "invite_pending"
                    }
                    toolbarFilterPill(
                        title: "Accepted / Hold (\(holdCount))",
                        isSelected: store.linkedinStageFilter == "accepted_hold",
                        accent: .orange
                    ) {
                        store.linkedinStageFilter = "accepted_hold"
                    }
                    toolbarFilterPill(
                        title: "First DM Sent (\(dmSentCount))",
                        isSelected: store.linkedinStageFilter == "dm_sent",
                        accent: .green
                    ) {
                        store.linkedinStageFilter = "dm_sent"
                    }
                }
                .padding(3)
                .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
                .fixedSize(horizontal: true, vertical: true)
            }

            // Search Field
            HStack(spacing: 6) {
                Image(systemName: "magnifyingglass")
                    .font(.system(size: 12))
                    .foregroundColor(.secondary)
                TextField("Search contact, company, role, or message…", text: $store.outreachSearchQuery)
                    .textFieldStyle(.plain)
                    .font(.system(size: 12.5))
                if !store.outreachSearchQuery.isEmpty {
                    Button {
                        store.outreachSearchQuery = ""
                    } label: {
                        Image(systemName: "xmark.circle.fill")
                            .foregroundColor(.secondary)
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.horizontal, 10)
            .frame(height: 32)
            .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
            .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

            if store.outreachSubView == "linkedin_pipeline" {
                HStack(spacing: 3) {
                    toolbarFilterPill(
                        title: "Split",
                        icon: "sidebar.left",
                        isSelected: store.linkedinLayoutMode == "split",
                        accent: .blue
                    ) {
                        store.linkedinLayoutMode = "split"
                    }
                    toolbarFilterPill(
                        title: "Board",
                        icon: "rectangle.split.3x1.fill",
                        isSelected: store.linkedinLayoutMode == "board",
                        accent: .blue
                    ) {
                        store.linkedinLayoutMode = "board"
                    }
                }
                .padding(3)
                .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 9).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
                .fixedSize(horizontal: true, vertical: true)
            }
        }
        .frame(height: 34)
        .fixedSize(horizontal: false, vertical: true)
    }

    private func outreachKPICard(
        id: String,
        title: String,
        value: String,
        subtitle: String,
        icon: String,
        color: Color,
        isSelected: Bool,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: 10) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8)
                        .fill(isSelected ? color : color.opacity(0.14))
                        .frame(width: 34, height: 34)
                    Image(systemName: icon)
                        .font(.system(size: 14, weight: .bold))
                        .foregroundColor(isSelected ? .white : color)
                }
                VStack(alignment: .leading, spacing: 1) {
                    HStack(spacing: 4) {
                        Text(title)
                            .font(.system(size: 10, weight: .heavy))
                            .foregroundColor(isSelected ? color : .secondary)
                            .lineLimit(1)
                        Spacer(minLength: 2)
                        Text(value)
                            .font(.system(size: 16, weight: .bold, design: .rounded))
                            .foregroundColor(.primary)
                    }
                    Text(subtitle)
                        .font(.system(size: 10.5))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 8)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(RoundedRectangle(cornerRadius: 10).fill(isSelected ? color.opacity(0.12) : Color(NSColor.controlBackgroundColor)))
            .overlay(RoundedRectangle(cornerRadius: 10).stroke(isSelected ? color : Color.secondary.opacity(0.16), lineWidth: isSelected ? 1.8 : 1))
            .fixedSize(horizontal: false, vertical: true)
        }
        .buttonStyle(.plain)
    }

