    // Sub-View B: LinkedIn Connection Pipeline (Clean Master-Detail Split View or 3-Column Board)
    private var filteredLinkedinList: [LinkedInConnectionItem] {
        let q = store.outreachSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return store.linkedinConnections.filter { item in
            let matchesStage = (store.linkedinStageFilter == "all") || (item.stage == store.linkedinStageFilter)
            let matchesSearch = q.isEmpty
                || item.contactName.lowercased().contains(q)
                || item.company.lowercased().contains(q)
                || item.role.lowercased().contains(q)
                || item.body.lowercased().contains(q)
            return matchesStage && matchesSearch
        }
    }

    private var linkedinConnectionsPipelineView: some View {
        let filtered = filteredLinkedinList
        return Group {
            if store.linkedinLayoutMode == "board" {
                let pendingList = filtered.filter { $0.stage == "invite_pending" }
                let holdList = filtered.filter { $0.stage == "accepted_hold" }
                let dmSentList = filtered.filter { $0.stage == "dm_sent" }

                HStack(alignment: .top, spacing: 12) {
                    linkedinPipelineColumn(
                        title: "1. INVITATION PENDING",
                        subtitle: "Scanned every 12h for acceptance",
                        items: pendingList,
                        color: .blue,
                        icon: "person.badge.clock.fill"
                    )
                    linkedinPipelineColumn(
                        title: "2. ACCEPTED (ON HOLD)",
                        subtitle: "Held due to prior email or employer check",
                        items: holdList,
                        color: .orange,
                        icon: "hand.raised.fill"
                    )
                    linkedinPipelineColumn(
                        title: "3. FIRST DM SENT",
                        subtitle: "Verified role-specific first DM in thread",
                        items: dmSentList,
                        color: .green,
                        icon: "checkmark.message.fill"
                    )
                }
            } else {
                HStack(alignment: .top, spacing: 14) {
                    // Left Column: Scannable LinkedIn Contacts
                    VStack(alignment: .leading, spacing: 7) {
                        ForEach(filtered.prefix(50)) { item in
                            let isSel = (store.selectedLinkedinConnection?.id ?? filtered.first?.id) == item.id
                            let col: Color = item.stage == "dm_sent" ? .green : (item.stage == "accepted_hold" ? .orange : .blue)
                            Button {
                                store.selectedLinkedinConnectionId = item.id
                            } label: {
                                VStack(alignment: .leading, spacing: 5) {
                                    HStack {
                                        Text(item.contactName)
                                            .font(.system(size: 12.5, weight: .bold))
                                            .foregroundColor(.primary)
                                            .lineLimit(1)
                                        Spacer(minLength: 4)
                                        StatusBadge(text: item.statusLabel, color: col)
                                    }
                                    Text("\(item.company) • \(item.role)")
                                        .font(.system(size: 11))
                                        .foregroundColor(.secondary)
                                        .lineLimit(1)
                                }
                                .padding(10)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .background(RoundedRectangle(cornerRadius: 10).fill(isSel ? col.opacity(0.12) : Color(NSColor.controlBackgroundColor)))
                                .overlay(RoundedRectangle(cornerRadius: 10).stroke(isSel ? col : Color.secondary.opacity(0.15), lineWidth: isSel ? 1.8 : 1))
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .frame(width: 340)

                    // Right Column: Selected LinkedIn Connection Inspector
                    if let sel = filtered.first(where: { $0.id == store.selectedLinkedinConnectionId }) ?? store.selectedLinkedinConnection ?? filtered.first {
                        let col: Color = sel.stage == "dm_sent" ? .green : (sel.stage == "accepted_hold" ? .orange : .blue)
                        VStack(alignment: .leading, spacing: 14) {
                            HStack(alignment: .top, spacing: 12) {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 10)
                                        .fill(col.opacity(0.15))
                                        .frame(width: 40, height: 40)
                                    Image(systemName: "person.crop.circle.badge.checkmark")
                                        .font(.system(size: 17, weight: .bold))
                                        .foregroundColor(col)
                                }
                                VStack(alignment: .leading, spacing: 4) {
                                    HStack(spacing: 8) {
                                        Text(sel.contactName)
                                            .font(.system(size: 17, weight: .bold))
                                        StatusBadge(text: sel.statusLabel, color: col)
                                    }
                                    Text("\(sel.company) — Role: \(sel.role)")
                                        .font(.system(size: 12.5))
                                        .foregroundColor(.secondary)
                                    if !sel.profileUrl.isEmpty {
                                        Text(sel.profileUrl)
                                            .font(.system(size: 11))
                                            .foregroundColor(.accentColor)
                                            .lineLimit(1)
                                            .truncationMode(.middle)
                                    }
                                }
                                Spacer()
                            }

                            HStack(spacing: 8) {
                                if !sel.profileUrl.isEmpty {
                                    Button {
                                        store.sendActionInBackground("launch_browser_session", payload: [
                                            "target": "linkedin_profile",
                                            "url": sel.profileUrl,
                                        ])
                                    } label: {
                                        Label("Open LinkedIn Profile", systemImage: "person.crop.rectangle.fill")
                                            .font(.system(size: 13, weight: .bold))
                                            .padding(.horizontal, 8)
                                            .lineLimit(1)
                                            .fixedSize(horizontal: true, vertical: false)
                                    }
                                    .buttonStyle(.borderedProminent)
                                    .tint(.blue)
                                    .controlSize(.large)
                                    .fixedSize(horizontal: true, vertical: false)
                                }
                                if !sel.threadUrl.isEmpty && sel.threadUrl != sel.profileUrl {
                                    Button {
                                        store.sendActionInBackground("launch_browser_session", payload: [
                                            "target": "linkedin_thread",
                                            "url": sel.threadUrl,
                                        ])
                                    } label: {
                                        Label("Open DM Thread", systemImage: "bubble.left.and.bubble.right.fill")
                                            .font(.system(size: 13, weight: .semibold))
                                            .padding(.horizontal, 6)
                                            .lineLimit(1)
                                            .fixedSize(horizontal: true, vertical: false)
                                    }
                                    .buttonStyle(.bordered)
                                    .controlSize(.large)
                                    .fixedSize(horizontal: true, vertical: false)
                                }
                                if !sel.body.isEmpty {
                                    Button {
                                        store.copyToClipboard(sel.body, label: "LinkedIn note")
                                    } label: {
                                        Label("Copy Note", systemImage: "doc.on.doc")
                                            .font(.system(size: 13, weight: .semibold))
                                            .padding(.horizontal, 6)
                                            .lineLimit(1)
                                            .fixedSize(horizontal: true, vertical: false)
                                    }
                                    .buttonStyle(.bordered)
                                    .controlSize(.large)
                                    .fixedSize(horizontal: true, vertical: false)
                                }
                                Spacer()
                            }
                            .fixedSize(horizontal: false, vertical: true)

                            Divider()

                            VStack(alignment: .leading, spacing: 6) {
                                Text("CONNECTION NOTE / PREPARED FIRST DM")
                                    .font(.system(size: 10.5, weight: .heavy))
                                    .foregroundColor(.secondary)
                                Text(sel.body.isEmpty ? "Connection request sent via LinkedIn for \(sel.role) at \(sel.company)." : sel.body)
                                    .font(.system(size: 13))
                                    .lineSpacing(3)
                                    .textSelection(.enabled)
                                    .padding(12)
                                    .frame(maxWidth: .infinity, alignment: .leading)
                                    .background(RoundedRectangle(cornerRadius: 9).fill(Color(NSColor.windowBackgroundColor)))
                            }
                        }
                        .padding(16)
                        .frame(maxWidth: .infinity, alignment: .topLeading)
                        .background(RoundedRectangle(cornerRadius: 12).fill(Color(NSColor.controlBackgroundColor)))
                        .overlay(RoundedRectangle(cornerRadius: 12).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
                    }
                }
            }
        }
    }

    private func linkedinPipelineColumn(
        title: String,
        subtitle: String,
        items: [LinkedInConnectionItem],
        color: Color,
        icon: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            VStack(alignment: .leading, spacing: 2) {
                HStack {
                    Image(systemName: icon).foregroundColor(color)
                    Text(title)
                        .font(.system(size: 11, weight: .heavy))
                    Spacer()
                    Text("\(items.count)")
                        .font(.system(size: 11, weight: .bold))
                        .padding(.horizontal, 7)
                        .padding(.vertical, 2)
                        .background(Capsule().fill(color.opacity(0.18)))
                        .foregroundColor(color)
                }
                Text(subtitle)
                    .font(.system(size: 10.5))
                    .foregroundColor(.secondary)
            }
            .padding(10)
            .background(RoundedRectangle(cornerRadius: 9).fill(color.opacity(0.08)))

            ForEach(items.prefix(25)) { item in
                let isSel = store.selectedLinkedinConnection?.id == item.id
                Button {
                    store.selectedLinkedinConnectionId = item.id
                    store.linkedinLayoutMode = "split"
                } label: {
                    VStack(alignment: .leading, spacing: 4) {
                        HStack {
                            Text(item.contactName)
                                .font(.system(size: 12.5, weight: .bold))
                                .foregroundColor(.primary)
                                .lineLimit(1)
                            Spacer()
                            if !item.sentAt.isEmpty && item.sentAt != "Recent" {
                                Text(String(item.sentAt.prefix(10)))
                                    .font(.system(size: 10))
                                    .foregroundColor(.secondary)
                            }
                        }
                        Text("\(item.company) • \(item.role)")
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                        if !item.body.isEmpty {
                            Text(item.body)
                                .font(.system(size: 10.5))
                                .foregroundColor(.primary.opacity(0.85))
                                .lineLimit(2)
                                .padding(.top, 2)
                        }
                    }
                    .padding(9)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .background(RoundedRectangle(cornerRadius: 8).fill(isSel ? color.opacity(0.15) : Color(NSColor.windowBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 8).stroke(isSel ? color : Color.secondary.opacity(0.14), lineWidth: isSel ? 1.5 : 1))
                }
                .buttonStyle(.plain)
            }
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .topLeading)
        .background(RoundedRectangle(cornerRadius: 12).fill(Color(NSColor.controlBackgroundColor)))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
    }

