    // Sub-View D: Suppressed Bounces & No-Send Guard
    private var suppressedBouncesListView: some View {
        let q = store.outreachSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let filtered = store.suppressedEmails.filter {
            q.isEmpty
                || $0.email.lowercased().contains(q)
                || $0.company.lowercased().contains(q)
                || $0.reason.lowercased().contains(q)
        }
        return CardBox(title: "Protected Email Bounce & Suppression Register (\(filtered.count) Blocked Addresses)", icon: "shield.lefthalf.filled.slash") {
            VStack(alignment: .leading, spacing: 8) {
                Text("Never email a suppressed address for applications or follow-ups. Hard bounces (550 / NDR) are permanently guarded against retry.")
                    .font(.caption)
                    .foregroundColor(.secondary)
                ForEach(filtered) { item in
                    HStack(spacing: 12) {
                        StatusBadge(text: "SMTP \(item.statusCode)", color: .red)
                        VStack(alignment: .leading, spacing: 2) {
                            HStack(spacing: 6) {
                                if !item.company.isEmpty {
                                    Text(item.company)
                                        .font(.system(size: 12.5, weight: .bold))
                                        .foregroundColor(.primary)
                                    Text("·")
                                        .foregroundColor(.secondary)
                                }
                                Text(item.email)
                                    .font(.system(size: 12, weight: .semibold, design: .monospaced))
                                    .foregroundColor(.secondary)
                            }
                            Text("\(item.reason) — \(item.diagnostic)")
                                .font(.caption)
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }
                        Spacer()
                    }
                    .padding(9)
                    .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.windowBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.red.opacity(0.20), lineWidth: 1))
                }
            }
        }
    }

    // MARK: - Subtab 3: Job Boards & Direct ATS Directory (Clean, Compact, Linear/Raycast-Inspired Directory)

    private var jobBoardsDirectoryView: some View {
        let q = store.jobBoardSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let matchesQuery: (JobBoardChannelItem) -> Bool = { board in
            q.isEmpty
                || board.name.lowercased().contains(q)
                || board.domain.lowercased().contains(q)
                || board.operationalNote.lowercased().contains(q)
                || board.attentionReason.lowercased().contains(q)
        }

        let allOperational = store.jobBoards.filter { !$0.excluded && $0.operational }
        let allPrimaryNeedsSetup = store.jobBoards.filter { !$0.excluded && !$0.operational && $0.isPrimary }
        let allOtherBoards = store.jobBoards.filter { !$0.excluded && !$0.operational && !$0.isPrimary }
        let allExcluded = store.jobBoards.filter { $0.excluded }

        let filteredOperational = allOperational.filter(matchesQuery)
        let filteredPrimaryNeedsSetup = allPrimaryNeedsSetup.filter(matchesQuery)
        let filteredOtherBoards = allOtherBoards.filter(matchesQuery)
        let filteredExcluded = allExcluded.filter(matchesQuery)

        let showOperationalSection = store.jobBoardCategoryFilter == "all" || store.jobBoardCategoryFilter == "operational"
        let showPrimaryNeedsSetupSection = store.jobBoardCategoryFilter == "all" || store.jobBoardCategoryFilter == "primary_needs_setup"
        let showOtherSection = store.jobBoardCategoryFilter == "all" || store.jobBoardCategoryFilter == "other_boards"
        let showExcludedSection = store.jobBoardCategoryFilter == "all" || store.jobBoardCategoryFilter == "excluded"

        return VStack(alignment: .leading, spacing: 14) {
            // 1. Clean Single-Level Search & Category Filter Strip (No Heavy Outer Box)
            HStack(spacing: 10) {
                // Search Field
                HStack(spacing: 7) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 12, weight: .medium))
                        .foregroundColor(.secondary)
                    TextField("Search \(store.jobBoards.count) job boards & ATS platforms…", text: $store.jobBoardSearchQuery)
                        .textFieldStyle(.plain)
                        .font(.system(size: 12.5))
                    if !store.jobBoardSearchQuery.isEmpty {
                        Button {
                            store.jobBoardSearchQuery = ""
                        } label: {
                            Image(systemName: "xmark.circle.fill")
                                .font(.system(size: 12))
                                .foregroundColor(.secondary)
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 10)
                .padding(.vertical, 6)
                .frame(minWidth: 220, maxWidth: 340)
                .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.controlBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.16), lineWidth: 1))

                // Compact Category Filter Pills
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 5) {
                        jobBoardFilterPill(
                            id: "all",
                            title: "All",
                            count: store.jobBoards.count,
                            dotColor: nil
                        )
                        jobBoardFilterPill(
                            id: "operational",
                            title: "Operational",
                            count: allOperational.count,
                            dotColor: .green
                        )
                        jobBoardFilterPill(
                            id: "primary_needs_setup",
                            title: "Needs Setup",
                            count: allPrimaryNeedsSetup.count,
                            dotColor: .orange
                        )
                        jobBoardFilterPill(
                            id: "other_boards",
                            title: "Direct ATS",
                            count: allOtherBoards.count,
                            dotColor: .blue
                        )
                        jobBoardFilterPill(
                            id: "excluded",
                            title: "Suspended",
                            count: allExcluded.count,
                            dotColor: allExcluded.isEmpty ? .secondary : .red
                        )
                    }
                }

                Spacer(minLength: 4)

                if !store.jobBoardSearchQuery.isEmpty || store.jobBoardCategoryFilter != "all" {
                    Button {
                        store.jobBoardSearchQuery = ""
                        store.jobBoardCategoryFilter = "all"
                    } label: {
                        Text("Reset")
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.secondary)
                    }
                    .buttonStyle(.plain)
                }
            }

            // 2. Collapsible Section 1: Operational
            if showOperationalSection {
                jobBoardsSectionCard(
                    title: "Operational",
                    subtitle: "Active channels ready for job discovery and application autofill",
                    statusSummary: "\(filteredOperational.count) active",
                    dotColor: .green,
                    boards: filteredOperational,
                    emptyMessage: "No operational job boards match your current search.",
                    sectionKind: "operational",
                    isExpanded: !q.isEmpty || store.jobBoardCategoryFilter == "operational" || store.jobBoardsExpandedOperational,
                    onToggleExpand: {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedOperational.toggle()
                        }
                    }
                )
            }

            // 3. Collapsible Section 2: Primary Job Boards — Needs Configuration
            if showPrimaryNeedsSetupSection {
                let authCount = filteredPrimaryNeedsSetup.filter(\.requiresAuth).count
                let configCount = filteredPrimaryNeedsSetup.count - authCount
                let summaryParts = [
                    authCount > 0 ? "\(authCount) auth required" : nil,
                    configCount > 0 ? "\(configCount) config required" : nil,
                ].compactMap { $0 }.joined(separator: " · ")

                jobBoardsSectionCard(
                    title: "Needs Configuration",
                    subtitle: "Primary job boards requiring account authentication or preference verification",
                    statusSummary: summaryParts.isEmpty ? "All configured" : summaryParts,
                    dotColor: .orange,
                    boards: filteredPrimaryNeedsSetup,
                    emptyMessage: "All primary job boards are operational or suspended.",
                    sectionKind: "primary_needs_setup",
                    isExpanded: !q.isEmpty || store.jobBoardCategoryFilter == "primary_needs_setup" || store.jobBoardsExpandedPrimarySetup,
                    onToggleExpand: {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedPrimarySetup.toggle()
                        }
                    }
                )
            }

            // 4. Collapsible Section 3: Direct ATS & Career Portals
            if showOtherSection {
                let authCount = filteredOtherBoards.filter(\.requiresAuth).count
                let configCount = filteredOtherBoards.count - authCount
                let summaryParts = [
                    authCount > 0 ? "\(authCount) auth required" : nil,
                    configCount > 0 ? "\(configCount) config required" : nil,
                ].compactMap { $0 }.joined(separator: " · ")

                jobBoardsSectionCard(
                    title: "Direct ATS & Career Portals",
                    subtitle: "Enterprise ATS platforms and company career portals requiring setup",
                    statusSummary: summaryParts.isEmpty ? "\(filteredOtherBoards.count) channels" : summaryParts,
                    dotColor: .blue,
                    boards: filteredOtherBoards,
                    emptyMessage: "No direct ATS channels match your current filter.",
                    sectionKind: "other",
                    isExpanded: !q.isEmpty || store.jobBoardCategoryFilter == "other_boards" || store.jobBoardsExpandedOther,
                    onToggleExpand: {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedOther.toggle()
                        }
                    }
                )
            }

            // 5. Collapsible Section 4: Excluded & Suspended (Compact when empty)
            if showExcludedSection {
                jobBoardsSectionCard(
                    title: "Excluded & Suspended",
                    subtitle: "Platforms paused from automated browsing and applications",
                    statusSummary: filteredExcluded.isEmpty ? "None suspended" : "\(filteredExcluded.count) suspended",
                    dotColor: filteredExcluded.isEmpty ? .secondary : .red,
                    boards: filteredExcluded,
                    emptyMessage: "No job boards are currently suspended.",
                    sectionKind: "excluded",
                    isExpanded: !q.isEmpty || store.jobBoardCategoryFilter == "excluded" || (!filteredExcluded.isEmpty && store.jobBoardsExpandedExcluded),
                    onToggleExpand: {
                        withAnimation(.easeInOut(duration: 0.14)) {
                            store.jobBoardsExpandedExcluded.toggle()
                        }
                    }
                )
            }
        }
    }

    private func jobBoardFilterPill(id: String, title: String, count: Int, dotColor: Color?) -> some View {
        let isSelected = store.jobBoardCategoryFilter == id
        return Button {
            withAnimation(.easeInOut(duration: 0.12)) {
                store.jobBoardCategoryFilter = (store.jobBoardCategoryFilter == id && id != "all") ? "all" : id
            }
        } label: {
            let _ = dotColor
            HStack(spacing: 5) {
                Text(title)
                    .font(.system(size: 11.5, weight: isSelected ? .semibold : .medium))
                    .foregroundColor(isSelected ? .white : .primary)
                    .lineLimit(1)
                Text("\(count)")
                    .font(.system(size: 10.5, weight: .semibold, design: .rounded))
                    .foregroundColor(isSelected ? .white.opacity(0.9) : .secondary)
                    .padding(.horizontal, 5)
                    .padding(.vertical, 1)
                    .background(Capsule().fill(isSelected ? Color.white.opacity(0.20) : Color.secondary.opacity(0.12)))
            }
            .padding(.horizontal, 9)
            .padding(.vertical, 5)
            .fixedSize(horizontal: true, vertical: false)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(isSelected ? Color.accentColor : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 6)
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.14), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }

    private func jobBoardsSectionCard(
        title: String,
        subtitle: String,
        statusSummary: String,
        dotColor: Color,
        boards: [JobBoardChannelItem],
        emptyMessage: String,
        sectionKind: String,
        isExpanded: Bool,
        onToggleExpand: @escaping () -> Void
    ) -> some View {
        let isCompactEmptyExcluded = (sectionKind == "excluded" && boards.isEmpty && !isExpanded)

        return VStack(alignment: .leading, spacing: 0) {
            // Clickable Collapsible Section Header
            Button(action: onToggleExpand) {
                let _ = dotColor
                HStack(alignment: .center, spacing: 8) {
                    Image(systemName: isExpanded ? "chevron.down" : "chevron.right")
                        .font(.system(size: 10.5, weight: .bold))
                        .foregroundColor(.secondary)
                        .frame(width: 12)

                    Text(title)
                        .font(.system(size: 13, weight: .semibold))
                        .foregroundColor(.primary)

                    Text("\(boards.count)")
                        .font(.system(size: 11, weight: .semibold, design: .rounded))
                        .foregroundColor(.secondary)
                        .padding(.horizontal, 6)
                        .padding(.vertical, 1)
                        .background(Capsule().fill(Color.secondary.opacity(0.12)))

                    if !isExpanded || isCompactEmptyExcluded {
                        Text("·")
                            .foregroundColor(.secondary.opacity(0.6))
                        Text(subtitle)
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                    }

                    Spacer(minLength: 8)

                    Text(statusSummary)
                        .font(.system(size: 11, weight: .medium))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                }
                .padding(.horizontal, 12)
                .padding(.vertical, isCompactEmptyExcluded ? 8 : 9)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)

            if isExpanded {
                Divider()
                    .opacity(0.5)

                if boards.isEmpty {
                    HStack(spacing: 8) {
                        Image(systemName: sectionKind == "excluded" ? "checkmark.circle" : "magnifyingglass")
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                        Text(emptyMessage)
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                        Spacer()
                    }
                    .padding(.horizontal, 14)
                    .padding(.vertical, 10)
                } else {
                    VStack(alignment: .leading, spacing: 0) {
                        ForEach(Array(boards.enumerated()), id: \.element.id) { idx, board in
                            jobBoardRowView(board: board, sectionKind: sectionKind)
                            if idx < boards.count - 1 {
                                Divider()
                                    .padding(.leading, 44)
                                    .opacity(0.35)
                            }
                        }
                    }
                }
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(Color(NSColor.controlBackgroundColor).opacity(0.45))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 8)
                .stroke(Color.secondary.opacity(0.14), lineWidth: 1)
        )
    }

    private func jobBoardRowView(board: JobBoardChannelItem, sectionKind: String) -> some View {
        let detailNote: String = {
            let raw: String
            if board.excluded {
                raw = "Excluded from AI Agent"
            } else if board.operational {
                raw = board.operationalNote
            } else {
                raw = board.attentionReason
            }
            return raw
                .replacingOccurrences(of: " — Operational", with: "")
                .replacingOccurrences(of: " Operational", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }()

        return HStack(alignment: .center, spacing: 10) {
            // 1. Platform Logo (Compact 22pt)
            PlatformLogoIconView(
                slug: board.slug,
                fallbackDomain: board.domain,
                repoRootDir: store.repoRootDir,
                size: 22
            )
            .opacity(board.excluded ? 0.55 : 1.0)

            // 2. Platform Name, Domain & Concise Requirement/Capability Note
            HStack(alignment: .firstTextBaseline, spacing: 6) {
                Text(board.name)
                    .font(.system(size: 12.5, weight: .semibold))
                    .foregroundColor(board.excluded ? .secondary : .primary)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)

                Text(board.domain)
                    .font(.system(size: 11, weight: .regular, design: .monospaced))
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)

                if !detailNote.isEmpty && detailNote.lowercased() != "operational" {
                    Text("·")
                        .font(.system(size: 11))
                        .foregroundColor(.secondary.opacity(0.6))

                    Text(detailNote)
                        .font(.system(size: 11.5))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                        .truncationMode(.tail)
                }
            }
            .help("\(board.name) (\(board.domain)) — \(detailNote)")

            Spacer(minLength: 10)

            // 3. Standardized Contextual Action Button (Only for Non-Operational / Setup Boards; Open Board is in the ⋯ menu)
            if board.excluded {
                Button {
                    store.setJobBoardExcluded(board.id, excluded: false)
                } label: {
                    Label("Reinstate", systemImage: "arrow.uturn.backward")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .help("Reinstate \(board.name) so AutoApply can discover and autofill jobs from this board.")
            } else if !board.operational {
                if board.requiresAuth {
                    Button {
                        store.openJobBoardAuthSetup(board)
                    } label: {
                        Label("Set Up Auth", systemImage: "key.fill")
                            .font(.system(size: 13, weight: .bold))
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.accentColor)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .help("Open \(board.name) in the AutoApply Browser to sign in and enable automated job discovery.")
                } else {
                    Button {
                        store.openJobBoardAuthSetup(board)
                    } label: {
                        Label("Configure", systemImage: "slider.horizontal.3")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .help("Configure search filters and preferences for \(board.name).")
                }
            }

            // 4. Three-Dot (⋯) Overflow Menu (Includes Open Board for clean operational rows)
            EllipsisActionMenuButton(helpText: "Open actions for \(board.name), including opening the board in the browser or changing its operational status.") {
                Button {
                    store.openJobBoardSearch(board)
                } label: {
                    Label("Open Board", systemImage: "arrow.up.right")
                }
                Divider()
                if board.excluded {
                    Button {
                        store.setJobBoardExcluded(board.id, excluded: false, operational: true)
                    } label: {
                        Label("Reinstate & Mark Operational", systemImage: "checkmark.circle")
                    }
                } else {
                    Button {
                        store.toggleJobBoardOperational(board.id, operational: !board.operational)
                    } label: {
                        Label(
                            board.operational ? "Mark as Needs Configuration" : "Mark as Operational",
                            systemImage: board.operational ? "sliders" : "checkmark.circle"
                        )
                    }
                    if board.operational {
                        Button {
                            store.openJobBoardAuthSetup(board)
                        } label: {
                            Label(board.requiresAuth ? "Set Up Authentication…" : "Configure Platform…", systemImage: "key")
                        }
                    }
                    Button {
                        store.copyToClipboard(board.url, label: "\(board.name) URL")
                    } label: {
                        Label("Copy Board URL", systemImage: "doc.on.doc")
                    }
                    Divider()
                    Button(role: .destructive) {
                        store.setJobBoardExcluded(board.id, excluded: true)
                    } label: {
                        Label("Suspend / Exclude from Agent", systemImage: "nosign")
                    }
                }
            }
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 7)
        .contentShape(Rectangle())
    }

    private func channelSystemIcon(_ channel: String) -> String {
        switch channel {
        case "linkedin_dm": return "bubble.left.and.bubble.right.fill"
        case "linkedin_invite": return "person.crop.circle.badge.plus"
        case "whatsapp": return "phone.bubble.fill"
        case "sms": return "message.fill"
        default: return "envelope.fill"
        }
    }

    private func channelAccentColor(_ channel: String) -> Color {
        switch channel {
        case "linkedin_dm": return .blue
        case "linkedin_invite": return .indigo
        case "whatsapp": return .green
        case "sms": return .teal
        default: return .purple
        }
    }

    private func outreachStatusColor(_ category: String) -> Color {
        switch category {
        case "verified_sent": return .green
        case "pending_invite": return .blue
        case "failed_or_blocked": return .red
        default: return .orange
        }
    }
}

// MARK: - 3B. Standalone Messages Main Tab (Unified Email, LinkedIn, HH & iMessage Aggregator)

struct FollowUpTrackerWorkspaceView: View {
    @ObservedObject var store: WorkspaceStore

    private var allThreadsCount: Int { store.outreachCounts.allCount }
    private var emailThreadsCount: Int { store.outreachCounts.emailCount }
    private var linkedinThreadsCount: Int { store.outreachCounts.linkedinCount }
    private var hhThreadsCount: Int { store.outreachCounts.hhCount }
    private var imessageThreadsCount: Int { store.outreachCounts.imessageCount }
    private var channelScopedCount: Int { store.outreachCounts.channelScopedCount }
    private var actionRequiredCount: Int { store.outreachCounts.actionRequiredCount }
    private var onlineAssessmentCount: Int { store.outreachCounts.onlineAssessmentCount }
    private var realInterviewCount: Int { store.outreachCounts.realInterviewCount }
    private var detailsRequestedCount: Int { store.outreachCounts.detailsRequestedCount }
    private var followUpCount: Int { store.outreachCounts.followUpCount }
    private var submittedConfirmationCount: Int { store.outreachCounts.submittedConfirmationCount }
    private var rejectedThreadsCount: Int { store.outreachCounts.rejectedCount }
    private var repliedThreadsCount: Int { store.outreachCounts.repliedCount }
    private var queuedThreadsCount: Int { store.outreachCounts.queuedCount }
    private var invitePendingCount: Int { store.outreachCounts.invitePendingCount }

    private func channelIconName(for channel: String) -> String {
        switch channel {
        case "linkedin": return "bubble.left.and.bubble.right.fill"
        case "hh": return "briefcase.fill"
        case "imessage": return "message.fill"
        default: return "envelope.fill"
        }
    }

    private func openButtonLabel(for channel: String) -> String {
        switch channel {
        case "linkedin": return "Open LinkedIn"
        case "hh": return "Open HH Chat"
        case "imessage": return "Open iMessage"
        default: return "Open Email"
        }
    }

    private func openExternalThread(_ thread: OutreachThreadItem) {
        if thread.channel == "imessage" {
            let rawHandle = thread.contactHandle
                .replacingOccurrences(of: "imessage://", with: "")
                .replacingOccurrences(of: "sms://", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            if !rawHandle.isEmpty,
               let encoded = rawHandle.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
               let url = URL(string: "imessage://\(encoded)")
            {
                NSWorkspace.shared.open(url)
                return
            }
            if let messagesUrl = URL(string: "imessage://") {
                NSWorkspace.shared.open(messagesUrl)
                return
            }
        }
        let targetUrl: String = {
            if thread.channel == "hh" {
                let candidates = [thread.threadUrl, thread.profileUrl, thread.contactHandle]
                if let chatUrl = candidates.first(where: { $0.contains("hh.ru/chat/") && !$0.hasSuffix("/chat/-1") }) {
                    return chatUrl
                }
                if let vacUrl = candidates.first(where: { $0.contains("hh.ru/vacancy/") }) {
                    return vacUrl
                }
                if let specific = candidates.first(where: {
                    $0.hasPrefix("http")
                        && $0 != "https://hh.ru/applicant/negotiations"
                        && $0 != "https://chatik.hh.ru"
                }) {
                    return specific
                }
                return "https://hh.ru/chat"
            }
            if thread.channel == "linkedin" {
                func normalizeLi(_ rawUrl: String) -> String {
                    let s = rawUrl.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !s.isEmpty else { return "" }
                    let low = s.lowercased()
                    if low.contains("linkedin.com/") && !low.hasPrefix("http://") && !low.hasPrefix("https://") {
                        return low.hasPrefix("www.") ? "https://\(s)" : "https://www.\(s)"
                    }
                    return s
                }
                let candidates = [thread.threadUrl, thread.profileUrl, thread.contactHandle].map(normalizeLi)
                if let msgThreadUrl = candidates.first(where: { $0.lowercased().contains("linkedin.com/messaging/thread/") }) {
                    return msgThreadUrl
                }
                if let profileUrl = candidates.first(where: {
                    let l = $0.lowercased()
                    return l.contains("linkedin.com/in/") && !l.contains("alex-mercer") && !l.contains("alexander-mercer")
                }) {
                    return profileUrl
                }
                if let specificLiUrl = candidates.first(where: {
                    let l = $0.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "/"))
                    return l.contains("linkedin.com/")
                        && l != "https://www.linkedin.com/messaging"
                        && l != "https://linkedin.com/messaging"
                }) {
                    return specificLiUrl
                }
                let cleanContact = thread.contactName.trimmingCharacters(in: .whitespacesAndNewlines)
                if !cleanContact.isEmpty,
                   !cleanContact.lowercased().contains("hiring team"),
                   let encoded = cleanContact.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed)
                {
                    return "https://www.linkedin.com/search/results/people/?keywords=\(encoded)"
                }
                return "https://www.linkedin.com/messaging/"
            }
            if thread.threadUrl.hasPrefix("http") { return thread.threadUrl }
            if thread.profileUrl.hasPrefix("http") { return thread.profileUrl }
            if thread.contactHandle.hasPrefix("http") { return thread.contactHandle }
            switch thread.channel {
            case "linkedin": return "https://www.linkedin.com/messaging/"
            case "hh": return "https://hh.ru/chat"
            default: return "https://mail.google.com/mail/u/0/#inbox"
            }
        }()
        store.sendActionInBackground("launch_browser_session", payload: [
            "target": "outreach_thread",
            "url": targetUrl,
            "thread_id": thread.id,
            "channel": thread.channel,
            "company": thread.company,
            "role": thread.role,
            "contact_name": thread.contactName,
            "contact_handle": thread.contactHandle,
            "profile_url": thread.profileUrl,
            "thread_url": thread.threadUrl,
            "subject": thread.subject,
        ])
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // 1. Consolidated Top Bar: Platform Switcher + Full-Width Status Filter Chips + Overflow Menu
            unifiedTopControlBar

            Divider()

            // 2. Collapsible New Message Drawer (when toggled from menu)
            if store.showLogOutreachForm {
                newConversationFormCard
                Divider()
            }

            // 3. Main Workspace Content
            if store.outreachSubView == "suppressed_bounces" {
                blockedAddressesWorkspaceView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                // Full-Height Master–Detail Split View:
                // Left: Search + Scannable Conversation List
                // Right: Conversation Header + Chat Transcript + Auto-Expanding Docked Composer
                conversationMasterDetailSplitView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(NSColor.windowBackgroundColor))
    }

