        let threads = store.filteredOutreachThreads
        return HSplitView {
            // LEFT PANE: Find Conversation (Search + Scannable Thread List; Status Filter Chips are now in unifiedTopControlBar)
            VStack(alignment: .leading, spacing: 0) {
                // Search Header inside Left Pane
