                            .textFieldStyle(.plain)
                            .font(.system(size: 12.5))
                        if !store.outreachSearchQuery.isEmpty {
                            Button {
                                store.outreachSearchQuery = ""
                            } label: {
                                Image(systemName: "xmark.circle.fill")
                                    .font(.system(size: 12))
                                    .foregroundColor(.secondary)
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .padding(.horizontal, 9)
                    .padding(.vertical, 6)
                    .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 9)
                .background(Color(NSColor.controlBackgroundColor).opacity(0.38))

                Divider()

                // Conversation List
                if threads.isEmpty {
                    VStack(spacing: 8) {
                        Spacer()
                        Image(systemName: "tray")
                            .font(.system(size: 22))
                            .foregroundColor(.secondary.opacity(0.65))
                        Text("No matching conversations")
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.primary)
                        Text("Try clearing your search or switching the status filter.")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                            .multilineTextAlignment(.center)
                        if store.outreachActionFilter != "all" || !store.outreachSearchQuery.isEmpty {
                            Button {
                                store.outreachActionFilter = "all"
                                store.outreachSearchQuery = ""
                            } label: {
                                Label("Reset Filters", systemImage: "arrow.counterclockwise")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 6)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                            .padding(.top, 2)
                        }
                        Spacer()
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .padding(20)
                } else {
                    let totalCount = threads.count
                    let visibleLimit = min(totalCount, max(WorkspaceStore.outreachPageSize, store.outreachVisiblePageLimit))
                    let visibleThreads = Array(threads.prefix(visibleLimit))
                    ScrollView {
                        LazyVStack(alignment: .leading, spacing: 3) {
                            ForEach(Array(visibleThreads.enumerated()), id: \.element.id) { index, thread in
                                conversationThreadRow(thread)
                                    .onAppear {
                                        if index >= max(0, visibleLimit - 8) {
                                            store.loadMoreOutreachThreadsIfNeeded(currentIndex: index)
                                        }
                                    }
                            }
                            if visibleLimit < totalCount {
                                Button {
                                    store.loadNextOutreachThreadsPage()
                                } label: {
                                    HStack(spacing: 6) {
                                        Image(systemName: "arrow.down.circle")
                                            .font(.system(size: 11, weight: .semibold))
                                        Text("Showing \(visibleLimit) of \(totalCount) · Load more")
                                            .font(.system(size: 11.5, weight: .medium))
                                    }
                                    .foregroundColor(.secondary)
                                    .frame(maxWidth: .infinity)
                                    .padding(.vertical, 8)
                                    .background(
                                        RoundedRectangle(cornerRadius: 6)
                                            .fill(Color(NSColor.controlBackgroundColor).opacity(0.62))
                                    )
                                }
                                .buttonStyle(.plain)
                                .padding(.top, 4)
                                .onAppear {
                                    store.loadNextOutreachThreadsPage()
                                }
                            }
                        }
                        .padding(.horizontal, 8)
                        .padding(.vertical, 6)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            }
            .frame(minWidth: 280, idealWidth: 325, maxWidth: 420, maxHeight: .infinity)
            .background(Color(NSColor.controlBackgroundColor).opacity(0.24))

            // RIGHT PANE: Review Status → Take Action
            if let activeThread = store.selectedOutreachThread {
                conversationDetailPane(activeThread)
                    .frame(minWidth: 460, maxWidth: .infinity, maxHeight: .infinity)
            } else {
                OutlookStyleEmptySelectionView(
                    kind: .conversation,
                    title: "No Conversation Selected",
                    subtitle: "Select a conversation to read."
                )
                .frame(minWidth: 460, maxWidth: .infinity, maxHeight: .infinity)
            }
        }
    }

