    // MARK: - Clean, Compact Conversation Row Card (Equatable & Precomputed for 60fps Responsiveness)

    private func stripQuotedEmailReply(_ rawBody: String) -> String {
        MessageTextProcessor.stripQuotedEmailReply(rawBody)
    }

    private func richMessageAttributedString(_ rawBody: String, cacheId: String = "") -> AttributedString {
        MessageTextProcessor.richMessageAttributedString(rawBody, cacheId: cacheId)
    }

    private func extractActionableMessageLinks(_ rawBody: String, cacheId: String = "") -> [(label: String, url: String)] {
        MessageTextProcessor.extractActionableMessageLinks(rawBody, cacheId: cacheId).map { (label: $0.label, url: $0.url) }
    }

    private func isFormSubmissionUrl(_ url: String, in thread: OutreachThreadItem) -> Bool {
        MessageTextProcessor.isFormSubmissionUrl(url, jevClassification: thread.jevClassification)
    }

    private func extractFormSubmissionLink(for thread: OutreachThreadItem) -> (label: String, url: String)? {
        guard !thread.detectedFormUrl.isEmpty else { return nil }
        return (label: thread.detectedFormLabel, url: thread.detectedFormUrl)
    }

    private struct ActionRowFlowLayout: Layout {
        var horizontalSpacing: CGFloat = 8
        var verticalSpacing: CGFloat = 8

        func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
            let maxWidth = proposal.width ?? .infinity
            var currentX: CGFloat = 0
            var currentY: CGFloat = 0
            var rowHeight: CGFloat = 0
            var usedWidth: CGFloat = 0

            for subview in subviews {
                let size = subview.sizeThatFits(.unspecified)
                if currentX > 0 && currentX + size.width > maxWidth {
                    usedWidth = max(usedWidth, currentX - horizontalSpacing)
                    currentX = 0
                    currentY += rowHeight + verticalSpacing
                    rowHeight = 0
                }
                currentX += size.width + horizontalSpacing
                rowHeight = max(rowHeight, size.height)
            }
            if currentX > 0 {
                usedWidth = max(usedWidth, currentX - horizontalSpacing)
            }
            let finalWidth = proposal.width ?? usedWidth
            return CGSize(width: finalWidth, height: currentY + rowHeight)
        }

        func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
            var currentX = bounds.minX
            var currentY = bounds.minY
            var rowHeight: CGFloat = 0

            for subview in subviews {
                let size = subview.sizeThatFits(.unspecified)
                if currentX > bounds.minX && currentX + size.width > bounds.maxX {
                    currentX = bounds.minX
                    currentY += rowHeight + verticalSpacing
                    rowHeight = 0
                }
                subview.place(
                    at: CGPoint(x: currentX, y: currentY),
                    anchor: .topLeading,
                    proposal: ProposedViewSize(size)
                )
                currentX += size.width + horizontalSpacing
                rowHeight = max(rowHeight, size.height)
            }
        }
    }

