    @ViewBuilder
    private func threadRowContextMenuItems(_ thread: OutreachThreadItem) -> some View {
        if let formLink = extractFormSubmissionLink(for: thread) {
            Button {
                store.autofillAndSubmitThreadForm(thread, formUrl: formLink.url)
            } label: {
                Label("Autofill Form", systemImage: "sparkles")
            }

            Divider()
        }

        Menu {
            reclassifyThreadMenuItems(thread)
        } label: {
            Label("Reclassify", systemImage: "tag")
        }

        Divider()

        if thread.actionRequired || thread.isFollowUp || !thread.isMarkedReplied {
            Button {
                store.setOutreachThreadStatus(thread, status: "replied")
            } label: {
                Label("Mark as Replied", systemImage: "arrowshape.turn.up.left")
            }
        }

        if !thread.isFollowUp {
            Button {
                store.setOutreachThreadStatus(thread, status: "followup")
            } label: {
                Label("Mark as Follow-Up", systemImage: "flag")
            }
        }

        if !thread.actionRequired {
            Button {
                store.setOutreachThreadStatus(thread, status: "action_required")
            } label: {
                Label("Mark as Action Required", systemImage: "exclamationmark.circle")
            }
        }

        if thread.actionRequired || thread.isFollowUp {
            Button {
                store.setOutreachThreadStatus(thread, status: "resolved")
            } label: {
                Label("Mark Resolved", systemImage: "checkmark.circle")
            }
        }

        Divider()

        Button {
            store.selectOutreachThread(thread)
            store.draftFollowUpForSelectedThread()
        } label: {
            Label("AI Draft Follow-Up", systemImage: "sparkles")
        }

        Button {
            openExternalThread(thread)
        } label: {
            Label(
                openButtonLabel(for: thread.channel),
                systemImage: "arrow.up.right"
            )
        }

        if !thread.contactHandle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Button {
                NSPasteboard.general.clearContents()
                NSPasteboard.general.setString(thread.contactHandle, forType: .string)
            } label: {
                Label("Copy Contact Address", systemImage: "doc.on.doc")
            }
        }

        Divider()

        Button(role: .destructive) {
            store.deleteOutreachThread(thread)
        } label: {
            Label("Remove Thread from List", systemImage: "trash")
        }
    }

    private struct OutreachConversationRowView: View, Equatable {
        let thread: OutreachThreadItem
        let isSelected: Bool
        let channelIcon: String
        let onSelect: () -> Void

        nonisolated static func == (lhs: OutreachConversationRowView, rhs: OutreachConversationRowView) -> Bool {
            lhs.isSelected == rhs.isSelected && lhs.thread == rhs.thread
        }

        var body: some View {
            let snippetText = thread.previewSnippet

            Button(action: onSelect) {
                HStack(spacing: 0) {
                    RoundedRectangle(cornerRadius: 1.5)
                        .fill(
                            isSelected
                                ? Color.accentColor
                                : (thread.actionRequired ? Color.blue : (thread.isFollowUp ? Color.orange : Color.clear))
                        )
                        .frame(width: 3)
                        .padding(.vertical, 6)

                    HStack(alignment: .top, spacing: 9) {
                        CachedAvatarImageView(
                            localPath: thread.avatarPath,
                            remoteUrl: thread.avatarUrl,
                            slugHint: thread.avatarSlugHint,
                            size: 28,
                            isCompanyLogo: thread.isCompanyContact,
                            fallbackInitials: thread.avatarInitials
                        )
                        .padding(.top, 2)

                        VStack(alignment: .leading, spacing: 3) {
                            HStack(alignment: .center, spacing: 6) {
                                Image(systemName: channelIcon)
                                    .font(.system(size: 10, weight: .medium))
                                    .foregroundColor(isSelected ? .accentColor : .secondary)
                                    .frame(width: 12)

                                Text(thread.primaryRowTitle)
                                    .font(.system(size: 12.5, weight: isSelected || thread.actionRequired || thread.isFollowUp ? .semibold : .medium))
                                    .foregroundColor(.primary)
                                    .lineLimit(1)

                                Spacer(minLength: 4)

                                Text(thread.compactLastActivity)
                                    .font(.system(size: 10.5))
                                    .foregroundColor(.secondary)
                                    .lineLimit(1)
                            }

                            Text(thread.roleSubtitle)
                                .font(.system(size: 11, weight: .medium))
                                .foregroundColor(.secondary)
                                .lineLimit(1)

                            HStack(alignment: .center, spacing: 6) {
                                Text(snippetText)
                                    .font(.system(size: 11))
                                    .foregroundColor(.secondary.opacity(0.85))
                                    .lineLimit(1)

                                Spacer(minLength: 4)

                                if thread.actionRequired {
                                    Text(thread.actionRequiredDisplayLabel)
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.blue)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.blue.opacity(0.12)))
                                } else if thread.isFollowUp {
                                    Text("Follow-Up")
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.orange)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.orange.opacity(0.12)))
                                } else if thread.isSubmittedConfirmation {
                                    Text("Submitted")
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.green)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.green.opacity(0.12)))
                                } else if thread.isRejectedThread {
                                    Text("Rejected")
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.red)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.red.opacity(0.12)))
                                } else if thread.isQueuedThread {
                                    Text("In Queue")
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.accentColor)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.accentColor.opacity(0.12)))
                                } else if thread.isPendingThread {
                                    Text("Pending")
                                        .font(.system(size: 9.5, weight: .semibold))
                                        .foregroundColor(.orange)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.orange.opacity(0.12)))
                                } else if thread.isResolvedMonitoring {
                                    Text("Resolved")
                                        .font(.system(size: 9.5, weight: .medium))
                                        .foregroundColor(.secondary)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.secondary.opacity(0.12)))
                                } else if thread.hasInboundReply {
                                    Text("Replied")
                                        .font(.system(size: 9.5, weight: .medium))
                                        .foregroundColor(.secondary)
                                        .padding(.horizontal, 5.5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.secondary.opacity(0.12)))
                                } else if thread.messages.count > 1 {
                                    Text("\(thread.messages.count)")
                                        .font(.system(size: 9.5, weight: .semibold, design: .rounded))
                                        .foregroundColor(.secondary)
                                        .padding(.horizontal, 5)
                                        .padding(.vertical, 1)
                                        .background(Capsule().fill(Color.secondary.opacity(0.10)))
                                }
                            }
                        }
                    }
                    .padding(.leading, 8)
                    .padding(.trailing, 9)
                    .padding(.vertical, 7)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(
                    RoundedRectangle(cornerRadius: 7)
                        .fill(
                            isSelected
                                ? Color(NSColor.controlBackgroundColor)
                                : Color.clear
                        )
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 7)
                        .stroke(
                            isSelected
                                ? Color.secondary.opacity(0.22)
                                : Color.clear,
                            lineWidth: 1
                        )
                )
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
        }
    }

    private func conversationThreadRow(_ thread: OutreachThreadItem) -> some View {
        OutreachConversationRowView(
            thread: thread,
            isSelected: store.selectedOutreachThreadId == thread.id,
            channelIcon: channelIconName(for: thread.channel),
            onSelect: { store.selectOutreachThread(thread) }
        )
        .equatable()
        .contextMenu {
            threadRowContextMenuItems(thread)
        }
    }

    // MARK: - Right Pane: Conversation Header + Paginated Lazy Transcript + Docked Composer

    private func conversationDetailPane(_ thread: OutreachThreadItem) -> some View {
        let cleanComp = thread.company.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanRole = thread.role.trimmingCharacters(in: .whitespacesAndNewlines)
        let isSubmittedConfirmation = thread.isSubmittedConfirmation
        let isRejected = thread.isRejectedThread
        let compactHandle = thread.compactHandle
        let showHandle = thread.showCompactHandle
        let totalMessages = thread.messages.count
        let visibleMessageLimit = min(totalMessages, max(WorkspaceStore.transcriptPageSize, store.transcriptVisibleMessageLimit))
        let hiddenEarlierCount = max(0, totalMessages - visibleMessageLimit)
        let visibleMessages: [OutreachChatMessageItem] = hiddenEarlierCount > 0
            ? Array(thread.messages.suffix(visibleMessageLimit))
            : thread.messages

        return VStack(alignment: .leading, spacing: 0) {
            // 1. Conversation Header: Full-Width Important Text + Non-Interfering Action Bar Below
            VStack(alignment: .leading, spacing: 10) {
                HStack(alignment: .top, spacing: 12) {
                    contactAvatarView(for: thread, name: thread.contactName, size: 38)
                        .padding(.top, 2)

                    VStack(alignment: .leading, spacing: 4) {
                        // Row 1: Full Contact Name + Spacer + Channel Badge + Simple Status Badge
                        HStack(alignment: .center, spacing: 8) {
                            Text(thread.contactName)
                                .font(.system(size: 16, weight: .bold))
                                .foregroundColor(.primary)
                                .lineLimit(2)
                                .textSelection(.enabled)

                            Spacer(minLength: 8)

                            HStack(spacing: 4) {
                                Image(systemName: channelIconName(for: thread.channel))
                                    .font(.system(size: 9.5, weight: .semibold))
                                Text(thread.channelLabel)
                                    .font(.system(size: 10.5, weight: .medium))
                                    .lineLimit(1)
                            }
                            .foregroundColor(.secondary)
                            .padding(.horizontal, 7)
                            .padding(.vertical, 2.5)
                            .background(Capsule().fill(Color.secondary.opacity(0.12)))
                            .fixedSize(horizontal: true, vertical: false)

                            if thread.actionRequired {
                                Text(thread.actionRequiredDisplayLabel)
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.blue)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.blue.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            } else if thread.isFollowUp {
                                Text("Follow-Up")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.orange)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.orange.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            } else if isSubmittedConfirmation {
                                Text("Submitted")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.green)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.green.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            } else if isRejected {
                                Text("Rejected")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.red)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.red.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            } else if thread.isRepliedBadgeVisible {
                                Text("Replied")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.secondary)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.secondary.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            } else if thread.isResolvedMonitoring {
                                Text("Resolved")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .lineLimit(1)
                                    .foregroundColor(.secondary)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 2.5)
                                    .background(Capsule().fill(Color.secondary.opacity(0.14)))
                                    .fixedSize(horizontal: true, vertical: false)
                            }

                            if thread.isQueuedThread {
                                HStack(spacing: 4) {
                                    Image(systemName: "clock.fill")
                                        .font(.system(size: 9.5, weight: .semibold))
                                    Text("In Queue")
                                        .font(.system(size: 10.5, weight: .semibold))
                                }
                                .lineLimit(1)
                                .foregroundColor(.accentColor)
                                .padding(.horizontal, 8)
                                .padding(.vertical, 2.5)
                                .background(Capsule().fill(Color.accentColor.opacity(0.14)))
                                .fixedSize(horizontal: true, vertical: false)
                            } else if thread.isPendingThread {
                                HStack(spacing: 4) {
                                    Image(systemName: "clock.badge.exclamationmark")
                                        .font(.system(size: 9.5, weight: .semibold))
                                    Text("Pending")
                                        .font(.system(size: 10.5, weight: .semibold))
                                }
                                .lineLimit(1)
                                .foregroundColor(.orange)
                                .padding(.horizontal, 8)
                                .padding(.vertical, 2.5)
                                .background(Capsule().fill(Color.orange.opacity(0.14)))
                                .fixedSize(horizontal: true, vertical: false)
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)

                        // Row 2: Clean Company Name (& Role when available, without "Company:" or "Role:" labels)
                        if !cleanComp.isEmpty {
                            HStack(alignment: .firstTextBaseline, spacing: 6) {
                                Text(cleanComp)
                                    .font(.system(size: 13.5, weight: .semibold))
                                    .foregroundColor(.primary.opacity(0.86))
                                    .lineLimit(1)
                                if !cleanRole.isEmpty && cleanRole.caseInsensitiveCompare(cleanComp) != .orderedSame {
                                    Text("·")
                                        .font(.system(size: 13.5, weight: .medium))
                                        .foregroundColor(.secondary)
                                    Text(cleanRole)
                                        .font(.system(size: 13, weight: .regular))
                                        .foregroundColor(.secondary)
                                        .lineLimit(1)
                                }
                            }
                            .textSelection(.enabled)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }

                        // Row 3: Full Email Address or URL Handle + Copy Icon (Full Width, Never Truncated)
