                                Text(compactHandle)
                                    .font(.system(size: 12, design: .monospaced))
                                    .foregroundColor(.secondary)
                                    .fixedSize(horizontal: false, vertical: true)
                                    .textSelection(.enabled)

                                Button {
                                    store.copyToClipboard(thread.contactHandle, label: "contact address")
                                } label: {
                                    Image(systemName: "doc.on.doc")
                                        .font(.system(size: 11, weight: .semibold))
                                        .foregroundColor(.secondary)
                                        .padding(4)
                                        .background(RoundedRectangle(cornerRadius: 5).fill(Color.secondary.opacity(0.10)))
                                }
                                .buttonStyle(.plain)
                                .help("Copy this contact email address or link to the clipboard.")
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }

                // Dedicated Action Row Below Important Text (Never collides with or truncates Contact Name, Role, or Handle)
                ActionRowFlowLayout(horizontalSpacing: 8, verticalSpacing: 8) {
                    if let formLink = extractFormSubmissionLink(for: thread) {
                        let isAutofilling = store.autofillingThreadId == thread.id
                        Button {
                            store.autofillAndSubmitThreadForm(thread, formUrl: formLink.url)
                        } label: {
                            HStack(spacing: 5) {
                                if isAutofilling {
                                    ProgressView()
                                        .controlSize(.small)
                                } else {
                                    Image(systemName: "sparkles")
                                        .font(.system(size: 12.5, weight: .semibold))
                                }
                                Text(isAutofilling ? "Autofilling Form..." : "Autofill Form")
                                    .font(.system(size: 13, weight: .semibold))
                                    .lineLimit(1)
                            }
                            .padding(.horizontal, 4)
                            .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.borderedProminent)
                        .tint(.accentColor)
                        .controlSize(.large)
                        .disabled(isAutofilling)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Open \(formLink.url) in AutoApply Browser, autofill your Knowledge Base details & tailored Resume PDF, and submit.")
                    }

                    if thread.actionRequired {
                        Button {
                            store.setOutreachThreadStatus(thread, status: "replied")
                        } label: {
                            Label("Mark as Replied", systemImage: "arrowshape.turn.up.left")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 3)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Mark that you replied or provided the requested details and are now waiting for them to get back to you.")

                        Button {
                            store.setOutreachThreadStatus(thread, status: "followup")
                        } label: {
                            Label("Mark as Follow-Up", systemImage: "flag")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 3)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Move out of Action Required into Follow-Up while waiting for them to get back to you.")
                    } else if thread.isFollowUp {
                        Button {
                            store.setOutreachThreadStatus(thread, status: "replied")
                        } label: {
                            Label("Mark as Replied", systemImage: "arrowshape.turn.up.left")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 3)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Mark that you replied or provided the requested details and are waiting for them to get back to you.")

                        Button {
                            store.setOutreachThreadStatus(thread, status: "resolved")
                        } label: {
                            Label("Mark Resolved", systemImage: "checkmark.circle")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 3)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Mark this conversation as resolved so it no longer requires follow-up.")
                    } else {
                        Button {
                            store.setOutreachThreadStatus(thread, status: "followup")
                        } label: {
                            Label("Mark as Follow-Up", systemImage: "flag")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 3)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("Flag this conversation for follow-up while waiting for them to get back to you.")

                        if !thread.isMarkedReplied {
                            Button {
                                store.setOutreachThreadStatus(thread, status: "replied")
                            } label: {
                                Label("Mark as Replied", systemImage: "arrowshape.turn.up.left")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 3)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                            .help("Mark that you replied or provided details and are waiting for them to get back to you.")
                        } else {
                            Button {
                                store.setOutreachThreadStatus(thread, status: "action_required")
                            } label: {
                                Label("Mark Action Required", systemImage: "exclamationmark.circle")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 3)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                            .help("Move this conversation back to Action Required.")
                        }
                    }

                    Button {
                        openExternalThread(thread)
                    } label: {
                        Label(
                            openButtonLabel(for: thread.channel),
                            systemImage: "arrow.up.right"
                        )
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 3)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .help(
                        thread.channel == "imessage"
                            ? "Open this conversation in macOS Messages."
                            : (thread.channel == "hh"
                                ? "Open this HeadHunter (hh.ru) chat or vacancy in your browser."
                                : (thread.channel == "linkedin"
                                    ? "Open this LinkedIn conversation or profile in your browser."
                                    : "Open this Gmail thread in your browser with the latest message in focus."))
                    )

                    EllipsisActionMenuButton(helpText: "Thread actions") {
                        threadRowContextMenuItems(thread)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.leading, 50)
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 12)
            .background(Color(NSColor.windowBackgroundColor))

            Divider()

            // 2. Independently Scrollable Conversation Thread (Lazy + Paginated for Long Threads)
            ScrollViewReader { scrollProxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 10) {
                        if hiddenEarlierCount > 0 {
                            Button {
                                store.loadEarlierTranscriptMessages(totalCount: totalMessages)
                            } label: {
                                HStack(spacing: 6) {
                                    Image(systemName: "clock.arrow.circlepath")
                                        .font(.system(size: 11, weight: .semibold))
                                    Text("Show \(hiddenEarlierCount) earlier \(hiddenEarlierCount == 1 ? "message" : "messages")")
                                        .font(.system(size: 11.5, weight: .medium))
                                }
                                .foregroundColor(.accentColor)
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 7)
                                .background(
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(Color.accentColor.opacity(0.09))
                                )
                                .overlay(
                                    RoundedRectangle(cornerRadius: 7)
                                        .stroke(Color.accentColor.opacity(0.22), lineWidth: 1)
                                )
                            }
                            .buttonStyle(.plain)
                        }

                        ForEach(visibleMessages) { msg in
                            chatMessageBubble(msg, thread: thread)
                                .id(msg.id)
                        }

                        Color.clear
                            .frame(height: 1)
                            .id("transcript_bottom_anchor")
                    }
                    .padding(.horizontal, 18)
                    .padding(.vertical, 14)
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
                .onChange(of: thread.messages.count) { _ in
                    withAnimation(.easeOut(duration: 0.2)) {
                        scrollProxy.scrollTo("transcript_bottom_anchor", anchor: .bottom)
                    }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(Color(NSColor.windowBackgroundColor))

            Divider()

            // 4. Docked Bottom Message Composer (Auto-Expanding, Standardized Buttons)
            followUpComposerCard(thread)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    // MARK: - User & Contact Circular Avatars (Compressed WebP Thumbnails via FastThumbnailCache)

    private var userFallbackInitials: String {
        let cleaned = store.profileFullName
            .replacingOccurrences(of: "Mr.", with: "")
            .replacingOccurrences(of: "Ms.", with: "")
            .replacingOccurrences(of: "Dr.", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let parts = cleaned.split(separator: " ")
        if parts.count >= 2 {
            return "\(parts[0].prefix(1))\(parts[1].prefix(1))".uppercased()
        }
        return "VB"
    }

    private var effectiveProfileThumbPath: String {
        store.profilePhotoThumbPath.isEmpty ? store.profilePhotoPath : store.profilePhotoThumbPath
    }

    @ViewBuilder
    private func userMessageAvatarView(size: CGFloat) -> some View {
        CachedAvatarImageView(
            localPath: effectiveProfileThumbPath,
            size: size,
            isCompanyLogo: false,
            fallbackInitials: userFallbackInitials,
            accentFallback: true
        )
    }

    @ViewBuilder
    private func contactAvatarView(for thread: OutreachThreadItem, name: String, size: CGFloat) -> some View {
        let initials: String = {
            if name == thread.contactName {
                return thread.avatarInitials
            }
            let displaySource = thread.isCompanyContact ? (thread.company.isEmpty ? name : thread.company) : name
            let parts = displaySource.split(separator: " ")
            if parts.count >= 2 {
                return "\(parts[0].prefix(1))\(parts[1].prefix(1))".uppercased()
            }
            return String(displaySource.prefix(2)).uppercased()
        }()
        CachedAvatarImageView(
            localPath: thread.avatarPath,
            remoteUrl: thread.avatarUrl,
            slugHint: thread.avatarSlugHint,
            size: size,
            isCompanyLogo: thread.isCompanyContact,
            fallbackInitials: initials
        )
    }

    private struct OutreachMessageBubbleView: View, Equatable {
        let msg: OutreachChatMessageItem
        let threadId: String
        let company: String
        let channel: String
        let threadSubject: String
        let jevClassification: String
        let isCompanyContact: Bool
        let threadAvatarPath: String
        let threadAvatarUrl: String
        let threadAvatarSlugHint: String
        let senderInitials: String
        let userAvatarPath: String
        let userInitials: String
        let isAutofilling: Bool
        let onOpenFormInBrowser: (String) -> Void
        let onAutofillForm: (String) -> Void
        let onCopyUrl: (String) -> Void
        let onBeginEditQueued: () -> Void
        let onSendQueuedNow: () -> Void
        let onCancelQueued: () -> Void

        nonisolated static func == (lhs: OutreachMessageBubbleView, rhs: OutreachMessageBubbleView) -> Bool {
            lhs.msg == rhs.msg
                && lhs.threadId == rhs.threadId
                && lhs.threadAvatarPath == rhs.threadAvatarPath
                && lhs.userAvatarPath == rhs.userAvatarPath
                && lhs.isAutofilling == rhs.isAutofilling
        }

        var body: some View {
            let isMe = (msg.senderRole == "me")
            let isQueuedMsg = isMe && msg.isQueued
            let isPendingMsg = isMe && !isQueuedMsg && msg.isPending
            let estLabel: String = {
                let trimmed = msg.queueEstimate.trimmingCharacters(in: .whitespacesAndNewlines)
                return trimmed.isEmpty ? "Est. in ~15m" : trimmed
            }()
            let cleanComp = company.trimmingCharacters(in: .whitespacesAndNewlines)
            let senderDisplayName: String = {
                if isMe {
                    return cleanComp.isEmpty ? "You" : "You → \(cleanComp)"
                }
                if cleanComp.isEmpty || msg.senderName.localizedCaseInsensitiveContains(cleanComp) {
                    return msg.senderName
                }
                return "\(msg.senderName) · \(cleanComp)"
            }()

            HStack(alignment: .top, spacing: 10) {
                if isMe {
                    CachedAvatarImageView(
                        localPath: userAvatarPath,
                        size: 26,
                        isCompanyLogo: false,
                        fallbackInitials: userInitials,
                        accentFallback: true
                    )
                    .padding(.top, 2)
                } else {
                    CachedAvatarImageView(
                        localPath: threadAvatarPath,
                        remoteUrl: threadAvatarUrl,
                        slugHint: threadAvatarSlugHint,
                        size: 26,
                        isCompanyLogo: isCompanyContact,
                        fallbackInitials: senderInitials
                    )
                    .padding(.top, 2)
                }

                VStack(alignment: .leading, spacing: 6) {
                    HStack(alignment: .firstTextBaseline, spacing: 6) {
                        Text(senderDisplayName)
                            .font(.system(size: 12.5, weight: .semibold))
                            .foregroundColor(.primary)

                        if !msg.compactSenderHandle.isEmpty && !isMe && msg.senderHandle != msg.senderName {
                            Text(msg.compactSenderHandle)
                                .font(.system(size: 11))
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }

                        Spacer(minLength: 8)

                        if isQueuedMsg {
                            HStack(spacing: 4) {
                                Image(systemName: "clock.fill")
                                    .font(.system(size: 9.5, weight: .semibold))
                                Text("In Queue · \(estLabel)")
                                    .font(.system(size: 10.5, weight: .semibold))
                            }
                            .foregroundColor(.accentColor)
                            .padding(.horizontal, 8)
                            .padding(.vertical, 2)
                            .background(Capsule().fill(Color.accentColor.opacity(0.14)))
                        } else if isPendingMsg {
                            HStack(spacing: 4) {
                                Image(systemName: "clock.badge.exclamationmark")
                                    .font(.system(size: 9.5, weight: .semibold))
                                Text("Pending")
                                    .font(.system(size: 10.5, weight: .semibold))
                            }
                            .foregroundColor(.orange)
                            .padding(.horizontal, 8)
                            .padding(.vertical, 2)
                            .background(Capsule().fill(Color.orange.opacity(0.14)))
                        }

                        Text(msg.readableTimestamp)
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                    }

                    if !msg.subject.isEmpty && channel == "email" && msg.subject != threadSubject {
                        Text(msg.subject)
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.secondary)
                    }

                    let displayBody = msg.displayBody
                    Text(MessageTextProcessor.richMessageAttributedString(displayBody, cacheId: msg.id))
                        .font(.system(size: 12.5))
                        .lineSpacing(3)
                        .foregroundColor(.primary.opacity(0.94))
                        .tint(.accentColor)
                        .textSelection(.enabled)
                        .fixedSize(horizontal: false, vertical: true)

                    let actionLinks = MessageTextProcessor.extractActionableMessageLinks(displayBody, cacheId: msg.id)
                    if !actionLinks.isEmpty {
                        HStack(spacing: 8) {
                            ForEach(Array(actionLinks.prefix(3).enumerated()), id: \.offset) { _, linkItem in
                                let isFormLink = msg.senderRole.lowercased() != "you"
                                    && MessageTextProcessor.isFormSubmissionUrl(linkItem.url, jevClassification: jevClassification)
                                Button {
                                    if isFormLink {
                                        onOpenFormInBrowser(linkItem.url)
                                    } else if let u = URL(string: linkItem.url) {
                                        NSWorkspace.shared.open(u)
                                    }
                                } label: {
                                    HStack(spacing: 5) {
                                        Image(systemName: "link")
                                            .font(.system(size: 10, weight: .semibold))
                                        Text(linkItem.label)
                                            .font(.system(size: 11.5, weight: .semibold))
                                            .lineLimit(1)
                                        Image(systemName: "arrow.up.right")
                                            .font(.system(size: 9.5, weight: .bold))
                                    }
                                    .foregroundColor(.accentColor)
                                    .padding(.horizontal, 9)
                                    .padding(.vertical, 4)
                                    .background(RoundedRectangle(cornerRadius: 6).fill(Color.accentColor.opacity(0.12)))
                                    .overlay(RoundedRectangle(cornerRadius: 6).stroke(Color.accentColor.opacity(0.28), lineWidth: 1))
                                }
                                .buttonStyle(.plain)
                                .help(linkItem.url)
                                .contextMenu {
                                    if isFormLink {
                                        Button {
                                            onAutofillForm(linkItem.url)
                                        } label: {
                                            Label("Autofill & Submit Form", systemImage: "sparkles")
                                        }
                                    }
                                    Button {
                                        if let u = URL(string: linkItem.url) {
                                            NSWorkspace.shared.open(u)
                                        }
                                    } label: {
                                        Label("Open Link in Browser", systemImage: "safari")
                                    }
                                    Button {
                                        onCopyUrl(linkItem.url)
                                    } label: {
                                        Label("Copy Link Address", systemImage: "doc.on.doc")
                                    }
                                }

                                if isFormLink {
                                    Button {
                                        onAutofillForm(linkItem.url)
                                    } label: {
                                        HStack(spacing: 5) {
                                            if isAutofilling {
                                                ProgressView()
                                                    .controlSize(.mini)
                                            } else {
                                                Image(systemName: "sparkles")
                                                    .font(.system(size: 10.5, weight: .semibold))
                                            }
                                            Text(isAutofilling ? "Autofilling..." : "Autofill Form")
                                                .font(.system(size: 11.5, weight: .semibold))
                                                .lineLimit(1)
                                        }
                                        .foregroundColor(.white)
                                        .padding(.horizontal, 10)
                                        .padding(.vertical, 4)
                                        .background(RoundedRectangle(cornerRadius: 6).fill(Color.accentColor))
                                    }
                                    .buttonStyle(.plain)
                                    .disabled(isAutofilling)
                                    .help("Open this form in AutoApply Browser, autofill your Knowledge Base details & tailored Resume PDF, and submit.")
                                }
                            }
                        }
                        .padding(.top, 2)
                    }

                    if !msg.attachments.isEmpty {
                        HStack(spacing: 6) {
                            ForEach(msg.attachments, id: \.self) { att in
                                HStack(spacing: 4) {
                                    Image(systemName: "paperclip")
                                        .font(.system(size: 9.5, weight: .semibold))
                                    Text(att)
                                        .font(.system(size: 11, weight: .medium))
                                        .lineLimit(1)
                                }
                                .foregroundColor(.secondary)
                                .padding(.horizontal, 7)
                                .padding(.vertical, 2.5)
                                .background(RoundedRectangle(cornerRadius: 5).fill(Color.secondary.opacity(0.10)))
                            }
                        }
                        .padding(.top, 2)
                    }

                    if isQueuedMsg || isPendingMsg {
                        Divider()
                            .padding(.top, 2)

                        HStack(alignment: .center, spacing: 8) {
                            if isQueuedMsg {
                                Image(systemName: "clock")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.accentColor)
                                Text("In Queue · Scheduled to send \(estLabel)")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.secondary)
                                    .lineLimit(1)
                            } else {
                                Image(systemName: "exclamationmark.clock")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.orange)
                                Text("Pending — not sent yet")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.secondary)
                                    .lineLimit(1)
                            }

                            Spacer(minLength: 8)

                            Button(action: onBeginEditQueued) {
                                Label("Update", systemImage: "pencil")
                                    .font(.system(size: 11.5, weight: .semibold))
                                    .padding(.horizontal, 4)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                            .help("Edit the subject or body of this message before it is sent.")

                            Button(action: onSendQueuedNow) {
                                Label("Send Now", systemImage: "paperplane.fill")
                                    .font(.system(size: 11.5, weight: .semibold))
                                    .padding(.horizontal, 4)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.borderedProminent)
                            .tint(.accentColor)
                            .controlSize(.small)
                            .help("Send this message immediately.")

                            Button(action: onCancelQueued) {
                                Label("Cancel", systemImage: "xmark")
                                    .font(.system(size: 11.5, weight: .semibold))
                                    .padding(.horizontal, 4)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.small)
                            .help("Cancel sending and restore this message back to your draft composer.")
                        }
                        .padding(.top, 2)
                    }
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 9)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(
                            isMe
                                ? Color(NSColor.controlBackgroundColor).opacity(0.55)
                                : Color(NSColor.controlBackgroundColor)
                        )
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(
                            isQueuedMsg
                                ? Color.accentColor.opacity(0.32)
                                : (isPendingMsg
                                    ? Color.orange.opacity(0.35)
                                    : (isMe ? Color.secondary.opacity(0.14) : Color.secondary.opacity(0.20))),
                            lineWidth: 1
                        )
                )
            }
        }
    }

    @ViewBuilder
    private func chatMessageBubble(_ msg: OutreachChatMessageItem, thread: OutreachThreadItem) -> some View {
        let isEditingThisMsg = (msg.senderRole == "me") && (store.editingQueuedMessageId == msg.id)
        if isEditingThisMsg {
            let cleanComp = thread.company.trimmingCharacters(in: .whitespacesAndNewlines)
            let senderDisplayName = cleanComp.isEmpty ? "You" : "You → \(cleanComp)"
            HStack(alignment: .top, spacing: 10) {
                userMessageAvatarView(size: 26)
                    .padding(.top, 2)

                VStack(alignment: .leading, spacing: 8) {
                    HStack(alignment: .firstTextBaseline, spacing: 6) {
                        Text(senderDisplayName)
                            .font(.system(size: 12.5, weight: .semibold))
                            .foregroundColor(.primary)
                        Spacer(minLength: 8)
                        Text(msg.readableTimestamp)
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                    }

                    if thread.channel == "email" {
                        HStack(spacing: 6) {
                            Text("Subject:")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundColor(.secondary)
                            TextField("Subject", text: $store.editingQueuedMessageSubject)
                                .textFieldStyle(.plain)
                                .font(.system(size: 11.5, weight: .medium))
                                .foregroundColor(.primary)
                        }
                        .padding(.horizontal, 8)
                        .padding(.vertical, 5)
                        .background(RoundedRectangle(cornerRadius: 6).fill(Color(NSColor.textBackgroundColor)))
                        .overlay(RoundedRectangle(cornerRadius: 6).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
                    }

                    TextEditor(text: $store.editingQueuedMessageBody)
                        .font(.system(size: 12.5))
                        .frame(minHeight: 74, maxHeight: 140)
                        .padding(5)
                        .background(RoundedRectangle(cornerRadius: 6).fill(Color(NSColor.textBackgroundColor)))
                        .overlay(RoundedRectangle(cornerRadius: 6).stroke(Color.accentColor.opacity(0.35), lineWidth: 1))

                    HStack(spacing: 8) {
                        Button {
                            store.saveEditedQueuedMessage(msg, thread: thread)
                        } label: {
                            Label("Save Update", systemImage: "checkmark")
                                .font(.system(size: 11.5, weight: .semibold))
                                .padding(.horizontal, 4)
                        }
                        .buttonStyle(.borderedProminent)
                        .tint(.accentColor)
                        .controlSize(.small)
                        .disabled(store.editingQueuedMessageBody.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                        Button {
                            store.cancelEditingQueuedMessage()
                        } label: {
                            Text("Discard")
                                .font(.system(size: 11.5, weight: .medium))
                                .padding(.horizontal, 4)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.small)

                        Spacer()

                        Button {
                            store.cancelQueuedOrPendingMessage(msg, thread: thread)
                        } label: {
                            Label("Cancel Send", systemImage: "xmark.circle")
                                .font(.system(size: 11.5, weight: .medium))
                                .padding(.horizontal, 4)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.small)
                    }
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 9)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.controlBackgroundColor).opacity(0.55)))
                .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.accentColor.opacity(0.32), lineWidth: 1))
            }
        } else {
            let senderInitials: String = {
                if msg.senderName == thread.contactName {
                    return thread.avatarInitials
                }
                let src = thread.isCompanyContact ? (thread.company.isEmpty ? msg.senderName : thread.company) : msg.senderName
                let parts = src.split(separator: " ")
                if parts.count >= 2 {
                    return "\(parts[0].prefix(1))\(parts[1].prefix(1))".uppercased()
                }
                return String(src.prefix(2)).uppercased()
            }()
            OutreachMessageBubbleView(
                msg: msg,
                threadId: thread.id,
                company: thread.company,
                channel: thread.channel,
                threadSubject: thread.subject,
                jevClassification: thread.jevClassification,
                isCompanyContact: thread.isCompanyContact,
                threadAvatarPath: thread.avatarPath,
                threadAvatarUrl: thread.avatarUrl,
                threadAvatarSlugHint: thread.avatarSlugHint,
                senderInitials: senderInitials,
                userAvatarPath: effectiveProfileThumbPath,
                userInitials: userFallbackInitials,
                isAutofilling: store.autofillingThreadId == thread.id,
                onOpenFormInBrowser: { url in
                    store.sendAction("launch_browser_session", payload: [
                        "target": "ats_ephemeral",
                        "url": url,
                        "company": thread.company,
                    ])
                },
                onAutofillForm: { url in
                    store.autofillAndSubmitThreadForm(thread, formUrl: url)
                },
                onCopyUrl: { url in
                    store.copyToClipboard(url, label: "link URL")
                },
                onBeginEditQueued: {
                    store.beginEditingQueuedMessage(msg, thread: thread)
                },
                onSendQueuedNow: {
                    store.sendQueuedOrPendingMessageNow(msg, thread: thread)
                },
                onCancelQueued: {
                    store.cancelQueuedOrPendingMessage(msg, thread: thread)
                }
            )
            .equatable()
        }
    }

    // MARK: - 4. Compact, Auto-Expanding Docked Message Composer

    private func composerDynamicHeight(for text: String) -> CGFloat {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return 52 }
        let explicitLines = text.components(separatedBy: "\n").count
        let wrappedLines = max(1, Int(ceil(Double(text.count) / 72.0)))
        let totalLines = max(explicitLines, wrappedLines)
        let computed = CGFloat(totalLines) * 19.0 + 18.0
        return min(max(computed, 52), 135)
    }

    private func followUpComposerCard(_ thread: OutreachThreadItem) -> some View {
        let isEmptyDraft = store.threadComposerText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let editorHeight = composerDynamicHeight(for: store.threadComposerText)
        let isDrafting = store.draftingFollowUpThreadId == thread.id
        let hasGeneratedDraft = !isEmptyDraft && (
            store.aiGeneratedDraftThreadIds.contains(thread.id)
                || !thread.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        )

        return VStack(alignment: .leading, spacing: 8) {
            if thread.channel == "email" {
                HStack(spacing: 6) {
                    Text("Subject:")
                        .font(.system(size: 11, weight: .medium))
                        .foregroundColor(.secondary)
                    TextField("Re: \(thread.subject)", text: $store.threadComposerSubject)
                        .textFieldStyle(.plain)
                        .font(.system(size: 11.5, weight: .medium))
                        .foregroundColor(.primary)
                        .onChange(of: store.threadComposerSubject) { newSubj in
                            if !store.isClearingComposerProgrammatically {
                                store.localThreadDraftSubjectById[thread.id] = newSubj
                            }
                        }
                }
                .padding(.horizontal, 10)
                .padding(.vertical, 5)
                .background(RoundedRectangle(cornerRadius: 6).fill(Color(NSColor.textBackgroundColor)))
                .overlay(RoundedRectangle(cornerRadius: 6).stroke(Color.secondary.opacity(0.14), lineWidth: 1))
            }

            ZStack(alignment: .topLeading) {
                TextEditor(text: $store.threadComposerText)
                    .font(.system(size: 12.5))
                    .frame(height: editorHeight)
                    .padding(5)
                    .opacity(isDrafting ? 0.52 : 1.0)
                    .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 7).stroke(isDrafting ? Color.accentColor.opacity(0.42) : Color.secondary.opacity(0.18), lineWidth: 1))
                    .onChange(of: store.threadComposerText) { newText in
                        store.localThreadDraftTextById[thread.id] = newText
                        if newText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            store.aiGeneratedDraftThreadIds.remove(thread.id)
                            if !store.isClearingComposerProgrammatically && !thread.draftText.isEmpty {
                                store.sendActionInBackground(
                                    "clear_thread_draft",
                                    payload: [
                                        "thread_id": thread.id,
                                        "company": thread.company,
                                        "contact_name": thread.contactName,
                                        "channel": thread.channel,
                                    ],
                                    silent: true,
                                    preserveLocalEdits: true
                                )
                            }
                        }
                    }

                if isEmptyDraft && !isDrafting {
                    Text("Reply to \(thread.contactName) (\(thread.company))…")
                        .font(.system(size: 12.5))
                        .foregroundColor(.secondary.opacity(0.65))
                        .padding(.horizontal, 10)
                        .padding(.top, 5)
                        .allowsHitTesting(false)
                }

                if isDrafting {
                    HStack {
                        Spacer(minLength: 0)
                        GeneratingProgressLabel(
                            title: hasGeneratedDraft ? "Regenerating draft" : "Generating draft",
                            fontSize: 12,
                            fontWeight: .semibold,
                            dotColor: .accentColor
                        )
                        .padding(.horizontal, 11)
                        .padding(.vertical, 5)
                        .background(
                            Capsule()
                                .fill(Color(NSColor.controlBackgroundColor).opacity(0.95))
                        )
                        .overlay(
                            Capsule()
                                .stroke(Color.accentColor.opacity(0.32), lineWidth: 1)
                        )
                        Spacer(minLength: 0)
                    }
                    .frame(height: editorHeight)
                    .allowsHitTesting(false)
                }
            }

            HStack(spacing: 8) {
                // Secondary Action: AI Draft Follow-Up -> becomes Regenerate once an AI draft is present
                Button {
                    store.draftFollowUpForSelectedThread()
                } label: {
                    Group {
                        if isDrafting {
                            GeneratingProgressLabel(
                                title: hasGeneratedDraft ? "Regenerating" : "Generating",
                                fontSize: 13,
                                fontWeight: .semibold
                            )
                        } else if hasGeneratedDraft {
                            Label("Regenerate", systemImage: "arrow.clockwise")
                                .font(.system(size: 13, weight: .semibold))
                        } else {
                            Label("AI Draft Follow-Up", systemImage: "sparkles")
                                .font(.system(size: 13, weight: .semibold))
                        }
                    }
                    .padding(.horizontal, 6)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(isDrafting)
                .help(
                    hasGeneratedDraft
                        ? "Regenerate a fresh AI follow-up draft with new phrasing grounded in your Knowledge Base."
                        : "Generate a JEV-verified follow-up message draft grounded in your Knowledge Base & VB Jobs canon."
                )

                if !isEmptyDraft {
                    Button {
                        store.clearSelectedThreadDraft()
                    } label: {
                        Label("Clear", systemImage: "xmark")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .help("Clear the current message draft from the composer.")
                }

                Spacer(minLength: 8)

                // Secondary Action: Queue to Send
                Button {
                    store.sendOrQueueSelectedThreadMessage(mode: "queue")
                } label: {
                    Label("Queue to Send", systemImage: "clock")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(isEmptyDraft)
                .help("Queue this follow-up message to be sent automatically in the next outreach batch.")

                // Primary Action: Send Follow-Up
                Button {
                    store.sendOrQueueSelectedThreadMessage(mode: "send_now")
                } label: {
                    Label("Send Follow-Up", systemImage: "paperplane.fill")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .tint(.accentColor)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(isEmptyDraft)
                .help("Send this follow-up message immediately.")
            }
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 10)
        .background(Color(NSColor.controlBackgroundColor).opacity(0.35))
    }

    // MARK: - Formatting Helpers

    private func formatCompactTimestamp(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 10 else { return trimmed }
        let datePart = String(trimmed.prefix(10))
        let parts = datePart.split(separator: "-")
        guard parts.count == 3, let monthInt = Int(parts[1]), let dayInt = Int(parts[2]) else {
            return datePart
        }
        let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        guard monthInt >= 1 && monthInt <= 12 else { return datePart }
        return "\(months[monthInt - 1]) \(dayInt)"
    }

    private func formatReadableTimestamp(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 10 else { return trimmed }
        let shortDate = formatCompactTimestamp(trimmed)
        if trimmed.count >= 16 {
            let timePart = String(trimmed.dropFirst(11).prefix(5))
            return "\(shortDate), \(timePart)"
        }
        return shortDate
    }

    private func formatCompactHandle(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.hasPrefix("https://www.linkedin.com/") {
            return trimmed.replacingOccurrences(of: "https://www.", with: "")
        }
        if trimmed.hasPrefix("https://") {
            return trimmed.replacingOccurrences(of: "https://", with: "")
        }
        return trimmed
    }

    private func cleanStatusLabel(for thread: OutreachThreadItem) -> String {
        if thread.deliveryState == "queued" { return "Queued" }
        if thread.deliveryState == "invite_pending" { return "Invite Sent" }
        if thread.messages.contains(where: { $0.senderRole == "them" }) { return "Replied" }
        return "Sent"
    }

    private func cleanJevBannerText(_ raw: String) -> String {
        return raw
            .replacingOccurrences(of: "JEV (~typesafe/jev-latest): ", with: "")
            .replacingOccurrences(of: "JEV: ", with: "")
    }

    // MARK: - 5. Blocked Email Addresses View (Compact, Human-Friendly with Expandable Diagnostics)

    private func humanFriendlyBlockedReason(_ item: SuppressedEmailItem) -> String {
        let combined = "\(item.reason) \(item.diagnostic)".lowercased()
        if combined.contains("recipnotfound") || combined.contains("not found") || combined.contains("user unknown") || combined.contains("no such user") {
            return "Recipient address does not exist"
        }
        if combined.contains("rejected") || combined.contains("policy") {
            return "Rejected by recipient mail server"
        }
        if combined.contains("domain") || combined.contains("nxdomain") {
            return "Recipient mail domain unavailable"
        }
        return "Permanent delivery failure — automatic sending paused"
    }

    private var blockedAddressesWorkspaceView: some View {
        let q = store.outreachSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let filtered = store.suppressedEmails.filter {
            q.isEmpty
                || $0.email.lowercased().contains(q)
                || $0.company.lowercased().contains(q)
                || $0.reason.lowercased().contains(q)
                || $0.diagnostic.lowercased().contains(q)
        }

        return ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                // Header & Search Bar
                HStack(alignment: .center, spacing: 12) {
                    VStack(alignment: .leading, spacing: 2) {
                        HStack(spacing: 7) {
                            Text("Blocked Email Addresses")
                                .font(.system(size: 14, weight: .semibold))
                                .foregroundColor(.primary)
                            Text("\(filtered.count)")
                                .font(.system(size: 11, weight: .semibold, design: .rounded))
                                .foregroundColor(.secondary)
                                .padding(.horizontal, 6)
                                .padding(.vertical, 1)
                                .background(Capsule().fill(Color.secondary.opacity(0.12)))
                        }
                        Text("Addresses that returned a permanent delivery failure are automatically paused so AutoApply never retries an invalid recipient.")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                    }

                    Spacer(minLength: 12)

                    // Search Blocked Addresses
                    HStack(spacing: 6) {
                        Image(systemName: "magnifyingglass")
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.secondary)
                        TextField("Filter by company or email…", text: $store.outreachSearchQuery)
                            .textFieldStyle(.plain)
                            .font(.system(size: 12))
                        if !store.outreachSearchQuery.isEmpty {
                            Button {
                                store.outreachSearchQuery = ""
                            } label: {
                                Image(systemName: "xmark.circle.fill")
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 6)
                    .frame(width: 240)
                    .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.controlBackgroundColor)))
                    .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
                }

                // Compact Blocked Address List Container
                VStack(alignment: .leading, spacing: 0) {
                    if filtered.isEmpty {
                        HStack(spacing: 8) {
                            Image(systemName: "checkmark.circle")
                                .font(.system(size: 12.5))
                                .foregroundColor(.secondary)
                            Text(q.isEmpty ? "No blocked email addresses recorded." : "No blocked addresses match \"\(store.outreachSearchQuery)\".")
                                .font(.system(size: 12))
                                .foregroundColor(.secondary)
                            Spacer()
                        }
                        .padding(14)
                    } else {
                        ForEach(Array(filtered.enumerated()), id: \.element.id) { idx, item in
                            let isExpanded = store.expandedBlockedEmailIds.contains(item.id)
                            VStack(alignment: .leading, spacing: 0) {
                                HStack(alignment: .center, spacing: 10) {
                                    if !item.company.isEmpty {
                                        HStack(spacing: 4) {
                                            Image(systemName: "building.2.fill")
                                                .font(.system(size: 10, weight: .semibold))
                                                .foregroundColor(.accentColor)
                                            Text(item.company)
                                                .font(.system(size: 12, weight: .semibold))
                                                .foregroundColor(.primary)
                                                .lineLimit(1)
                                        }
                                        .padding(.horizontal, 7)
                                        .padding(.vertical, 2.5)
                                        .background(
                                            RoundedRectangle(cornerRadius: 5)
                                                .fill(Color.accentColor.opacity(0.10))
                                        )
                                        .overlay(
                                            RoundedRectangle(cornerRadius: 5)
                                                .stroke(Color.accentColor.opacity(0.22), lineWidth: 0.8)
                                        )
                                        .fixedSize(horizontal: true, vertical: false)
                                    }

                                    Text(item.email)
                                        .font(.system(size: 12.5, weight: .semibold, design: .monospaced))
                                        .foregroundColor(.primary)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)

                                    Text("·")
                                        .foregroundColor(.secondary.opacity(0.6))

                                    Text(humanFriendlyBlockedReason(item))
                                        .font(.system(size: 11.5))
                                        .foregroundColor(.secondary)
                                        .lineLimit(1)

                                    Spacer(minLength: 8)

                                    Button {
                                        store.copyToClipboard(item.email, label: "email address")
                                    } label: {
                                        Image(systemName: "doc.on.doc")
                                            .font(.system(size: 12, weight: .medium))
                                            .foregroundColor(.secondary)
                                            .frame(width: 28, height: 28)
                                            .background(RoundedRectangle(cornerRadius: 6).fill(Color.secondary.opacity(0.08)))
                                            .contentShape(Rectangle())
                                    }
                                    .buttonStyle(.plain)
                                    .help("Copy the blocked email address (\(item.email)) to your clipboard.")

                                    Button {
                                        withAnimation(.easeInOut(duration: 0.12)) {
                                            if isExpanded {
                                                store.expandedBlockedEmailIds.remove(item.id)
                                            } else {
                                                store.expandedBlockedEmailIds.insert(item.id)
                                            }
                                        }
                                    } label: {
                                        Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                                            .font(.system(size: 11, weight: .semibold))
                                            .foregroundColor(.secondary)
                                            .frame(width: 28, height: 28)
                                            .background(RoundedRectangle(cornerRadius: 6).fill(Color.secondary.opacity(0.08)))
                                            .contentShape(Rectangle())
                                    }
                                    .buttonStyle(.plain)
                                    .help("Show or hide the SMTP bounce diagnostic details for \(item.email).")
                                }
                                .padding(.horizontal, 12)
                                .padding(.vertical, 7)

                                if isExpanded {
                                    HStack(spacing: 12) {
                                        Text("SMTP \(item.statusCode)")
                                            .font(.system(size: 10.5, weight: .semibold, design: .monospaced))
                                            .foregroundColor(.secondary)
                                            .padding(.horizontal, 6)
                                            .padding(.vertical, 1.5)
                                            .background(RoundedRectangle(cornerRadius: 4).fill(Color.secondary.opacity(0.12)))

                                        Text("\(item.reason) — \(item.diagnostic)")
                                            .font(.system(size: 11, design: .monospaced))
                                            .foregroundColor(.secondary)
                                            .textSelection(.enabled)
                                            .lineLimit(2)

                                        Spacer()
                                    }
                                    .padding(.horizontal, 28)
                                    .padding(.bottom, 8)
                                }

                                if idx < filtered.count - 1 {
                                    Divider()
                                        .padding(.leading, 28)
                                        .opacity(0.35)
                                }
                            }
                        }
                    }
                }
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color(NSColor.controlBackgroundColor).opacity(0.45))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(Color.secondary.opacity(0.14), lineWidth: 1)
                )
            }
            .padding(20)
        }
    }
}

// MARK: - 4. Rethought Resumes Studio View

struct GeneratingDotsView: View {
    var dotSize: CGFloat = 4.5
    var color: Color = .primary

    var body: some View {
        TimelineView(.periodic(from: .now, by: 0.28)) { context in
            let phase = Int(floor(context.date.timeIntervalSinceReferenceDate / 0.28)) % 3
            HStack(spacing: 3.5) {
                ForEach(0..<3, id: \.self) { idx in
                    Circle()
                        .fill(color.opacity(phase == idx ? 1.0 : 0.28))
                        .frame(width: dotSize, height: dotSize)
                        .scaleEffect(phase == idx ? 1.18 : 0.88)
                        .animation(.easeInOut(duration: 0.22), value: phase)
                }
            }
        }
    }
}

struct GeneratingProgressLabel: View {
    let title: String
    var fontSize: CGFloat = 13
    var fontWeight: Font.Weight = .semibold
    var dotColor: Color = .primary

    var body: some View {
        HStack(spacing: 6) {
            ProgressView()
                .controlSize(.small)
                .scaleEffect(0.82)
            Text(title)
                .font(.system(size: fontSize, weight: fontWeight))
                .lineLimit(1)
            GeneratingDotsView(dotSize: 4.5, color: dotColor)
        }
    }
}

struct EllipsisActionMenuButton<MenuItems: View>: View {
    var helpText: String = "More actions"
    @ViewBuilder let menuItems: () -> MenuItems

    var body: some View {
        Menu {
            menuItems()
        } label: {
            Image(systemName: "ellipsis")
                .font(.system(size: 13.5, weight: .bold))
                .foregroundColor(.primary)
                .frame(width: 34, height: 32)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(Color.secondary.opacity(0.28), lineWidth: 1)
                )
                .contentShape(Rectangle())
        }
        .menuStyle(.borderlessButton)
        .menuIndicator(.hidden)
        .fixedSize()
        .help(helpText)
    }
}

struct ResumesStudioView: View {
    @ObservedObject var store: WorkspaceStore

    private var styleAutoSaveSignature: String {
        "\(store.resumeFontChoice)::\(store.resumePageTarget)::\(store.includePhotoOnResume)::\(store.documentMode)"
    }

    private var filteredDocuments: [DocumentArtifactItem] {
        let q = store.myResumesSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return store.documents }
        return store.documents.filter { doc in
            doc.jobLabel.lowercased().contains(q)
                || doc.roleTitle.lowercased().contains(q)
                || doc.companyName.lowercased().contains(q)
                || doc.createdAt.lowercased().contains(q)
        }
    }

    private func parsedRoleAndCompany(for doc: DocumentArtifactItem) -> (role: String, company: String) {
        let r = doc.roleTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        let c = doc.companyName.trimmingCharacters(in: .whitespacesAndNewlines)
        if !r.isEmpty && !c.isEmpty {
            return (r, c)
        }
        let parts = doc.jobLabel.components(separatedBy: " — ")
        if parts.count >= 2 {
            return (
                parts[0].trimmingCharacters(in: .whitespacesAndNewlines),
                parts.dropFirst().joined(separator: " — ").trimmingCharacters(in: .whitespacesAndNewlines)
            )
        }
        return (doc.jobLabel, c)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Sticky Top Navigation Bar: Master Resume | My Resumes | Generate Resume
            resumesTopSubtabBar
                .padding(.horizontal, 16)
                .padding(.vertical, 10)
                .background(Color(NSColor.windowBackgroundColor))

            Divider()

            // Main Tab Content
            if store.resumesSubtab == "master_resume" {
                ScrollView {
                    masterResumeSubtabView
                        .padding(18)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if store.resumesSubtab == "generate_resume" {
                ScrollView {
                    generateResumeSubtabView
                        .padding(18)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                myResumesSubtabView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .background(Color(NSColor.windowBackgroundColor))
        .onAppear {
            if let doc = store.selectedDocument {
                if store.resumeEditorText.isEmpty {
                    store.resumeEditorText = doc.resumeMarkdown
                }
                if store.coverLetterEditorText.isEmpty {
                    store.coverLetterEditorText = doc.coverLetterMarkdown
                }
                if store.isDocumentSubmitted(doc) {
                    store.resumeShowEditor = false
                    store.resumeShowPreview = true
                }
            }
        }
        .onDisappear {
            store.autoSaveCurrentEditedDocument(silent: true)
            store.resumeShowEditor = false
            store.resumeShowPreview = true
        }
    }

    // MARK: - Top Navigation Bar

    private var resumesTopSubtabBar: some View {
        HStack(spacing: 12) {
            HStack(spacing: 2) {
                resumeSubtabButton(
                    id: "master_resume",
                    title: "Master Resume",
                    icon: "doc.richtext",
                    badgeCount: store.resumes.count
                )
                resumeSubtabButton(
                    id: "generated",
                    title: "My Resumes",
                    icon: "doc.on.doc",
                    badgeCount: store.documents.count
                )
                resumeSubtabButton(
                    id: "generate_resume",
                    title: "Generate Resume",
                    icon: "sparkles",
                    badgeCount: 0
                )
            }
            .padding(3)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(Color.secondary.opacity(0.18), lineWidth: 1)
            )

            Spacer()

            if store.isGeneratingTailoredDocument {
                GeneratingProgressLabel(
                    title: "Generating tailored package",
                    fontSize: 12,
                    fontWeight: .semibold,
                    dotColor: .accentColor
                )
                .padding(.horizontal, 10)
                .padding(.vertical, 5)
                .background(
                    Capsule()
                        .fill(Color.accentColor.opacity(0.10))
                )
                .overlay(
                    Capsule()
                        .stroke(Color.accentColor.opacity(0.28), lineWidth: 1)
                )
            }

            if store.resumesSubtab == "master_resume" {
                Button {
                    store.chooseResumeFileWithOpenPanel()
                } label: {
                    Label("Upload Base Resume…", systemImage: "arrow.up.doc")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .tint(.accentColor)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
            }
        }
    }

    private func resumeSubtabButton(
        id: String,
        title: String,
        icon: String,
        badgeCount: Int
    ) -> some View {
        let isSelected = store.resumesSubtab == id
        return Button {
            withAnimation(.easeInOut(duration: 0.15)) {
                if id == "generated" {
                    if !store.selectedDocumentId.isEmpty {
                        store.autoSaveCurrentEditedDocument(silent: true)
                    }
                    store.selectedDocumentId = ""
                }
                store.resumesSubtab = id
            }
        } label: {
            HStack(spacing: 6) {
                Image(systemName: icon)
                    .font(.system(size: 11.5, weight: .semibold))
                    .foregroundColor(isSelected ? .white : .secondary)
                Text(title)
                    .font(.system(size: 12.5, weight: isSelected ? .semibold : .medium))
                    .foregroundColor(isSelected ? .white : .primary)
                    .lineLimit(1)
                if badgeCount > 0 {
                    Text("\(badgeCount)")
                        .font(.system(size: 10.5, weight: .semibold, design: .rounded))
                        .foregroundColor(isSelected ? .white.opacity(0.92) : .secondary)
                        .padding(.horizontal, 5)
                        .padding(.vertical, 1)
                        .background(
                            Capsule()
                                .fill(isSelected ? Color.white.opacity(0.20) : Color.secondary.opacity(0.12))
                        )
                }
            }
            .padding(.horizontal, 11)
            .padding(.vertical, 5)
            .background(
                RoundedRectangle(cornerRadius: 7)
                    .fill(isSelected ? Color.accentColor : Color.clear)
            )
            .contentShape(Rectangle())
            .fixedSize(horizontal: true, vertical: false)
        }
        .buttonStyle(.plain)
        .fixedSize(horizontal: true, vertical: false)
    }

