    private var myResumesSubtabView: some View {
        Group {
            if store.documents.isEmpty {
                VStack(spacing: 12) {
                    Image(systemName: "doc.on.doc")
                        .font(.system(size: 28))
                        .foregroundColor(.secondary.opacity(0.6))
                    Text("No generated resumes yet")
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundColor(.primary)
                    Text("Create a tailored resume and cover letter from a job URL or role description.")
                        .font(.system(size: 12))
                        .foregroundColor(.secondary)
                    Button {
                        store.resumesSubtab = "generate_resume"
                    } label: {
                        Label("Generate Resume", systemImage: "sparkles")
                            .font(.system(size: 13, weight: .bold))
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.accentColor)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                HSplitView {
                    // Left Panel: Independently Scrollable Resume List
                    myResumesListPanel
                        .frame(minWidth: 265, idealWidth: 305, maxWidth: 390, maxHeight: .infinity)

                    // Right Panel: Sticky Toolbar + Independently Scrollable Document Preview / Editor
                    if let doc = store.selectedDocument,
                       filteredDocuments.contains(where: { $0.id == doc.id }) {
                        myResumeDetailPanel(for: doc)
                            .frame(minWidth: 480, maxWidth: .infinity, maxHeight: .infinity)
                    } else {
                        OutlookStyleEmptySelectionView(
                            kind: .resume,
                            title: "No Resume Selected",
                            subtitle: "Select a resume to read."
                        )
                        .frame(minWidth: 480, maxWidth: .infinity, maxHeight: .infinity)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
    }

    private var myResumesListPanel: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Sticky List Header & Search Filter
            VStack(alignment: .leading, spacing: 8) {
                HStack(spacing: 6) {
                    Text("GENERATED RESUMES")
                        .font(.system(size: 10.5, weight: .semibold))
                        .foregroundColor(.secondary)
                        .tracking(0.4)
                    Text("\(filteredDocuments.count)")
                        .font(.system(size: 10, weight: .medium, design: .monospaced))
                        .foregroundColor(.secondary)
                        .padding(.horizontal, 5)
                        .padding(.vertical, 1)
                        .background(Capsule().fill(Color.secondary.opacity(0.14)))
                    Spacer()
                }

                HStack(spacing: 6) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 11))
                        .foregroundColor(.secondary)
                    TextField("Filter by role or company…", text: $store.myResumesSearchQuery)
                        .textFieldStyle(.plain)
                        .font(.system(size: 12))
                    if !store.myResumesSearchQuery.isEmpty {
                        Button {
                            store.myResumesSearchQuery = ""
                        } label: {
                            Image(systemName: "xmark.circle.fill")
                                .font(.system(size: 11))
                                .foregroundColor(.secondary)
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 8)
                .padding(.vertical, 5)
                .background(
                    RoundedRectangle(cornerRadius: 6)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 6)
                        .stroke(Color.secondary.opacity(0.18), lineWidth: 1)
                )
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 10)

            Divider()

            // Independently Scrollable Resume Cards
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 3) {
                    ForEach(filteredDocuments) { doc in
                        myResumeListRow(doc)
                    }
                }
                .padding(.horizontal, 8)
                .padding(.vertical, 8)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .background(Color(NSColor.windowBackgroundColor))
    }

    private func resumeSubmissionStatusPill(isSubmitted: Bool, compact: Bool = false) -> some View {
        HStack(spacing: compact ? 4 : 5) {
            if isSubmitted {
                Image(systemName: "checkmark")
                    .font(.system(size: compact ? 8.5 : 9.5, weight: .bold))
                    .foregroundColor(.green)
                Text("Submitted")
                    .font(.system(size: compact ? 10 : 11, weight: .semibold))
                    .foregroundColor(.green)
            } else {
                Text("Draft")
                    .font(.system(size: compact ? 10 : 11, weight: .medium))
                    .foregroundColor(.secondary)
            }
        }
        .padding(.horizontal, compact ? 7 : 8.5)
        .padding(.vertical, compact ? 2.5 : 3.5)
        .background(
            Capsule()
                .fill(isSubmitted ? Color.green.opacity(0.14) : Color.secondary.opacity(0.12))
        )
        .overlay(
            Capsule()
                .stroke(
                    isSubmitted ? Color.green.opacity(0.28) : Color.secondary.opacity(0.2),
                    lineWidth: 0.75
                )
        )
        .fixedSize(horizontal: true, vertical: false)
    }

    private func myResumeListRow(_ doc: DocumentArtifactItem) -> some View {
        let isSelected = store.selectedDocument?.id == doc.id
        let docLocked = store.isDocumentSubmitted(doc)
        let parsed = parsedRoleAndCompany(for: doc)

        return Button {
            store.selectDocument(doc.id)
        } label: {
            HStack(alignment: .top, spacing: 10) {
                Image(systemName: "doc.richtext.fill")
                    .font(.system(size: 13.5, weight: .semibold))
                    .foregroundColor(isSelected ? .accentColor : .secondary)
                    .padding(.top, 2)

                VStack(alignment: .leading, spacing: 3) {
                    // Line 1: Role Title + Single Elegant Status Pill (Submitted or Draft)
                    HStack(alignment: .top, spacing: 6) {
                        Text(parsed.role)
                            .font(.system(size: 13, weight: isSelected ? .bold : .semibold))
                            .foregroundColor(.primary)
                            .lineLimit(2)
                            .fixedSize(horizontal: false, vertical: true)

                        Spacer(minLength: 4)

                        resumeSubmissionStatusPill(isSubmitted: docLocked, compact: true)
                    }

                    // Line 2: Company Name
                    if !parsed.company.isEmpty {
                        Text(parsed.company)
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                    }

                    // Line 3: Creation Date & Page Count
                    HStack(spacing: 5) {
                        Text(doc.createdAt)
                            .font(.system(size: 10.5))
                            .foregroundColor(.secondary.opacity(0.8))
                            .lineLimit(1)
                        Text("•")
                            .font(.system(size: 9))
                            .foregroundColor(.secondary.opacity(0.5))
                        Text("\(doc.estimatedPages)p")
                            .font(.system(size: 10.5))
                            .foregroundColor(.secondary.opacity(0.8))
                        if !doc.coverLetterMarkdown.isEmpty {
                            Text("•")
                                .font(.system(size: 9))
                                .foregroundColor(.secondary.opacity(0.5))
                            Text("Cover Letter")
                                .font(.system(size: 10.5))
                                .foregroundColor(.secondary.opacity(0.8))
                        }
                    }
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 9)
            .background(
                RoundedRectangle(cornerRadius: 9)
                    .fill(isSelected ? Color.accentColor.opacity(0.14) : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 9)
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.18), lineWidth: isSelected ? 1.5 : 1)
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .contextMenu {
            myResumeRowContextMenuItems(doc)
        }
    }

    @ViewBuilder
    private func myResumeRowContextMenuItems(_ doc: DocumentArtifactItem) -> some View {
        let isSubmittedLocked = store.isDocumentSubmitted(doc)

        if isSubmittedLocked {
            Button {
                store.setDocumentSubmittedStatus(doc, isSubmitted: false)
            } label: {
                Label("Mark as Draft", systemImage: "arrow.uturn.backward.circle")
            }
        } else {
            Button {
                store.submitResumePackage(doc)
            } label: {
                Label("Submit Package", systemImage: "paperplane.fill")
            }
            .disabled(!store.submittingDocumentId.isEmpty)

            Button {
                store.setDocumentSubmittedStatus(doc, isSubmitted: true)
            } label: {
                Label("Mark as Submitted", systemImage: "checkmark.circle")
            }
        }

        Divider()

        Button {
            store.selectDocument(doc.id)
            let pdfToOpen = (store.resumePreviewTab == .coverLetter && !doc.coverLetterPdfPath.isEmpty) ? doc.coverLetterPdfPath : doc.pdfPath
            store.openFileOnMac(pdfToOpen)
        } label: {
            Label("Open PDF", systemImage: "doc.richtext")
        }

        Button {
            store.selectDocument(doc.id)
            let docxToOpen = (store.resumePreviewTab == .coverLetter && !doc.coverLetterDocxPath.isEmpty) ? doc.coverLetterDocxPath : doc.docxPath
            store.openFileOnMac(docxToOpen)
        } label: {
            Label("Open DOCX", systemImage: "doc.text")
        }

        Button {
            store.selectDocument(doc.id)
            let pdfToReveal = (store.resumePreviewTab == .coverLetter && !doc.coverLetterPdfPath.isEmpty) ? doc.coverLetterPdfPath : doc.pdfPath
            store.openFileOnMac(pdfToReveal, revealInFinder: true)
        } label: {
            Label("Show in Finder", systemImage: "folder")
        }

        if !doc.jobId.isEmpty {
            Divider()
            Button {
                store.generateTailoredDocument(payload: ["job_id": doc.jobId])
            } label: {
                Label("Regenerate Package", systemImage: "arrow.clockwise")
            }
            .disabled(store.isGeneratingTailoredDocument)
        }

        Divider()

        Button(role: .destructive) {
            store.deleteGeneratedDocument(doc)
        } label: {
            Label("Remove Resume from List", systemImage: "trash")
        }
    }

    private func myResumeDetailPanel(for doc: DocumentArtifactItem) -> some View {
        let isSubmittedLocked = store.isDocumentSubmitted(doc)
        let parsed = parsedRoleAndCompany(for: doc)
        let isEditOnly = store.resumeShowEditor && !store.resumeShowPreview
        let isSplitMode = store.resumeShowEditor && store.resumeShowPreview

        return VStack(alignment: .leading, spacing: 0) {
            // Sticky Document Header & Action Toolbar (Full-Width Position Title + Company & Action Controls — Never Clipped)
            VStack(alignment: .leading, spacing: 10) {
                VStack(alignment: .leading, spacing: 4) {
                    Text(parsed.role)
                        .font(.system(size: 16.5, weight: .bold))
                        .foregroundColor(.primary)
                        .lineLimit(2)
                        .fixedSize(horizontal: false, vertical: true)

                    HStack(alignment: .firstTextBaseline, spacing: 6) {
                        if !parsed.company.isEmpty {
                            Text(parsed.company)
                                .font(.system(size: 13.5, weight: .semibold))
                                .foregroundColor(.primary.opacity(0.88))
                                .lineLimit(1)
                                .layoutPriority(2)

                            Text("•")
                                .font(.system(size: 11))
                                .foregroundColor(.secondary.opacity(0.6))
                        }

                        Text("Created \(doc.createdAt)  •  \(doc.estimatedPages) \(doc.estimatedPages == 1 ? "page" : "pages")  •")
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                            .layoutPriority(1)

                        HStack(spacing: 4) {
                            if isSubmittedLocked {
                                Image(systemName: "checkmark.circle.fill")
                                    .font(.system(size: 10.5, weight: .semibold))
                                    .foregroundColor(.green)
                                Text("Submitted")
                                    .font(.system(size: 12, weight: .semibold))
                                    .foregroundColor(.green)
                            } else {
                                Text("Draft")
                                    .font(.system(size: 12, weight: .medium))
                                    .foregroundColor(.secondary)
                            }
                        }
                        .fixedSize(horizontal: true, vertical: false)
                        .help(
                            isSubmittedLocked
                                ? "Submitted application (read-only). Use the ⋯ menu or right-click to revert to Draft if needed."
                                : "Draft resume. Use the ⋯ menu or right-click to mark as Submitted."
                        )

                        Spacer(minLength: 0)
                    }
                }

                // Row 2: Document Type Chips (Tailored Resume | Cover Letter) + Joined [ ✎ | 👁 ] Toggle + ⋯ Menu
                HStack(alignment: .center, spacing: 10) {
                    ForEach(ResumePreviewTab.allCases) { tab in
                        SelectableChip(
                            title: tab.rawValue,
                            icon: tab.icon,
                            isSelected: store.resumePreviewTab == tab
                        ) {
                            store.autoSaveCurrentEditedDocument(silent: true)
                            store.resumePreviewTab = tab
                        }
                        .fixedSize(horizontal: true, vertical: false)
                    }

                    Spacer(minLength: 8)

                    if !isSubmittedLocked {
                        // Joined 2-button icon toggle matching Knowledge Base: [ ✎ | 👁 ] (cycles: View -> Edit -> View+Edit -> View)
                        HStack(spacing: 0) {
                            Button {
                                store.autoSaveCurrentEditedDocument(silent: true)
                                store.cycleResumeViewEditMode()
                            } label: {
                                Image(systemName: "pencil")
                                    .font(.system(size: 12.5, weight: .semibold))
                                    .foregroundColor(store.resumeShowEditor ? .accentColor : .secondary)
                                    .frame(width: 34, height: 32)
                                    .background(store.resumeShowEditor ? Color.accentColor.opacity(0.16) : Color.clear)
                                    .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .help("Cycle between Preview, Edit, and Split view to edit the Markdown source of this document.")

                            Rectangle()
                                .fill(Color.secondary.opacity(0.25))
                                .frame(width: 1, height: 20)

                            Button {
                                store.autoSaveCurrentEditedDocument(silent: true)
                                store.cycleResumeViewEditMode()
                            } label: {
                                Image(systemName: "eye.fill")
                                    .font(.system(size: 12.5, weight: .semibold))
                                    .foregroundColor(store.resumeShowPreview ? .accentColor : .secondary)
                                    .frame(width: 34, height: 32)
                                    .background(store.resumeShowPreview ? Color.accentColor.opacity(0.16) : Color.clear)
                                    .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .help("Cycle between Preview, Edit, and Split view to preview the formatted document.")
                        }
                        .background(Color(NSColor.controlBackgroundColor))
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                        .overlay(
                            RoundedRectangle(cornerRadius: 8)
                                .stroke(Color.secondary.opacity(0.28), lineWidth: 1)
                        )
                        .fixedSize()

                        // Primary Submit Package Action for Draft Resumes
                        Button {
                            store.submitResumePackage(doc)
                        } label: {
                            Group {
                                if store.submittingDocumentId == doc.id {
                                    GeneratingProgressLabel(
                                        title: "Submitting",
                                        fontSize: 12.5,
                                        fontWeight: .semibold,
                                        dotColor: .white
                                    )
                                } else {
                                    HStack(spacing: 6) {
                                        Image(systemName: "paperplane.fill")
                                            .font(.system(size: 11.5, weight: .semibold))
                                        Text("Submit Package")
                                            .font(.system(size: 12.5, weight: .semibold))
                                    }
                                }
                            }
                            .padding(.horizontal, 8)
                            .frame(minHeight: 24)
                        }
                        .buttonStyle(.borderedProminent)
                        .tint(.accentColor)
                        .controlSize(.regular)
                        .fixedSize(horizontal: true, vertical: false)
                        .disabled(!store.submittingDocumentId.isEmpty)
                        .help("Save any edits, attach this tailored Resume and Cover Letter package, autofill the application form, and submit.")
                    }

                    // Consolidated 3-Dot Menu for Secondary Actions
                    EllipsisActionMenuButton(helpText: "Open document actions such as submitting the package, marking as Submitted, viewing the PDF or Word file, revealing in Finder, or regenerating.") {
                        if isSubmittedLocked {
                            Button {
                                store.setDocumentSubmittedStatus(doc, isSubmitted: false)
                            } label: {
                                Label("Mark as Draft", systemImage: "arrow.uturn.backward.circle")
                            }
                        } else {
                            Button {
                                store.submitResumePackage(doc)
                            } label: {
                                Label("Submit Package", systemImage: "paperplane.fill")
                            }
                            .disabled(!store.submittingDocumentId.isEmpty)

                            Button {
                                store.setDocumentSubmittedStatus(doc, isSubmitted: true)
                            } label: {
                                Label("Mark as Submitted", systemImage: "checkmark.circle")
                            }
                        }

                        Divider()

                        Button {
                            store.autoSaveCurrentEditedDocument(silent: true)
                            let refreshedDoc = store.selectedDocument ?? doc
                            let pdfToOpen = (store.resumePreviewTab == .coverLetter && !refreshedDoc.coverLetterPdfPath.isEmpty) ? refreshedDoc.coverLetterPdfPath : refreshedDoc.pdfPath
                            store.openFileOnMac(pdfToOpen)
                        } label: {
                            Label("Open PDF", systemImage: "doc.richtext")
                        }

                        Button {
                            store.autoSaveCurrentEditedDocument(silent: true)
                            let refreshedDoc = store.selectedDocument ?? doc
                            let docxToOpen = (store.resumePreviewTab == .coverLetter && !refreshedDoc.coverLetterDocxPath.isEmpty) ? refreshedDoc.coverLetterDocxPath : refreshedDoc.docxPath
                            store.openFileOnMac(docxToOpen)
                        } label: {
                            Label("Open DOCX", systemImage: "doc.text")
                        }

                        Button {
                            store.autoSaveCurrentEditedDocument(silent: true)
                            let refreshedDoc = store.selectedDocument ?? doc
                            let pdfToReveal = (store.resumePreviewTab == .coverLetter && !refreshedDoc.coverLetterPdfPath.isEmpty) ? refreshedDoc.coverLetterPdfPath : refreshedDoc.pdfPath
                            store.openFileOnMac(pdfToReveal, revealInFinder: true)
                        } label: {
                            Label("Show in Finder", systemImage: "folder")
                        }

                        if !doc.jobId.isEmpty {
                            Divider()
                            Button {
                                store.generateTailoredDocument(payload: ["job_id": doc.jobId])
                            } label: {
                                Label("Regenerate Package", systemImage: "arrow.clockwise")
                            }
                            .disabled(store.isGeneratingTailoredDocument)
                        }

                        Divider()

                        Button(role: .destructive) {
                            store.deleteGeneratedDocument(doc)
                        } label: {
                            Label("Remove Resume from List", systemImage: "trash")
                        }
                    }
                }
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 12)
            .background(Color(NSColor.windowBackgroundColor))

            Divider()

            // Independently Scrollable Document Preview / Editor Surface
            switch store.resumePreviewTab {
            case .resume:
                if !isSubmittedLocked && isSplitMode {
                    SynchronizedSplitMarkdownView(
                        text: $store.resumeEditorText,
                        focusLineText: store.resumeFocusLineText,
                        focusTriggerCount: store.resumeFocusTriggerCount
                    ) {
                        store.autoSaveCurrentEditedDocument(silent: true)
                    }
                    .padding(14)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else if !isSubmittedLocked && isEditOnly {
                    MarkdownCodeEditorView(
                        text: $store.resumeEditorText,
                        focusLineText: store.resumeFocusLineText,
                        focusTriggerCount: store.resumeFocusTriggerCount
                    ) {
                        store.autoSaveCurrentEditedDocument(silent: true)
                    }
                    .padding(14)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    ScrollView {
                        VisualMarkdownRendererView(
                            markdown: store.resumeEditorText.isEmpty ? doc.resumeMarkdown : store.resumeEditorText
                        ) { tappedRawLine in
                            guard !isSubmittedLocked else { return }
                            store.resumeFocusLineText = tappedRawLine
                            store.resumeFocusTriggerCount += 1
                            store.resumeShowEditor = true
                            store.resumeShowPreview = false
                        }
                        .padding(14)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            case .coverLetter:
                if !isSubmittedLocked && isSplitMode {
                    SynchronizedSplitMarkdownView(
                        text: $store.coverLetterEditorText,
                        focusLineText: store.resumeFocusLineText,
                        focusTriggerCount: store.resumeFocusTriggerCount
                    ) {
                        store.autoSaveCurrentEditedDocument(silent: true)
                    }
                    .padding(14)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else if !isSubmittedLocked && isEditOnly {
                    MarkdownCodeEditorView(
                        text: $store.coverLetterEditorText,
                        focusLineText: store.resumeFocusLineText,
                        focusTriggerCount: store.resumeFocusTriggerCount
                    ) {
                        store.autoSaveCurrentEditedDocument(silent: true)
                    }
                    .padding(14)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    ScrollView {
                        VisualMarkdownRendererView(
                            markdown: store.coverLetterEditorText.isEmpty ? doc.coverLetterMarkdown : store.coverLetterEditorText
                        ) { tappedRawLine in
                            guard !isSubmittedLocked else { return }
                            store.resumeFocusLineText = tappedRawLine
                            store.resumeFocusTriggerCount += 1
                            store.resumeShowEditor = true
                            store.resumeShowPreview = false
                        }
                        .padding(14)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            }
        }
        .background(Color(NSColor.windowBackgroundColor))
    }

    // MARK: - Tab 3: Generate Resume (Tailor Resume & Cover Letter for a Target Role)

    private var generateResumeSubtabView: some View {
        let isInputEmpty = !store.customTailorManualMode
            ? store.customTailorJobUrl.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            : (store.customTailorCompany.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && store.customTailorRole.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && store.customTailorDescription.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

        return VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 14) {
                HStack(alignment: .center) {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Tailor Resume & Cover Letter for a Target Role")
                            .font(.system(size: 15, weight: .semibold))
                            .foregroundColor(.primary)
                        Text("Generate a role-specific resume and cover letter grounded strictly in your verified Knowledge Base.")
                            .font(.system(size: 12))
                            .foregroundColor(.secondary)
                    }
                    Spacer()

                    // Segmented Input Mode Switcher: From Job URL | Specify Manually
                    HStack(spacing: 8) {
                        SelectableChip(
                            title: "From Job URL",
                            icon: "link",
                            isSelected: !store.customTailorManualMode
                        ) {
                            store.customTailorManualMode = false
                            store.customTailorUrlError = ""
                        }
                        .fixedSize(horizontal: true, vertical: false)

                        SelectableChip(
                            title: "Specify Manually",
                            icon: "square.and.pencil",
                            isSelected: store.customTailorManualMode
                        ) {
                            store.customTailorManualMode = true
                        }
                        .fixedSize(horizontal: true, vertical: false)
                    }
                }

                if !store.customTailorUrlError.isEmpty {
                    HStack(spacing: 8) {
                        Image(systemName: "exclamationmark.triangle.fill")
                            .font(.system(size: 12))
                            .foregroundColor(.orange)
                        Text(store.customTailorUrlError)
                            .font(.system(size: 12))
                            .foregroundColor(.orange)
                        Spacer()
                    }
                    .padding(10)
                    .background(RoundedRectangle(cornerRadius: 7).fill(Color.orange.opacity(0.12)))
                }

                if !store.customTailorManualMode {
                    VStack(alignment: .leading, spacing: 5) {
                        Text("Job Posting URL")
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.secondary)
                        TextField(
                            "Paste job posting URL (e.g. https://boards.greenhouse.io/... or LinkedIn / Lever / Ashby URL)",
                            text: $store.customTailorJobUrl
                        )
                        .textFieldStyle(.plain)
                        .font(.system(size: 12.5))
                        .padding(.horizontal, 10)
                        .padding(.vertical, 7)
                        .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                        .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.22), lineWidth: 1))
                    }
                } else {
                    HStack(spacing: 14) {
                        VStack(alignment: .leading, spacing: 5) {
                            Text("Target Company")
                                .font(.system(size: 11.5, weight: .medium))
                                .foregroundColor(.secondary)
                            TextField("e.g. Anthropic, Stripe, Linear", text: $store.customTailorCompany)
                                .textFieldStyle(.plain)
                                .font(.system(size: 12.5))
                                .padding(.horizontal, 10)
                                .padding(.vertical, 7)
                                .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                                .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.22), lineWidth: 1))
                        }

                        VStack(alignment: .leading, spacing: 5) {
                            Text("Target Role Title")
                                .font(.system(size: 11.5, weight: .medium))
                                .foregroundColor(.secondary)
                            TextField("e.g. Staff Product Manager, Senior Systems Engineer", text: $store.customTailorRole)
                                .textFieldStyle(.plain)
                                .font(.system(size: 12.5))
                                .padding(.horizontal, 10)
                                .padding(.vertical, 7)
                                .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                                .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.22), lineWidth: 1))
                        }
                    }

                    VStack(alignment: .leading, spacing: 5) {
                        Text("Job Description or Key Requirements")
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.secondary)
                        ZStack(alignment: .topLeading) {
                            TextEditor(text: $store.customTailorDescription)
                                .font(.system(size: 12.5))
                                .frame(height: 150)
                                .padding(8)
                                .background(RoundedRectangle(cornerRadius: 7).fill(Color(NSColor.textBackgroundColor)))
                                .overlay(RoundedRectangle(cornerRadius: 7).stroke(Color.secondary.opacity(0.22), lineWidth: 1))

                            if store.customTailorDescription.isEmpty {
                                Text("Paste job requirements, responsibilities, or domain focus here…")
                                    .font(.system(size: 12))
                                    .foregroundColor(.secondary.opacity(0.65))
                                    .padding(.horizontal, 13)
                                    .padding(.vertical, 13)
                                    .allowsHitTesting(false)
                            }
                        }
                    }
                }

                Divider()

                HStack(spacing: 12) {
                    HStack(spacing: 6) {
                        Image(systemName: "checkmark.seal.fill")
                            .foregroundColor(.green)
                            .font(.system(size: 11.5))
                        Text("Uses only verified facts from your Knowledge Base — never fabricates experience.")
                            .font(.system(size: 11.5))
                            .foregroundColor(.secondary)
                    }

                    Spacer()

                    Button {
                        if !store.customTailorManualMode {
                            store.generateTailoredDocument(
                                payload: [
                                    "job_id": store.selectedJobId,
                                    "job_url": store.customTailorJobUrl,
                                ],
                                clearInputsOnSuccess: true
                            )
                        } else {
                            store.generateTailoredDocument(
                                payload: [
                                    "job_id": store.selectedJobId,
                                    "custom_company": store.customTailorCompany,
                                    "custom_role": store.customTailorRole,
                                    "custom_description": store.customTailorDescription,
                                ],
                                clearInputsOnSuccess: true
                            )
                        }
                    } label: {
                        Group {
                            if store.isGeneratingTailoredDocument {
                                GeneratingProgressLabel(
                                    title: "Generating",
                                    fontSize: 13,
                                    fontWeight: .bold
                                )
                            } else {
                                Label("Generate Tailored Resume & Cover Letter", systemImage: "sparkles")
                                    .font(.system(size: 13, weight: .bold))
                            }
                        }
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.accentColor)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .disabled(isInputEmpty || store.isGeneratingTailoredDocument)
                }
            }
            .padding(16)
            .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.controlBackgroundColor)))
            .overlay(RoundedRectangle(cornerRadius: 8).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
        }
        .frame(maxWidth: 840, alignment: .leading)
    }
}

// MARK: - 5. Rethought Knowledge Base Section (Questionable Facts Queue + Growing Markdown Sections + Profile Photo)

struct KnowledgeBaseMarkdownView: View {
    @ObservedObject var store: WorkspaceStore

    private var profileHeaderSignature: String {
        [
            store.profileFullName,
            store.profilePronouns,
            store.profileHeadline,
            store.profileEmail,
            store.profilePhone,
            store.profileLocation,
            store.profileLinkedinUrl,
            store.profileGithubUrl,
            String(store.includePhotoOnResume),
        ].joined(separator: "::")
    }

    private func placeholderCount(in markdown: String) -> Int {
        max(0, markdown.components(separatedBy: "[PLEASE SPECIFY HERE]").count - 1)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // 1. Compact Profile Identity Header (Auto-Saved, Collapsible, Non-Truncated Fields)
            kbProfileHeaderBar
                .onChange(of: profileHeaderSignature) { _ in
                    store.autoSaveProfileHeader()
                }

            Divider()

            // 2. Full-Height Master–Detail Split View: Section Navigation + Document Workspace
            HSplitView {
                kbSectionsSidebar
                    .frame(minWidth: 275, idealWidth: 295, maxWidth: 335, maxHeight: .infinity)

                if let activeSection = store.selectedKBSection {
                    kbSectionWorkspacePane(for: activeSection)
                        .frame(minWidth: 460, maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    VStack(spacing: 8) {
                        Image(systemName: "book.pages")
                            .font(.system(size: 26))
                            .foregroundColor(.secondary.opacity(0.6))
                        Text("Select a Knowledge Base section")
                            .font(.system(size: 13.5, weight: .semibold))
                            .foregroundColor(.primary)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color(NSColor.windowBackgroundColor))
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .background(Color(NSColor.windowBackgroundColor))
        .sheet(isPresented: $store.showAddFactModal) {
            AddFactModalSheet(store: store)
        }
        .onAppear {
            store.kbShowEditor = false
            store.kbShowPreview = true
        }
        .onChange(of: store.selectedSection) { _ in
            store.kbShowEditor = false
            store.kbShowPreview = true
        }
        .onDisappear {
            store.kbShowEditor = false
            store.kbShowPreview = true
            store.autoSaveCurrentKBSection()
        }
    }

    // MARK: - Compact Profile Header Bar

    private var kbProfileHeaderBar: some View {
        HStack(alignment: .center, spacing: 18) {
            // Left compact avatar + photo actions
            VStack(alignment: .center, spacing: 7) {
                kbCompactAvatar(size: 58)

                Button {
                    store.chooseProfilePhotoWithOpenPanel()
                } label: {
                    Label(store.profilePhotoPath.isEmpty ? "Upload Photo" : "Change Photo", systemImage: "camera.fill")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)

                Toggle("Use on Resume", isOn: $store.includePhotoOnResume)
                    .toggleStyle(.checkbox)
                    .controlSize(.small)
                    .font(.system(size: 11))
                    .foregroundColor(.secondary)
            }
            .frame(width: 155)

            // Right 2-row properly proportioned field grid (no truncation on long fields)
            VStack(alignment: .leading, spacing: 8) {
                HStack(alignment: .bottom, spacing: 10) {
                    kbProfileField(label: "Full Name", placeholder: "Full name", text: $store.profileFullName)
                        .frame(minWidth: 165, idealWidth: 195, maxWidth: 230)

                    kbProfileField(label: "Pronouns", placeholder: "Pronouns", text: $store.profilePronouns)
                        .frame(width: 92)

                    kbProfileField(label: "Professional Headline", placeholder: "Role or professional headline", text: $store.profileHeadline)
                        .frame(minWidth: 230, maxWidth: .infinity)

                    kbProfileField(label: "Location", placeholder: "City, Country", text: $store.profileLocation)
                        .frame(minWidth: 135, idealWidth: 160, maxWidth: 195)
                }

                HStack(alignment: .bottom, spacing: 10) {
                    kbProfileField(label: "Email", placeholder: "email@domain.com", text: $store.profileEmail)
                        .frame(minWidth: 185, idealWidth: 220, maxWidth: 255)

                    kbProfileField(label: "Phone", placeholder: "+1 (555) 000-0000", text: $store.profilePhone)
                        .frame(width: 145)

                    kbProfileField(label: "LinkedIn URL", placeholder: "https://linkedin.com/in/username", text: $store.profileLinkedinUrl)
                        .frame(minWidth: 210, maxWidth: .infinity)

                    kbProfileField(label: "GitHub / Portfolio", placeholder: "https://github.com/username", text: $store.profileGithubUrl)
                        .frame(minWidth: 170, maxWidth: .infinity)
                }
            }
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 12)
        .background(Color(NSColor.windowBackgroundColor))
    }

    @ViewBuilder
    private func kbCompactAvatar(size: CGFloat) -> some View {
        let effectiveThumb = store.profilePhotoThumbPath.isEmpty ? store.profilePhotoPath : store.profilePhotoThumbPath
        CachedAvatarImageView(
            localPath: effectiveThumb,
            size: size,
            isCompanyLogo: false,
            fallbackInitials: "",
            accentBorder: false
        )
    }

    private func kbProfileField(label: String, placeholder: String, text: Binding<String>) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(label)
                .font(.system(size: 10.5, weight: .medium))
                .foregroundColor(.secondary)
                .lineLimit(1)
            TextField(placeholder, text: text)
                .textFieldStyle(.plain)
                .font(.system(size: 12))
                .padding(.horizontal, 8)
                .padding(.vertical, 5)
                .background(
                    RoundedRectangle(cornerRadius: 6)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 6)
                        .stroke(Color.secondary.opacity(0.20), lineWidth: 1)
                )
        }
    }

    // MARK: - Left Sections Navigation Sidebar

    private var kbSectionsSidebar: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Top bar: Profile Sections label + Add Knowledge action
            HStack(spacing: 8) {
                Label("Profile Sections", systemImage: "list.bullet.indent")
                    .font(.subheadline.bold())
                    .lineLimit(1)

                Spacer()

                Button {
                    store.showAddFactModal = true
                } label: {
                    Label("Add Knowledge", systemImage: "sparkles")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .tint(.accentColor)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 10)

            Divider()

            // Scrollable section list (selected section subtab is larger and more prominent)
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 6) {
                    ForEach(store.kbSections) { section in
                        kbSectionNavRow(section)
                    }
                }
                .padding(.horizontal, 10)
                .padding(.vertical, 10)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)

            Divider()

            // Pinned bottom bar: Add custom section
            HStack(spacing: 6) {
                TextField("New section…", text: $store.newCustomSectionTitle)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit {
                        let trimmed = store.newCustomSectionTitle.trimmingCharacters(in: .whitespacesAndNewlines)
                        guard !trimmed.isEmpty else { return }
                        store.autoSaveCurrentKBSection()
                        store.sendAction("add_kb_section", payload: ["title": trimmed])
                        store.newCustomSectionTitle = ""
                    }

                Button {
                    let trimmed = store.newCustomSectionTitle.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !trimmed.isEmpty else { return }
                    store.autoSaveCurrentKBSection()
                    store.sendAction("add_kb_section", payload: ["title": trimmed])
                    store.newCustomSectionTitle = ""
                } label: {
                    Label("Add", systemImage: "plus.circle.fill")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(store.newCustomSectionTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 10)
        }
        .background(Color(NSColor.windowBackgroundColor))
    }

    private func kbSectionNavRow(_ section: KBSectionItem) -> some View {
        let isSelected = store.selectedKBSectionId == section.id
        let needsSpecify = section.markdown.contains("[PLEASE SPECIFY HERE]")

        return Button {
            withAnimation(.easeInOut(duration: 0.14)) {
                store.selectKBSection(section.id)
            }
        } label: {
            HStack(spacing: isSelected ? 12 : 9) {
                Image(systemName: section.icon)
                    .font(.system(size: isSelected ? 16 : 13, weight: isSelected ? .bold : .semibold))
                    .foregroundColor(isSelected ? .accentColor : .secondary)
                    .frame(width: isSelected ? 24 : 20)

                VStack(alignment: .leading, spacing: 2) {
                    let _ = needsSpecify
                    HStack(spacing: 6) {
                        Text(section.title)
                            .font(.system(size: isSelected ? 14.5 : 13, weight: isSelected ? .bold : .medium))
                            .foregroundColor(.primary)
                            .lineLimit(1)
                    }

                    if isSelected && !section.subtitle.isEmpty {
                        Text(section.subtitle)
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                    }
                }

                Spacer(minLength: 4)

                Image(systemName: "chevron.right")
                    .font(.system(size: isSelected ? 11.5 : 10, weight: isSelected ? .bold : .regular))
                    .foregroundColor(isSelected ? .accentColor : .secondary)
            }
            .padding(.horizontal, isSelected ? 13 : 10)
            .padding(.vertical, isSelected ? 12 : 8)
            .background(
                RoundedRectangle(cornerRadius: isSelected ? 10 : 8)
                    .fill(isSelected ? Color.accentColor.opacity(0.15) : Color(NSColor.controlBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: isSelected ? 10 : 8)
                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.18), lineWidth: isSelected ? 1.5 : 1)
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }

    // MARK: - Right Section Content & Editor Workspace

    private func kbSectionWorkspacePane(for activeSection: KBSectionItem) -> some View {
        let isEditOnly = store.kbShowEditor && !store.kbShowPreview
        let isSplitMode = store.kbShowEditor && store.kbShowPreview

        return VStack(alignment: .leading, spacing: 0) {
            // Section Header & Established Joined [ ✎ | 👁 ] Mode Toggle
            HStack(alignment: .center, spacing: 10) {
                Image(systemName: activeSection.icon)
                    .font(.system(size: 14, weight: .bold))
                    .foregroundColor(.accentColor)

                VStack(alignment: .leading, spacing: 2) {
                    Text(activeSection.title)
                        .font(.system(size: 15, weight: .bold))
                        .foregroundColor(.primary)
                        .lineLimit(1)

                    if !activeSection.subtitle.isEmpty {
                        Text(activeSection.subtitle)
                            .font(.caption)
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                    }
                }

                Spacer()

                // Joined 2-button icon toggle: [ ✎ | 👁 ] (cycles: View -> Edit -> View+Edit -> View)
                HStack(spacing: 0) {
                    Button {
                        store.autoSaveCurrentKBSection()
                        store.cycleKBViewEditMode()
                    } label: {
                        Image(systemName: "pencil")
                            .font(.system(size: 12.5, weight: .semibold))
                            .foregroundColor(store.kbShowEditor ? .accentColor : .secondary)
                            .frame(width: 34, height: 32)
                            .background(store.kbShowEditor ? Color.accentColor.opacity(0.16) : Color.clear)
                            .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .help("Cycle between Preview, Edit, and Split view to edit the Markdown source of this Knowledge Base section.")

                    Rectangle()
                        .fill(Color.secondary.opacity(0.25))
                        .frame(width: 1, height: 20)

                    Button {
                        store.autoSaveCurrentKBSection()
                        store.cycleKBViewEditMode()
                    } label: {
                        Image(systemName: "eye.fill")
                            .font(.system(size: 12.5, weight: .semibold))
                            .foregroundColor(store.kbShowPreview ? .accentColor : .secondary)
                            .frame(width: 34, height: 32)
                            .background(store.kbShowPreview ? Color.accentColor.opacity(0.16) : Color.clear)
                            .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .help("Cycle between Preview, Edit, and Split view to preview the formatted Knowledge Base section.")
                }
                .background(Color(NSColor.controlBackgroundColor))
                .clipShape(RoundedRectangle(cornerRadius: 8))
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(Color.secondary.opacity(0.28), lineWidth: 1)
                )
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 10)

            Divider()

            // Full-Height Content / Editor Surface
            if isSplitMode {
                SynchronizedSplitMarkdownView(
                    text: $store.kbEditorText,
                    focusLineText: store.kbFocusLineText,
                    focusTriggerCount: store.kbFocusTriggerCount
                ) {
                    store.autoSaveCurrentKBSection()
                }
                .padding(14)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if isEditOnly {
                MarkdownCodeEditorView(
                    text: $store.kbEditorText,
                    focusLineText: store.kbFocusLineText,
                    focusTriggerCount: store.kbFocusTriggerCount
                ) {
                    store.autoSaveCurrentKBSection()
                }
                .padding(14)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                ScrollView {
                    VisualMarkdownRendererView(markdown: store.kbEditorText) { tappedRawLine in
                        store.kbFocusLineText = tappedRawLine
                        store.kbFocusTriggerCount += 1
                        store.kbShowEditor = true
                        store.kbShowPreview = false
                    }
                    .padding(14)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .background(Color(NSColor.windowBackgroundColor))
    }
}

struct AddFactModalSheet: View {
    @ObservedObject var store: WorkspaceStore

    private var canSubmit: Bool {
        !store.isIngestingKnowledge && (
            !store.newFactValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ||
            !store.kbIngestFilePaths.isEmpty
        )
    }

    private func fileSizeLabel(for path: String) -> String {
        guard let attrs = try? FileManager.default.attributesOfItem(atPath: path),
              let bytes = attrs[.size] as? Int64 else { return "" }
        if bytes < 1024 { return "\(bytes) B" }
        if bytes < 1024 * 1024 { return String(format: "%.1f KB", Double(bytes) / 1024.0) }
        return String(format: "%.1f MB", Double(bytes) / (1024.0 * 1024.0))
    }

    private func iconForFile(_ path: String) -> String {
        let ext = URL(fileURLWithPath: path).pathExtension.lowercased()
        switch ext {
        case "pdf": return "doc.richtext.fill"
        case "docx", "doc", "rtf": return "doc.text.fill"
        case "md", "txt": return "text.alignleft"
        case "csv", "json", "yaml", "yml": return "tablecells.fill"
        case "wav", "mp3", "m4a": return "waveform"
        case "png", "jpg", "jpeg", "webp", "heic": return "photo.fill"
        default: return "doc.fill"
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            // Header
            HStack(alignment: .center, spacing: 12) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color.accentColor.opacity(0.14))
                        .frame(width: 34, height: 34)
                    Image(systemName: "sparkles")
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundColor(.accentColor)
                }
                VStack(alignment: .leading, spacing: 2) {
                    Text("Add Knowledge")
                        .font(.system(size: 15, weight: .semibold))
                    Text("Paste notes, achievements, Q&As, or drop files — AutoApply will organize and integrate them into the right sections.")
                        .font(.system(size: 11.5))
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                }
                Spacer()
                CalibratedIconButton(systemName: "xmark", helpText: "Close") {
                    if !store.isIngestingKnowledge {
                        store.showAddFactModal = false
                    }
                }
            }

            Divider()

            // Knowledge Input Editor
            VStack(alignment: .leading, spacing: 6) {
                HStack {
                    Text("Notes, Experience, Metrics, or Q&As")
                        .font(.system(size: 11.5, weight: .semibold))
                        .foregroundColor(.primary)
                    Spacer()
                    let wordCount = store.newFactValue.split { $0.isWhitespace || $0.isNewline }.count
                    if wordCount > 0 {
                        Text("\(wordCount) word\(wordCount == 1 ? "" : "s")")
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                    } else {
                        Text("Auto-routed to matching sections")
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                    }
                }

                ZStack(alignment: .topLeading) {
                    TextEditor(text: $store.newFactValue)
                        .font(.system(size: 12.5))
                        .frame(height: 175)
                        .padding(8)
                        .background(RoundedRectangle(cornerRadius: 8).fill(Color(NSColor.textBackgroundColor)))
                        .overlay(
                            RoundedRectangle(cornerRadius: 8)
                                .stroke(Color.secondary.opacity(0.20), lineWidth: 1)
                        )

                    if store.newFactValue.isEmpty {
                        Text("Paste or type project achievements, metrics, work history, skills, certifications, or Q&A answers…")
                            .font(.system(size: 12))
                            .foregroundColor(.secondary.opacity(0.65))
                            .padding(.horizontal, 13)
                            .padding(.vertical, 13)
                            .allowsHitTesting(false)
                    }
                }
            }

            // File Upload & Dropzone Area
            VStack(alignment: .leading, spacing: 8) {
                HStack(spacing: 10) {
                    Image(systemName: "doc.badge.plus")
                        .font(.system(size: 14, weight: .medium))
                        .foregroundColor(.secondary)
                        .frame(width: 24)
                    VStack(alignment: .leading, spacing: 1) {
                        Text("Attach or Drop Files")
                            .font(.system(size: 12, weight: .medium))
                        Text("PDF, Word (.docx), Markdown, Text, CSV, JSON, or Audio")
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                    }
                    Spacer()
                    Button {
                        store.chooseKBIngestFilesWithOpenPanel()
                    } label: {
                        Label("Choose Files…", systemImage: "folder")
                            .font(.system(size: 13, weight: .semibold))
                            .padding(.horizontal, 6)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.large)
                    .fixedSize(horizontal: true, vertical: false)
                    .disabled(store.isIngestingKnowledge)
                }
                .padding(10)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(store.kbIsDropTargeted ? Color.accentColor.opacity(0.08) : Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .strokeBorder(
                            store.kbIsDropTargeted ? Color.accentColor : Color.secondary.opacity(0.20),
                            style: StrokeStyle(lineWidth: 1, dash: [5, 3])
                        )
                )

                if !store.kbIngestFilePaths.isEmpty {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 6) {
                            ForEach(store.kbIngestFilePaths, id: \.self) { filePath in
                                let fileName = URL(fileURLWithPath: filePath).lastPathComponent
                                let sizeStr = fileSizeLabel(for: filePath)
                                HStack(spacing: 6) {
                                    Image(systemName: iconForFile(filePath))
                                        .font(.system(size: 11, weight: .semibold))
                                        .foregroundColor(.accentColor)
                                        .frame(width: 14, height: 14)
                                    Text(fileName)
                                        .font(.system(size: 11.5, weight: .medium))
                                        .lineLimit(1)
                                    if !sizeStr.isEmpty {
                                        Text(sizeStr)
                                            .font(.system(size: 10))
                                            .foregroundColor(.secondary)
                                    }
                                    Button {
                                        store.kbIngestFilePaths.removeAll { $0 == filePath }
                                    } label: {
                                        Image(systemName: "xmark.circle.fill")
                                            .font(.system(size: 11.5))
                                            .foregroundColor(.secondary)
                                    }
                                    .buttonStyle(.plain)
                                    .disabled(store.isIngestingKnowledge)
                                }
                                .padding(.horizontal, 8)
                                .padding(.vertical, 4)
                                .background(RoundedRectangle(cornerRadius: 6).fill(Color.secondary.opacity(0.10)))
                            }
                        }
                    }
                }
            }

            if store.isIngestingKnowledge {
                VStack(alignment: .leading, spacing: 6) {
                    HStack(spacing: 8) {
                        ProgressView()
                            .controlSize(.small)
                        Text(store.kbIngestProgressMessage.isEmpty ? "Processing and integrating into your Knowledge Base…" : store.kbIngestProgressMessage)
                            .font(.system(size: 11.5, weight: .medium))
                            .foregroundColor(.primary)
                            .lineLimit(1)
                            .truncationMode(.tail)
                        Spacer()
                        Text("\(Int(round(store.kbIngestProgressFraction * 100)))%")
                            .font(.system(size: 11, weight: .semibold, design: .monospaced))
                            .foregroundColor(.accentColor)
                    }
                    ProgressView(value: max(0.06, min(1.0, store.kbIngestProgressFraction)), total: 1.0)
                        .progressViewStyle(.linear)
                        .tint(.accentColor)
                }
                .padding(.horizontal, 10)
                .padding(.vertical, 8)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color.accentColor.opacity(0.08))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(Color.accentColor.opacity(0.22), lineWidth: 1)
                )
            }

            Divider()

            // Footer Actions
            HStack(spacing: 10) {
                Text("Automatically structured and merged into your sections")
                    .font(.system(size: 11))
                    .foregroundColor(.secondary)
                    .lineLimit(1)

                Spacer()

                Button {
                    store.showAddFactModal = false
                } label: {
                    Text("Cancel")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(store.isIngestingKnowledge)

                Button {
                    store.submitKnowledgeIngestion()
                } label: {
                    Label(
                        store.isIngestingKnowledge ? "Integrating…" : "Save to Knowledge Base",
                        systemImage: "sparkles"
                    )
                    .font(.system(size: 13, weight: .bold))
                    .padding(.horizontal, 8)
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .tint(.accentColor)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(!canSubmit)
            }
        }
        .padding(18)
        .frame(width: 540)
        .onDrop(of: [.fileURL], isTargeted: $store.kbIsDropTargeted) { providers in
            var handled = false
            for provider in providers {
                if provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
                    handled = true
                    provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { item, _ in
                        var resolvedURL: URL?
                        if let data = item as? Data {
                            resolvedURL = URL(dataRepresentation: data, relativeTo: nil)
                        } else if let url = item as? URL {
                            resolvedURL = url
                        }
                        if let url = resolvedURL {
                            DispatchQueue.main.async {
                                let p = url.path
                                if !store.kbIngestFilePaths.contains(p) {
                                    store.kbIngestFilePaths.append(p)
                                }
                            }
                        }
                    }
                }
            }
            return handled
        }
    }
}

/// Shared Markdown styling helper so the editable Markdown Editor and the Preview have the exact same colors, boldness, font sizes, and [PLEASE SPECIFY HERE] highlight.
@MainActor
enum MarkdownRichStyler {
    static let h1Font = NSFont.systemFont(ofSize: 17, weight: .bold)
    static let h2Font = NSFont.systemFont(ofSize: 14.5, weight: .bold)
    static let h3Font = NSFont.systemFont(ofSize: 13.5, weight: .semibold)
    static let bodyFont = NSFont.systemFont(ofSize: 13, weight: .regular)
    static let boldFont = NSFont.systemFont(ofSize: 13, weight: .bold)

    /// Styles an editable NSTextStorage in-place without modifying any characters so cursor position and undo history are preserved.
    static func applyLiveEditorSyntaxStyling(to storage: NSTextStorage) {
        let fullNSString = storage.string as NSString
        let totalLength = fullNSString.length
        guard totalLength > 0 else { return }

        storage.beginEditing()
        defer { storage.endEditing() }

        let baseParagraph = NSMutableParagraphStyle()
        baseParagraph.lineSpacing = 3
        baseParagraph.paragraphSpacing = 5
        baseParagraph.lineBreakMode = .byWordWrapping

        // Reset base attributes across the entire string
        storage.setAttributes([
            .font: bodyFont,
            .foregroundColor: NSColor.labelColor,
            .paragraphStyle: baseParagraph,
        ], range: NSRange(location: 0, length: totalLength))

        var lineStart = 0
        while lineStart < totalLength {
            var lineEnd = 0
            var contentEnd = 0
            fullNSString.getLineStart(&lineStart, end: &lineEnd, contentsEnd: &contentEnd, for: NSRange(location: lineStart, length: 0))
            let lineRange = NSRange(location: lineStart, length: contentEnd - lineStart)
            let rawLine = fullNSString.substring(with: lineRange)
            let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
            let leadingSpaces = rawLine.prefix(while: { $0 == " " || $0 == "\t" }).count
            let trimmedStart = lineStart + leadingSpaces
            let trimmedLen = max(0, contentEnd - trimmedStart)
            let trimmedRange = NSRange(location: trimmedStart, length: trimmedLen)

            let paragraph = NSMutableParagraphStyle()
            paragraph.lineSpacing = 3
            paragraph.paragraphSpacing = 5
            paragraph.lineBreakMode = .byWordWrapping

            if trimmed.hasPrefix("# ") {
                storage.addAttributes([
                    .font: h1Font,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ], range: trimmedRange)
                if trimmedLen >= 2 {
                    storage.addAttribute(.foregroundColor, value: NSColor.controlAccentColor, range: NSRange(location: trimmedStart, length: 2))
                }
            } else if trimmed.hasPrefix("## ") {
                storage.addAttributes([
                    .font: h2Font,
                    .foregroundColor: NSColor.systemTeal,
                    .paragraphStyle: paragraph,
                ], range: trimmedRange)
            } else if trimmed.hasPrefix("### ") {
                storage.addAttributes([
                    .font: h3Font,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ], range: trimmedRange)
            } else if trimmed.hasPrefix("- ") || trimmed.hasPrefix("* ") {
                paragraph.headIndent = 14
                storage.addAttribute(.paragraphStyle, value: paragraph, range: lineRange)
                if trimmedLen >= 2 {
                    storage.addAttributes([
                        .font: boldFont,
                        .foregroundColor: NSColor.controlAccentColor,
                    ], range: NSRange(location: trimmedStart, length: 2))
                }
                let afterBulletStr = String(trimmed.dropFirst(2))
                if let colonIdx = afterBulletStr.firstIndex(of: ":"),
                   afterBulletStr.distance(from: afterBulletStr.startIndex, to: colonIdx) < 42 {
                    let keyLen = afterBulletStr.distance(from: afterBulletStr.startIndex, to: colonIdx) + 1
                    let keyRange = NSRange(location: trimmedStart + 2, length: min(keyLen, max(0, trimmedLen - 2)))
                    storage.addAttributes([
                        .font: boldFont,
                        .foregroundColor: NSColor.labelColor,
                    ], range: keyRange)
                }
            }

            // Bold any **...** spans on this line
            let lineNS = rawLine as NSString
            var searchIdx = 0
            while searchIdx < lineNS.length {
                let openRange = lineNS.range(of: "**", options: [], range: NSRange(location: searchIdx, length: lineNS.length - searchIdx))
                if openRange.location == NSNotFound { break }
                let afterOpen = openRange.location + openRange.length
                if afterOpen >= lineNS.length { break }
                let closeRange = lineNS.range(of: "**", options: [], range: NSRange(location: afterOpen, length: lineNS.length - afterOpen))
                if closeRange.location == NSNotFound { break }
                let fullBoldRange = NSRange(location: lineStart + openRange.location, length: (closeRange.location + closeRange.length) - openRange.location)
                storage.addAttributes([
                    .font: boldFont,
                    .foregroundColor: NSColor.labelColor,
                ], range: fullBoldRange)
                searchIdx = closeRange.location + closeRange.length
            }

            // Highlight every [PLEASE SPECIFY HERE] occurrence in bright amber/orange in the Markdown editor
            var specIdx = 0
            while specIdx < lineNS.length {
                let found = lineNS.range(of: "[PLEASE SPECIFY HERE]", options: [], range: NSRange(location: specIdx, length: lineNS.length - specIdx))
                if found.location == NSNotFound { break }
                let absFound = NSRange(location: lineStart + found.location, length: found.length)
                storage.addAttributes([
                    .font: boldFont,
                    .foregroundColor: NSColor.systemOrange,
                    .backgroundColor: NSColor.systemOrange.withAlphaComponent(0.18),
                ], range: absFound)
                specIdx = found.location + found.length
            }

            if lineEnd <= lineStart { break }
            lineStart = lineEnd
        }
    }

    /// Builds the formatted Preview NSAttributedString with the exact same typography, colors, and [PLEASE SPECIFY HERE] highlight.
    static func renderPreviewAttributedMarkdown(_ markdown: String) -> NSAttributedString {
        let result = NSMutableAttributedString()
        let lines = markdown.components(separatedBy: .newlines)

        for (index, rawLine) in lines.enumerated() {
            let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
            let lineAttr = NSMutableAttributedString()

            if trimmed.isEmpty {
                lineAttr.append(NSAttributedString(string: index < lines.count - 1 ? "\n" : ""))
                result.append(lineAttr)
                continue
            }

            let paragraph = NSMutableParagraphStyle()
            paragraph.lineSpacing = 3
            paragraph.paragraphSpacing = 5
            paragraph.lineBreakMode = .byWordWrapping

            let leadingSpaces = rawLine.prefix(while: { $0 == " " || $0 == "\t" }).count
            let isIndentedSubBullet = leadingSpaces >= 2 && (trimmed.hasPrefix("- ") || trimmed.hasPrefix("* "))

            if trimmed.hasPrefix("# ") {
                if index > 0 {
                    paragraph.paragraphSpacingBefore = 12
                }
                let content = String(trimmed.dropFirst(2))
                lineAttr.append(NSAttributedString(string: content, attributes: [
                    .font: h1Font,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ]))
            } else if trimmed.hasPrefix("## ") {
                paragraph.paragraphSpacingBefore = 5
                let content = String(trimmed.dropFirst(3))
                lineAttr.append(NSAttributedString(string: content, attributes: [
                    .font: h2Font,
                    .foregroundColor: NSColor.systemTeal,
                    .paragraphStyle: paragraph,
                ]))
            } else if trimmed.hasPrefix("### ") {
                let content = String(trimmed.dropFirst(4))
                lineAttr.append(NSAttributedString(string: content, attributes: [
                    .font: h3Font,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ]))
            } else if isIndentedSubBullet {
                let content = String(trimmed.dropFirst(2)).replacingOccurrences(of: "**", with: "")
                paragraph.firstLineHeadIndent = 18
                paragraph.headIndent = 30
                lineAttr.append(NSAttributedString(string: "◦  ", attributes: [
                    .font: bodyFont,
                    .foregroundColor: NSColor.secondaryLabelColor,
                    .paragraphStyle: paragraph,
                ]))
                lineAttr.append(NSAttributedString(string: content, attributes: [
                    .font: bodyFont,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ]))
            } else if trimmed.hasPrefix("- ") || trimmed.hasPrefix("* ") {
                let content = String(trimmed.dropFirst(2)).replacingOccurrences(of: "**", with: "")
                paragraph.headIndent = 14
                lineAttr.append(NSAttributedString(string: "•  ", attributes: [
                    .font: boldFont,
                    .foregroundColor: NSColor.secondaryLabelColor,
                    .paragraphStyle: paragraph,
                ]))
                if let colonIdx = content.firstIndex(of: ":"), content.distance(from: content.startIndex, to: colonIdx) < 42 {
                    let keyPart = String(content[...colonIdx])
                    let valPart = String(content[content.index(after: colonIdx)...])
                    lineAttr.append(NSAttributedString(string: keyPart, attributes: [
                        .font: boldFont,
                        .foregroundColor: NSColor.labelColor,
                        .paragraphStyle: paragraph,
                    ]))
                    lineAttr.append(NSAttributedString(string: valPart, attributes: [
                        .font: bodyFont,
                        .foregroundColor: NSColor.labelColor,
                        .paragraphStyle: paragraph,
                    ]))
                } else {
                    lineAttr.append(NSAttributedString(string: content, attributes: [
                        .font: bodyFont,
                        .foregroundColor: NSColor.labelColor,
                        .paragraphStyle: paragraph,
                    ]))
                }
            } else {
                let cleaned = trimmed.replacingOccurrences(of: "**", with: "")
                lineAttr.append(NSAttributedString(string: cleaned, attributes: [
                    .font: bodyFont,
                    .foregroundColor: NSColor.labelColor,
                    .paragraphStyle: paragraph,
                ]))
            }

            // Highlight every [PLEASE SPECIFY HERE] occurrence in bright amber/orange
            let fullStr = lineAttr.string as NSString
            var searchRange = NSRange(location: 0, length: fullStr.length)
            while searchRange.location < fullStr.length {
                let found = fullStr.range(of: "[PLEASE SPECIFY HERE]", options: [], range: searchRange)
                if found.location == NSNotFound { break }
                lineAttr.addAttributes([
                    .font: boldFont,
                    .foregroundColor: NSColor.systemOrange,
                    .backgroundColor: NSColor.systemOrange.withAlphaComponent(0.18),
                ], range: found)
                let nextLoc = found.location + found.length
                searchRange = NSRange(location: nextLoc, length: fullStr.length - nextLoc)
            }

            if index < lines.count - 1 {
                lineAttr.append(NSAttributedString(string: "\n"))
            }
            result.append(lineAttr)
        }
        return result
    }
}

/// NSScrollView subclass that always keeps its NSTextView documentView and NSTextContainer wrapped to the visible scroll view width so lines wrap instead of scrolling horizontally.
final class WrappingMarkdownScrollView: NSScrollView {
    override func layout() {
        super.layout()
        guard let tv = documentView as? NSTextView else { return }
        let targetWidth = max(120, contentSize.width)
        if abs(tv.frame.size.width - targetWidth) > 0.5 {
            tv.frame.size.width = targetWidth
        }
        let containerWidth = max(80, targetWidth - (tv.textContainerInset.width * 2))
        tv.textContainer?.widthTracksTextView = true
        tv.textContainer?.containerSize = NSSize(width: containerWidth, height: CGFloat.greatestFiniteMagnitude)
    }
}

/// Single-pane Markdown editor with live heading/bold/bullet formatting and [PLEASE SPECIFY HERE] highlighting matching the Preview.
struct MarkdownCodeEditorView: NSViewRepresentable {
    @Binding var text: String
    var focusLineText: String = ""
    var focusTriggerCount: Int = 0
    var onAutoSave: (() -> Void)? = nil

    func makeCoordinator() -> Coordinator {
        Coordinator(text: $text, onAutoSave: onAutoSave)
    }

    func makeNSView(context: Context) -> NSScrollView {
        let sv = WrappingMarkdownScrollView()
        sv.hasVerticalScroller = true
        sv.hasHorizontalScroller = false
        sv.autohidesScrollers = false
        sv.borderType = .noBorder
        sv.drawsBackground = true
        sv.wantsLayer = true
        sv.layer?.cornerRadius = 8
        sv.layer?.borderWidth = 1
        sv.layer?.borderColor = NSColor.separatorColor.cgColor

        let tv = NSTextView(frame: NSRect(x: 0, y: 0, width: 600, height: 430))
        tv.isEditable = true
        tv.isSelectable = true
        tv.isRichText = false
        tv.allowsUndo = true
        tv.isAutomaticQuoteSubstitutionEnabled = false
        tv.isAutomaticDashSubstitutionEnabled = false
        tv.minSize = NSSize(width: 0, height: 0)
        tv.maxSize = NSSize(width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
        tv.isVerticallyResizable = true
        tv.isHorizontallyResizable = false
        tv.autoresizingMask = [.width]
        tv.textContainerInset = NSSize(width: 12, height: 12)
        tv.textContainer?.widthTracksTextView = true
        tv.textContainer?.containerSize = NSSize(width: 576, height: CGFloat.greatestFiniteMagnitude)
        tv.font = MarkdownRichStyler.bodyFont
        tv.backgroundColor = NSColor.textBackgroundColor
        tv.delegate = context.coordinator

        sv.documentView = tv
        context.coordinator.textView = tv
        context.coordinator.updateTextIfNeeded(text, force: true)
        context.coordinator.focusSpecifyIfNeeded(focusLine: focusLineText, triggerCount: focusTriggerCount)
        return sv
    }

    func updateNSView(_ nsView: NSScrollView, context: Context) {
        context.coordinator.textBinding = $text
        context.coordinator.onAutoSave = onAutoSave
        if let tv = nsView.documentView as? NSTextView {
            let targetWidth = max(120, nsView.contentSize.width)
            if abs(tv.frame.size.width - targetWidth) > 0.5 {
                tv.frame.size.width = targetWidth
            }
            let containerWidth = max(80, targetWidth - (tv.textContainerInset.width * 2))
            tv.textContainer?.widthTracksTextView = true
            tv.textContainer?.containerSize = NSSize(width: containerWidth, height: CGFloat.greatestFiniteMagnitude)
        }
        context.coordinator.updateTextIfNeeded(text)
        context.coordinator.focusSpecifyIfNeeded(focusLine: focusLineText, triggerCount: focusTriggerCount)
    }

    @MainActor
    final class Coordinator: NSObject, NSTextViewDelegate {
        var textBinding: Binding<String>
        var onAutoSave: (() -> Void)?
        weak var textView: NSTextView?
        var isUpdatingProgrammatically = false
        var lastFocusTriggerCount: Int = 0
        private var autoSaveWorkItem: DispatchWorkItem?

        init(text: Binding<String>, onAutoSave: (() -> Void)?) {
            self.textBinding = text
            self.onAutoSave = onAutoSave
            super.init()
        }

        func focusSpecifyIfNeeded(focusLine: String, triggerCount: Int) {
            guard triggerCount != lastFocusTriggerCount, triggerCount > 0, let tv = textView else { return }
            lastFocusTriggerCount = triggerCount
            let nsStr = tv.string as NSString
            var targetRange = NSRange(location: NSNotFound, length: 0)
            if !focusLine.isEmpty {
                let lineRange = nsStr.range(of: focusLine)
                if lineRange.location != NSNotFound {
                    let specInLine = nsStr.range(of: "[PLEASE SPECIFY HERE]", options: [], range: lineRange)
                    if specInLine.location != NSNotFound {
                        targetRange = specInLine
                    } else {
                        targetRange = NSRange(location: NSMaxRange(lineRange), length: 0)
                    }
                }
            }
            if targetRange.location == NSNotFound {
                targetRange = nsStr.range(of: "[PLEASE SPECIFY HERE]")
            }
            guard targetRange.location != NSNotFound else { return }
            let applyFocus = { [weak tv] in
                guard let tv = tv else { return }
                tv.window?.makeFirstResponder(tv)
                tv.setSelectedRange(targetRange)
                tv.scrollRangeToVisible(targetRange)
            }
            DispatchQueue.main.async(execute: applyFocus)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.06, execute: applyFocus)
        }

        func updateTextIfNeeded(_ newText: String, force: Bool = false) {
            guard let tv = textView else { return }
            if !force && tv.string == newText { return }
            isUpdatingProgrammatically = true
            let selected = tv.selectedRanges
            tv.string = newText
            if let storage = tv.textStorage {
                MarkdownRichStyler.applyLiveEditorSyntaxStyling(to: storage)
            }
            tv.selectedRanges = selected
            isUpdatingProgrammatically = false
        }

        func textDidChange(_ notification: Notification) {
            guard !isUpdatingProgrammatically, let tv = textView else { return }
            let updated = tv.string
            textBinding.wrappedValue = updated
            isUpdatingProgrammatically = true
            let selected = tv.selectedRanges
            if let storage = tv.textStorage {
                MarkdownRichStyler.applyLiveEditorSyntaxStyling(to: storage)
            }
            tv.selectedRanges = selected
            isUpdatingProgrammatically = false

            autoSaveWorkItem?.cancel()
            let work = DispatchWorkItem { [weak self] in
                Task { @MainActor in
                    self?.onAutoSave?()
                }
            }
            autoSaveWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8, execute: work)
        }
    }
}

/// Two-way proportionally synchronized split view: scrolling the left Markdown editor scrolls the right preview proportionally, and vice versa.
struct SynchronizedSplitMarkdownView: NSViewRepresentable {
    @Binding var text: String
    var focusLineText: String = ""
    var focusTriggerCount: Int = 0
    var onAutoSave: (() -> Void)? = nil

    func makeCoordinator() -> Coordinator {
        Coordinator(text: $text, onAutoSave: onAutoSave)
    }

    func makeNSView(context: Context) -> NSView {
        let container = ProportionalSplitContainerView(coordinator: context.coordinator)
        context.coordinator.setupViews(in: container, initialText: text)
        context.coordinator.focusSpecifyIfNeeded(focusLine: focusLineText, triggerCount: focusTriggerCount)
        return container
    }

    func updateNSView(_ nsView: NSView, context: Context) {
        context.coordinator.textBinding = $text
        context.coordinator.onAutoSave = onAutoSave
        context.coordinator.updateTextIfNeeded(text)
        context.coordinator.focusSpecifyIfNeeded(focusLine: focusLineText, triggerCount: focusTriggerCount)
    }

    final class ProportionalSplitContainerView: NSView {
        weak var coordinator: Coordinator?

        init(coordinator: Coordinator) {
            self.coordinator = coordinator
            super.init(frame: .zero)
        }

        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        override func layout() {
            super.layout()
            coordinator?.layoutScrollViews(in: bounds)
        }
    }

    @MainActor
    final class Coordinator: NSObject, NSTextViewDelegate {
        var textBinding: Binding<String>
        var onAutoSave: (() -> Void)?
        weak var leftScrollView: NSScrollView?
        weak var rightScrollView: NSScrollView?
        weak var leftTextView: NSTextView?
        weak var rightTextView: NSTextView?
        var isSyncingScroll: Bool = false
        var isUpdatingTextProgrammatically: Bool = false
        var lastFocusTriggerCount: Int = 0
        private var autoSaveWorkItem: DispatchWorkItem?

        init(text: Binding<String>, onAutoSave: (() -> Void)?) {
            self.textBinding = text
            self.onAutoSave = onAutoSave
            super.init()
        }

        nonisolated deinit {
            NotificationCenter.default.removeObserver(self)
        }

        func focusSpecifyIfNeeded(focusLine: String, triggerCount: Int) {
            guard triggerCount != lastFocusTriggerCount, triggerCount > 0, let tv = leftTextView else { return }
            lastFocusTriggerCount = triggerCount
            let nsStr = tv.string as NSString
            var targetRange = NSRange(location: NSNotFound, length: 0)
            if !focusLine.isEmpty {
                let lineRange = nsStr.range(of: focusLine)
                if lineRange.location != NSNotFound {
                    let specInLine = nsStr.range(of: "[PLEASE SPECIFY HERE]", options: [], range: lineRange)
                    if specInLine.location != NSNotFound {
                        targetRange = specInLine
                    } else {
                        targetRange = NSRange(location: NSMaxRange(lineRange), length: 0)
                    }
                }
            }
            if targetRange.location == NSNotFound {
                targetRange = nsStr.range(of: "[PLEASE SPECIFY HERE]")
            }
            guard targetRange.location != NSNotFound else { return }
            let applyFocus = { [weak tv] in
                guard let tv = tv else { return }
                tv.window?.makeFirstResponder(tv)
                tv.setSelectedRange(targetRange)
                tv.scrollRangeToVisible(targetRange)
            }
            DispatchQueue.main.async(execute: applyFocus)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.06, execute: applyFocus)
        }

        func setupViews(in container: NSView, initialText: String) {
            let leftScroll = configuredScrollView()
            let rightScroll = configuredScrollView()

            let leftTV = configuredTextView(editable: true)
            leftTV.delegate = self
            leftScroll.documentView = leftTV

            let rightTV = configuredTextView(editable: false)
            rightTV.backgroundColor = NSColor.controlBackgroundColor
            rightScroll.documentView = rightTV

            container.addSubview(leftScroll)
            container.addSubview(rightScroll)

            self.leftScrollView = leftScroll
            self.rightScrollView = rightScroll
            self.leftTextView = leftTV
            self.rightTextView = rightTV

            leftScroll.contentView.postsBoundsChangedNotifications = true
            rightScroll.contentView.postsBoundsChangedNotifications = true

            NotificationCenter.default.addObserver(
                self,
                selector: #selector(handleClipBoundsChanged(_:)),
                name: NSView.boundsDidChangeNotification,
                object: leftScroll.contentView
            )
            NotificationCenter.default.addObserver(
                self,
                selector: #selector(handleClipBoundsChanged(_:)),
                name: NSView.boundsDidChangeNotification,
                object: rightScroll.contentView
            )

            updateTextIfNeeded(initialText, force: true)
        }

        private func configuredScrollView() -> NSScrollView {
            let sv = NSScrollView()
            sv.hasVerticalScroller = true
            sv.hasHorizontalScroller = false
            sv.autohidesScrollers = false
            sv.borderType = .noBorder
            sv.drawsBackground = true
            sv.wantsLayer = true
            sv.layer?.cornerRadius = 8
            sv.layer?.borderWidth = 1
            sv.layer?.borderColor = NSColor.separatorColor.cgColor
            return sv
        }

        private func configuredTextView(editable: Bool) -> NSTextView {
            let tv = NSTextView(frame: NSRect(x: 0, y: 0, width: 320, height: 430))
            tv.isEditable = editable
            tv.isSelectable = true
            tv.isRichText = false
            tv.allowsUndo = editable
            tv.isAutomaticQuoteSubstitutionEnabled = false
            tv.isAutomaticDashSubstitutionEnabled = false
            tv.isVerticallyResizable = true
            tv.isHorizontallyResizable = false
            tv.autoresizingMask = [.width]
            tv.textContainerInset = NSSize(width: 10, height: 10)
            tv.textContainer?.widthTracksTextView = true
            tv.textContainer?.containerSize = NSSize(width: 320, height: CGFloat.greatestFiniteMagnitude)
            tv.font = MarkdownRichStyler.bodyFont
            tv.backgroundColor = editable ? NSColor.textBackgroundColor : NSColor.controlBackgroundColor
            return tv
        }

        func layoutScrollViews(in bounds: NSRect) {
            guard let leftScroll = leftScrollView, let rightScroll = rightScrollView else { return }
            let spacing: CGFloat = 14
            let paneWidth = max(140, (bounds.width - spacing) / 2.0)
            let paneHeight = max(200, bounds.height)
            leftScroll.frame = NSRect(x: 0, y: 0, width: paneWidth, height: paneHeight)
            rightScroll.frame = NSRect(x: paneWidth + spacing, y: 0, width: paneWidth, height: paneHeight)

            if let leftTV = leftTextView {
                let contentWidth = max(120, leftScroll.contentSize.width)
                if abs(leftTV.frame.width - contentWidth) > 0.5 {
                    leftTV.frame.size.width = contentWidth
                }
                let containerWidth = max(80, contentWidth - (leftTV.textContainerInset.width * 2))
                leftTV.textContainer?.widthTracksTextView = true
                leftTV.textContainer?.containerSize = NSSize(width: containerWidth, height: CGFloat.greatestFiniteMagnitude)
            }
            if let rightTV = rightTextView {
                let contentWidth = max(120, rightScroll.contentSize.width)
                if abs(rightTV.frame.width - contentWidth) > 0.5 {
                    rightTV.frame.size.width = contentWidth
                }
                let containerWidth = max(80, contentWidth - (rightTV.textContainerInset.width * 2))
                rightTV.textContainer?.widthTracksTextView = true
                rightTV.textContainer?.containerSize = NSSize(width: containerWidth, height: CGFloat.greatestFiniteMagnitude)
            }
        }

        func updateTextIfNeeded(_ newText: String, force: Bool = false) {
            guard let leftTV = leftTextView, let rightTV = rightTextView else { return }
            if !force && leftTV.string == newText {
                return
            }
            isUpdatingTextProgrammatically = true
            let selectedRanges = leftTV.selectedRanges
            if leftTV.string != newText {
                leftTV.string = newText
            }
            if let leftStorage = leftTV.textStorage {
                MarkdownRichStyler.applyLiveEditorSyntaxStyling(to: leftStorage)
            }
            leftTV.selectedRanges = selectedRanges
            rightTV.textStorage?.setAttributedString(MarkdownRichStyler.renderPreviewAttributedMarkdown(newText))
            isUpdatingTextProgrammatically = false
        }

        func textDidChange(_ notification: Notification) {
            guard !isUpdatingTextProgrammatically, let leftTV = leftTextView, let rightTV = rightTextView else { return }
            let updated = leftTV.string
            textBinding.wrappedValue = updated
            isUpdatingTextProgrammatically = true
            let selectedRanges = leftTV.selectedRanges
            if let leftStorage = leftTV.textStorage {
                MarkdownRichStyler.applyLiveEditorSyntaxStyling(to: leftStorage)
            }
            leftTV.selectedRanges = selectedRanges
            rightTV.textStorage?.setAttributedString(MarkdownRichStyler.renderPreviewAttributedMarkdown(updated))
            isUpdatingTextProgrammatically = false

            autoSaveWorkItem?.cancel()
            let work = DispatchWorkItem { [weak self] in
                Task { @MainActor in
                    self?.onAutoSave?()
                }
            }
            autoSaveWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8, execute: work)
        }

        @objc func handleClipBoundsChanged(_ notification: Notification) {
            guard !isSyncingScroll,
                  let sourceClip = notification.object as? NSClipView,
                  let leftScroll = leftScrollView,
                  let rightScroll = rightScrollView,
                  let leftDoc = leftScroll.documentView,
                  let rightDoc = rightScroll.documentView
            else { return }

            isSyncingScroll = true
            defer { isSyncingScroll = false }

            if let leftTV = leftTextView, let lm = leftTV.layoutManager, let tc = leftTV.textContainer {
                lm.ensureLayout(for: tc)
            }
            if let rightTV = rightTextView, let lm = rightTV.layoutManager, let tc = rightTV.textContainer {
                lm.ensureLayout(for: tc)
            }

            if sourceClip === leftScroll.contentView {
                let leftRange = max(0, leftDoc.bounds.height - leftScroll.contentView.bounds.height)
                let fraction = leftRange > 1 ? min(1, max(0, leftScroll.contentView.bounds.origin.y / leftRange)) : 0
                let rightRange = max(0, rightDoc.bounds.height - rightScroll.contentView.bounds.height)
                let targetY = fraction * rightRange
                if abs(rightScroll.contentView.bounds.origin.y - targetY) > 0.5 {
                    rightScroll.contentView.scroll(to: NSPoint(x: 0, y: targetY))
                    rightScroll.reflectScrolledClipView(rightScroll.contentView)
                }
            } else if sourceClip === rightScroll.contentView {
                let rightRange = max(0, rightDoc.bounds.height - rightScroll.contentView.bounds.height)
                let fraction = rightRange > 1 ? min(1, max(0, rightScroll.contentView.bounds.origin.y / rightRange)) : 0
                let leftRange = max(0, leftDoc.bounds.height - leftScroll.contentView.bounds.height)
                let targetY = fraction * leftRange
                if abs(leftScroll.contentView.bounds.origin.y - targetY) > 0.5 {
                    leftScroll.contentView.scroll(to: NSPoint(x: 0, y: targetY))
                    leftScroll.reflectScrolledClipView(leftScroll.contentView)
                }
            }
        }
    }
}

struct VisualMarkdownRendererView: View {
    let markdown: String
    var onTapSpecify: ((String) -> Void)? = nil

    var body: some View {
        VStack(alignment: .leading, spacing: 9) {
            ForEach(Array(markdown.components(separatedBy: .newlines).enumerated()), id: \.offset) { idx, rawLine in
                let line = rawLine.trimmingCharacters(in: .whitespaces)
                let leadingSpaceCount = rawLine.prefix(while: { $0 == " " || $0 == "\t" }).count
                let isIndentedSubBullet = leadingSpaceCount >= 2 && (line.hasPrefix("- ") || line.hasPrefix("* "))
                if line.isEmpty {
                    Spacer().frame(height: 3)
                } else if line.hasPrefix("HEADER_META:") {
                    let metaText = String(line.dropFirst("HEADER_META:".count)).trimmingCharacters(in: .whitespaces)
                    Text(metaText)
                        .font(.system(size: 12, weight: .medium))
                        .foregroundColor(.secondary)
                } else if line.hasPrefix("ORG_LINE:") {
                    let orgText = String(line.dropFirst("ORG_LINE:".count)).trimmingCharacters(in: .whitespaces)
                    Text(orgText)
                        .font(.system(size: 12.5, weight: .semibold))
                        .italic()
                        .foregroundColor(.secondary)
                } else if line == "---" || line == "***" || line == "___" {
                    Divider()
                        .padding(.vertical, 4)
                } else if line.hasPrefix("# ") {
                    VStack(alignment: .leading, spacing: 5) {
                        Text(String(line.dropFirst(2)))
                            .font(.system(size: 18, weight: .bold))
                            .foregroundColor(.primary)
                        Divider()
                    }
                    .padding(.top, idx > 0 ? 14 : 0)
                    .padding(.bottom, 2)
                } else if line.hasPrefix("## ") {
                    Text(String(line.dropFirst(3)))
                        .font(.system(size: 15, weight: .bold))
                        .foregroundColor(.teal)
                        .padding(.top, 6)
                } else if line.hasPrefix("### ") {
                    Text(String(line.dropFirst(4)))
                        .font(.system(size: 13.5, weight: .semibold))
                        .foregroundColor(.primary)
                        .padding(.top, 3)
                } else if isIndentedSubBullet {
                    let content = String(line.dropFirst(2))
                    HStack(alignment: .top, spacing: 8) {
                        Text("◦")
                            .font(.system(size: 12.5, weight: .semibold))
                            .foregroundColor(.secondary)
                        FormattedInlineMarkdownText(text: content) {
                            onTapSpecify?(rawLine)
                        }
                    }
                    .padding(.leading, 20)
                } else if line.hasPrefix("- ") || line.hasPrefix("* ") {
                    let content = String(line.dropFirst(2))
                    HStack(alignment: .top, spacing: 8) {
                        Text("•")
                            .font(.system(size: 13, weight: .bold))
                            .foregroundColor(.secondary)
                        FormattedInlineMarkdownText(text: content) {
                            onTapSpecify?(rawLine)
                        }
                    }
                } else {
                    FormattedInlineMarkdownText(text: line) {
                        onTapSpecify?(rawLine)
                    }
                }
            }
        }
        .padding(16)
        .frame(maxWidth: .infinity, minHeight: 340, alignment: .topLeading)
        .background(RoundedRectangle(cornerRadius: 10).fill(Color(NSColor.controlBackgroundColor)))
    }
}

struct FormattedInlineMarkdownText: View {
    let text: String
    var onTapSpecify: (() -> Void)? = nil

    private func cleanWikiLinks(_ raw: String) -> String {
        guard let regex = try? NSRegularExpression(pattern: "\\[\\[([^\\]|]+)(?:\\|([^\\]]+))?\\]\\]") else {
            return raw
        }
        let ns = raw as NSString
        var result = raw
        let matches = regex.matches(in: raw, range: NSRange(location: 0, length: ns.length)).reversed()
        for m in matches {
            let labelRange = (m.numberOfRanges > 2 && m.range(at: 2).location != NSNotFound) ? m.range(at: 2) : m.range(at: 1)
            let label = ns.substring(with: labelRange).trimmingCharacters(in: .whitespaces)
            if let swiftRange = Range(m.range, in: result) {
                result.replaceSubrange(swiftRange, with: "⟦\(label)⟧")
            }
        }
        return result
    }

    var body: some View {
        let cleaned = cleanWikiLinks(text.replacingOccurrences(of: "**", with: ""))
        let isSpecify = cleaned.contains("[PLEASE SPECIFY HERE]")
        if text.contains("**:") || text.contains(":**") {
            let parts = cleaned.split(separator: ":", maxSplits: 1).map(String.init)
            if parts.count == 2 {
                let keyLabel = parts[0].trimmingCharacters(in: .whitespaces) + ":"
                let valLabel = parts[1].trimmingCharacters(in: .whitespaces)
                if isSpecify {
                    HStack(alignment: .top, spacing: 6) {
                        Text(keyLabel)
                            .font(.system(size: 13, weight: .bold))
                        Text(valLabel)
                            .font(.system(size: 13, weight: .bold))
                            .foregroundColor(.orange)
                            .padding(.horizontal, 6)
                            .padding(.vertical, 1)
                            .background(RoundedRectangle(cornerRadius: 4).fill(Color.orange.opacity(0.18)))
                            .contentShape(Rectangle())
                            .onTapGesture {
                                onTapSpecify?()
                            }
                            .help("Click to edit this placeholder")
                    }
                } else {
                    (Text(keyLabel + " ")
                        .font(.system(size: 13, weight: .bold))
                        .foregroundColor(.primary)
                    + Text(valLabel)
                        .font(.system(size: 13, weight: .regular))
                        .foregroundColor(.primary))
                        .fixedSize(horizontal: false, vertical: true)
                }
            } else {
                Text(cleaned)
                    .font(.system(size: 13, weight: isSpecify ? .bold : .regular))
                    .foregroundColor(isSpecify ? .orange : .primary)
                    .padding(.horizontal, isSpecify ? 6 : 0)
                    .padding(.vertical, isSpecify ? 1 : 0)
                    .background(isSpecify ? RoundedRectangle(cornerRadius: 4).fill(Color.orange.opacity(0.18)) : nil)
                    .contentShape(Rectangle())
                    .onTapGesture {
                        if isSpecify { onTapSpecify?() }
                    }
                    .help(isSpecify ? "Click to edit this placeholder" : "")
            }
        } else {
            Text(cleaned)
                .font(.system(size: 13, weight: isSpecify ? .bold : .regular))
                .foregroundColor(isSpecify ? .orange : .primary)
                .padding(.horizontal, isSpecify ? 6 : 0)
                .padding(.vertical, isSpecify ? 1 : 0)
                .background(isSpecify ? RoundedRectangle(cornerRadius: 4).fill(Color.orange.opacity(0.18)) : nil)
                .contentShape(Rectangle())
                .onTapGesture {
                    if isSpecify { onTapSpecify?() }
                }
                .help(isSpecify ? "Click to edit this placeholder" : "")
        }
    }
}

// MARK: - 6. Voice Interview Section (Redesigned Conversation Studio & Unified Control Bar)

struct VoiceInterviewSectionView: View {
    @ObservedObject var store: WorkspaceStore
    @ObservedObject var recorder: VoiceRecorderController

    init(store: WorkspaceStore) {
        self.store = store
        self.recorder = store.voiceRecorder
    }

    private func advanceToNextQuestionImmediately(removing currentQ: InterviewQuestionItem) -> InterviewQuestionItem? {
        let curIdx = store.interviewQuestions.firstIndex(where: { $0.id == currentQ.id }) ?? 0
        var updated = store.interviewQuestions
        if curIdx < updated.count {
            updated.remove(at: curIdx)
        }
        store.interviewQuestions = updated
        if !updated.isEmpty {
            let nextIdx = min(curIdx, updated.count - 1)
            let nextQ = updated[nextIdx]
            store.selectedInterviewQuestionId = nextQ.id
            store.interviewDraftText = nextQ.savedTranscript
            recorder.syncPreTypedDraft(nextQ.savedTranscript)
            return nextQ
        } else {
            store.selectedInterviewQuestionId = ""
            store.interviewDraftText = ""
            recorder.syncPreTypedDraft("")
            store.advanceToNextInterviewQuestion()
            return nil
        }
    }

    private func handleSaveAndNext(for q: InterviewQuestionItem) {
        let wasInConversation = recorder.isConversationActive || recorder.isConversationSessionActive
        let wasActivelyRecording = recorder.isRecording
        let preTyped = recorder.preRecordingDraftText.trimmingCharacters(in: .whitespacesAndNewlines)
        let currentDraft = store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines)

        if wasInConversation {
            let capturedAudioPath = recorder.captureAndStopForImmediateNext()
            let nextQuestion = advanceToNextQuestionImmediately(removing: q)
            if let nextQ = nextQuestion {
                recorder.startInterviewTurn(
                    questionId: nextQ.id,
                    questionPrompt: nextQ.prompt,
                    speakFirst: true,
                    repoRootDir: store.repoRootDir,
                    store: store
                )
            } else {
                recorder.isConversationSessionActive = false
            }
            recorder.backgroundProcessingCount += 1
            store.sendActionInBackground(
                "save_voice_interview_answer",
                payload: [
                    "question_id": q.id,
                    "transcript": currentDraft,
                    "pre_typed_text": preTyped,
                    "mode": "voice_conversation",
                    "audio_path": capturedAudioPath,
                    "rewrite_with_llm": wasActivelyRecording,
                    "kb_section_id": q.kbSectionId,
                ],
                silent: true,
                preserveInterviewSelection: true
            ) {
                recorder.backgroundProcessingCount = max(0, recorder.backgroundProcessingCount - 1)
            }
        } else {
            guard !currentDraft.isEmpty else { return }
            let capturedAudioPath = recorder.lastAudioFilePath
            recorder.lastAudioFilePath = ""
            _ = advanceToNextQuestionImmediately(removing: q)
            recorder.backgroundProcessingCount += 1
            store.sendActionInBackground(
                "save_voice_interview_answer",
                payload: [
                    "question_id": q.id,
                    "transcript": currentDraft,
                    "pre_typed_text": preTyped,
                    "mode": capturedAudioPath.isEmpty ? "typed" : "voice_mic",
                    "audio_path": capturedAudioPath,
                    "rewrite_with_llm": false,
                    "kb_section_id": q.kbSectionId,
                ],
                silent: true,
                preserveInterviewSelection: true
            ) {
                recorder.backgroundProcessingCount = max(0, recorder.backgroundProcessingCount - 1)
            }
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            // 1. Top Horizontal Question Stepper Queue Bar + "+ New AI Questions"
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(store.interviewQuestions) { q in
                        let isSelected = store.selectedInterviewQuestionId == q.id
                        Button {
                            guard q.id != store.selectedInterviewQuestionId else { return }
                            store.selectInterviewQuestion(q.id)
                        } label: {
                            HStack(spacing: 7) {
                                Image(systemName: q.icon)
                                    .font(.system(size: 11, weight: .semibold))
                                    .foregroundColor(isSelected ? .accentColor : .secondary)
                                Text(q.title)
                                    .font(.system(size: 12.5, weight: isSelected ? .bold : .medium))
                                    .foregroundColor(isSelected ? .primary : .secondary)
                                    .lineLimit(1)
                                if q.isLlmGenerated {
                                    Image(systemName: "sparkles")
                                        .font(.system(size: 9, weight: .bold))
                                        .foregroundColor(.purple)
                                }
                            }
                            .padding(.horizontal, 13)
                            .padding(.vertical, 8)
                            .fixedSize(horizontal: true, vertical: false)
                            .background(
                                Capsule()
                                    .fill(isSelected ? Color.accentColor.opacity(0.15) : Color(NSColor.windowBackgroundColor))
                            )
                            .overlay(
                                Capsule()
                                    .stroke(isSelected ? Color.accentColor : Color.secondary.opacity(0.18), lineWidth: isSelected ? 1.5 : 1)
                            )
                        }
                        .buttonStyle(.plain)
                    }

                    Button {
                        store.requestInterruptableAction {
                            let oldIds = Set(store.interviewQuestions.map(\.id))
                            store.sendActionInBackground("generate_more_interview_questions", payload: ["count": 3], silent: true) {
                                if let firstNew = store.interviewQuestions.first(where: { !oldIds.contains($0.id) }) {
                                    store.selectInterviewQuestion(firstNew.id)
                                }
                            }
                        }
                    } label: {
                        HStack(spacing: 6) {
                            Image(systemName: "sparkles")
                                .font(.system(size: 11, weight: .bold))
                                .foregroundColor(.purple)
                            Text("+ New AI Questions")
                                .font(.system(size: 12.5, weight: .semibold))
                                .foregroundColor(.purple)
                                .lineLimit(1)
                        }
                        .padding(.horizontal, 13)
                        .padding(.vertical, 8)
                        .fixedSize(horizontal: true, vertical: false)
                        .background(Capsule().fill(Color.purple.opacity(0.09)))
                        .overlay(Capsule().stroke(Color.purple.opacity(0.35), lineWidth: 1))
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.horizontal, 14)
            .padding(.vertical, 11)
            .background(RoundedRectangle(cornerRadius: 14).fill(Color(NSColor.controlBackgroundColor).opacity(0.75)))
            .overlay(RoundedRectangle(cornerRadius: 14).stroke(Color.secondary.opacity(0.15), lineWidth: 1))
            .fixedSize(horizontal: false, vertical: true)

            if let q = store.selectedInterviewQuestion {
                // 2. Unified High-Taste Conversation Studio Card
                VStack(alignment: .leading, spacing: 16) {
                    // A. Clean Prompt Header (No "Question 2" badge, no "Listen" button, no quotation marks)
                    HStack(alignment: .top, spacing: 16) {
                        ZStack {
                            RoundedRectangle(cornerRadius: 14)
                                .fill(
                                    LinearGradient(
                                        colors: recorder.isRecording
                                            ? [Color.red, Color.orange]
                                            : (recorder.isSpeakingQuestion ? [Color.teal, Color.blue] : [Color.accentColor, Color.purple]),
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                )
                                .frame(width: 52, height: 52)
                            Image(
                                systemName: recorder.isSpeakingQuestion
                                    ? "waveform.circle.fill"
                                    : (recorder.isRecording ? "mic.fill" : (recorder.isTranscribing ? "sparkles" : q.icon))
                            )
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(.white)
                        }

                        VStack(alignment: .leading, spacing: 6) {
                            HStack(spacing: 8) {
                                Text(q.title.uppercased())
                                    .font(.system(size: 11, weight: .bold))
                                    .tracking(0.8)
                                    .foregroundColor(.teal)
                                if q.isLlmGenerated {
                                    StatusBadge(text: "AI Tailored", color: .purple)
                                }
                                Spacer()
                                if recorder.backgroundProcessingCount > 0 {
                                    HStack(spacing: 6) {
                                        ProgressView()
                                            .controlSize(.small)
                                        Text("Incorporating into Knowledge Base…")
                                            .font(.caption2.bold())
                                            .foregroundColor(.secondary)
                                    }
                                    .padding(.horizontal, 10)
                                    .padding(.vertical, 4)
                                    .background(Capsule().fill(Color.secondary.opacity(0.10)))
                                }
                            }

                            Text(q.prompt)
                                .font(.system(size: 19, weight: .bold))
                                .foregroundColor(.primary)
                                .fixedSize(horizontal: false, vertical: true)

                            Text(q.whyItMatters)
                                .font(.system(size: 13))
                                .foregroundColor(.secondary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }
                    .fixedSize(horizontal: false, vertical: true)

                    // B. Live Conversation Audio Visualizer Strip
                    HStack(spacing: 16) {
                        HStack(spacing: 7) {
                            Circle()
                                .fill(
                                    recorder.isRecording
                                        ? Color.red
                                        : (recorder.isSpeakingQuestion ? Color.teal : (recorder.isTranscribing ? Color.purple : Color.green))
                                )
                                .frame(width: 8, height: 8)
                            Text(
                                recorder.isSpeakingQuestion
                                    ? (store.isGeneratingInterviewAnswer ? "SPEAKING — GENERATING ANSWER…" : "SPEAKING ALOUD…")
                                    : (recorder.isRecording
                                        ? "CONVERSATION LIVE — LISTENING…"
                                        : (recorder.isTranscribing || store.isGeneratingInterviewAnswer ? "PREPARING YOUR ANSWER…" : "READY FOR CONVERSATION"))
                            )
                            .font(.system(size: 11, weight: .bold))
                            .foregroundColor(recorder.isRecording ? .red : (recorder.isSpeakingQuestion ? .teal : .secondary))
                        }
                        .frame(width: 240, alignment: .leading)

                        // 24-Bar Equalizer
                        HStack(alignment: .center, spacing: 4) {
                            ForEach(0..<recorder.waveformBars.count, id: \.self) { idx in
                                let level = recorder.waveformBars[idx]
                                RoundedRectangle(cornerRadius: 2.5)
                                    .fill(
                                        LinearGradient(
                                            colors: recorder.isRecording
                                                ? [Color.red, Color.orange]
                                                : (recorder.isSpeakingQuestion ? [Color.teal, Color.blue] : [Color.accentColor.opacity(0.45), Color.teal.opacity(0.45)]),
                                            startPoint: .bottom,
                                            endPoint: .top
                                        )
                                    )
                                    .frame(width: 7, height: CGFloat(max(6.0, level * 36.0)))
                            }
                        }
                        .frame(height: 40)
                        .frame(maxWidth: .infinity)

                        Text(recorder.formattedDuration)
                            .font(.system(size: 13, weight: .bold, design: .monospaced))
                            .foregroundColor(recorder.isRecording ? .red : .secondary)
                            .padding(.horizontal, 10)
                            .padding(.vertical, 4)
                            .background(Capsule().fill(Color.secondary.opacity(0.12)))
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 10)
                    .background(
                        RoundedRectangle(cornerRadius: 12)
                            .fill(Color(NSColor.windowBackgroundColor))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 12)
                            .stroke(
                                recorder.isRecording
                                    ? Color.red.opacity(0.45)
                                    : (recorder.isSpeakingQuestion ? Color.teal.opacity(0.45) : Color.secondary.opacity(0.16)),
                                lineWidth: 1.2
                            )
                    )
                    .fixedSize(horizontal: false, vertical: true)

                    // C. Live Transcript & Polished Answer Editor (Bounded & Internally Scrollable so Bottom Buttons Always Fit)
                    VStack(alignment: .leading, spacing: 8) {
                        HStack {
                            Label("Your Answer", systemImage: "text.bubble.fill")
                                .font(.system(size: 13, weight: .bold))
                                .foregroundColor(.secondary)
                            Spacer()
                            Text(recorder.statusText)
                                .font(.caption)
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }

                        ZStack(alignment: .topLeading) {
                            TextEditor(text: $store.interviewDraftText)
                                .font(.system(size: 14))
                                .frame(minHeight: 120, maxHeight: .infinity)
                                .padding(10)
                                .background(RoundedRectangle(cornerRadius: 12).fill(Color(NSColor.textBackgroundColor)))
                                .overlay(
                                    RoundedRectangle(cornerRadius: 12)
                                        .stroke(
                                            recorder.isRecording ? Color.red.opacity(0.45) : Color.secondary.opacity(0.22),
                                            lineWidth: recorder.isRecording ? 1.5 : 1
                                        )
                                )
                                .onChange(of: store.interviewDraftText) { newVal in
                                    guard !store.isGeneratingInterviewAnswer else { return }
                                    if newVal != recorder.lastAppliedCombinedDraftText {
                                        if !recorder.lastLiveTranscriptText.isEmpty,
                                           let range = newVal.range(of: recorder.lastLiveTranscriptText, options: .backwards) {
                                            recorder.preRecordingDraftText = String(newVal[..<range.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
                                        } else {
                                            recorder.preRecordingDraftText = newVal
                                            recorder.lastLiveTranscriptText = ""
                                        }
                                        recorder.lastAppliedCombinedDraftText = newVal
                                    }
                                }

                            if store.interviewDraftText.isEmpty {
                                Text("Click 'Start Conversation' to hear the question and answer out loud, or click 'AI Recommended Answer' to generate a recommended response based on your profile.")
                                    .font(.system(size: 13.5))
                                    .foregroundColor(.secondary.opacity(0.55))
                                    .padding(.horizontal, 16)
                                    .padding(.vertical, 18)
                                    .allowsHitTesting(false)
                            }
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)

                    // D. Unified Single-Line Control Panel Bar (Always Fixed Visible at Bottom)
                    HStack(spacing: 12) {
                        // 1. Cancel / Stop Button [ ✕ ]
                        Button {
                            if recorder.isConversationActive {
                                store.requestInterruptableAction {
                                    // Confirmed inside confirmInterruptRecording()
                                }
                            } else {
                                recorder.cancelRecordingOrReset(store: store, currentQuestion: q)
                            }
                        } label: {
                            Image(systemName: "xmark")
                                .font(.system(size: 13, weight: .bold))
                                .frame(width: 34, height: 32)
                                .background(
                                    RoundedRectangle(cornerRadius: 8)
                                        .fill(recorder.isConversationActive ? Color.red.opacity(0.14) : Color.secondary.opacity(0.10))
                                )
                                .foregroundColor(recorder.isConversationActive ? .red : .secondary)
                        }
                        .buttonStyle(.plain)
                        .help("Stop and discard current recording")
                        .disabled(!recorder.isConversationActive && store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                        // 2. Skip Button (Moves to max(end, current + 5); hides if skipped > 3 times; skips immediately in Conversation Mode and keeps conversation going)
                        Button {
                            store.skipCurrentInterviewQuestion(q)
                        } label: {
                            Label("Skip", systemImage: "forward.end.fill")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 6)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)

                        Spacer()

                        // 3. AI Recommended Answer Button (Enabled in Conversation Mode & Speaks Prompts Aloud)
                        Button {
                            store.generateRecommendedInterviewAnswer(for: q)
                        } label: {
                            Group {
                                if store.isGeneratingInterviewAnswer {
                                    GeneratingProgressLabel(
                                        title: "Generating",
                                        fontSize: 13,
                                        fontWeight: .semibold
                                    )
                                } else {
                                    Label("AI Recommended Answer", systemImage: "sparkles")
                                        .font(.system(size: 13, weight: .semibold))
                                }
                            }
                            .padding(.horizontal, 8)
                            .lineLimit(1)
                            .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .disabled(recorder.isTranscribing || store.isGeneratingInterviewAnswer)
                        .help("Generate a quick, HR-recommended answer based on your profile and Knowledge Base")

                        // 4. Start Conversation / Stop & Review Button
                        if recorder.isConversationActive || (recorder.isConversationSessionActive && !recorder.userExplicitlyStoppedSession && store.isGeneratingInterviewAnswer) {
                            Button {
                                recorder.stopRecordingAndTranscribe(store: store)
                            } label: {
                                Label("Stop & Review", systemImage: "pause.circle.fill")
                                    .font(.system(size: 13, weight: .bold))
                                    .padding(.horizontal, 8)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.borderedProminent)
                            .tint(.orange)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                        } else {
                            Button {
                                recorder.startInterviewTurn(
                                    questionId: q.id,
                                    questionPrompt: q.prompt,
                                    speakFirst: true,
                                    repoRootDir: store.repoRootDir,
                                    store: store
                                )
                            } label: {
                                Label("Start Conversation", systemImage: "waveform.and.mic")
                                    .font(.system(size: 13, weight: .bold))
                                    .padding(.horizontal, 8)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.borderedProminent)
                            .tint(.accentColor)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                            .disabled(recorder.isTranscribing)
                        }

                        // 5. Save & Next Button
                        Button {
                            handleSaveAndNext(for: q)
                        } label: {
                            Label("Save & Next", systemImage: "arrow.right.circle.fill")
                                .font(.system(size: 13, weight: .bold))
                                .padding(.horizontal, 8)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.borderedProminent)
                        .tint(.green)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                        .disabled(!recorder.isConversationActive && store.interviewDraftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    }
                    .padding(12)
                    .background(
                        RoundedRectangle(cornerRadius: 12)
                            .fill(Color(NSColor.windowBackgroundColor))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 12)
                            .stroke(Color.secondary.opacity(0.16), lineWidth: 1)
                    )
                    .fixedSize(horizontal: false, vertical: true)
                }
                .padding(20)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                .background(RoundedRectangle(cornerRadius: 16).fill(Color(NSColor.controlBackgroundColor).opacity(0.68)))
                .overlay(RoundedRectangle(cornerRadius: 16).stroke(Color.secondary.opacity(0.16), lineWidth: 1))
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
}

// MARK: - 7. Connections & Settings Views

struct ConnectionsView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            SetupStep2AIView(store: store, showWizardNavigation: false)
            SetupStep3AccountsView(store: store, showWizardNavigation: false)
        }
    }
}

struct LicenseSettingsAccordionCard: View {
    @ObservedObject var store: WorkspaceStore
    @Binding var expandedId: String

    var body: some View {
        let planLabel = store.activeSubscriptionPlanLabel.isEmpty ? "Monthly Pro ($30/month)" : store.activeSubscriptionPlanLabel
        AccordionCardBox(
            itemId: "license_section",
            expandedId: $expandedId,
            title: store.isLicenseActivated ? "License Management" : "Activate License",
            subtitle: store.isLicenseActivated
                ? "Active Subscription: \(planLabel) — upgrade your plan, pause your subscription, or replace your license key"
                : "Free trial status, buy a Pro license key on our website, or activate your license key",
            icon: store.isLicenseActivated ? "checkmark.seal.fill" : "key.fill",
            badgeText: store.isLicenseActivated ? store.activeSubscriptionPlanName.uppercased() : store.trialDaysRemainingLabel,
            badgeColor: .green
        ) {
            FreeTrialAndLicenseCardsView(store: store)
        }
    }
}

struct SettingsView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            // When license is NOT activated: "Activate License" is at the TOP and expanded
            if !store.isLicenseActivated {
                LicenseSettingsAccordionCard(store: store, expandedId: $store.expandedWorkPrefItemId)
            }

            // 1. Application Review & Browser Visibility (collapsible, no ugly badge)
            AccordionCardBox(
                itemId: "app_review_visibility",
                expandedId: $store.expandedWorkPrefItemId,
                title: "Application Review & Browser Visibility",
                subtitle: "Choose whether eligible applications submit automatically or wait for review, and set browser window behavior",
                icon: "gearshape.2.fill"
            ) {
                HStack(spacing: 24) {
                    VStack(alignment: .leading, spacing: 6) {
                        Label("Application Mode", systemImage: "hand.raised.fill").font(.caption.bold())
                        Picker("", selection: $store.autonomyMode) {
                            Text("Review Each Application Before Submit").tag("review_each_application")
                            Text("Automatic When Eligible").tag("autonomous_if_eligible")
                        }
                        .labelsHidden()
                        .frame(width: 280)
                    }
                    VStack(alignment: .leading, spacing: 6) {
                        Label("Browser Window Visibility", systemImage: "macwindow").font(.caption.bold())
                        Picker("", selection: $store.visibilityMode) {
                            Text("Show Browser Window in Foreground").tag("foreground")
                            Text("Run Browser in Background").tag("background")
                        }
                        .labelsHidden()
                        .frame(width: 260)
                    }
                    Spacer()
                }
            }
            .onChange(of: store.autonomyMode) { _ in
                store.autoSaveOperatingPolicy()
            }
            .onChange(of: store.visibilityMode) { _ in
                store.autoSaveOperatingPolicy()
            }

            // 2. Language Models (Logic & Copywriting) — Collapsible & Accessible in Settings
            LanguageModelsAccordionCard(store: store, expandedId: $store.expandedWorkPrefItemId)

            // 3. Collapsible Preference Sections (Desired Work, Work Auth, US EEO, Smart Filters)
            WorkAuthAndDesiredWorkEditor(store: store)

            // When license IS activated: "License Management" is at the BOTTOM right before the Danger Zone, and collapsed
            if store.isLicenseActivated {
                LicenseSettingsAccordionCard(store: store, expandedId: $store.expandedWorkPrefItemId)
            }

            // 4. Collapsible Workspace Data & Uninstaller (Danger Zone)
            AccordionCardBox(
                itemId: "workspace_danger_zone",
                expandedId: $store.expandedWorkPrefItemId,
                title: "Workspace Data, Updates & Uninstaller",
                subtitle: "Software updates, portable backup & restore, setup wizard, workspace reset, and complete uninstaller",
                icon: "exclamationmark.triangle.fill",
                badgeText: store.isForceUpdateLocked ? "REQUIRED UPDATE" : "DANGER ZONE",
                badgeColor: store.isForceUpdateLocked ? .orange : .red,
                isDangerZone: true
            ) {
                VStack(alignment: .leading, spacing: 14) {
                    // Row 0: Software Updates (Daily Check + Force Update Support)
                    VStack(alignment: .leading, spacing: 10) {
                        HStack(alignment: .center, spacing: 16) {
                            ZStack {
                                RoundedRectangle(cornerRadius: 8)
                                    .fill(Color.secondary.opacity(0.12))
                                    .frame(width: 34, height: 34)
                                Image(systemName: store.isForceUpdateLocked ? "exclamationmark.arrow.triangle.2.circlepath" : (store.updateAvailable ? "arrow.down.circle.fill" : "checkmark.seal.fill"))
                                    .font(.system(size: 15, weight: .semibold))
                                    .foregroundColor(store.isForceUpdateLocked ? .orange : (store.updateAvailable ? .green : .accentColor))
                            }
                            VStack(alignment: .leading, spacing: 3) {
                                HStack(spacing: 8) {
                                    Text("Software Updates (v\(store.currentAppVersion))")
                                        .font(.system(size: 13, weight: .bold))
                                        .foregroundColor(.primary)
                                    if store.isForceUpdateLocked {
                                        Text("Required: v\(store.latestAppVersion)")
                                            .font(.system(size: 11, weight: .semibold))
                                            .foregroundColor(.orange)
                                    } else if store.updateAvailable {
                                        Text("Update Available: v\(store.latestAppVersion)")
                                            .font(.system(size: 11, weight: .semibold))
                                            .foregroundColor(.green)
                                    }
                                }
                                Text(store.updateStatusMessage)
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            HStack(spacing: 10) {
                                Button {
                                    store.checkForUpdatesAndPresentModal()
                                } label: {
                                    Label("Check for Updates", systemImage: "arrow.clockwise")
                                        .font(.system(size: 13, weight: .semibold))
                                        .padding(.horizontal, 6)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)
                                }
                                .buttonStyle(.bordered)
                                .controlSize(.large)
                                .fixedSize(horizontal: true, vertical: false)

                                if store.updateAvailable {
                                    Button {
                                        store.sendAction("install_update", payload: [
                                            "target_version": store.latestAppVersion,
                                        ])
                                    } label: {
                                        Label("Update Now", systemImage: "arrow.down.circle.fill")
                                            .font(.system(size: 13, weight: .bold))
                                            .padding(.horizontal, 8)
                                            .lineLimit(1)
                                            .fixedSize(horizontal: true, vertical: false)
                                    }
                                    .buttonStyle(.borderedProminent)
                                    .controlSize(.large)
                                    .fixedSize(horizontal: true, vertical: false)
                                }
                            }
                        }
                    }
                    .padding(14)
                    .background(RoundedRectangle(cornerRadius: 10).fill(Color.secondary.opacity(0.06)))
                    .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

                    // Row A: Portable Workspace Backup & Restore
                    VStack(alignment: .leading, spacing: 10) {
                        HStack(alignment: .center, spacing: 16) {
                            ZStack {
                                RoundedRectangle(cornerRadius: 8)
                                    .fill(Color.teal.opacity(0.14))
                                    .frame(width: 34, height: 34)
                                Image(systemName: "externaldrive.fill.badge.checkmark")
                                    .font(.system(size: 15, weight: .semibold))
                                    .foregroundColor(.teal)
                            }
                            VStack(alignment: .leading, spacing: 3) {
                                Text("Portable Workspace Backup & Restore")
                                    .font(.system(size: 13, weight: .bold))
                                    .foregroundColor(.primary)
                                Text("Export a complete snapshot (Knowledge Base, Resumes, Connections, AI Skills & Databases) or restore from an archive.")
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            HStack(spacing: 10) {
                                Button {
                                    store.exportAllDataWithSavePanel()
                                } label: {
                                    Label("Export All Data", systemImage: "square.and.arrow.up")
                                        .font(.system(size: 13, weight: .bold))
                                        .padding(.horizontal, 8)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)
                                }
                                .buttonStyle(.borderedProminent)
                                .controlSize(.large)
                                .fixedSize(horizontal: true, vertical: false)

                                Button {
                                    store.importAllDataWithOpenPanel()
                                } label: {
                                    Label("Import Data…", systemImage: "square.and.arrow.down")
                                        .font(.system(size: 13, weight: .semibold))
                                        .padding(.horizontal, 6)
                                        .lineLimit(1)
                                        .fixedSize(horizontal: true, vertical: false)
                                }
                                .buttonStyle(.bordered)
                                .controlSize(.large)
                                .fixedSize(horizontal: true, vertical: false)
                            }
                        }

                        if !store.lastExportPath.isEmpty {
                            HStack(spacing: 8) {
                                Image(systemName: "checkmark.circle.fill")
                                    .foregroundColor(.green)
                                    .font(.caption)
                                Text("Latest backup: \(store.lastExportPath)")
                                    .font(.system(size: 11, design: .monospaced))
                                    .foregroundColor(.secondary)
                                    .lineLimit(1)
                                    .truncationMode(.middle)
                                Button("Reveal in Finder") {
                                    store.openFileOnMac(store.lastExportPath, revealInFinder: true)
                                }
                                .buttonStyle(.link)
                                .font(.caption.bold())
                                Spacer()
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(RoundedRectangle(cornerRadius: 7).fill(Color.green.opacity(0.08)))
                        }

                        if !store.lastImportPath.isEmpty {
                            HStack(spacing: 8) {
                                Image(systemName: "arrow.down.circle.fill")
                                    .foregroundColor(.teal)
                                    .font(.caption)
                                Text("Restored from: \(store.lastImportPath)")
                                    .font(.system(size: 11, design: .monospaced))
                                    .foregroundColor(.secondary)
                                    .lineLimit(1)
                                    .truncationMode(.middle)
                                Spacer()
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(RoundedRectangle(cornerRadius: 7).fill(Color.teal.opacity(0.08)))
                        }
                    }
                    .padding(14)
                    .background(RoundedRectangle(cornerRadius: 10).fill(Color.secondary.opacity(0.06)))
                    .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

                    // Row B: Setup Wizard
                    HStack(alignment: .center, spacing: 16) {
                        ZStack {
                            RoundedRectangle(cornerRadius: 8)
                                .fill(Color.accentColor.opacity(0.14))
                                .frame(width: 34, height: 34)
                            Image(systemName: "sparkles")
                                .font(.system(size: 15, weight: .semibold))
                                .foregroundColor(.accentColor)
                        }
                        VStack(alignment: .leading, spacing: 3) {
                            Text("Guided Setup Wizard")
                                .font(.system(size: 13, weight: .bold))
                                .foregroundColor(.primary)
                            Text("Re-open the 5-step onboarding wizard to review AI providers, browser accounts, or base resume import.")
                                .font(.system(size: 11.5))
                                .foregroundColor(.secondary)
                        }
                        Spacer()
                        Button {
                            store.isSetupWizardReopened = true
                            store.sendAction("reopen_onboarding", payload: ["step": "O-01"])
                            store.selectedSection = .setup
                        } label: {
                            Label("Open Setup Wizard", systemImage: "wand.and.stars")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 6)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                    .padding(14)
                    .background(RoundedRectangle(cornerRadius: 10).fill(Color.secondary.opacity(0.06)))
                    .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.secondary.opacity(0.14), lineWidth: 1))

                    // Row C: Danger Zone — Destructive Actions
                    VStack(alignment: .leading, spacing: 12) {
                        HStack(spacing: 6) {
                            Image(systemName: "exclamationmark.octagon.fill")
                                .font(.system(size: 12, weight: .bold))
                                .foregroundColor(.red)
                            Text("DANGER ZONE — IRREVERSIBLE ACTIONS")
                                .font(.system(size: 10.5, weight: .heavy))
                                .tracking(0.6)
                                .foregroundColor(.red)
                            Spacer()
                        }

                        Divider().opacity(0.5)

                        // Reset Workspace
                        HStack(alignment: .center, spacing: 16) {
                            VStack(alignment: .leading, spacing: 3) {
                                Text("Reset Workspace to Clean State")
                                    .font(.system(size: 13, weight: .bold))
                                    .foregroundColor(.primary)
                                Text("Clears the current job queue and resets workspace preferences back to factory defaults.")
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            Button {
                                store.confirmAndResetToCleanState()
                            } label: {
                                Label("Reset Workspace", systemImage: "arrow.counterclockwise")
                                    .font(.system(size: 13, weight: .semibold))
                                    .padding(.horizontal, 6)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.bordered)
                            .tint(.red)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                        }

                        Divider().opacity(0.5)

                        // Uninstall AutoApply
                        HStack(alignment: .center, spacing: 16) {
                            VStack(alignment: .leading, spacing: 3) {
                                Text("Uninstall AutoApply from This Mac")
                                    .font(.system(size: 13, weight: .bold))
                                    .foregroundColor(.primary)
                                Text("Completely removes AutoApply, its background helpers, browser profiles, and local application support data.")
                                    .font(.system(size: 11.5))
                                    .foregroundColor(.secondary)
                            }
                            Spacer()
                            Button(role: .destructive) {
                                store.confirmAndRunCleanUninstall()
                            } label: {
                                Label("Uninstall AutoApply…", systemImage: "trash.fill")
                                    .font(.system(size: 13, weight: .bold))
                                    .padding(.horizontal, 8)
                                    .lineLimit(1)
                                    .fixedSize(horizontal: true, vertical: false)
                            }
                            .buttonStyle(.borderedProminent)
                            .tint(.red)
                            .controlSize(.large)
                            .fixedSize(horizontal: true, vertical: false)
                        }
                    }
                    .padding(14)
                    .background(RoundedRectangle(cornerRadius: 10).fill(Color.red.opacity(0.06)))
                    .overlay(RoundedRectangle(cornerRadius: 10).stroke(Color.red.opacity(0.32), lineWidth: 1))
                }
            }
        }
        .onAppear {
            store.expandedWorkPrefItemId = store.isLicenseActivated ? "" : "license_section"
        }
        .onChange(of: store.isLicenseActivated) { isActivated in
            store.expandedWorkPrefItemId = isActivated ? "" : "license_section"
        }
    }
}

struct SoftwareUpdateSheetView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack(alignment: .center, spacing: 12) {
                Image(
                    systemName: store.isForceUpdateLocked
                        ? "exclamationmark.arrow.triangle.2.circlepath"
                        : (store.updateAvailable ? "arrow.down.circle.fill" : "checkmark.circle.fill")
                )
                .font(.system(size: 32, weight: .semibold))
                .foregroundColor(
                    store.isForceUpdateLocked
                        ? .orange
                        : (store.updateAvailable ? .green : .accentColor)
                )

                VStack(alignment: .leading, spacing: 4) {
                    Text(
                        store.isForceUpdateLocked
                            ? "Required Update Available (v\(store.latestAppVersion))"
                            : (store.updateAvailable
                                ? "Update Available (v\(store.latestAppVersion))"
                                : "AutoApply is Up to Date")
                    )
                    .font(.system(size: 15, weight: .bold))
                    Text(
                        store.updateAvailable
                            ? "Current version: v\(store.currentAppVersion)  →  New version: v\(store.latestAppVersion)"
                            : "Version \(store.currentAppVersion) · Checked daily"
                    )
                    .font(.system(size: 12))
                    .foregroundColor(.secondary)
                }
                Spacer()
            }

            if store.isForceUpdateLocked {
                Text("This update is required to continue running AutoApply. Automations and execution are paused until you update. You can still access Settings and browse your workspace in view-only mode.")
                    .font(.system(size: 12))
                    .foregroundColor(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(10)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .background(RoundedRectangle(cornerRadius: 8).fill(Color.secondary.opacity(0.08)))
            }

            if store.updateAvailable && !store.updateReleaseNotes.isEmpty {
                VStack(alignment: .leading, spacing: 4) {
                    Text("Release Notes")
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundColor(.secondary)
                    Text(store.updateReleaseNotes)
                        .font(.system(size: 12))
                        .foregroundColor(.primary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(10)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: 8).fill(Color.secondary.opacity(0.06)))
            }

            Toggle("Automatically check for updates daily", isOn: $store.autoCheckForUpdates)
                .toggleStyle(.checkbox)
                .font(.caption)

            Divider()

            HStack(spacing: 10) {
                Button {
                    store.sendAction("check_for_updates", payload: [
                        "channel": store.updateChannel,
                        "feed_url": store.updateFeedUrl,
                        "auto_check": store.autoCheckForUpdates,
                    ])
                } label: {
                    Label("Check Again", systemImage: "arrow.clockwise")
                        .font(.system(size: 12.5, weight: .medium))
                }
                .buttonStyle(.bordered)
                .controlSize(.regular)

                Spacer()

                if store.isForceUpdateLocked {
                    Button {
                        store.selectedSection = .settings
                        store.showUpdateModal = false
                    } label: {
                        Text("Settings")
                            .font(.system(size: 12.5, weight: .medium))
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.regular)

                    Button {
                        store.showUpdateModal = false
                    } label: {
                        Text("View-Only Mode")
                            .font(.system(size: 12.5, weight: .medium))
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.regular)

                    Button {
                        store.sendAction("install_update", payload: [
                            "target_version": store.latestAppVersion,
                        ])
                        if !store.isForceUpdateLocked {
                            store.showUpdateModal = false
                        }
                    } label: {
                        Label("Update Now", systemImage: "arrow.down.circle.fill")
                            .font(.system(size: 12.5, weight: .semibold))
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.regular)
                } else if store.updateAvailable {
                    Button {
                        store.sendActionInBackground("dismiss_daily_update_prompt", payload: [:], silent: true, preserveLocalEdits: true)
                        store.showUpdateModal = false
                    } label: {
                        Text("Remind Me Tomorrow")
                            .font(.system(size: 12.5, weight: .medium))
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.regular)

                    Button {
                        store.sendAction("install_update", payload: [
                            "target_version": store.latestAppVersion,
                        ])
                        store.showUpdateModal = false
                    } label: {
                        Label("Install Update", systemImage: "arrow.down.circle.fill")
                            .font(.system(size: 12.5, weight: .semibold))
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.regular)
                } else {
                    Button {
                        store.showUpdateModal = false
                    } label: {
                        Text("OK")
                            .font(.system(size: 12.5, weight: .semibold))
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.regular)
                }
            }
        }
        .padding(22)
        .frame(width: 480)
    }
}

// MARK: - Reusable Visual UI Components

struct CardBox<Content: View>: View {
    let title: String
    let icon: String
    @ViewBuilder let content: () -> Content

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Image(systemName: icon)
                    .font(.system(size: 15, weight: .semibold))
                    .foregroundColor(.accentColor)
                Text(title)
                    .font(.system(size: 15, weight: .bold))
                Spacer()
            }
            content()
        }
        .padding(16)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 12)
                .fill(Color(NSColor.controlBackgroundColor).opacity(0.65))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(Color.secondary.opacity(0.16), lineWidth: 1)
        )
    }
}

struct AccordionCardBox<Content: View>: View {
    let itemId: String
    @Binding var expandedId: String
    let title: String
    var subtitle: String = ""
    let icon: String
    var badgeText: String = ""
    var badgeColor: Color = .accentColor
    var isDangerZone: Bool = false
    @ViewBuilder let content: () -> Content

    private var isExpanded: Bool {
        expandedId == itemId
    }

    private var activeThemeColor: Color {
        isDangerZone ? .red : .accentColor
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Button {
                expandedId = isExpanded ? "" : itemId
            } label: {
                HStack(spacing: 12) {
                    ZStack {
                        RoundedRectangle(cornerRadius: 8)
                            .fill(
                                isDangerZone
                                    ? Color.red.opacity(isExpanded ? 0.20 : 0.12)
                                    : (isExpanded ? Color.accentColor.opacity(0.16) : Color.secondary.opacity(0.10))
                            )
                            .frame(width: 32, height: 32)
                        Image(systemName: icon)
                            .font(.system(size: 14, weight: .semibold))
                            .foregroundColor(isDangerZone ? .red : (isExpanded ? .accentColor : .secondary))
                    }
                    VStack(alignment: .leading, spacing: 2) {
                        Text(title)
                            .font(.system(size: 14, weight: .bold))
                            .foregroundColor(.primary)
                        if !subtitle.isEmpty {
                            Text(subtitle)
                                .font(.caption)
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                        }
                    }
                    Spacer()
                    if !badgeText.isEmpty {
                        StatusBadge(text: badgeText, color: badgeColor)
                    }
                    Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                        .font(.system(size: 11, weight: .bold))
                        .foregroundColor(isDangerZone ? .red.opacity(0.85) : .secondary)
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 12)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)

            if isExpanded {
                Divider()
                    .padding(.horizontal, 16)
                VStack(alignment: .leading, spacing: 12) {
                    content()
                }
                .padding(16)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 12)
                .fill(Color(NSColor.controlBackgroundColor).opacity(isExpanded ? 0.85 : 0.62))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(
                    isDangerZone
                        ? Color.red.opacity(isExpanded ? 0.50 : 0.28)
                        : (isExpanded ? activeThemeColor.opacity(0.45) : Color.secondary.opacity(0.16)),
                    lineWidth: isExpanded ? 1.5 : 1
                )
        )
    }
}

