struct ToastNotificationOverlayView: View {
    @ObservedObject var store: WorkspaceStore

    var body: some View {
        VStack(alignment: .trailing, spacing: 8) {
            if !store.errorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                BannerAlert(
                    icon: "exclamationmark.triangle.fill",
                    text: store.errorMessage,
                    color: .red
                ) {
                    withAnimation(.easeInOut(duration: 0.18)) {
                        store.errorMessage = ""
                    }
                }
                .transition(.move(edge: .top).combined(with: .opacity))
            }
            if !store.statusBannerMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                BannerAlert(
                    icon: store.statusBannerIcon,
                    text: store.statusBannerMessage,
                    color: store.statusBannerColor
                ) {
                    withAnimation(.easeInOut(duration: 0.18)) {
                        store.statusBannerMessage = ""
                    }
                }
                .transition(.move(edge: .top).combined(with: .opacity))
            }
        }
        .zIndex(100)
    }
}

struct BannerAlert: View {
    let icon: String
    let text: String
    let color: Color
    let onDismiss: () -> Void

    static func sanitizeNotificationText(_ raw: String) -> String {
        var cleaned = raw
            .replacingOccurrences(of: " (Submitted to AutoApply Feedback Server (@AutoApplyFeedbackBot))", with: "")
            .replacingOccurrences(of: " (Saved Locally & Queued for Feedback Server Retry)", with: "")
            .replacingOccurrences(of: " (Saved Locally & Queued for Feedback Server)", with: "")
            .replacingOccurrences(of: "(@AutoApplyFeedbackBot)", with: "")
            .replacingOccurrences(of: "@AutoApplyFeedbackBot", with: "")
            .replacingOccurrences(of: "AutoApply Feedback Server", with: "")
            .replacingOccurrences(of: "JEV (~typesafe/jev-latest) synced & classified ", with: "Synced ")
            .replacingOccurrences(of: "conversation threads • ", with: "conversations. ")
            .replacingOccurrences(of: "require action from your side.", with: "require your attention.")
            .replacingOccurrences(of: "JEV (~typesafe/jev-latest): ", with: "")
            .replacingOccurrences(of: "JEV-verified ", with: "")
            .replacingOccurrences(of: " using VB Jobs canon", with: "")
            .replacingOccurrences(of: " via JEV", with: "")
            .replacingOccurrences(of: "JEV: ", with: "")
            .replacingOccurrences(of: "Bridge execution error: ", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        // Normalize legacy feedback submission notice if encountered
        let lower = cleaned.lowercased()
        if lower.hasPrefix("submitted ") && lower.contains("feedback") {
            let digits = cleaned.components(separatedBy: CharacterSet.decimalDigits.inverted).joined()
            let count = Int(digits) ?? 0
            if count == 0 {
                cleaned = "Feedback sent successfully\nYour feedback has been submitted."
            } else if count == 1 {
                cleaned = "Feedback sent successfully\nYour feedback and 1 attachment have been submitted."
            } else {
                cleaned = "Feedback sent successfully\nYour feedback and \(count) attachments have been submitted."
            }
        }
        return cleaned
    }

    static func parsedTitleAndSubtitle(from raw: String, icon: String, color: Color) -> (title: String, subtitle: String) {
        let cleaned = sanitizeNotificationText(raw)
        guard !cleaned.isEmpty else { return ("", "") }

        if let newlineRange = cleaned.range(of: "\n") {
            let title = String(cleaned[..<newlineRange.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            let subtitle = String(cleaned[newlineRange.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
            return (title, subtitle)
        }

        if let dashRange = cleaned.range(of: " — ") {
            let title = String(cleaned[..<dashRange.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            let subtitle = String(cleaned[dashRange.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
            if title.count <= 48 {
                return (title, subtitle)
            }
        }

        if let dotSpaceRange = cleaned.range(of: ". ") {
            let firstSentence = String(cleaned[..<dotSpaceRange.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            let remainder = String(cleaned[dotSpaceRange.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
            if firstSentence.count <= 56 && !remainder.isEmpty {
                return (firstSentence, remainder)
            }
        }

        if cleaned.count <= 50 {
            let trimmedTitle = cleaned.hasSuffix(".") ? String(cleaned.dropLast()) : cleaned
            return (trimmedTitle, "")
        }

        let lower = cleaned.lowercased()
        let fallbackTitle: String
        if icon.contains("exclamationmark.triangle") || color == .red {
            if lower.contains("license") {
                fallbackTitle = "License activation failed"
            } else if lower.contains("update") {
                fallbackTitle = "Update required"
            } else {
                fallbackTitle = "Action could not be completed"
            }
        } else if icon.contains("exclamationmark.circle") || color == .orange {
            fallbackTitle = "Attention required"
        } else if icon.contains("info.circle") {
            fallbackTitle = "Status update"
        } else if lower.contains("queued") {
            fallbackTitle = "Message queued"
        } else if lower.contains("sending") {
            fallbackTitle = "Sending message"
        } else if lower.contains("models updated") {
            fallbackTitle = "Models updated"
        } else {
            fallbackTitle = "Completed"
        }
        return (fallbackTitle, cleaned)
    }

    var body: some View {
        let parsed = Self.parsedTitleAndSubtitle(from: text, icon: icon, color: color)
        HStack(alignment: parsed.subtitle.isEmpty ? .center : .top, spacing: 10) {
            Image(systemName: icon)
                .font(.system(size: 13.5, weight: .semibold))
                .foregroundColor(color.opacity(0.85))
                .padding(.top, parsed.subtitle.isEmpty ? 0 : 1.5)

            VStack(alignment: .leading, spacing: 2.5) {
                Text(parsed.title)
                    .font(.system(size: 12.5, weight: .semibold))
                    .foregroundColor(.primary)
                    .lineLimit(1)

                if !parsed.subtitle.isEmpty {
                    Text(parsed.subtitle)
                        .font(.system(size: 11.5, weight: .regular))
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .layoutPriority(1)

            Spacer(minLength: 6)

            Button(action: onDismiss) {
                Image(systemName: "xmark")
                    .font(.system(size: 9.5, weight: .semibold))
                    .foregroundColor(.secondary.opacity(0.75))
                    .frame(width: 18, height: 18)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .help("Dismiss notification")
        }
        .padding(.horizontal, 13)
        .padding(.vertical, 9.5)
        .frame(minWidth: 260, maxWidth: 390, alignment: .leading)
        .fixedSize(horizontal: false, vertical: true)
        .background(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .fill(Color(NSColor.controlBackgroundColor).opacity(0.98))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(Color.primary.opacity(0.11), lineWidth: 1)
        )
        .shadow(color: Color.black.opacity(0.26), radius: 10, x: 0, y: 4)
    }
}

// MARK: - AI Agent Chat Section, Model Dropdowns, Composer & Markdown Table Renderer

struct AIModelDropdownControl: View {
    @ObservedObject var store: WorkspaceStore
    let role: String // "logic" or "writer"
    let compact: Bool

    private var isWriter: Bool {
        role == "writer"
    }

    private var catalog: [AIModelChoiceItem] {
        isWriter ? AIModelChoiceItem.writerCatalog : AIModelChoiceItem.logicCatalog
    }

    private var selectedModelId: String {
        isWriter ? store.hermesWriterModel : AIModelChoiceItem.normalizeLogicModelId(store.hermesLogicModel)
    }

    private var selectedEffort: String {
        isWriter ? store.hermesWriterReasoningEffort : store.hermesLogicReasoningEffort
    }

    private var isCustomModelSelected: Bool {
        !catalog.contains(where: { $0.id == selectedModelId })
    }

    private var rolePrefix: String {
        isWriter ? "Copywriting:" : "Logic:"
    }

    private var shortModelTitle: String {
        isWriter
            ? AIModelChoiceItem.shortWriterTitle(for: selectedModelId)
            : AIModelChoiceItem.shortLogicTitle(for: selectedModelId)
    }

    private func selectModelAndEffort(modelId: String, effort: String) {
        if isWriter {
            store.updateAIModels(
                logicModel: nil,
                writerModel: modelId,
                logicReasoningEffort: nil,
                writerReasoningEffort: effort
            )
        } else {
            store.updateAIModels(
                logicModel: modelId,
                writerModel: nil,
                logicReasoningEffort: effort,
                writerReasoningEffort: nil
            )
        }
    }

    @ViewBuilder
    private func modelMenuItem(_ choice: AIModelChoiceItem) -> some View {
        let isCurrentModel = (selectedModelId == choice.id)
        Menu {
            ForEach(AIModelChoiceItem.reasoningEffortLevels, id: \.id) { effort in
                Button {
                    selectModelAndEffort(modelId: choice.id, effort: effort.id)
                } label: {
                    HStack {
                        Text("Reasoning Effort: \(effort.label) — \(effort.subtitle)")
                        if isCurrentModel && selectedEffort == effort.id {
                            Image(systemName: "checkmark")
                        }
                    }
                }
            }
        } label: {
            Text(isCurrentModel ? "✓ \(choice.menuLabel) [\(selectedEffort.capitalized)]" : choice.menuLabel)
        }
    }

    var body: some View {
        Menu {
            if isCustomModelSelected && !selectedModelId.isEmpty {
                Menu {
                    ForEach(AIModelChoiceItem.reasoningEffortLevels, id: \.id) { effort in
                        Button {
                            selectModelAndEffort(modelId: selectedModelId, effort: effort.id)
                        } label: {
                            HStack {
                                Text("Reasoning Effort: \(effort.label) — \(effort.subtitle)")
                                if selectedEffort == effort.id {
                                    Image(systemName: "checkmark")
                                }
                            }
                        }
                    }
                } label: {
                    Text("✓ Custom (\(selectedModelId)) [\(selectedEffort.capitalized)]")
                }
                Divider()
            }

            if isWriter {
                ForEach(AIModelChoiceItem.writerCatalog) { choice in
                    modelMenuItem(choice)
                }
            } else {
                Section("Provider: OpenAI Codex (ChatGPT Subscription — $0 Token Cost)") {
                    ForEach(AIModelChoiceItem.codexCatalog) { choice in
                        modelMenuItem(choice)
                    }
                }

                Divider()

                Section("Provider: OpenRouter Models") {
                    ForEach(AIModelChoiceItem.openRouterLogicCatalog) { choice in
                        modelMenuItem(choice)
                    }
                }
            }

            Divider()

            Menu("Reasoning Effort (\(selectedEffort.capitalized))") {
                ForEach(AIModelChoiceItem.reasoningEffortLevels, id: \.id) { effort in
                    Button {
                        selectModelAndEffort(modelId: selectedModelId, effort: effort.id)
                    } label: {
                        HStack {
                            Text("\(effort.label) — \(effort.subtitle)")
                            if selectedEffort == effort.id {
                                Image(systemName: "checkmark")
                            }
                        }
                    }
                }
            }

            Divider()

            Button {
                store.openCustomOpenRouterModelPrompt(role: role)
            } label: {
                Label(
                    isWriter
                        ? "Other OpenRouter Model (Search / Paste ID)…"
                        : "Search / Specify Model (Codex ChatGPT or OpenRouter)…",
                    systemImage: "magnifyingglass.circle"
                )
            }
        } label: {
            HStack(spacing: 6) {
                Text(rolePrefix)
                    .font(.system(size: compact ? 11 : 11.5, weight: .medium))
                    .foregroundColor(.secondary)
                Text(shortModelTitle)
                    .font(.system(size: compact ? 11.5 : 12, weight: .semibold))
                    .foregroundColor(.primary)
                    .lineLimit(1)
                Text("(\(AIModelChoiceItem.shortEffortLabel(for: selectedEffort)))")
                    .font(.system(size: compact ? 10.5 : 11, weight: .medium))
                    .foregroundColor(.secondary)
                if !compact {
                    Spacer(minLength: 4)
                }
                Rectangle()
                    .fill(Color.secondary.opacity(0.22))
                    .frame(width: 1, height: compact ? 13 : 15)
                    .padding(.leading, 2)
                Image(systemName: "chevron.down")
                    .font(.system(size: compact ? 9 : 10, weight: .semibold))
                    .foregroundColor(.secondary)
            }
            .padding(.horizontal, compact ? 9 : 10)
            .padding(.vertical, compact ? 5 : 7)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(NSColor.textBackgroundColor))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 6)
                    .stroke(Color.secondary.opacity(0.32), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
        .fixedSize(horizontal: compact, vertical: true)
        .help("Select \(isWriter ? "Copywriting" : "Logic") Model & Reasoning Effort (\(selectedModelId) • \(selectedEffort.capitalized))")
    }
}

struct CustomOpenRouterModelSheetView: View {
    @ObservedObject var store: WorkspaceStore

    private var isWriterRole: Bool {
        store.customModelRoleTarget == "writer"
    }

    private var matchingModels: [AIModelChoiceItem] {
        let basePool: [AIModelChoiceItem]
        if isWriterRole {
            basePool = AIModelChoiceItem.writerCatalog
        } else {
            switch store.customModelProviderFilter {
            case "codex":
                basePool = AIModelChoiceItem.codexCatalog
            case "openrouter":
                basePool = AIModelChoiceItem.openRouterLogicCatalog
            default:
                basePool = AIModelChoiceItem.logicCatalog
            }
        }
        let q = store.customModelIdInput.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return basePool }
        let wantsCodexAll = !isWriterRole && (q == "codex" || q == "chatgpt" || q == "codex chatgpt" || q == "chatgpt codex" || q == "openai codex" || q == "openai-codex")
        if wantsCodexAll {
            return AIModelChoiceItem.codexCatalog
        }
        let tokens = q.split(separator: " ").map { String($0) }
        return basePool.filter { item in
            let hay = "\(item.id) \(item.shortLabel) \(item.menuLabel) \(item.badge) \(item.id.hasPrefix("openai-codex/") ? "codex chatgpt openai subscription" : "openrouter")".lowercased()
            return tokens.allSatisfy { hay.contains($0) }
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(spacing: 10) {
                Image(systemName: "cpu.fill")
                    .font(.system(size: 18, weight: .semibold))
                    .foregroundColor(.accentColor)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Select or Specify Model (OpenAI Codex ChatGPT & OpenRouter)")
                        .font(.system(size: 15.5, weight: .bold))
                    Text("Type 'codex' or 'chatgpt' to list all applicable OpenAI Codex models, or enter any OpenRouter model ID.")
                        .font(.caption)
                        .foregroundColor(.secondary)
                }
                Spacer()
            }

            VStack(alignment: .leading, spacing: 6) {
                Text("Target Role")
                    .font(.system(size: 12, weight: .semibold))
                Picker("Target Role", selection: $store.customModelRoleTarget) {
                    Text("Logic & Reasoning (Supports OpenAI Codex & OpenRouter)").tag("logic")
                    Text("Copywriting (Resume & Cover Letter — OpenRouter)").tag("writer")
                }
                .pickerStyle(.segmented)
                .labelsHidden()
            }

            if !isWriterRole {
                VStack(alignment: .leading, spacing: 6) {
                    Text("Provider Filter")
                        .font(.system(size: 12, weight: .semibold))
                    Picker("Provider Filter", selection: $store.customModelProviderFilter) {
                        Text("All Applicable Models").tag("all")
                        Text("OpenAI Codex (ChatGPT Subscription — $0)").tag("codex")
                        Text("OpenRouter").tag("openrouter")
                    }
                    .pickerStyle(.segmented)
                    .labelsHidden()
                }
            }

            VStack(alignment: .leading, spacing: 6) {
                Text("Search Provider / Model or Paste Exact Model ID")
                    .font(.system(size: 12, weight: .semibold))
                TextField("Type 'codex chatgpt' or paste e.g. openai-codex/gpt-6.1-sol or ~deepseek/deepseek-pro-latest", text: $store.customModelIdInput)
                    .textFieldStyle(.roundedBorder)
                    .font(.system(size: 13, design: .monospaced))
            }

            VStack(alignment: .leading, spacing: 6) {
                HStack {
                    Text("Applicable Models (\(matchingModels.count))")
                        .font(.system(size: 11.5, weight: .semibold))
                        .foregroundColor(.secondary)
                    Spacer()
                    Text("Click any model to select")
                        .font(.caption2)
                        .foregroundColor(.secondary)
                }
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 6) {
                        ForEach(matchingModels) { item in
                            let isCodex = item.id.hasPrefix("openai-codex/")
                            let isSelected = store.customModelIdInput.trimmingCharacters(in: .whitespacesAndNewlines) == item.id
                                || (store.customModelIdInput.isEmpty && (isWriterRole ? store.hermesWriterModel : AIModelChoiceItem.normalizeLogicModelId(store.hermesLogicModel)) == item.id)
                            Button {
                                store.customModelIdInput = item.id
                                store.saveCustomOpenRouterModel()
                            } label: {
                                HStack(alignment: .center, spacing: 10) {
                                    VStack(alignment: .leading, spacing: 2) {
                                        HStack(spacing: 6) {
                                            Text(item.shortLabel)
                                                .font(.system(size: 12.5, weight: .bold))
                                                .foregroundColor(.primary)
                                            Text(item.id)
                                                .font(.system(size: 11, design: .monospaced))
                                                .foregroundColor(.secondary)
                                        }
                                        Text(item.menuLabel)
                                            .font(.system(size: 11))
                                            .foregroundColor(.secondary)
                                            .lineLimit(1)
                                    }
                                    Spacer()
                                    Text(item.badge)
                                        .font(.system(size: 10, weight: .semibold))
                                        .foregroundColor(isCodex ? .teal : .accentColor)
                                        .padding(.horizontal, 7)
                                        .padding(.vertical, 3)
                                        .background(
                                            Capsule()
                                                .fill((isCodex ? Color.teal : Color.accentColor).opacity(0.14))
                                        )
                                    if isSelected {
                                        Image(systemName: "checkmark.circle.fill")
                                            .foregroundColor(.teal)
                                    }
                                }
                                .padding(.horizontal, 10)
                                .padding(.vertical, 7)
                                .background(
                                    RoundedRectangle(cornerRadius: 7)
                                        .fill(isSelected ? Color.teal.opacity(0.10) : Color(NSColor.controlBackgroundColor))
                                )
                                .overlay(
                                    RoundedRectangle(cornerRadius: 7)
                                        .stroke(isSelected ? Color.teal.opacity(0.45) : Color.secondary.opacity(0.18), lineWidth: 1)
                                )
                            }
                            .buttonStyle(.plain)
                        }
                    }
                }
                .frame(height: 195)
            }

            VStack(alignment: .leading, spacing: 6) {
                Text("Reasoning Effort")
                    .font(.system(size: 12, weight: .semibold))
                Picker("Reasoning Effort", selection: $store.customModelReasoningEffort) {
                    Text("Low").tag("low")
                    Text("Medium").tag("medium")
                    Text("High").tag("high")
                }
                .pickerStyle(.segmented)
                .labelsHidden()
            }

            HStack {
                Button {
                    store.showCustomModelSheet = false
                } label: {
                    Label("Cancel", systemImage: "xmark")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)

                Spacer()

                Button {
                    store.saveCustomOpenRouterModel()
                } label: {
                    Label("Use Selected Model", systemImage: "checkmark.circle.fill")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .disabled(store.customModelIdInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding(.top, 2)
        }
        .padding(22)
        .frame(width: 560)
    }
}

final class ChatInputNSTextView: NSTextView {
    var onSubmit: (() -> Void)?
    var placeholderString: String = "Message AutoApply…"

    override func keyDown(with event: NSEvent) {
        // Return (36) or Keypad Enter (76)
        if (event.keyCode == 36 || event.keyCode == 76) && !hasMarkedText() {
            let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
            if flags.contains(.shift) {
                super.insertNewlineIgnoringFieldEditor(nil)
                return
            } else {
                onSubmit?()
                return
            }
        }
        super.keyDown(with: event)
    }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)
        if string.isEmpty {
            let attrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: 13.5),
                .foregroundColor: NSColor.placeholderTextColor,
            ]
            NSString(string: placeholderString).draw(at: NSPoint(x: 2, y: 4), withAttributes: attrs)
        }
    }
}

struct ChatComposerTextView: NSViewRepresentable {
    @Binding var text: String
    var placeholder: String
    var onSubmit: () -> Void

    final class Coordinator: NSObject, NSTextViewDelegate {
        var parent: ChatComposerTextView

        init(_ parent: ChatComposerTextView) {
            self.parent = parent
        }

        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            if parent.text != textView.string {
                parent.text = textView.string
            }
            textView.needsDisplay = true
        }
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    func makeNSView(context: Context) -> NSScrollView {
        let scrollView = NSScrollView()
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.borderType = .noBorder
        scrollView.drawsBackground = false

        let textView = ChatInputNSTextView()
        textView.delegate = context.coordinator
        textView.placeholderString = placeholder
        textView.onSubmit = {
            context.coordinator.parent.onSubmit()
        }
        textView.isRichText = false
        textView.importsGraphics = false
        textView.isEditable = true
        textView.isSelectable = true
        textView.allowsUndo = true
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.drawsBackground = false
        textView.font = NSFont.systemFont(ofSize: 13.5)
        textView.textColor = NSColor.labelColor
        textView.textContainerInset = NSSize(width: 0, height: 4)
        textView.textContainer?.lineFragmentPadding = 2
        textView.textContainer?.widthTracksTextView = true
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.autoresizingMask = [.width]
        textView.string = text

        scrollView.documentView = textView
        return scrollView
    }

    func updateNSView(_ nsView: NSScrollView, context: Context) {
        context.coordinator.parent = self
        guard let textView = nsView.documentView as? ChatInputNSTextView else { return }
        textView.placeholderString = placeholder
        textView.onSubmit = {
            context.coordinator.parent.onSubmit()
        }
        if textView.string != text {
            textView.string = text
            textView.needsDisplay = true
        }
    }
}

