struct HermesAgentChatView: View {
    @ObservedObject var store: WorkspaceStore
    @ObservedObject var recorder: VoiceRecorderController

    init(store: WorkspaceStore) {
        self.store = store
        self.recorder = store.voiceRecorder
    }

    private var activeSession: HermesChatSessionItem? {
        store.activeHermesSession
    }

    private var cleanSessionTitle: String {
        guard let rawTitle = activeSession?.title, !rawTitle.isEmpty else {
            return "Conversation"
        }
        return rawTitle
            .replacingOccurrences(of: "Hermes Sandbox Session", with: "Conversation")
            .replacingOccurrences(of: "AutoApply AI Agent", with: "Conversation")
            .replacingOccurrences(of: "Hermes", with: "AutoApply")
    }

    private var canSendMessage: Bool {
        !store.hermesPromptInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || !store.hermesPendingAttachments.isEmpty
    }

    var body: some View {
        VStack(spacing: 0) {
            // Pinned Header Toolbar: Thread Switcher & New Conversation
            HStack(spacing: 10) {
                Menu {
                    ForEach(store.hermesSessions) { session in
                        let title = session.title
                            .replacingOccurrences(of: "Hermes Sandbox Session", with: "Conversation")
                            .replacingOccurrences(of: "AutoApply AI Agent", with: "Conversation")
                            .replacingOccurrences(of: "Hermes", with: "AutoApply")
                        Button {
                            store.selectHermesSession(session.id)
                        } label: {
                            HStack {
                                Text(title)
                                if session.id == activeSession?.id {
                                    Image(systemName: "checkmark")
                                }
                            }
                        }
                    }
                    if store.hermesSessions.count > 1, let curId = activeSession?.id {
                        Divider()
                        Button(role: .destructive) {
                            store.pendingDeleteChatSessionId = curId
                        } label: {
                            Label("Delete Conversation", systemImage: "trash")
                        }
                    }
                } label: {
                    HStack(spacing: 6) {
                        Image(systemName: "bubble.left.and.bubble.right.fill")
                            .font(.system(size: 11, weight: .semibold))
                            .foregroundColor(.accentColor)
                        Text(cleanSessionTitle)
                            .lineLimit(1)
                        Image(systemName: "chevron.down")
                            .font(.system(size: 9, weight: .semibold))
                            .foregroundColor(.secondary)
                    }
                    .font(.system(size: 12.5, weight: .semibold))
                    .foregroundColor(.primary)
                    .padding(.horizontal, 10)
                    .padding(.vertical, 5)
                    .background(
                        RoundedRectangle(cornerRadius: 6)
                            .fill(Color(NSColor.textBackgroundColor))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 6)
                            .stroke(Color.secondary.opacity(0.26), lineWidth: 1)
                    )
                }
                .buttonStyle(.plain)
                .fixedSize()

                Spacer()

                Button {
                    store.createNewHermesSession()
                } label: {
                    Label("New Chat", systemImage: "square.and.pencil")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .help("New Conversation")
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 10)
            .background(Color(NSColor.controlBackgroundColor).opacity(0.55))

            Divider()

            // Dedicated Scrollable Chat Stream (scrolls ONLY the messages, never the outer window)
            ScrollViewReader { proxy in
                ScrollView(.vertical, showsIndicators: true) {
                    LazyVStack(alignment: .leading, spacing: 16) {
                        if let session = activeSession {
                            ForEach(session.messages) { msg in
                                HermesMessageBubbleView(
                                    message: msg,
                                    providerLabel: store.hermesProviderLabel
                                )
                                .id(msg.id)
                            }
                        }
                        if store.isHermesSending {
                            HermesTypingIndicatorBubbleView()
                                .id("hermes-typing-indicator")
                        }
                    }
                    .padding(.horizontal, 22)
                    .padding(.vertical, 18)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .onAppear {
                    store.markAgentChatRead()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                        if store.isHermesSending {
                            proxy.scrollTo("hermes-typing-indicator", anchor: .bottom)
                        } else if let lastId = activeSession?.messages.last?.id {
                            proxy.scrollTo(lastId, anchor: .bottom)
                        }
                    }
                }
                .onChange(of: activeSession?.id ?? "") { _ in
                    if let lastId = activeSession?.messages.last?.id {
                        withAnimation(.easeOut(duration: 0.18)) {
                            proxy.scrollTo(lastId, anchor: .bottom)
                        }
                    }
                }
                .onChange(of: activeSession?.messages.count ?? 0) { _ in
                    withAnimation(.easeOut(duration: 0.2)) {
                        if store.isHermesSending {
                            proxy.scrollTo("hermes-typing-indicator", anchor: .bottom)
                        } else if let lastId = activeSession?.messages.last?.id {
                            proxy.scrollTo(lastId, anchor: .bottom)
                        }
                    }
                }
                .onChange(of: store.isHermesSending) { sending in
                    if sending {
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                            withAnimation(.easeOut(duration: 0.2)) {
                                proxy.scrollTo("hermes-typing-indicator", anchor: .bottom)
                            }
                        }
                    } else if let lastId = activeSession?.messages.last?.id {
                        withAnimation(.easeOut(duration: 0.2)) {
                            proxy.scrollTo(lastId, anchor: .bottom)
                        }
                    }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)

            Divider()

            // Pinned Bottom Composer
            VStack(alignment: .leading, spacing: 8) {
                if !store.hermesPendingAttachments.isEmpty {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 8) {
                            ForEach(store.hermesPendingAttachments) { att in
                                HStack(spacing: 6) {
                                    Image(systemName: iconForAttachmentKind(att.kind))
                                        .font(.system(size: 11.5, weight: .semibold))
                                        .foregroundColor(.teal)
                                    Text(att.name)
                                        .font(.system(size: 11, weight: .medium))
                                        .lineLimit(1)
                                    Button {
                                        store.removeHermesPendingAttachment(att.id)
                                    } label: {
                                        Image(systemName: "xmark.circle.fill")
                                            .font(.system(size: 12))
                                            .foregroundColor(.secondary)
                                    }
                                    .buttonStyle(.plain)
                                }
                                .padding(.horizontal, 9)
                                .padding(.vertical, 4)
                                .background(Capsule().fill(Color.secondary.opacity(0.12)))
                            }
                        }
                    }
                }

                VStack(alignment: .leading, spacing: 8) {
                    // Top Row: Flush-left text input (Enter to send, Shift+Enter for new line)
                    ChatComposerTextView(
                        text: $store.hermesPromptInput,
                        placeholder: "Message AutoApply… (Enter to send, Shift+Enter for new line)"
                    ) {
                        if canSendMessage && !store.isHermesSending {
                            store.sendHermesChatMessage()
                        }
                    }
                    .frame(minHeight: 38, maxHeight: 84)
                    .padding(.horizontal, 2)

                    // Bottom Row: Attach + Model Dropdowns + Microphone + Circular Up-Arrow Send Button on the same level
                    HStack(alignment: .center, spacing: 8) {
                        Button {
                            store.pickHermesAttachmentsWithOpenPanel()
                        } label: {
                            Image(systemName: "paperclip")
                                .font(.system(size: 13.5, weight: .medium))
                                .foregroundColor(.secondary)
                                .frame(width: 28, height: 28)
                                .background(
                                    RoundedRectangle(cornerRadius: 6)
                                        .fill(Color(NSColor.textBackgroundColor))
                                )
                                .overlay(
                                    RoundedRectangle(cornerRadius: 6)
                                        .stroke(Color.secondary.opacity(0.28), lineWidth: 1)
                                )
                        }
                        .buttonStyle(.plain)
                        .help("Attach files")

                        // Logic Model Dropdown (on the same level as the Send button)
                        AIModelDropdownControl(store: store, role: "logic", compact: true)

                        // Copywriting Model Dropdown (on the same level as the Send button)
                        AIModelDropdownControl(store: store, role: "writer", compact: true)

                        Spacer(minLength: 6)

                        if recorder.isChatRecording {
                            HStack(spacing: 5) {
                                Circle()
                                    .fill(Color.red)
                                    .frame(width: 7, height: 7)
                                Text("Recording \(recorder.formattedDuration)")
                                    .font(.system(size: 11, weight: .semibold, design: .monospaced))
                                    .foregroundColor(.red)
                            }
                            .padding(.horizontal, 8)
                            .padding(.vertical, 4)
                            .background(Capsule().fill(Color.red.opacity(0.12)))
                        } else if recorder.isTranscribing {
                            HStack(spacing: 5) {
                                ProgressView()
                                    .controlSize(.mini)
                                Text("Transcribing…")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.secondary)
                            }
                        }

                        // Stop button is strictly visible ONLY while an ongoing message is being processed
                        if store.isHermesSending {
                            Button {
                                store.stopHermesChatGeneration()
                            } label: {
                                HStack(spacing: 4) {
                                    Image(systemName: "stop.fill")
                                        .font(.system(size: 10, weight: .bold))
                                    Text("Stop")
                                        .font(.system(size: 11.5, weight: .semibold))
                                }
                                .foregroundColor(.white)
                                .padding(.horizontal, 10)
                                .padding(.vertical, 6)
                                .background(Capsule().fill(Color.red))
                            }
                            .buttonStyle(.plain)
                            .help("Stop generating response")
                        }

                        // Microphone Button next to Send Button
                        Button {
                            recorder.toggleChatMicrophoneRecording(store: store)
                        } label: {
                            Image(systemName: recorder.isChatRecording ? "waveform" : "mic.fill")
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundColor(recorder.isChatRecording ? .white : .primary)
                                .frame(width: 30, height: 30)
                                .background(
                                    Circle()
                                        .fill(recorder.isChatRecording ? Color.red : Color(NSColor.textBackgroundColor))
                                )
                                .overlay(
                                    Circle()
                                        .stroke(recorder.isChatRecording ? Color.red : Color.secondary.opacity(0.32), lineWidth: 1)
                                )
                        }
                        .buttonStyle(.plain)
                        .help(recorder.isChatRecording ? "Stop voice recording" : "Record voice message")

                        // Circular Up-Arrow Send Button (icon only)
                        Button {
                            store.sendHermesChatMessage()
                        } label: {
                            Image(systemName: "arrow.up")
                                .font(.system(size: 13.5, weight: .bold))
                                .foregroundColor(.white)
                                .frame(width: 30, height: 30)
                                .background(
                                    Circle()
                                        .fill(canSendMessage ? Color.accentColor : Color.secondary.opacity(0.28))
                                )
                        }
                        .buttonStyle(.plain)
                        .disabled(!canSendMessage)
                        .help("Send message (Enter)")
                    }
                }
                .padding(.horizontal, 10)
                .padding(.vertical, 9)
                .background(
                    RoundedRectangle(cornerRadius: 12)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 12)
                        .stroke(store.hermesDropTargeted ? Color.accentColor : Color.secondary.opacity(0.22), lineWidth: 1)
                )
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 12)
            .background(Color(NSColor.controlBackgroundColor).opacity(0.35))
            .onDrop(of: [.fileURL], isTargeted: $store.hermesDropTargeted) { providers in
                var handled = false
                for provider in providers {
                    if provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
                        handled = true
                        provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { item, _ in
                            var resolvedURL: URL?
                            if let data = item as? Data {
                                resolvedURL = URL(dataRepresentation: data, relativeTo: nil)
                            } else if let url = item as? URL {
                                resolvedURL = url
                            }
                            if let fileURL = resolvedURL {
                                Task { @MainActor in
                                    store.addHermesAttachmentPath(fileURL.path)
                                }
                            }
                        }
                    }
                }
                return handled
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(
            RoundedRectangle(cornerRadius: 14)
                .fill(Color(NSColor.windowBackgroundColor))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 14)
                .stroke(Color.secondary.opacity(0.14), lineWidth: 1)
        )
    }

    private func iconForAttachmentKind(_ kind: String) -> String {
        switch kind.lowercased() {
        case "pdf", "document": return "doc.richtext.fill"
        case "docx": return "doc.text.fill"
        case "image": return "photo.fill"
        case "audio": return "waveform"
        default: return "doc.fill"
        }
    }
}

struct MarkdownTableView: View {
    let headers: [String]
    let rows: [[String]]

    private var columnCount: Int {
        max(headers.count, rows.map { $0.count }.max() ?? 0)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Header Row
            HStack(alignment: .top, spacing: 0) {
                ForEach(0..<columnCount, id: \.self) { colIdx in
                    let cellText = colIdx < headers.count ? headers[colIdx] : ""
                    Text(inlineAttributed(cellText))
                        .font(.system(size: 12.5, weight: .bold))
                        .foregroundColor(.primary)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 10)
                        .padding(.vertical, 7)
                    if colIdx < columnCount - 1 {
                        Divider()
                    }
                }
            }
            .background(Color.teal.opacity(0.12))

            Divider()

            // Data Rows
            ForEach(Array(rows.enumerated()), id: \.offset) { rowIdx, row in
                HStack(alignment: .top, spacing: 0) {
                    ForEach(0..<columnCount, id: \.self) { colIdx in
                        let cellText = colIdx < row.count ? row[colIdx] : ""
                        Text(inlineAttributed(cellText))
                            .font(.system(size: 12.5))
                            .foregroundColor(.primary)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                        if colIdx < columnCount - 1 {
                            Divider()
                        }
                    }
                }
                .background(rowIdx % 2 == 1 ? Color.secondary.opacity(0.06) : Color.clear)

                if rowIdx < rows.count - 1 {
                    Divider()
                }
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 8))
        .overlay(
            RoundedRectangle(cornerRadius: 8)
                .stroke(Color.secondary.opacity(0.28), lineWidth: 1)
        )
        .padding(.vertical, 4)
    }

    private func inlineAttributed(_ raw: String) -> AttributedString {
        if let parsed = try? AttributedString(
            markdown: raw,
            options: AttributedString.MarkdownParsingOptions(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        ) {
            return parsed
        }
        return AttributedString(raw)
    }
}

struct ChatMarkdownMessageView: View {
    let markdown: String

    private enum MarkdownRenderBlock {
        case line(String)
        case table(headers: [String], rows: [[String]])
    }

    private static func isTableSeparatorLine(_ line: String) -> Bool {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        guard trimmed.contains("|") && trimmed.contains("-") else { return false }
        let stripped = trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "| "))
        guard !stripped.isEmpty else { return false }
        let allowed = CharacterSet(charactersIn: "|-: ")
        return stripped.unicodeScalars.allSatisfy { allowed.contains($0) }
    }

    private static func parseTableCells(_ line: String) -> [String] {
        var working = line.trimmingCharacters(in: .whitespaces)
        if working.hasPrefix("|") { working.removeFirst() }
        if working.hasSuffix("|") { working.removeLast() }
        return working.components(separatedBy: "|").map { $0.trimmingCharacters(in: .whitespaces) }
    }

    private var blocks: [MarkdownRenderBlock] {
        let cleaned = markdown
            .replacingOccurrences(of: "VB House Template", with: "Reference Resume Style")
            .replacingOccurrences(of: "VB Reference Resume", with: "Reference Resume")
        let rawLines = cleaned.components(separatedBy: .newlines)
        var result: [MarkdownRenderBlock] = []
        var idx = 0
        while idx < rawLines.count {
            let cur = rawLines[idx].trimmingCharacters(in: .whitespaces)
            if cur.contains("|"),
               idx + 1 < rawLines.count,
               Self.isTableSeparatorLine(rawLines[idx + 1]) {
                let headers = Self.parseTableCells(cur)
                idx += 2
                var tableRows: [[String]] = []
                while idx < rawLines.count {
                    let rowLine = rawLines[idx].trimmingCharacters(in: .whitespaces)
                    if rowLine.isEmpty || !rowLine.contains("|") {
                        break
                    }
                    if !Self.isTableSeparatorLine(rowLine) {
                        tableRows.append(Self.parseTableCells(rowLine))
                    }
                    idx += 1
                }
                result.append(.table(headers: headers, rows: tableRows))
            } else {
                result.append(.line(rawLines[idx]))
                idx += 1
            }
        }
        return result
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            ForEach(Array(blocks.enumerated()), id: \.offset) { _, block in
                switch block {
                case .table(let headers, let rows):
                    MarkdownTableView(headers: headers, rows: rows)
                case .line(let rawLine):
                    let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
                    if trimmed.isEmpty {
                        Spacer().frame(height: 2)
                    } else if trimmed == "---" || trimmed == "***" {
                        Divider().padding(.vertical, 3)
                    } else if trimmed.hasPrefix("# ") {
                        let text = String(trimmed.dropFirst(2))
                        Text(inlineAttributed(text))
                            .font(.system(size: 15.5, weight: .bold))
                            .foregroundColor(.primary)
                            .padding(.top, 2)
                    } else if trimmed.hasPrefix("## ") {
                        let text = String(trimmed.dropFirst(3))
                        Text(inlineAttributed(text))
                            .font(.system(size: 14, weight: .bold))
                            .foregroundColor(.teal)
                            .padding(.top, 2)
                    } else if trimmed.hasPrefix("### ") {
                        let text = String(trimmed.dropFirst(4))
                        Text(inlineAttributed(text))
                            .font(.system(size: 13.5, weight: .semibold))
                            .foregroundColor(.primary)
                            .padding(.top, 1)
                    } else if trimmed.hasPrefix("- ") || trimmed.hasPrefix("* ") || trimmed.hasPrefix("• ") {
                        let bodyText = String(trimmed.dropFirst(2))
                        HStack(alignment: .firstTextBaseline, spacing: 8) {
                            Circle()
                                .fill(Color.teal)
                                .frame(width: 5, height: 5)
                                .padding(.top, 5)
                            Text(inlineAttributed(bodyText))
                                .font(.system(size: 13.5))
                                .foregroundColor(.primary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        .padding(.leading, 2)
                    } else if trimmed.hasPrefix("> ") {
                        let quoteText = String(trimmed.dropFirst(2))
                        HStack(spacing: 8) {
                            Rectangle()
                                .fill(Color.teal)
                                .frame(width: 3)
                            Text(inlineAttributed(quoteText))
                                .font(.system(size: 13))
                                .foregroundColor(.secondary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        .padding(.vertical, 4)
                        .padding(.horizontal, 8)
                        .background(RoundedRectangle(cornerRadius: 6).fill(Color.teal.opacity(0.06)))
                    } else if let dotIndex = trimmed.firstIndex(of: "."),
                              trimmed.distance(from: trimmed.startIndex, to: dotIndex) <= 3,
                              Int(trimmed[..<dotIndex]) != nil,
                              trimmed.index(after: dotIndex) < trimmed.endIndex,
                              trimmed[trimmed.index(after: dotIndex)] == " " {
                        let numPrefix = String(trimmed[...dotIndex])
                        let bodyText = String(trimmed[trimmed.index(dotIndex, offsetBy: 2)...])
                        HStack(alignment: .firstTextBaseline, spacing: 6) {
                            Text(numPrefix)
                                .font(.system(size: 12.5, weight: .semibold, design: .monospaced))
                                .foregroundColor(.teal)
                            Text(inlineAttributed(bodyText))
                                .font(.system(size: 13.5))
                                .foregroundColor(.primary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        .padding(.leading, 2)
                    } else {
                        Text(inlineAttributed(trimmed))
                            .font(.system(size: 13.5))
                            .foregroundColor(.primary)
                            .lineSpacing(3)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
            }
        }
        .textSelection(.enabled)
    }

    private func inlineAttributed(_ raw: String) -> AttributedString {
        if let parsed = try? AttributedString(
            markdown: raw,
            options: AttributedString.MarkdownParsingOptions(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        ) {
            return parsed
        }
        return AttributedString(raw)
    }
}

struct HermesMessageBubbleView: View {
    let message: HermesChatMessageItem
    let providerLabel: String

    private var isUser: Bool {
        message.role == "user"
    }

    var body: some View {
        HStack(alignment: .top, spacing: 10) {
            if isUser {
                Spacer(minLength: 80)
            } else {
                ZStack {
                    Circle()
                        .fill(Color.teal.opacity(0.15))
                        .frame(width: 28, height: 28)
                    Image(systemName: "sparkles")
                        .font(.system(size: 12, weight: .semibold))
                        .foregroundColor(.teal)
                }
                .padding(.top, 2)
            }

            VStack(alignment: isUser ? .trailing : .leading, spacing: 6) {
                if !isUser {
                    HStack(spacing: 6) {
                        Text("AutoApply")
                            .font(.system(size: 11.5, weight: .semibold))
                            .foregroundColor(.secondary)

                        Button {
                            NSPasteboard.general.clearContents()
                            NSPasteboard.general.setString(message.content, forType: .string)
                        } label: {
                            Image(systemName: "doc.on.doc")
                                .font(.system(size: 10))
                                .foregroundColor(.secondary.opacity(0.75))
                        }
                        .buttonStyle(.plain)
                        .help("Copy message")
                    }
                }

                // Attached Files Chips (if any)
                if !message.attachments.isEmpty {
                    HStack(spacing: 6) {
                        ForEach(message.attachments) { att in
                            HStack(spacing: 6) {
                                Image(systemName: "doc.fill")
                                    .font(.system(size: 11))
                                    .foregroundColor(isUser ? .white : .teal)
                                Text(att.name)
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(isUser ? .white : .primary)
                                    .lineLimit(1)
                                if !att.path.isEmpty && FileManager.default.fileExists(atPath: att.path) {
                                    Button {
                                        NSWorkspace.shared.open(URL(fileURLWithPath: att.path))
                                    } label: {
                                        Image(systemName: "arrow.up.forward.square")
                                            .font(.system(size: 10.5))
                                            .foregroundColor(isUser ? .white : .teal)
                                    }
                                    .buttonStyle(.plain)
                                }
                            }
                            .padding(.horizontal, 9)
                            .padding(.vertical, 5)
                            .background(
                                Capsule().fill(isUser ? Color.white.opacity(0.18) : Color.secondary.opacity(0.10))
                            )
                        }
                    }
                }

                // Message Content Card
                Group {
                    if isUser {
                        Text(message.content)
                            .font(.system(size: 13.5))
                            .foregroundColor(.white)
                            .textSelection(.enabled)
                            .lineSpacing(2)
                            .padding(.horizontal, 14)
                            .padding(.vertical, 10)
                            .background(
                                RoundedRectangle(cornerRadius: 14)
                                    .fill(Color.accentColor)
                            )
                    } else {
                        ChatMarkdownMessageView(markdown: message.content)
                            .padding(.horizontal, 14)
                            .padding(.vertical, 12)
                            .background(
                                RoundedRectangle(cornerRadius: 14)
                                    .fill(Color(NSColor.controlBackgroundColor))
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: 14)
                                    .stroke(Color.secondary.opacity(0.12), lineWidth: 1)
                            )
                    }
                }
            }

            if !isUser {
                Spacer(minLength: 60)
            }
        }
    }
}

// MARK: - Password Manager Section View & Pop-up Editor Modal

public struct PasswordManagerSectionView: View {
    @ObservedObject var store: WorkspaceStore

    public init(store: WorkspaceStore) {
        self.store = store
    }

    private var filteredEntries: [PasswordVaultEntryItem] {
        let q = store.passwordSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return store.passwordVaultEntries }
        return store.passwordVaultEntries.filter { entry in
            entry.websiteName.lowercased().contains(q)
                || entry.websiteUrl.lowercased().contains(q)
                || entry.username.lowercased().contains(q)
                || entry.description.lowercased().contains(q)
        }
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            // Clean Toolbar: Search + Count + Add Login Modal Trigger
            HStack(spacing: 12) {
                HStack(spacing: 8) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 13, weight: .medium))
                        .foregroundColor(.secondary)
                        .frame(width: 16, height: 16)

                    TextField("Search by name, URL, or email…", text: $store.passwordSearchQuery)
                        .textFieldStyle(.plain)
                        .font(.system(size: 13))

                    if !store.passwordSearchQuery.isEmpty {
                        Button {
                            store.passwordSearchQuery = ""
                        } label: {
                            Image(systemName: "xmark.circle.fill")
                                .font(.system(size: 12.5, weight: .medium))
                                .foregroundColor(.secondary)
                                .frame(width: 16, height: 16)
                        }
                        .buttonStyle(.plain)
                        .help("Clear search")
                    }
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 8)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(Color.primary.opacity(0.10), lineWidth: 1)
                )

                Text("\(filteredEntries.count) \(filteredEntries.count == 1 ? "login" : "logins")")
                    .font(.system(size: 12, weight: .medium))
                    .foregroundColor(.secondary)
                    .padding(.horizontal, 4)

                Button {
                    store.startAddingPasswordEntry()
                } label: {
                    Label("Add Login", systemImage: "plus")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
            }

            // Compact List or Empty State
            if filteredEntries.isEmpty {
                VStack(spacing: 12) {
                    ZStack {
                        Circle()
                            .fill(Color.accentColor.opacity(0.10))
                            .frame(width: 48, height: 48)
                        Image(systemName: "key.fill")
                            .font(.system(size: 20, weight: .semibold))
                            .foregroundColor(.accentColor)
                            .frame(width: 22, height: 22)
                    }
                    Text(store.passwordVaultEntries.isEmpty ? "No Saved Logins" : "No Matching Logins")
                        .font(.system(size: 15, weight: .semibold))
                    Text(
                        store.passwordVaultEntries.isEmpty
                            ? "Logins saved automatically during applications or added with \"Add Login\" will appear here."
                            : "Try a different search term."
                    )
                    .font(.system(size: 12.5))
                    .foregroundColor(.secondary)
                    .multilineTextAlignment(.center)
                    .frame(maxWidth: 420)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 48)
                .background(
                    RoundedRectangle(cornerRadius: 12)
                        .fill(Color(NSColor.controlBackgroundColor).opacity(0.55))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 12)
                        .stroke(Color.primary.opacity(0.08), lineWidth: 1)
                )
            } else {
                VStack(alignment: .leading, spacing: 0) {
                    // Subtle Column Headers: Name | URL | Email
                    HStack(spacing: 16) {
                        Text("NAME")
                            .frame(width: 210, alignment: .leading)
                        Text("URL")
                            .frame(width: 220, alignment: .leading)
                        Text("EMAIL")
                            .frame(maxWidth: .infinity, alignment: .leading)
                        Spacer()
                            .frame(width: 24)
                    }
                    .font(.system(size: 10.5, weight: .semibold))
                    .foregroundColor(.secondary)
                    .padding(.horizontal, 16)
                    .padding(.vertical, 9)
                    .background(Color.secondary.opacity(0.05))

                    Divider()

                    ForEach(Array(filteredEntries.enumerated()), id: \.element.id) { index, entry in
                        let isExpanded = (store.expandedPasswordEntryId == entry.id)
                        PasswordVaultCompactRow(
                            entry: entry,
                            isExpanded: isExpanded,
                            isRevealed: store.revealedPasswordIds.contains(entry.id),
                            onToggleExpand: {
                                withAnimation(.easeInOut(duration: 0.16)) {
                                    if isExpanded {
                                        store.expandedPasswordEntryId = ""
                                    } else {
                                        store.expandedPasswordEntryId = entry.id
                                    }
                                }
                            },
                            onToggleReveal: {
                                if store.revealedPasswordIds.contains(entry.id) {
                                    store.revealedPasswordIds.remove(entry.id)
                                } else {
                                    store.revealedPasswordIds.insert(entry.id)
                                }
                            },
                            onCopyUrl: {
                                store.copyToClipboard(entry.websiteUrl, label: "URL")
                            },
                            onCopyUsername: {
                                store.copyToClipboard(entry.username, label: "Email / Username")
                            },
                            onCopyPassword: {
                                store.copyToClipboard(entry.password, label: "Password")
                            },
                            onCopyTotp: {
                                let valueToCopy = entry.totpCurrentCode.isEmpty ? entry.totpToken : entry.totpCurrentCode
                                store.copyToClipboard(valueToCopy, label: "2FA code")
                            },
                            onEdit: {
                                store.startEditingPasswordEntry(entry)
                            },
                            onDelete: {
                                store.pendingDeletePasswordEntry = entry
                            }
                        )

                        if index < filteredEntries.count - 1 {
                            Divider()
                                .padding(.leading, 16)
                        }
                    }
                }
                .background(
                    RoundedRectangle(cornerRadius: 12)
                        .fill(Color(NSColor.controlBackgroundColor))
                )
                .clipShape(RoundedRectangle(cornerRadius: 12))
                .overlay(
                    RoundedRectangle(cornerRadius: 12)
                        .stroke(Color.primary.opacity(0.10), lineWidth: 1)
                )
            }
        }
        .onAppear {
            store.sendActionInBackground("get_state", payload: [:], silent: true, preserveLocalEdits: true)
        }
    }
}

private struct PasswordVaultCompactRow: View {
    let entry: PasswordVaultEntryItem
    let isExpanded: Bool
    let isRevealed: Bool
    let onToggleExpand: () -> Void
    let onToggleReveal: () -> Void
    let onCopyUrl: () -> Void
    let onCopyUsername: () -> Void
    let onCopyPassword: () -> Void
    let onCopyTotp: () -> Void
    let onEdit: () -> Void
    let onDelete: () -> Void

    private var displayName: String {
        let trimmed = entry.websiteName.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "Website Login" : trimmed
    }

    private var initialLetter: String {
        String(displayName.prefix(1)).uppercased()
    }

    private var compactUrlLabel: String {
        let raw = entry.websiteUrl.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !raw.isEmpty else { return "—" }
        if let url = URL(string: raw), let host = url.host, !host.isEmpty {
            return host.replacingOccurrences(of: "www.", with: "")
        }
        return raw
            .replacingOccurrences(of: "https://", with: "")
            .replacingOccurrences(of: "http://", with: "")
            .replacingOccurrences(of: "www.", with: "")
    }

    private var maskedPassword: String {
        let count = max(10, min(entry.password.count, 16))
        return String(repeating: "•", count: count)
    }

    private var cleanNotes: String {
        let desc = entry.description.trimmingCharacters(in: .whitespacesAndNewlines)
        if desc.hasPrefix("Saved login (") && desc.hasSuffix("-char password)") {
            return ""
        }
        return desc
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Compact Summary Row: Name, URL, Email
            Button(action: onToggleExpand) {
                HStack(alignment: .center, spacing: 16) {
                    // Name with calibrated badge
                    HStack(spacing: 10) {
                        ZStack {
                            RoundedRectangle(cornerRadius: 7)
                                .fill(isExpanded ? Color.accentColor.opacity(0.18) : Color.secondary.opacity(0.12))
                                .frame(width: 28, height: 28)
                            Text(initialLetter)
                                .font(.system(size: 12.5, weight: .bold, design: .rounded))
                                .foregroundColor(isExpanded ? .accentColor : .primary)
                        }
                        Text(displayName)
                            .font(.system(size: 13.5, weight: .semibold))
                            .foregroundColor(.primary)
                            .lineLimit(1)
                    }
                    .frame(width: 210, alignment: .leading)

                    // URL
                    Text(compactUrlLabel)
                        .font(.system(size: 12.5))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                        .truncationMode(.middle)
                        .frame(width: 220, alignment: .leading)

                    // Email
                    Text(entry.username.isEmpty ? "—" : entry.username)
                        .font(.system(size: 12.5))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                        .truncationMode(.middle)
                        .frame(maxWidth: .infinity, alignment: .leading)

                    // Calibrated Chevron
                    Image(systemName: isExpanded ? "chevron.up" : "chevron.right")
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundColor(.secondary)
                        .frame(width: 24, height: 24)
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 11)
                .background(isExpanded ? Color.accentColor.opacity(0.05) : Color.clear)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)

            // Expanded Details View (Only shown when clicked)
            if isExpanded {
                Divider()
                    .padding(.horizontal, 16)

                VStack(alignment: .leading, spacing: 14) {
                    // Grid of Details
                    HStack(alignment: .top, spacing: 28) {
                        // Email / Username Detail
                        VStack(alignment: .leading, spacing: 4) {
                            Text("Email / Username")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundColor(.secondary)
                            HStack(spacing: 6) {
                                Text(entry.username.isEmpty ? "—" : entry.username)
                                    .font(.system(size: 13, weight: .medium))
                                    .textSelection(.enabled)
                                    .lineLimit(1)

                                if !entry.username.isEmpty {
                                    CalibratedIconButton(
                                        systemName: "doc.on.doc",
                                        helpText: "Copy email / username",
                                        action: onCopyUsername
                                    )
                                }
                            }
                        }
                        .frame(minWidth: 210, alignment: .leading)

                        // Password Detail
                        VStack(alignment: .leading, spacing: 4) {
                            Text("Password")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundColor(.secondary)
                            HStack(spacing: 6) {
                                Text(isRevealed ? entry.password : maskedPassword)
                                    .font(.system(size: 13, weight: .medium, design: .monospaced))
                                    .foregroundColor(isRevealed ? .primary : .secondary)
                                    .textSelection(.enabled)
                                    .lineLimit(1)

                                CalibratedIconButton(
                                    systemName: isRevealed ? "eye.slash" : "eye",
                                    helpText: isRevealed ? "Hide password" : "Show password",
                                    isActive: isRevealed,
                                    action: onToggleReveal
                                )

                                if !entry.password.isEmpty {
                                    CalibratedIconButton(
                                        systemName: "doc.on.doc",
                                        helpText: "Copy password",
                                        action: onCopyPassword
                                    )
                                }
                            }
                        }
                        .frame(minWidth: 220, alignment: .leading)

                        // Website URL Detail
                        if !entry.websiteUrl.isEmpty {
                            VStack(alignment: .leading, spacing: 4) {
                                Text("Website")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.secondary)
                                HStack(spacing: 6) {
                                    Text(entry.websiteUrl)
                                        .font(.system(size: 12.5))
                                        .foregroundColor(.accentColor)
                                        .lineLimit(1)
                                        .truncationMode(.middle)

                                    CalibratedIconButton(
                                        systemName: "arrow.up.right.square",
                                        helpText: "Open website",
                                        action: {
                                            openWebsiteUrl(entry.websiteUrl)
                                        }
                                    )

                                    CalibratedIconButton(
                                        systemName: "doc.on.doc",
                                        helpText: "Copy URL",
                                        action: onCopyUrl
                                    )
                                }
                            }
                        }

                        // Optional 2FA / TOTP Detail
                        if !entry.totpToken.isEmpty || !entry.totpCurrentCode.isEmpty {
                            VStack(alignment: .leading, spacing: 4) {
                                Text("2FA Code")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundColor(.secondary)
                                HStack(spacing: 6) {
                                    Text(entry.totpCurrentCode.isEmpty ? entry.totpToken : entry.totpCurrentCode)
                                        .font(.system(size: 13, weight: .semibold, design: .monospaced))
                                        .foregroundColor(.teal)
                                    CalibratedIconButton(
                                        systemName: "doc.on.doc",
                                        helpText: "Copy 2FA code",
                                        action: onCopyTotp
                                    )
                                }
                            }
                        }

                        Spacer()
                    }

                    // Notes & Action Bar (Edit / Delete)
                    HStack(alignment: .center, spacing: 12) {
                        if !cleanNotes.isEmpty {
                            HStack(spacing: 6) {
                                Image(systemName: "note.text")
                                    .font(.system(size: 11.5, weight: .medium))
                                    .foregroundColor(.secondary)
                                    .frame(width: 14, height: 14)
                                Text(cleanNotes)
                                    .font(.system(size: 12))
                                    .foregroundColor(.secondary)
                                    .lineLimit(2)
                            }
                        }

                        Spacer()

                        Button(action: onEdit) {
                            Label("Edit", systemImage: "pencil")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 6)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)

                        Button(role: .destructive, action: onDelete) {
                            Label("Delete", systemImage: "trash")
                                .font(.system(size: 13, weight: .semibold))
                                .padding(.horizontal, 6)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                        }
                        .buttonStyle(.bordered)
                        .tint(.red)
                        .controlSize(.large)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 14)
                .background(Color(NSColor.windowBackgroundColor).opacity(0.45))
            }
        }
    }

    private func openWebsiteUrl(_ rawUrl: String) {
        let trimmed = rawUrl.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        if let url = URL(string: trimmed),
           let scheme = url.scheme?.lowercased(),
           scheme == "http" || scheme == "https" {
            NSWorkspace.shared.open(url)
        } else if let url = URL(string: "https://\(trimmed)") {
            NSWorkspace.shared.open(url)
        }
    }
}

private struct CalibratedIconButton: View {
    let systemName: String
    let helpText: String
    var isActive: Bool = false
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            Image(systemName: systemName)
                .font(.system(size: 11.5, weight: .medium))
                .foregroundColor(isActive ? .accentColor : .secondary)
                .frame(width: 24, height: 24)
                .background(
                    RoundedRectangle(cornerRadius: 5)
                        .fill(Color.secondary.opacity(0.08))
                )
        }
        .buttonStyle(.plain)
        .help(helpText)
    }
}

