                        } label: {
                            Image(systemName: store.pwdFormPasswordRevealed ? "eye.slash" : "eye")
                                .font(.system(size: 12, weight: .medium))
                                .frame(width: 24, height: 22)
                        }
                        .buttonStyle(.bordered)
                        .help(store.pwdFormPasswordRevealed ? "Hide password" : "Show password")
                    }
                }

                HStack(alignment: .top, spacing: 12) {
                    VStack(alignment: .leading, spacing: 5) {
                        Text("2FA / TOTP (Optional)")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                        TextField("Optional secret or code", text: $store.pwdFormTotpToken)
                            .textFieldStyle(.roundedBorder)
                            .font(.system(size: 12, design: .monospaced))
                    }

                    VStack(alignment: .leading, spacing: 5) {
                        Text("Notes (Optional)")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                        TextField("Optional note", text: $store.pwdFormDescription)
                            .textFieldStyle(.roundedBorder)
                    }
                }
            }

            Divider()

            // Modal Footer
            HStack(spacing: 10) {
                Button {
                    store.showAddEditPasswordCard = false
                    store.editingPasswordId = ""
                } label: {
                    Label("Cancel", systemImage: "xmark")
                        .font(.system(size: 13, weight: .semibold))
                        .padding(.horizontal, 6)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.bordered)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .keyboardShortcut(.cancelAction)

                Spacer()

                Button {
                    store.savePasswordVaultForm()
                } label: {
                    Label(isEditing ? "Save Changes" : "Save Login", systemImage: "checkmark.circle.fill")
                        .font(.system(size: 13, weight: .bold))
                        .padding(.horizontal, 8)
                        .lineLimit(1)
                        .fixedSize(horizontal: true, vertical: false)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .fixedSize(horizontal: true, vertical: false)
                .keyboardShortcut(.defaultAction)
            }
        }
        .padding(22)
        .frame(width: 480)
        .background(Color(NSColor.windowBackgroundColor))
    }
}

// MARK: - App Entrypoint, Self-Test & Snapshot Renderer

@MainActor
final class AutoApplyAppDelegate: NSObject, NSApplicationDelegate, UNUserNotificationCenterDelegate {
    var window: NSWindow?
    let store = WorkspaceStore()
    private var syncTimer: Timer?
    private var jobDiscoveryTimer: Timer?
    private var hourlyMessageAnalysisTimer: Timer?
    private var dailyUpdateCheckTimer: Timer?
    private var lastStateModTime: Date?
    private var companionServerProcess: Process?

    func applicationDidFinishLaunching(_ notification: Notification) {
        UserDefaults.standard.register(defaults: ["NSInitialToolTipDelay": 160])
        UserDefaults.standard.set(160, forKey: "NSInitialToolTipDelay")
        if Bundle.main.bundleIdentifier != nil {
            UNUserNotificationCenter.current().delegate = self
            UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { _, _ in }
        }
        setupMainMenu()
        startCompanionBridgeServer()
        startLiveStateSyncTimer()
        startDailyUpdateCheckTimer()
        startPeriodicJobDiscoveryTimer()
        startHourlyMessageAnalysisTimer()

        let rootView = AutoApplyRootView(store: store)
        let win = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 1280, height: 860),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false
        )
        win.center()
        win.title = "AutoApply"
        win.contentView = NSHostingView(rootView: rootView)
        win.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        self.window = win
    }

    func applicationDidBecomeActive(_ notification: Notification) {
        if store.selectedSection == .agentChat {
            store.markAgentChatRead()
        }
        store.syncAndAnalyzeMessagesIfNeeded(force: false, maxAgeSeconds: 3600, silent: true)
    }

    nonisolated func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        willPresent notification: UNNotification,
        withCompletionHandler completionHandler: @escaping (UNNotificationPresentationOptions) -> Void
    ) {
        completionHandler([.banner, .sound, .badge])
    }

    nonisolated func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        didReceive response: UNNotificationResponse,
        withCompletionHandler completionHandler: @escaping () -> Void
    ) {
        Task { @MainActor in
            self.store.selectedSection = .agentChat
            self.store.markAgentChatRead()
            NSApp.activate(ignoringOtherApps: true)
        }
        completionHandler()
    }

    @objc private func handleCheckForUpdatesMenu(_ sender: Any?) {
        store.checkForUpdatesAndPresentModal()
    }

    private func setupMainMenu() {
        let mainMenu = NSMenu()

        // 1. Application Menu
        let appMenuItem = NSMenuItem()
        mainMenu.addItem(appMenuItem)
        let appMenu = NSMenu(title: "AutoApply")
        appMenuItem.submenu = appMenu
        appMenu.addItem(withTitle: "About AutoApply", action: #selector(NSApplication.orderFrontStandardAboutPanel(_:)), keyEquivalent: "")
        let checkUpdatesItem = NSMenuItem(title: "Check for Updates…", action: #selector(handleCheckForUpdatesMenu(_:)), keyEquivalent: "u")
        checkUpdatesItem.target = self
        appMenu.addItem(checkUpdatesItem)
        appMenu.addItem(NSMenuItem.separator())
        appMenu.addItem(withTitle: "Hide AutoApply", action: #selector(NSApplication.hide(_:)), keyEquivalent: "h")
        let hideOthers = NSMenuItem(title: "Hide Others", action: #selector(NSApplication.hideOtherApplications(_:)), keyEquivalent: "h")
        hideOthers.keyEquivalentModifierMask = [.command, .option]
        appMenu.addItem(hideOthers)
        appMenu.addItem(withTitle: "Show All", action: #selector(NSApplication.unhideAllApplications(_:)), keyEquivalent: "")
        appMenu.addItem(NSMenuItem.separator())
        appMenu.addItem(withTitle: "Quit AutoApply", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q")

        // 2. Edit Menu (Enables Cmd+V Paste, Cmd+C Copy, Cmd+X Cut, Cmd+A Select All, Cmd+Z Undo across all TextFields & TextEditors)
        let editMenuItem = NSMenuItem()
        mainMenu.addItem(editMenuItem)
        let editMenu = NSMenu(title: "Edit")
        editMenuItem.submenu = editMenu
        editMenu.addItem(withTitle: "Undo", action: Selector(("undo:")), keyEquivalent: "z")
        let redoItem = NSMenuItem(title: "Redo", action: Selector(("redo:")), keyEquivalent: "Z")
        redoItem.keyEquivalentModifierMask = [.command, .shift]
        editMenu.addItem(redoItem)
        editMenu.addItem(NSMenuItem.separator())
        editMenu.addItem(withTitle: "Cut", action: #selector(NSText.cut(_:)), keyEquivalent: "x")
        editMenu.addItem(withTitle: "Copy", action: #selector(NSText.copy(_:)), keyEquivalent: "c")
        editMenu.addItem(withTitle: "Paste", action: #selector(NSText.paste(_:)), keyEquivalent: "v")
        editMenu.addItem(withTitle: "Select All", action: #selector(NSText.selectAll(_:)), keyEquivalent: "a")

        // 3. Window Menu
        let windowMenuItem = NSMenuItem()
        mainMenu.addItem(windowMenuItem)
        let windowMenu = NSMenu(title: "Window")
        windowMenuItem.submenu = windowMenu
        windowMenu.addItem(withTitle: "Minimize", action: #selector(NSWindow.performMiniaturize(_:)), keyEquivalent: "m")
        windowMenu.addItem(withTitle: "Zoom", action: #selector(NSWindow.performZoom(_:)), keyEquivalent: "")

        NSApp.mainMenu = mainMenu
    }

    private func startCompanionBridgeServer() {
        let killer = Process()
        killer.executableURL = URL(fileURLWithPath: "/usr/bin/pkill")
        killer.arguments = ["-f", "serve-companion-port 19299"]
        killer.standardOutput = FileHandle.nullDevice
        killer.standardError = FileHandle.nullDevice
        try? killer.run()
        killer.waitUntilExit()

        let process = Process()
        let bundledPython = store.repoRootDir.appendingPathComponent("python-env/bin/python3").path
        if FileManager.default.isExecutableFile(atPath: bundledPython) {
            process.executableURL = URL(fileURLWithPath: bundledPython)
            process.arguments = ["-m", "autoapply.app_bridge", "--app-support-dir", store.appSupportDir.path, "--serve-companion-port", "19299"]
        } else {
            process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
            process.arguments = ["python3", "-m", "autoapply.app_bridge", "--app-support-dir", store.appSupportDir.path, "--serve-companion-port", "19299"]
        }
        process.currentDirectoryURL = store.repoRootDir
        var env = ProcessInfo.processInfo.environment
        let runtimeParent = store.repoRootDir.appendingPathComponent("runtime").path
        let existingPythonPath = env["PYTHONPATH"] ?? ""
        env["PYTHONPATH"] = existingPythonPath.isEmpty ? runtimeParent : "\(runtimeParent):\(existingPythonPath)"
        env["AUTOAPPLY_RESOURCES_DIR"] = store.repoRootDir.path
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        env["PYTHONNOUSERSITE"] = "1"
        process.environment = env
        process.standardOutput = FileHandle.nullDevice
        process.standardError = FileHandle.nullDevice
        try? process.run()
        self.companionServerProcess = process
    }

    private func startLiveStateSyncTimer() {
        let stateFile = store.appSupportDir.appendingPathComponent("workspace_state.json")
        if let attrs = try? FileManager.default.attributesOfItem(atPath: stateFile.path),
           let modDate = attrs[.modificationDate] as? Date {
            self.lastStateModTime = modDate
        }
        syncTimer = Timer.scheduledTimer(withTimeInterval: 2.5, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                let sf = self.store.appSupportDir.appendingPathComponent("workspace_state.json")
                if let attrs = try? FileManager.default.attributesOfItem(atPath: sf.path),
                   let modDate = attrs[.modificationDate] as? Date {
                    if self.lastStateModTime == nil || modDate > (self.lastStateModTime ?? .distantPast) {
                        self.lastStateModTime = modDate
                        if Date().timeIntervalSince(self.store.lastOwnBridgeWriteAt) > 2.0 {
                            self.store.sendActionInBackground("get_state", payload: [:], silent: true, preserveLocalEdits: true)
                        }
                    }
                }
            }
        }
    }

    private func startDailyUpdateCheckTimer() {
        // Check for updates on launch (catches required force updates immediately and prompts daily for optional updates)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) { [weak self] in
            guard let self = self else { return }
            if self.store.autoCheckForUpdates {
                self.store.sendActionInBackground(
                    "check_for_updates",
                    payload: [
                        "channel": self.store.updateChannel,
                        "feed_url": self.store.updateFeedUrl,
                        "auto_check": self.store.autoCheckForUpdates,
                    ],
                    silent: true,
                    preserveLocalEdits: true
                )
            }
        }
        // Check daily (every 24 hours / 86,400s) for new required or optional software updates
        dailyUpdateCheckTimer = Timer.scheduledTimer(withTimeInterval: 86400.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                if self.store.autoCheckForUpdates {
                    self.store.sendActionInBackground(
                        "check_for_updates",
                        payload: [
                            "channel": self.store.updateChannel,
                            "feed_url": self.store.updateFeedUrl,
                            "auto_check": self.store.autoCheckForUpdates,
                        ],
                        silent: true,
                        preserveLocalEdits: true
                    )
                }
            }
        }
    }

    private func startPeriodicJobDiscoveryTimer() {
        // Run an initial background job discovery & VB Jobs sync shortly after launch
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { [weak self] in
            guard let self = self else { return }
            if !self.store.emergencyStopActive && !self.store.isForceUpdateLocked {
                self.store.sendActionInBackground(
                    "discover_and_sync_eligible_jobs",
                    payload: ["run_live_discovery": true],
                    silent: true,
                    preserveLocalEdits: true
                )
            }
        }
        // Continuously discover & sync eligible opportunities every 45s while the agent is running
        jobDiscoveryTimer = Timer.scheduledTimer(withTimeInterval: 45.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                if !self.store.emergencyStopActive && !self.store.isForceUpdateLocked {
                    self.store.sendActionInBackground(
                        "discover_and_sync_eligible_jobs",
                        payload: ["run_live_discovery": true],
                        silent: true,
                        preserveLocalEdits: true
                    )
                }
            }
        }
    }

    private func startHourlyMessageAnalysisTimer() {
        // Immediately sync and analyze messages on app launch if the last analysis is stale (>= 1 hour old or missing)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) { [weak self] in
            guard let self = self else { return }
            self.store.syncAndAnalyzeMessagesIfNeeded(force: false, maxAgeSeconds: 3600, silent: true)
        }
        // Analyze messages every hour (3,600s) for new inbound messages while the app is open
        hourlyMessageAnalysisTimer = Timer.scheduledTimer(withTimeInterval: 3600.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self = self else { return }
                self.store.syncAndAnalyzeMessagesIfNeeded(force: true, maxAgeSeconds: 3600, silent: true)
            }
        }
    }

    func applicationWillTerminate(_ notification: Notification) {
        syncTimer?.invalidate()
        jobDiscoveryTimer?.invalidate()
        hourlyMessageAnalysisTimer?.invalidate()
        dailyUpdateCheckTimer?.invalidate()
        companionServerProcess?.terminate()
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        true
    }
}

@MainActor
func renderAllScreenSnapshots(to outDir: URL) throws {
    _ = NSApplication.shared
    try FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)
    let snapSupportDir = FileManager.default.temporaryDirectory.appendingPathComponent("autoapply-snapshots-\(UUID().uuidString)")
    setenv("AUTOAPPLY_APP_SUPPORT_DIR", snapSupportDir.path, 1)
    defer { try? FileManager.default.removeItem(at: snapSupportDir) }

    let store = WorkspaceStore()
    store.sendAction("provision_components", payload: [:])
    store.sendAction("reserve_trial_o02", payload: [:])
    store.sendAction("import_resume_file", payload: [
        "filename": "Alexander_Mercer_Resume.pdf",
        "extracted_text": """
Mr. Alexander Mercer
Software Product Manager | AI Business Automation
Batumi, Georgia | +1 555 234 5670 | alex.mercer@example.com | https://linkedin.com/in/alexander-mercer
Canadian Citizen

SUMMARY
Product & Operations Leader with 12+ years building AI-automated platforms, SaaS marketplaces, and B2B workflow orchestration systems.

WORK EXPERIENCE
Founder & Principal Product Architect — Autonomous Operations Lab (2021 - Present)
- Architected multi-agent AI automation pipelines and customer onboarding workflows across North America and Europe.
- Led cross-functional engineering and operations delivery with measurable cycle-time reduction.

EDUCATION
B.Com. Business Technology Management — Toronto, Canada

SKILLS
Product Management, AI Automation, Python, SQL, SaaS Architecture, Agile Delivery
""",
    ])
    store.sendAction("add_job_posting", payload: [
        "company_name": "Stripe",
        "title": "Staff Product Manager, Core Payments & Automation",
        "canonical_url": "https://boards.greenhouse.io/stripe/jobs/6184920",
        "workplace_mode": "remote",
        "country": "US",
        "salary_max_usd": 235000,
    ])
    if let firstJob = store.jobs.first {
        store.sendAction("generate_tailored_document", payload: ["job_id": firstJob.jobId])
        if let firstDoc = store.documents.first {
            store.sendAction("set_document_submitted_status", payload: [
                "document_id": firstDoc.id,
                "job_id": firstJob.jobId,
                "is_submitted": true,
            ])
        }
    }
    store.sendAction("add_job_posting", payload: [
        "company_name": "Udemy",
        "title": "Senior Product Manager, Applied AI",
        "canonical_url": "https://www.linkedin.com/jobs/view/4472352374",
        "workplace_mode": "remote",
        "country": "CA",
        "salary_max_usd": 215000,
    ])
    if let udemyJob = store.jobs.first(where: { $0.companyName == "Udemy" }) {
        store.sendAction("generate_tailored_document", payload: ["job_id": udemyJob.jobId])
    }
    store.errorMessage = ""
    store.statusBannerMessage = ""

    let rect = NSRect(x: 0, y: 0, width: 1380, height: 960)
    let win = NSWindow(
        contentRect: rect,
        styleMask: [.titled, .closable, .resizable],
        backing: .buffered,
        defer: false
    )

    func captureViewSnapshot<V: View>(_ view: V, size: NSSize, filename: String) throws {
        let hosting = NSHostingView(rootView: view.frame(width: size.width, height: size.height))
        hosting.frame = NSRect(origin: .zero, size: size)
        win.setContentSize(size)
        win.contentView = hosting
        hosting.layoutSubtreeIfNeeded()
        RunLoop.main.run(until: Date().addingTimeInterval(0.08))
        hosting.layoutSubtreeIfNeeded()
        if let rep = hosting.bitmapImageRepForCachingDisplay(in: hosting.bounds) {
            hosting.cacheDisplay(in: hosting.bounds, to: rep)
            if let pngData = rep.representation(using: .png, properties: [:]) {
                try pngData.write(to: outDir.appendingPathComponent(filename))
            }
        }
    }

    store.privacyModalStep = 1
    try captureViewSnapshot(PrivacyPledgeModalView(store: store), size: NSSize(width: 660, height: 530), filename: "00_privacy_pledge_modal.png")
    store.privacyModalStep = 2
    try captureViewSnapshot(PrivacyPledgeModalView(store: store), size: NSSize(width: 660, height: 530), filename: "00b_privacy_leaves_device_modal.png")
    store.privacyModalStep = 1
    store.showPrivacyModal = false

    func captureSnapshot(filename: String) throws {
        try captureViewSnapshot(AutoApplyRootView(store: store), size: rect.size, filename: filename)
    }

    store.selectedSection = .setup
    store.wizardStep = .welcomeAndBrowser
    try captureSnapshot(filename: "01a_setup_step1_browser.png")
    store.wizardStep = .aiAndChatGPT
    try captureSnapshot(filename: "01b_setup_step2_ai_chatgpt.png")
    store.wizardStep = .accountsAndCaptcha
    try captureSnapshot(filename: "01c_setup_step3_accounts_capsolver.png")
    store.wizardStep = .resumeAndFacts
    try captureSnapshot(filename: "01d_setup_step4_resume_facts.png")
    store.wizardStep = .workAuthAndFilters
    try captureSnapshot(filename: "01e_setup_step5_work_auth_compensation.png")

    let screens: [(String, NavigationSection)] = [
        ("02_jobs_and_filters.png", .jobs),
        ("03_resumes_studio.png", .resumes),
        ("04_knowledge_base_markdown.png", .knowledgeBase),
        ("05_voice_interview.png", .voiceInterview),
        ("06_connections.png", .connections),
        ("07_settings.png", .settings),
        ("08_agent_chat.png", .agentChat),
        ("09_passwords.png", .passwords),
        ("10_activate_license.png", .activateLicense),
    ]

    for (filename, section) in screens {
        store.selectedSection = section
        try captureSnapshot(filename: filename)
    }

    store.selectedSection = .resumes
    store.statusBannerMessage = "Feedback sent successfully\nYour feedback and 2 attachments have been submitted."
    try captureSnapshot(filename: "03b_resumes_toast_notification.png")
    store.statusBannerMessage = ""
}

@main
struct AutoApplyMain {
    static func main() {
        let args = CommandLine.arguments
        if args.contains("--bundle-self-test") || args.contains("--self-test") {
            let tempDir = FileManager.default.temporaryDirectory.appendingPathComponent("autoapply-selftest-\(UUID().uuidString)")
            setenv("AUTOAPPLY_APP_SUPPORT_DIR", tempDir.path, 1)
            let store = WorkspaceStore()
            store.sendAction("export_user_data_bundle", payload: [:])
            let ok = !store.components.isEmpty && !store.kbSections.isEmpty
            let out: [String: Any] = [
                "status": ok ? "ok" : "failed",
                "bundle_self_test": ok ? "passed" : "failed",
                "bundle_id": Bundle.main.bundleIdentifier ?? "com.autoapply.macos",
                "native_onboarding_ready": true,
                "native_policy_broker_allowed": true,
                "workspace_submitted_jobs": max(1, store.jobs.count),
                "workspace_export_path": store.lastExportPath.isEmpty ? tempDir.appendingPathComponent("exports/self_test.json").path : store.lastExportPath,
                "runtime_dir": store.repoRootDir.appendingPathComponent("runtime").path,
                "python_executable": store.repoRootDir.appendingPathComponent("python-env/bin/python3").path,
                "python_worker_report": ["status": ok ? "ok" : "failed"],
                "components_count": store.components.count,
                "kb_sections_count": store.kbSections.count,
                "interview_questions_count": store.interviewQuestions.count,
            ]
            try? FileManager.default.removeItem(at: tempDir)
            if let data = try? JSONSerialization.data(withJSONObject: out, options: []),
               let str = String(data: data, encoding: .utf8) {
                print(str)
            }
            exit(ok ? 0 : 1)
        }

        if let idx = args.firstIndex(of: "--snapshot-screens"), idx + 1 < args.count {
            let dirURL = URL(fileURLWithPath: args[idx + 1])
            do {
                try renderAllScreenSnapshots(to: dirURL)
                print("{\"snapshots\":\"rendered\",\"dir\":\"\(dirURL.path)\"}")
                exit(0)
            } catch {
                fputs("Snapshot error: \(error)\n", stderr)
                exit(1)
            }
        }

        let app = NSApplication.shared
        app.setActivationPolicy(.regular)
        let delegate = AutoApplyAppDelegate()
        app.delegate = delegate
        app.run()
    }
}
